type CodexReasoningEffort = string;

// Runtime CLI d'un compte / agent. Les fournisseurs API annexes sont tous
// executes par OpenCode ; Codex et Claude Code conservent leur CLI natif.
// freebuff est un TUI interactif : il ne vit qu'en onglet terminal, jamais
// dans le flux de chat (le backend refuse explicitement un tour de chat).
type Provider =
  | "codex"
  | "claude"
  | "opencode"
  | "freebuff"
  | "aihubmix"
  | "openai-compatible";
type OpenCodeInferenceProvider =
  | "zai"
  | "zai-coding-plan"
  | "minimax"
  | "minimax-coding-plan"
  | "deepseek"
  | "openrouter";

type AccountProfile = {
  id: string;
  label: string;
  // Date d'ajout (secondes Unix). Absente sur les comptes historiques, qui ne
  // sont jamais concernes par l'expiration de premiere connexion.
  createdAt?: number | null;
  // Fournisseur CLI de ce compte. Optionnel pour la retro-compat (defaut Codex).
  provider?: Provider;
  // Fournisseur de modele authentifie dans le store isole OpenCode.
  inferenceProvider?: string | null;
  codexHome: string;
  projectDir?: string | null;
  proxyId?: string | null;
  startupCommand?: string | null;
  limits?: AccountLimitTracking;
  // Bypass Codex par compte (defaut ON). Absent des configs anterieures : on
  // retombe alors sur le defaut global `codexBypass`, puis `true`.
  bypass?: boolean;
  // Preferences Codex propres a ce CODEX_HOME. Optionnelles pour rester
  // compatible avec les settings.json crees avant leur introduction.
  model?: string | null;
  reasoningEffort?: CodexReasoningEffort | null;
  // Configuration d'un compte « Autre ». La cle n'est presente que dans la
  // requete d'enregistrement : le serveur ne la renvoie jamais au navigateur.
  baseUrl?: string | null;
  reasoningEffortField?: string | null;
  apiKey?: string | null;
  // Palier rapide par compte. Absent des anciens settings => mode normal.
  fastMode?: boolean;
  // Jour civil local ou l'utilisateur a marque ce compte comme termine.
  // Une date anterieure reste compatible mais est affichee comme non terminee.
  completedOn?: string | null;
};

const DEFAULT_CODEX_MODEL = "gpt-5.6-sol";
const DEFAULT_CODEX_REASONING_EFFORT: CodexReasoningEffort = "medium";
// Claude Code : alias de modele (pas d'intensite de raisonnement).
// Les alias `sonnet`/`opus`/`haiku` suivent automatiquement le modele courant de
// chaque palier ; les IDs exacts permettent d'epingler une version precise.
// Le champ accepte aussi tout autre ID tape manuellement.
const DEFAULT_CLAUDE_MODEL = "sonnet";
const CLAUDE_MODEL_SUGGESTIONS = [
  "sonnet",
  "opus",
  "haiku",
  "claude-fable-5",
  "claude-opus-5",
  "claude-opus-4-8",
  "claude-opus-4-7",
  "claude-opus-4-6",
  "claude-sonnet-5",
  "claude-sonnet-4-6",
  "claude-haiku-4-5",
];
// Claude Code : niveaux d'intensite (`--effort`). Sous-ensemble valide cote CLI
// (low/medium/high/xhigh/max) ; `medium` est volontairement omis car c'est le
// defaut Codex herite ("medium") qui a pu etre persiste sur des comptes Claude
// avant cette fonctionnalite — l'exclure evite qu'un ancien compte reste bloque
// sous le defaut natif de Claude (high). Defaut aligne sur Claude Code (high).
const CLAUDE_REASONING_EFFORTS: CodexReasoningEffort[] = [
  "low",
  "high",
  "xhigh",
  "max",
];
const DEFAULT_CLAUDE_REASONING_EFFORT: CodexReasoningEffort = "high";
const CODEX_MODEL_SUGGESTIONS = [
  "gpt-5.6-sol",
  "gpt-5.6-terra",
  "gpt-5.6-luna",
  "gpt-5.5",
  "gpt-5.4",
  "gpt-5.4-mini",
];
const CODEX_REASONING_EFFORTS: Array<{ value: CodexReasoningEffort; label: string }> = [
  { value: "minimal", label: "Minimale" },
  { value: "low", label: "Faible" },
  { value: "medium", label: "Moyenne" },
  { value: "high", label: "Elevee" },
  { value: "xhigh", label: "Tres elevee" },
  { value: "max", label: "Max" },
  { value: "ultra", label: "Ultra" },
];

