// Ouvrir l'Historique depuis la navigation signifie toujours « tout afficher ».
// Un identifiant de session peut etre passe uniquement par le raccourci interne
// qui cherche une conversation precise. Sans ce point d'entree unique, ce
// filtre technique restait actif lorsque l'utilisateur revenait dans la vue.
const openDiscussionHistory = (search = "") => {
  discussionSearch = search;
  setActiveView("discussions");
};

const stopLimitRefreshFollowup = () => {
  if (limitRefreshFollowupTimer !== null) {
    window.clearTimeout(limitRefreshFollowupTimer);
    limitRefreshFollowupTimer = null;
  }
};

const scheduleLimitRefreshFollowup = () => {
  if (limitRefreshFollowupTimer !== null) return;
  limitRefreshFollowupTimer = window.setTimeout(() => {
    limitRefreshFollowupTimer = null;
    runWhenPageVisible(() => void refreshLimitStatus(true));
  }, LIMIT_REFRESH_FOLLOWUP_MS);
};

const refreshLimitStatus = (silent = false, force = false): Promise<void> => {
  if (limitStatusRefreshPromise) return limitStatusRefreshPromise;
  const pending = (async () => {
    limitStatusInFlight = true;
    const announceInLimitsView = !silent && activeView === "limits";
    const wasBackgroundRefreshing = limitStatus.some((row) => row.refreshing === true);
    if (announceInLimitsView) {
      statusText = "Lecture des limites serveur";
    }
    let statusChanged = false;
    let accountSettingsChanged = false;
    let backgroundRefreshing = false;
    try {
      limitStatus = await invoke<AccountLimitView[]>("account_limit_status", { force });
      backgroundRefreshing = limitStatus.some((row) => row.refreshing === true);
      if (
        settings &&
        !accountCatalogMatchesLimitRows(settings.accounts, limitStatus)
      ) {
        const previousAccounts = JSON.stringify(settings.accounts);
        const freshSettings = await invoke<AppSettings>("load_settings");
        settings = freshSettings;
        scheduleUnconnectedAccountCleanup();
        accountSettingsChanged = JSON.stringify(freshSettings.accounts) !== previousAccounts;

        if (!freshSettings.accounts.some((account) => account.id === selectedAccountId)) {
          selectedAccountId = freshSettings.defaultAccountId ?? freshSettings.accounts[0]?.id ?? null;
        }
        if (!freshSettings.accounts.some((account) => account.id === chatAccountId)) {
          chatAccountId = selectedAccountId;
        }
        if (!freshSettings.accounts.some((account) => account.id === newChatAccountId)) {
          newChatAccountId = selectedAccountId;
        }
      }
      const nextSignature = JSON.stringify(limitStatus);
      statusChanged = nextSignature !== limitStatusSignature;
      limitStatusSignature = nextSignature;
      limitStatusLoaded = true;
      if (announceInLimitsView) {
        statusText = backgroundRefreshing
          ? "Limites affichees, actualisation en arriere-plan"
          : "Limites serveur actualisees";
      } else if (wasBackgroundRefreshing && !backgroundRefreshing && activeView === "limits") {
        statusText = "Limites serveur actualisees";
      }
      recoverQuotaExhaustedChatTurns();
    } catch (error) {
      if (announceInLimitsView) statusText = String(error);
      limitStatusLoaded = true;
      backgroundRefreshing = limitStatus.some((row) => row.refreshing === true);
    } finally {
      limitStatusInFlight = false;
    }

    if (backgroundRefreshing) scheduleLimitRefreshFollowup();
    else stopLimitRefreshFollowup();

    if (newChatModalOpen) syncNewChatAccountUsageUi();
    if (activeView === "chat") syncExpertChatGlobalUsageUi();

    if (
      activeView === "limits" &&
      (statusChanged || accountSettingsChanged || announceInLimitsView)
    ) {
      render();
    } else if (activeView === "chat" && (statusChanged || accountSettingsChanged)) {
      if (accountSettingsChanged) render();
      else refreshAllChatRuntimeStatus();
    } else if (activeView === "discussions" && (statusChanged || accountSettingsChanged)) {
      render();
    }
    if (
      activeView !== "chat" &&
      activeView !== "limits" &&
      !chatTurnIsBusy(chatTurn?.status) &&
      !expertChatPanes.some((pane) => chatTurnIsBusy(pane.turn?.status))
    ) {
      stopLimitPoll();
    }
  })();
  limitStatusRefreshPromise = pending;
  const clear = () => {
    if (limitStatusRefreshPromise === pending) limitStatusRefreshPromise = null;
  };
  void pending.then(clear, clear);
  return pending;
};

// Ouvre un terminal interactif `codex login` (ou l'equivalent du provider) pour
// le compte cible : c'est la seule facon de regenerer une session revoquee /
// expiree, sans laquelle la vue Limites ne peut relire aucun quota. On reutilise
// la machinerie terminal existante (meme CODEX_HOME/agent que le compte).
const reloginAccount = async (accountId: string, openAiTabPrepared = false) => {
  if (!settings) return;
  const account = settings.accounts.find((candidate) => candidate.id === accountId);
  if (!account) {
    statusText = "Compte introuvable";
    render();
    return;
  }
  const provider = accountProvider(account);
  const agentId = providerAgentId(provider);
  const agent = agentById(agentId);
  const reconnectCommand = reconnectCommandForAccount(account, agent);
  // Un login n'a besoin d'aucun projet : son terminal temporaire travaille dans
  // le home isole du compte. Le backend reserve toujours l'exigence d'un vrai
  // environnement aux terminaux de travail.
  if (!account.codexHome.trim()) {
    statusText = "Dossier du compte introuvable";
    render();
    return;
  }
  const popupOpened =
    provider === "codex" && isRemoteMode()
      ? openAiTabPrepared
        ? prepareRemoteCodexLoginTab(account.id, account.label)
        : openRemoteCodexLoginWindow(account.id, account.label)
      : false;
  statusText = popupOpened
    ? `Préparation de la fenêtre OpenAI pour ${account.label}…`
    : `Ouverture de la connexion ${accountProviderLabel(account)} pour ${account.label}…`;
  try {
    const session = await createNewTerminal(
      accountId,
      true,
      reconnectCommand,
      agentId,
      null,
      null,
      true,
    );
    if (!session && popupOpened) {
      failRemoteCodexLoginWindow(accountId, "Le terminal de connexion n’a pas pu démarrer.");
    }
  } catch (error) {
    const message = String(error);
    if (popupOpened) failRemoteCodexLoginWindow(accountId, message);
    statusText = message;
    render();
  }
};

const nextUnconnectedAccountExpiry = (): number | null => {
  if (!settings) return null;
  let next: number | null = null;
  for (const account of settings.accounts) {
    if (account.limits?.connectedAt != null || !Number.isFinite(account.createdAt)) continue;
    const deadline = Number(account.createdAt) * 1_000 + UNCONNECTED_ACCOUNT_EXPIRY_MS;
    next = next === null ? deadline : Math.min(next, deadline);
  }
  return next;
};

const stopUnconnectedAccountCleanup = () => {
  if (unconnectedAccountCleanupTimer !== null) {
    clearTimeout(unconnectedAccountCleanupTimer);
    unconnectedAccountCleanupTimer = null;
  }
};

const reconcileAccountSelections = () => {
  if (!settings) return;
  const fallback = settings.defaultAccountId ?? settings.accounts[0]?.id ?? null;
  const keepOrFallback = (accountId: string | null) =>
    settings?.accounts.some((account) => account.id === accountId) ? accountId : fallback;

  selectedAccountId = keepOrFallback(selectedAccountId);
  chatAccountId = keepOrFallback(chatAccountId);
  newChatAccountId = keepOrFallback(newChatAccountId);
  newTerminalAccountId = keepOrFallback(newTerminalAccountId);
  autonomousAccountId = keepOrFallback(autonomousAccountId);
  orchestrationAccountId = keepOrFallback(orchestrationAccountId);
};

const scheduleUnconnectedAccountCleanup = (minimumDelayMs = 0) => {
  stopUnconnectedAccountCleanup();
  const deadline = nextUnconnectedAccountExpiry();
  if (deadline === null) return;

  const delay = Math.max(minimumDelayMs, deadline - Date.now() + 25);
  unconnectedAccountCleanupTimer = window.setTimeout(
    () => void cleanupExpiredUnconnectedAccounts(),
    Math.min(delay, 2_147_000_000),
  );
};

const cleanupExpiredUnconnectedAccounts = async () => {
  if (!settings || unconnectedAccountCleanupInFlight) return;
  stopUnconnectedAccountCleanup();
  unconnectedAccountCleanupInFlight = true;
  const previousAccounts = settings.accounts;

  try {
    const freshSettings = await invoke<AppSettings>("load_settings");
    const freshIds = new Set(freshSettings.accounts.map((account) => account.id));
    const removed = previousAccounts.filter((account) => !freshIds.has(account.id));
    settings = freshSettings;
    reconcileAccountSelections();
    limitStatus = limitStatus.filter((row) => freshIds.has(row.id));
    limitStatusSignature = JSON.stringify(limitStatus);
    removed.forEach((account) => {
      chatModelCatalogs.delete(account.id);
      chatModelCatalogErrors.delete(account.id);
      chatModelCatalogUpdatedAt.delete(account.id);
    });

    if (removed.length > 0 && poolStatus?.running) {
      try {
        poolStatus = await invoke<PoolStatus>("pool_start");
        startPoolPoll();
      } catch {
        // Le profil est bien supprime meme si le pool ne peut pas etre relance.
      }
    }

    if (removed.length > 0) {
      const labels = removed.map((account) => `« ${account.label} »`).join(", ");
      statusText = `${removed.length === 1 ? "Compte" : "Comptes"} ${labels} supprime${removed.length === 1 ? "" : "s"} automatiquement : aucune connexion dans les 10 minutes`;
      render();
    }

    // Si un serveur plus ancien n'a pas encore applique l'expiration, evite
    // une boucle immediate tout en retentant regulierement.
    const nextDeadline = nextUnconnectedAccountExpiry();
    scheduleUnconnectedAccountCleanup(
      nextDeadline !== null && nextDeadline <= Date.now()
        ? UNCONNECTED_ACCOUNT_CLEANUP_RETRY_MS
        : 0,
    );
  } catch {
    scheduleUnconnectedAccountCleanup(UNCONNECTED_ACCOUNT_CLEANUP_RETRY_MS);
  } finally {
    unconnectedAccountCleanupInFlight = false;
  }
};

const startLimitPoll = () => {
  if (limitPoll !== null) return;
  limitPoll = window.setInterval(
    () => runWhenPageVisible(() => void refreshLimitStatus()),
    LIMIT_POLL_INTERVAL_MS,
  );
};

const stopLimitPoll = () => {
  if (limitPoll !== null) {
    clearInterval(limitPoll);
    limitPoll = null;
  }
};

const refreshUsageDashboard = async () => {
  if (usageDashboardInFlight) return;
  usageDashboardInFlight = true;
  let dashboardChanged = false;
  try {
    try {
      usageDashboard = await invoke<UsageDashboard>("usage_dashboard");
      const nextSignature = JSON.stringify(usageDashboard);
      dashboardChanged = nextSignature !== usageDashboardSignature;
      usageDashboardSignature = nextSignature;
    } catch (error) {
      statusText = String(error);
      dashboardChanged = true;
    }

    if (activeView === "dashboard" && dashboardChanged) {
      render();
    }
  } finally {
    usageDashboardInFlight = false;
  }
};

// Le backend met en cache les rollouts inchangés. Le poll peut donc suivre les
// sessions actives sans reparcourir tout l'historique toutes les cinq secondes.
const optionalPositiveNumber = (value: unknown): number | null =>
  typeof value === "number" && Number.isFinite(value) && value >= 0 ? value : null;

const normalizeApiModelUsages = (value: unknown): ApiModelTokenUsage[] => {
  if (!Array.isArray(value)) return [];
  return aggregateApiModelUsage(
    value.flatMap((raw): ApiModelTokenUsage[] => {
      if (!raw || typeof raw !== "object") return [];
      const usage = raw as Partial<ApiModelTokenUsage>;
      const model = typeof usage.model === "string" ? usage.model.trim() : "";
      if (!model) return [];
      return [
        {
          model,
          pricingModel:
            typeof usage.pricingModel === "string" && usage.pricingModel.trim()
              ? usage.pricingModel.trim()
              : null,
          priced: usage.priced === true,
          inputTokens: optionalPositiveNumber(usage.inputTokens) ?? 0,
          cachedInputTokens: optionalPositiveNumber(usage.cachedInputTokens) ?? 0,
          outputTokens: optionalPositiveNumber(usage.outputTokens) ?? 0,
          reasoningOutputTokens: optionalPositiveNumber(usage.reasoningOutputTokens) ?? 0,
          totalTokens: optionalPositiveNumber(usage.totalTokens) ?? 0,
          apiEquivalentUsd: optionalPositiveNumber(usage.apiEquivalentUsd) ?? 0,
          inputPricePerMillion: optionalPositiveNumber(usage.inputPricePerMillion),
          cachedInputPricePerMillion: optionalPositiveNumber(usage.cachedInputPricePerMillion),
          outputPricePerMillion: optionalPositiveNumber(usage.outputPricePerMillion),
          longContextThresholdTokens: optionalPositiveNumber(usage.longContextThresholdTokens),
          longInputPricePerMillion: optionalPositiveNumber(usage.longInputPricePerMillion),
          longCachedInputPricePerMillion: optionalPositiveNumber(
            usage.longCachedInputPricePerMillion,
          ),
          longOutputPricePerMillion: optionalPositiveNumber(usage.longOutputPricePerMillion),
          longContextRequests: optionalPositiveNumber(usage.longContextRequests) ?? 0,
        },
      ];
    }),
  );
};

const normalizeAccountUsageDashboard = (
  dashboard: AccountUsageDashboard,
): AccountUsageDashboard => {
  const normalizedAccounts = (Array.isArray(dashboard.accounts) ? dashboard.accounts : []).map(
    (account) => {
      const profileLabels = Array.isArray(account.profileLabels)
        ? account.profileLabels.filter(
            (label): label is string => typeof label === "string" && label.trim().length > 0,
          )
        : [];
      const usageSource =
        account.usageSource === "codex-account" ||
        account.usageSource === "local-sessions" ||
        account.usageSource === "unavailable"
          ? account.usageSource
          : "local-sessions";
      const normalized: AccountUsageView = {
        ...account,
        profileLabels: profileLabels.length ? profileLabels : [account.label],
        usageSource,
        sourceError: account.sourceError ?? account.error ?? null,
        days: Array.isArray(account.days) ? account.days : [],
        models: normalizeApiModelUsages(account.models),
      };
      normalized.days = normalized.days.map((day) => ({
        ...day,
        models: normalizeApiModelUsages(day.models),
      }));
      if (normalized.models.length === 0) {
        normalized.models = aggregateApiModelUsage(
          normalized.days.flatMap((day) => day.models),
        );
      }
      return normalized;
    },
  );
  const fallbackProfileCount = normalizedAccounts.reduce(
    (total, account) => total + Math.max(1, account.profileLabels.length),
    0,
  );
  const accounts = deduplicateAccountTokenAccounts(normalizedAccounts);
  const dashboardModels = normalizeApiModelUsages(dashboard.models);
  const models =
    dashboardModels.length > 0
      ? dashboardModels
      : aggregateApiModelUsage(accounts.flatMap((account) => account.models));
  return {
    ...dashboard,
    accounts,
    models,
    totalTokens: accounts.reduce((total, account) => total + (account.totalTokens || 0), 0),
    totalCostUsd: accounts.reduce((total, account) => total + (account.costUsd || 0), 0),
    totalSessions: accounts.reduce((total, account) => total + (account.sessionCount || 0), 0),
    profileCount:
      Number.isFinite(dashboard.profileCount) && dashboard.profileCount > 0
        ? dashboard.profileCount
        : fallbackProfileCount,
  };
};

const refreshAccountUsage = async () => {
  if (accountUsageInFlight) return;  accountUsageInFlight = true;
  accountUsageLastRefreshAt = Date.now();
  let accountUsageChanged = false;
  try {
    const nextAccountUsage = normalizeAccountUsageDashboard(
      await invoke<AccountUsageDashboard>("account_token_usage"),
    );
    const nextSignature = JSON.stringify({
      totalTokens: nextAccountUsage.totalTokens,
      totalSessions: nextAccountUsage.totalSessions,
      accounts: nextAccountUsage.accounts,
    });
    accountUsageChanged =
      !accountUsageLoaded || nextSignature !== accountUsageSignature;
    accountUsage = nextAccountUsage;
    accountUsageSignature = nextSignature;
    accountUsageLoaded = true;
  } catch (error) {
    statusText = String(error);
    accountUsageChanged = !accountUsageLoaded;
    accountUsageLoaded = true;
  } finally {
    accountUsageInFlight = false;
  }

  if (activeView === "dashboard" && accountUsageChanged) {
    render();
  }
};

const normalizeWorkTimeDashboard = (dashboard: WorkTimeDashboard): WorkTimeDashboard => ({
  ...dashboard,
  totalSeconds: Math.max(0, Number(dashboard.totalSeconds) || 0),
  trackedChats: Math.max(0, Number(dashboard.trackedChats) || 0),
  trackedTurns: Math.max(0, Number(dashboard.trackedTurns) || 0),
  days: (Array.isArray(dashboard.days) ? dashboard.days : [])
    .filter((day) => /^\d{4}-\d{2}-\d{2}$/.test(day.date))
    .map((day) => ({
      date: day.date,
      activeSeconds: Math.max(0, Number(day.activeSeconds) || 0),
      turnCount: Math.max(0, Number(day.turnCount) || 0),
    })),
});

const refreshWorkTimeDashboard = async () => {
  if (workTimeInFlight) return;
  workTimeInFlight = true;
  let workTimeChanged = false;
  try {
    const nextDashboard = normalizeWorkTimeDashboard(
      await invoke<WorkTimeDashboard>("work_time_dashboard"),
    );
    const nextSignature = JSON.stringify({
      totalSeconds: nextDashboard.totalSeconds,
      trackedChats: nextDashboard.trackedChats,
      trackedTurns: nextDashboard.trackedTurns,
      firstActivity: nextDashboard.firstActivity,
      lastActivity: nextDashboard.lastActivity,
      days: nextDashboard.days,
    });
    workTimeChanged = !workTimeLoaded || nextSignature !== workTimeSignature;
    workTimeDashboard = nextDashboard;
    workTimeSignature = nextSignature;
    workTimeLoaded = true;
  } catch (error) {
    statusText = String(error);
    workTimeChanged = !workTimeLoaded;
    workTimeLoaded = true;
  } finally {
    workTimeInFlight = false;
  }

  if (activeView === "dashboard" && workTimeChanged) {
    render();
  }
};

const startUsagePoll = () => {
  stopUsagePoll();
  usagePoll = window.setInterval(
    () =>
      runWhenPageVisible(() => {
        void refreshUsageDashboard();
        void refreshWorkTimeDashboard();
        void refreshReferralDashboard(false, true);
        const now = Date.now();
        if (
          !accountUsageLoaded
          || now - accountUsageLastRefreshAt >= ACCOUNT_USAGE_REFRESH_INTERVAL_MS
        ) {
          void refreshAccountUsage();
        }
      }),
    DASHBOARD_POLL_INTERVAL_MS,
  );
};

const stopUsagePoll = () => {
  if (usagePoll !== null) {
    clearInterval(usagePoll);
    usagePoll = null;
  }
};

const kombaiStatusSummary = (status: KombaiStatus) =>
  status.running ? "Kombai actif" : status.started ? "Kombai en cours de demarrage" : "Kombai arrete";

const refreshKombaiStatus = async () => {
  if (kombaiStatusInFlight) return;
  kombaiStatusInFlight = true;
  try {
    try {
      const wasRunning = kombaiStatus?.running ?? false;
      kombaiStatus = await invoke<KombaiStatus>("kombai_status");
      kombaiLoaded = true;
      const recoveredFromError = kombaiStatusError;
      const runningChanged = kombaiStatus.running !== wasRunning;
      kombaiStatusError = false;
          if (activeView === "design" && activeDesignTool === "kombai") {
        if (recoveredFromError || runningChanged) {
          statusText = kombaiStatusSummary(kombaiStatus);
        }
        // Evite de recharger l'iframe a chaque tick : le statut stable ne
        // justifie aucun rendu global. Le premier rendu est couvert par
        // l'absence de l'iframe, puis seuls les changements d'etat redessinent.
        if (recoveredFromError || runningChanged || !document.querySelector("#kombaiFrame")) {
          render();
        }
      }
    } catch (error) {
      kombaiStatusError = true;
      statusText = String(error);
      kombaiLoaded = true;
      if (activeView === "design" && activeDesignTool === "kombai") render();
    }
  } finally {
    kombaiStatusInFlight = false;
  }
};

const startKombaiPoll = () => {
  stopKombaiPoll();
  kombaiPoll = window.setInterval(
    () => runWhenPageVisible(() => void refreshKombaiStatus()),
    2000,
  );
};

const stopKombaiPoll = () => {
  if (kombaiPoll !== null) {
    clearInterval(kombaiPoll);
    kombaiPoll = null;
  }
};

const applyDiscussionsSnapshot = (snapshot: DiscussionsView) => {
  discussions = snapshot;
  discussionsLoaded = true;
  const latestDiscussions = snapshot.accounts.flatMap((group) => group.discussions);
  const newlyAttachedPanes = attachPendingExpertChatRecords(latestDiscussions);
  const nextRenderSignature = JSON.stringify([snapshot.totalDiscussions, snapshot.accounts]);
  if (nextRenderSignature === discussionsRenderSignature && newlyAttachedPanes.length === 0) return;
  discussionsRenderSignature = nextRenderSignature;
  const latestByDiscussion = new Map(
    latestDiscussions.map((discussion) => [discussionIdentityKey(discussion), discussion]),
  );
  const syncPanelTitle = (root: ParentNode | null, discussion: DiscussionSummary) => {
    const element = root?.querySelector<HTMLElement>(".chat-title");
    if (!element) return;
    const title = discussion.title?.trim() || "Nouvelle conversation";
    element.textContent = title;
    element.title = title;
  };
  const syncPanelTokenUsage = (
    root: ParentNode | null,
    model: ChatPanelModel,
    blocked = false,
  ) => {
    const current = root?.querySelector<HTMLElement>("[data-chat-control='tokens']");
    if (!current) return;
    const signature = chatTokenUsagePresentation(
      model.totalTokens,
      model.contextUsage,
    ).signature;
    if (
      current.dataset.chatTokenSignature === signature
      && current.classList.contains("is-compacting") === model.contextCompacting
    ) return;
    current.outerHTML = renderChatTokenUsage(model, blocked || chatTurnIsBusy(model.turnStatus));
    const next = root?.querySelector<HTMLElement>("[data-chat-control='tokens']");
    if (next) renderIcons(next);
  };
  if (chatDiscussion) {
    const latest = latestByDiscussion.get(discussionIdentityKey(chatDiscussion));
    if (latest) {
      Object.assign(chatDiscussion, latest);
      syncPanelTitle(document.querySelector<HTMLElement>("#chatPanel"), chatDiscussion);
      syncPanelTokenUsage(document.querySelector<HTMLElement>("#chatPanel"), chatPanelModel());
    }
  }
  expertChatPanes.forEach((pane) => {
    if (!pane.discussion && pane.accountId && pane.resumeSessionId) {
      const restored = discussionForSession(
        latestDiscussions,
        pane.accountId,
        pane.resumeSessionId,
      );
      if (restored) {
        const capturedWorkspace = userEnvironmentPath(pane.pendingWorkspace);
        if (capturedWorkspace && !restored.folderPath) restored.folderPath = capturedWorkspace;
        pane.discussion = restored;
        pane.resumeSessionId = restored.rolloutId?.trim() || pane.resumeSessionId;
        pane.accountId = restored.accountId;
        pane.contextUsage = null;
        pane.loading = true;
        pane.error = null;
        newlyAttachedPanes.push(pane);
      }
    }
    if (!pane.discussion) return;
    const latest = latestByDiscussion.get(discussionIdentityKey(pane.discussion));
    if (latest) {
      Object.assign(pane.discussion, latest);
      syncPanelTitle(expertChatPaneRoot(pane), pane.discussion);
      syncPanelTokenUsage(
        expertChatPaneRoot(pane),
        expertChatPanelModel(pane),
        expertChatAccountTransitions.has(pane.key),
      );
    }
  });
  if (activeView === "discussions") {
    const host = document.querySelector<HTMLDivElement>("#discussionGroups");
    if (host) {
      refreshDiscussionList();
    } else {
      render();
    }
  } else if (activeView === "chat") {
    const host = document.querySelector<HTMLElement>("#chatSideConversations");
    // Ne remplace jamais le DOM sous le pointeur pendant un drag natif : sinon
    // le navigateur annule le geste avant que le drop atteigne son workspace.
    if (host && !draggedChatSessionId) {
      chatSidebarRefreshPending = false;
      host.innerHTML = renderChatSidebarConversations();
      renderIcons(host);
      bindDiscussionRowUi();
      bindWorkspaceSwitcherUi(host);
    } else if (host) {
      chatSidebarRefreshPending = true;
    }
    // Garde le compteur global des workspaces et conversations a jour.
    refreshWorkspaceSwitcher();
  }
  if (newlyAttachedPanes.length > 0) {
    persistExpertChats();
    newlyAttachedPanes.forEach((pane) => void loadChatModelCatalog(pane.accountId));
    if (activeView === "chat") {
      // Un panneau place en attente n'existait pas encore dans le DOM. Le
      // rafraichissement cible ne pouvait donc rien afficher ; reconstruire le
      // mur restaure aussi la selection active qui attendait ce rattachement.
      render();
      startAllExpertChatWork();
    }
  }
};

const refreshDiscussions = (): Promise<void> => {
  if (discussionsRefreshPromise) return discussionsRefreshPromise;
  const pending = (async () => {
    try {
      applyDiscussionsSnapshot(await invoke<DiscussionsView>("list_discussions"));
    } catch (error) {
      statusText = String(error);
      discussionsLoaded = true;
    }
  })();
  discussionsRefreshPromise = pending;
  const clear = () => {
    if (discussionsRefreshPromise === pending) discussionsRefreshPromise = null;
  };
  void pending.then(clear, clear);
  return pending;
};

const startDiscussionsPoll = () => {
  stopDiscussionsPoll();
  if (isRemoteMode() && remoteNodesText().trim()) {
    // Un seul WebSocket ne represente qu'un VPS. En mode multi-noeuds, le
    // snapshot REST agrege maintient l'index complet et actualise les routes
    // collantes des sessions.
    discussionsSyncState = "polling";
    discussionsPoll = window.setInterval(
      () => runWhenPageVisible(() => {
        void refreshDiscussions();
      }),
      DISCUSSIONS_POLL_INTERVAL_MS,
    );
  } else if (isRemoteMode()) {
    discussionsSyncState = "connecting";
    discussionsLiveUnlisten = subscribeDiscussionUpdates(
      {},
      (message: DiscussionStreamMessage) => {
        if (message.type === "dashboard") {
          applyDiscussionsSnapshot(message.dashboard as DiscussionsView);
        } else if (message.type === "error") {
          statusText = `Synchronisation des discussions : ${message.message}`;
        }
      },
      (state) => {
        discussionsSyncState = state;
      },
    );
    // Filet de securite si un proxy intermediaire coupe durablement les WS.
    discussionsPoll = window.setInterval(() => {
      runWhenPageVisible(() => {
        if (discussionsSyncState !== "live") void refreshDiscussions();
      });
    }, DISCUSSIONS_POLL_INTERVAL_MS);
  } else {
    // Le bureau local n'a pas de serveur WebSocket : le scan ne tourne que tant
    // que la vue est ouverte, avec une cadence assez courte pour suivre un chat.
    discussionsPoll = window.setInterval(
      () => runWhenPageVisible(() => {
        void refreshDiscussions();
      }),
      DISCUSSIONS_POLL_INTERVAL_MS,
    );
  }
  startActiveChatTurnsPoll();
};

const stopDiscussionsPoll = () => {
  stopActiveChatTurnsPoll();
  discussionsLiveUnlisten?.();
  discussionsLiveUnlisten = null;
  discussionsSyncState = "closed";
  if (discussionsPoll !== null) {
    clearInterval(discussionsPoll);
    discussionsPoll = null;
  }
};

const allDiscussions = (): DiscussionSummary[] =>
  discussions?.accounts.flatMap((group) => group.discussions) ?? [];

const findDiscussion = (id: string | null | undefined, accountId?: string | null) =>
  (id && allDiscussions().find((discussion) =>
    discussion.sessionId === id && (!accountId || discussion.accountId === accountId)
  )) || null;

const renameDiscussion = async (discussion: DiscussionSummary): Promise<void> => {
  if (discussionBusyId) return;
  const currentTitle = discussion.title?.trim() ?? "";
  const requested = window.prompt(
    "Nouveau nom du chat (laissez vide pour restaurer le titre automatique)",
    currentTitle,
  );
  if (requested === null || requested.trim() === currentTitle) return;
  if (requested.trim().length > 80) {
    statusText = "Le nom du chat ne peut pas dépasser 80 caractères";
    render();
    return;
  }

  discussionBusyId = discussionIdentityKey(discussion);
  if (activeView === "discussions") refreshDiscussionList();
  else refreshChatSidebarConversations();
  try {
    const renamed = await invoke<DiscussionSummary>("rename_discussion", {
      accountId: discussion.accountId,
      sessionId: discussion.sessionId,
      title: requested,
    });
    Object.assign(discussion, renamed);
    statusText = requested.trim()
      ? `Chat renommé « ${renamed.title ?? requested.trim()} »`
      : "Titre automatique restauré";
  } catch (error) {
    statusText = `Renommage impossible : ${String(error)}`;
  }
  discussionBusyId = null;
  await refreshDiscussions();
  render();
};

const discussionMatches = (discussion: DiscussionSummary, label: string) => {
  const query = discussionSearch.trim().toLowerCase();
  if (!query) return true;
  return [discussion.title ?? "", discussion.preview ?? "", discussionFolderPath(discussion) ?? "", discussion.sessionId, label]
    .some((field) => field.toLowerCase().includes(query));
};

const persistDiscussionFolder = async (
  discussion: DiscussionSummary,
  folderPath: string,
): Promise<DiscussionSummary> => {
  discussion.folderPath = folderPath;
  if (
    discussion.cwd?.trim() &&
    normalizeWorkspacePath(discussion.cwd) === normalizeWorkspacePath(folderPath)
  ) {
    return discussion;
  }
  const moved = await invoke<DiscussionSummary>("move_discussion", {
    accountId: discussion.accountId,
    sessionId: discussion.sessionId,
    workspacePath: folderPath,
  });
  moved.folderPath = folderPath;
  Object.assign(discussion, moved);
  return discussion;
};

const restoreDiscussionFolder = async (
  discussion: DiscussionSummary,
): Promise<string | null> => {
  const folderPath = activateDiscussionFolder(discussion);
  if (!folderPath) return null;
  await persistDiscussionFolder(discussion, folderPath);
  return folderPath;
};

// Une reprise automatique (quota epuise, chat suivi en arriere-plan) doit
// conserver l'environnement actuellement affiche. Elle resout et persiste le
// dossier du chat concerne sans toucher au workspace, au filtre ou au terminal
// actifs de l'utilisateur.
const preserveDiscussionFolder = async (
  discussion: DiscussionSummary,
): Promise<string | null> => {
  const folderPath = discussionFolderPath(discussion);
  if (!folderPath) return null;
  discussion.folderPath = folderPath;
  await persistDiscussionFolder(discussion, folderPath);
  return folderPath;
};

// Quand un terminal se ferme, on retrouve son transcript par son id (ou par le
// dossier courant pour une nouvelle session), puis on persiste ce dossier afin
// que la prochaine reprise restaure le meme contexte.
const persistTerminalDiscussionFolder = async (session: TerminalSession): Promise<void> => {
  const folderPath = session.folderPath?.trim();
  if (!folderPath) return;
  const linkedIds = new Set(
    [session.codexSessionId, session.resumeSessionId].filter(
      (id): id is string => !!id,
    ),
  );

  for (const delay of [0, 200, 600]) {
    if (delay) await sleep(delay);
    await refreshDiscussions();
    const discussion = allDiscussions().find(
      (candidate) =>
        candidate.accountId === session.accountId &&
        (linkedIds.has(candidate.sessionId) || linkedIds.has(candidate.rolloutId)),
    ) ?? allDiscussions()
      .filter(
        (candidate) =>
          candidate.accountId === session.accountId &&
          !!candidate.cwd &&
          !!session.workspacePath &&
          normalizeWorkspacePath(candidate.cwd) === normalizeWorkspacePath(session.workspacePath) &&
          candidate.lastActivity >= (session.startedAtUnix ?? 0) - 5,
      )
      .sort((left, right) => right.lastActivity - left.lastActivity)[0];
    if (!discussion) continue;
    await persistDiscussionFolder(discussion, folderPath);
    await refreshDiscussions();
    return;
  }
};

const freebuffResumeId = (discussion: DiscussionSummary): string | null => {
  const explicit = discussion.resumeId?.trim();
  if (explicit && FREEBUFF_RESUME_ID_RE.test(explicit) && explicit !== "." && explicit !== "..") {
    return explicit;
  }
  // Compatibilite avec un backend anterieur au champ `resumeId` : le fichier
  // est toujours `<projet>/chats/<id>/chat-messages.json`.
  const parts = discussion.filePath.replace(/\\/g, "/").split("/").filter(Boolean);
  const inferred = parts.at(-2)?.trim() ?? "";
  return FREEBUFF_RESUME_ID_RE.test(inferred) && inferred !== "." && inferred !== ".."
    ? inferred
    : null;
};

const launchFreebuffDiscussionTerminal = async (
  discussion: DiscussionSummary,
  target: AccountProfile,
  folderPath: string,
) => {
  if (accountProvider(target) !== "freebuff") {
    throw new Error("le compte cible n'est pas un compte Freebuff");
  }
  await assertFreebuffAccountAvailable(target);
  const resumeId = freebuffResumeId(discussion);
  if (!resumeId) {
    throw new Error("l'identifiant natif de la conversation Freebuff est invalide");
  }
  const session = await createNewTerminal(
    target.id,
    false,
    buildResumeCommand(resumeId, target),
    providerAgentId("freebuff"),
    resumeId,
    folderPath,
  );
  if (!session) throw new Error(`le terminal Freebuff de ${target.label} n'a pas pu être créé`);
  if (!session.running || session.ptyId === null || session.status === "Erreur") {
    const failure = statusText || `${target.label} est indisponible`;
    await closeTerminalSession(session.key);
    throw new Error(failure);
  }
  return session;
};

// Reprise dans le compte D'ORIGINE : les providers non interactifs ouvrent le
// fil dans le chat classique. Freebuff restaure son dossier natif dans un
// terminal TUI, car il n'expose pas de mode chat structure/non interactif.
const resumeDiscussion = async (discussion: DiscussionSummary) => {
  const provider = discussion.provider ?? accountProvider(accountById(discussion.accountId));
  if (provider === "freebuff") {
    if (discussionBusyId) return;
    const target = accountById(discussion.accountId);
    if (!target) return;
    discussionBusyId = discussionIdentityKey(discussion);
    render();
    try {
      const folderPath = userEnvironmentPath(activateDiscussionFolder(discussion));
      if (!folderPath) throw new Error("la discussion n'a pas d'environnement associe");
      await launchFreebuffDiscussionTerminal(discussion, target, folderPath);
      statusText = `Conversation Freebuff reprise avec ${target.label}`;
    } catch (error) {
      statusText = `Reprise Freebuff impossible : ${String(error)}`;
    }
    discussionBusyId = null;
    render();
    return;
  }
  try {
    const folderPath = userEnvironmentPath(await restoreDiscussionFolder(discussion));
    if (!folderPath) {
      throw new Error("la discussion n'a pas d'environnement associe");
    }
    const resumed = await resumeDiscussionInChat(
      discussion,
      discussion.accountId,
      folderPath,
      "continue",
    );
    if (!resumed) {
      statusText = "Le chat n'a pas pu demarrer cette discussion";
      render();
    }
  } catch (error) {
    statusText = `Impossible de restaurer l'environnement de la discussion : ${String(error)}`;
    render();
  }
};

const transferredDiscussionStatus = (
  _target: AccountProfile,
) => "Conversation poursuivie · historique complet conservé";

const transferredDiscussionPendingStatus = (_target: AccountProfile) =>
  "Conversation prête";

// Ferme uniquement les vues encore rattachees a la source apres une reprise
// reussie. Les fichiers de session ne sont ni archives ni supprimes : la
// conversation reste donc dans l'Historique jusqu'au retrait manuel. Detacher
// la vue evite aussi que le polling du tour source echoue relance la bascule en
// boucle une fois le panneau cible actif.
const detachTransferredDiscussionSourceFromOpenViews = (
  discussion: DiscussionSummary,
) => {
  const sourceIds = new Set([discussion.sessionId, discussion.rolloutId]);
  const isSourceDiscussion = (candidate: DiscussionSummary | null | undefined) =>
    !!candidate
    && candidate.accountId === discussion.accountId
    && (sourceIds.has(candidate.sessionId) || sourceIds.has(candidate.rolloutId));

  const sourcePanes = expertChatPanes.filter((pane) => isSourceDiscussion(pane.discussion));
  sourcePanes.forEach((pane) => {
    stopExpertChatSync(pane);
    stopExpertChatTurnPoll(pane);
    resetExpertModelCapacityRetry(pane);
    expertChatAccountTransitions.delete(pane.key);
    automaticQuotaResumeVisibilityPins.delete(pane.key);
    explicitlyOpenedBusyChatVisibilityPins.delete(pane.key);
  });
  expertChatPanes = expertChatPanes.filter((pane) => !isSourceDiscussion(pane.discussion));
  if (sourcePanes.some((pane) => pane.key === activeExpertChatKey)) {
    activeExpertChatKey = expertChatPanes.at(-1)?.key ?? null;
  }
  if (sourcePanes.some((pane) => pane.key === expertChatFullscreenKey)) {
    expertChatFullscreenKey = null;
  }
  if (sourcePanes.length) {
    reconcileExpertChatPage();
    persistExpertChats();
  }

  if (isSourceDiscussion(chatDiscussion)) {
    stopChatSync();
    stopChatTurnPoll();
    resetMainModelCapacityRetry();
    chatDiscussion = null;
    chatMessages = [];
    chatTurn = null;
    chatQueuedSubmissions = [];
    chatQueueDrainInFlight = false;
    chatError = null;
    chatLoading = false;
    chatTruncated = false;
    chatContextUsage = null;
    chatContextCompacting = false;
    chatHistoryOpen = false;
  }
};

const syncStatusTextDom = () => {
  document.querySelectorAll<HTMLElement>(".chat-status-toast").forEach((element) => {
    element.textContent = statusText;
  });
};

const refreshAccountTransitionUi = (pane: ExpertChatPane | null) => {
  syncStatusTextDom();
  if (pane && activeView === "chat" && expertChatPanes.includes(pane)) {
    // Un chat d'une autre page peut basculer en arriere-plan : ne jamais
    // deplacer la page courante ni reconstruire la grille pour lui.
    if (expertChatPaneRoot(pane)) refreshExpertChatPane(pane);
    return;
  }
  render();
};

const setExpertChatAccountTransition = (
  pane: ExpertChatPane | null,
  transition: ChatAccountTransition | null,
) => {
  if (!pane) {
    refreshAccountTransitionUi(null);
    return;
  }
  if (transition) {
    expertChatAccountTransitions.set(pane.key, transition);
  } else if (!expertChatAccountTransitions.delete(pane.key)) {
    // Le chemin d'echec a deja restaure le panneau. Il ne reste qu'a annoncer
    // le nouveau statut, sans remplacer une deuxieme fois son DOM.
    syncStatusTextDom();
    return;
  }
  refreshAccountTransitionUi(pane);
};

// Le compte cible est utilisable des que start_chat_turn a confirme son
// demarrage. La source reste volontairement dans l'Historique : seul
// l'utilisateur peut ensuite la retirer avec l'action dediee. Le rescannage de
// l'index ne doit pas bloquer le compositeur pendant plusieurs secondes.
const finalizeTransferredDiscussion = async (
  discussion: DiscussionSummary,
  target: AccountProfile,
  pendingStatus: string,
) => {
  // Revenir au compte d'origine dans son ancienne ligne d'historique, au lieu
  // de laisser le selecteur pointe vers la copie qui vient d'etre creee.
  discussionTargetSel.delete(discussionIdentityKey(discussion));

  // Le verrou protege uniquement la source contre une seconde copie. Le
  // chat cible, lui, est deja interactif depuis releaseTransferredDiscussion.
  if (discussionIsBusy(discussion)) discussionBusyId = null;
  await refreshDiscussions();
  // Ne pas ecraser une action plus recente de l'utilisateur avec la fin d'une
  // tache d'arriere-plan devenue stale.
  if (statusText === pendingStatus) {
    statusText = transferredDiscussionStatus(target);
    syncStatusTextDom();
  }
};

const releaseTransferredDiscussion = (
  discussion: DiscussionSummary,
  target: AccountProfile,
  transferPane: ExpertChatPane | null,
) => {
  const pendingStatus = transferredDiscussionPendingStatus(target);
  statusText = pendingStatus;
  detachTransferredDiscussionSourceFromOpenViews(discussion);
  setExpertChatAccountTransition(transferPane, null);
  void finalizeTransferredDiscussion(discussion, target, pendingStatus);
};

const expertPaneForDiscussion = (
  discussion: DiscussionSummary,
  preferred: ExpertChatPane | null = null,
): ExpertChatPane | null => {
  const ids = new Set([discussion.sessionId, discussion.rolloutId]);
  const matches = (pane: ExpertChatPane | null | undefined) =>
    !!pane?.discussion &&
    pane.discussion.accountId === discussion.accountId &&
    (ids.has(pane.discussion.sessionId) || ids.has(pane.discussion.rolloutId));
  if (matches(preferred)) return preferred;
  return expertChatPanes.find(matches) ?? null;
};

// Reprise dans un AUTRE compte = copie avec historique source conserve. Deux cas :
//  - MEME provider Codex : copie FIDELE du rollout HEAD vers le compte cible,
//    puis reprise native sur la nouvelle copie.
//  - INTER-provider (ou impliquant Claude) : export du transcript, injection
//    dans une session NEUVE du provider cible.
//
// Aucune bascule n'archive ni ne supprime automatiquement la source : elle
// reste dans l'Historique jusqu'a ce que l'utilisateur choisisse de la retirer.
// Freebuff garde seulement un flux d'ouverture TUI special ; son identifiant
// natif identique sur deux comptes est distingue par l'identite composite UI.
type DiscussionContinuationOptions = {
  preserveNavigation?: boolean;
  /** Affiche explicitement le panneau cible (necessaire depuis le main-chat). */
  activateTarget?: boolean;
  sourceTerminalKey?: string;
};

const continueDiscussionWith = async (
  discussion: DiscussionSummary,
  targetAccountId: string,
  preferredPane: ExpertChatPane | null = null,
  options: DiscussionContinuationOptions = {},
) => {
  if (discussionBusyId) return;
  if (!settings || !targetAccountId || targetAccountId === discussion.accountId) return;
  const target = accountById(targetAccountId);
  if (!target) return;
  const transferPane = expertPaneForDiscussion(discussion, preferredPane);
  const sourceProvider = discussion.provider ?? accountProvider(accountById(discussion.accountId));
  const targetProvider = accountProvider(target);
  discussionBusyId = discussionIdentityKey(discussion);
  if (transferPane) {
    setExpertChatAccountTransition(transferPane, {
      label: "Continuité automatique",
      detail: "Préparation de la suite de la conversation",
    });
  } else {
    render();
  }
  try {
    if (sourceProvider === "freebuff") {
      if (targetProvider !== "freebuff") {
        throw new Error("une conversation Freebuff doit etre reprise avec un compte Freebuff");
      }
      // Controle avant la copie : si le compte est occupe, aucun doublon de
      // conversation ni terminal d'erreur n'est cree. Le lancement refait ce
      // controle juste avant le spawn pour couvrir le temps de la copie.
      await assertFreebuffAccountAvailable(target);
      const rawFolderPath = options.preserveNavigation
        ? discussionFolderPath(discussion)
        : activateDiscussionFolder(discussion);
      const folderPath = userEnvironmentPath(rawFolderPath);
      if (!folderPath) {
        throw new Error("la discussion n'a pas d'environnement associe");
      }
      discussion.folderPath = folderPath;
      const copied = await invoke<DiscussionSummary>("copy_discussion_to_account", {
        sessionId: discussion.sessionId,
        sourceAccountId: discussion.accountId,
        targetAccountId,
      });
      copied.folderPath = folderPath;
      await launchFreebuffDiscussionTerminal(copied, target, folderPath);
      const sourceTerminal = options.sourceTerminalKey
        ? terminalSessions.find((session) => session.key === options.sourceTerminalKey) ?? null
        : null;
      if (sourceTerminal && sourceTerminal.accountId === discussion.accountId) {
        await closeTerminalSession(sourceTerminal.key);
      }
      releaseTransferredDiscussion(discussion, target, transferPane);
      return;
    }

    const folderPath = userEnvironmentPath(await (
      options.preserveNavigation
        ? preserveDiscussionFolder(discussion)
        : restoreDiscussionFolder(discussion)
    ));
    if (!folderPath) {
      throw new Error("la discussion n'a pas d'environnement associe");
    }
    // Codex -> Freebuff : Freebuff n'expose ni chat structure ni mode non
    // interactif, la reprise se fait donc dans son terminal TUI. Le transcript
    // Codex est importe dans un nouveau chat natif (import_codex_transcript_to_freebuff,
    // la source n'est jamais modifiee par cette commande), puis le terminal du
    // compte cible est lance dessus. La source reste dans l'Historique ; toutes
    // les actions frontend resolvent la ligne par compte ET identifiant.
    if (targetProvider === "freebuff") {
      await assertFreebuffAccountAvailable(target);
      const transcript = await invoke<string>("export_discussion_transcript", {
        accountId: discussion.accountId,
        sessionId: discussion.rolloutId || discussion.sessionId,
      });
      const copied = await invoke<DiscussionSummary>("import_codex_transcript_to_freebuff", {
        sourceAccountId: discussion.accountId,
        sessionId: discussion.rolloutId || discussion.sessionId,
        targetAccountId,
        folderPath,
        transcript,
      });
      copied.folderPath = folderPath;
      await launchFreebuffDiscussionTerminal(copied, target, folderPath);
      releaseTransferredDiscussion(discussion, target, transferPane);
      return;
    }
    if (sourceProvider === "codex" && targetProvider === "codex") {
      const copied = await invoke<DiscussionSummary>("copy_discussion_to_account", {
        sessionId: discussion.rolloutId || discussion.sessionId,
        sourceAccountId: discussion.accountId,
        targetAccountId,
      });
      const resumeId = copied.rolloutId || copied.sessionId;
      if (!isPlausibleSessionId(resumeId)) {
        discussionBusyId = null;
        statusText = "La conversation n’a pas pu être reprise. La version précédente a été conservée.";
        setExpertChatAccountTransition(transferPane, null);
        await refreshDiscussions();
        return;
      }
      copied.folderPath = folderPath;
      const resumed = await resumeDiscussionInChat(
        copied,
        targetAccountId,
        folderPath,
        "continue",
        transferPane,
        {
          preserveNavigation: options.preserveNavigation,
          activateTarget: options.activateTarget,
        },
      );
      if (!resumed) {
        discussionBusyId = null;
        statusText = "La reprise n’a pas démarré. La conversation précédente a été conservée.";
        setExpertChatAccountTransition(transferPane, null);
        await refreshDiscussions();
        return;
      }
      releaseTransferredDiscussion(discussion, target, transferPane);
      return;
    }

    // Inter-provider : export du transcript puis amorce dans une session neuve.
    const transcript = await invoke<string>("export_discussion_transcript", {
      accountId: discussion.accountId,
      sessionId: discussion.rolloutId || discussion.sessionId,
    });
    const resumed = await resumeDiscussionInChat(
      null,
      targetAccountId,
      folderPath,
      transcript,
      transferPane,
      {
        preserveNavigation: options.preserveNavigation,
        activateTarget: options.activateTarget,
      },
    );
    if (!resumed) {
      discussionBusyId = null;
      statusText = "La reprise n’a pas démarré. La conversation précédente a été conservée.";
      setExpertChatAccountTransition(transferPane, null);
      return;
    }
    releaseTransferredDiscussion(discussion, target, transferPane);
  } catch (error) {
    discussionBusyId = null;
    statusText = `Reprise incomplète : ${String(error)}. La conversation précédente a été conservée.`;
    setExpertChatAccountTransition(transferPane, null);
  }
};

// Retrouve la conversation native liee a un terminal Freebuff. Les nouveaux
// terminaux memorisent directement le resumeId ; le repli par compte+dossier
// permet aussi de gerer un terminal deja ouvert avant cette mise a jour.
//
// Un terminal cree depuis le bouton « Nouveau terminal » n'a pas encore de
// resumeId. Si plusieurs historiques partagent le meme environnement, le
// dossier seul est donc ambigu. On utilise alors l'horodatage de demarrage du
// PTY et l'activite recente de la discussion : Freebuff n'autorise qu'un seul
// terminal par compte, donc la session creee par ce PTY est la plus recente dans
// cette fenetre. Sans cette preuve temporelle, on conserve le refus plutot que
// de transferer silencieusement le mauvais historique.
const FREEBUFF_TERMINAL_MATCH_WINDOW_SECONDS = 60;
const FREEBUFF_TERMINAL_RECENT_ACTIVITY_SECONDS = 15 * 60;

const freebuffDiscussionSortNewest = (left: DiscussionSummary, right: DiscussionSummary) =>
  right.lastActivity - left.lastActivity
  || right.startedAt - left.startedAt
  || (freebuffResumeId(right) ?? right.sessionId).localeCompare(
    freebuffResumeId(left) ?? left.sessionId,
  );

const freebuffDiscussionForTerminal = (session: TerminalSession): DiscussionSummary | null => {
  if (accountProvider(accountById(session.accountId)) !== "freebuff") return null;
  const candidates = allDiscussions().filter((discussion) =>
    discussion.accountId === session.accountId &&
    (discussion.provider ?? "freebuff") === "freebuff"
  );
  const knownIds = new Set(
    [session.resumeSessionId, session.codexSessionId].filter(
      (id): id is string => !!id,
    ),
  );
  const exact = candidates.find((discussion) =>
    knownIds.has(discussion.sessionId) ||
    knownIds.has(discussion.rolloutId) ||
    knownIds.has(freebuffResumeId(discussion) ?? "")
  );
  if (exact) return exact;

  const terminalFolder = session.workspacePath ?? session.folderPath ?? session.projectDir;
  const sameFolder = terminalFolder
    ? candidates.filter((discussion) => {
      const folder = discussionFolderPath(discussion);
      return !!folder && normalizeWorkspacePath(folder) === normalizeWorkspacePath(terminalFolder);
    })
    : [];
  const scoped = sameFolder.length > 0 ? sameFolder : candidates;
  const terminalStartedAt = session.startedAtUnix ?? 0;
  if (terminalStartedAt > 0) {
    const startedWithTerminal = scoped
      .filter((discussion) =>
        Math.abs(discussion.startedAt - terminalStartedAt) <= FREEBUFF_TERMINAL_MATCH_WINDOW_SECONDS,
      )
      .sort(freebuffDiscussionSortNewest);
    if (startedWithTerminal.length > 0) return startedWithTerminal[0];
  }

  const recentlyActive = scoped
    .filter((discussion) =>
      discussion.lastActivity >= Math.floor(Date.now() / 1000) - FREEBUFF_TERMINAL_RECENT_ACTIVITY_SECONDS,
    )
    .sort(freebuffDiscussionSortNewest);
  if (recentlyActive.length > 0) return recentlyActive[0];

  if (sameFolder.length === 1) return sameFolder[0];
  if (candidates.length === 1) return candidates[0];
  return null;
};

// La creation du chat Freebuff et son apparition dans l'index ne sont pas
// synchrones avec le lancement du PTY. Quelques lectures espacees evitent de
// conclure a tort a une ambiguite juste apres l'ouverture du terminal.
const findFreebuffDiscussionForTerminal = async (
  session: TerminalSession,
): Promise<DiscussionSummary | null> => {
  for (const delay of [0, 200, 600, 1_200]) {
    if (delay) await sleep(delay);
    await refreshDiscussions();
    const discussion = freebuffDiscussionForTerminal(session);
    if (discussion) return discussion;
  }
  return null;
};

// Applique un nouveau modele Freebuff au terminal : le modele est sauvegarde
// sur le compte, la config `freebuffModel` reecrite, puis le TUI redemarre sur
// la conversation en cours (le CLI Freebuff ne lit le modele qu'au demarrage).
const switchFreebuffTerminalAccount = async (
  session: TerminalSession,
  targetAccountId: string,
): Promise<void> => {
  if (freebuffTerminalAccountSwitches.has(session.key) || targetAccountId === session.accountId) {
    return;
  }
  const target = accountById(targetAccountId);
  if (!target || accountProvider(target) !== "freebuff") return;

  freebuffTerminalAccountSwitches.add(session.key);
  statusText = `Transfert du terminal Freebuff vers ${target.label}…`;
  render();
  try {
    await assertFreebuffAccountAvailable(target);
    const discussion = await findFreebuffDiscussionForTerminal(session);
    if (!discussion) {
      throw new Error("la conversation active n’a pas pu être identifiée sans ambiguïté");
    }
    await continueDiscussionWith(discussion, target.id, null, {
      preserveNavigation: true,
      sourceTerminalKey: session.key,
    });
  } catch (error) {
    statusText = `Transfert du terminal Freebuff impossible : ${String(error)}`;
  } finally {
    freebuffTerminalAccountSwitches.delete(session.key);
    render();
  }
};

const discussionHasRunningTurn = (discussion: DiscussionSummary): boolean =>
  (chatDiscussion?.accountId === discussion.accountId
    && chatDiscussion.sessionId === discussion.sessionId
    && chatTurnIsBusy(chatTurn?.status)) ||
  expertChatPanes.some(
    (pane) =>
      pane.discussion?.accountId === discussion.accountId
      && pane.discussion.sessionId === discussion.sessionId
      && chatTurnIsBusy(pane.turn?.status),
  );

// Applique un nouveau modele Freebuff au terminal : le modele est sauvegarde
// sur le compte, la config `freebuffModel` reecrite, puis le TUI redemarre sur
// la conversation en cours (le CLI Freebuff ne lit le modele qu'au demarrage).
const applyFreebuffTerminalModel = async (
  session: TerminalSession,
  model: string,
): Promise<boolean> => {
  const normalized = model.trim();
  const account = accountById(session.accountId);
  if (!account || accountProvider(account) !== "freebuff") {
    throw new Error("ce terminal n'est pas un terminal Freebuff");
  }
  if (!normalized || normalized === accountModel(account)) return false;
  if (terminalActivityStatus(session) === "running") {
    const confirmed = window.confirm(
      "Le terminal Freebuff est en train de travailler. Redémarrer maintenant pour appliquer le nouveau modèle ?",
    );
    if (!confirmed) return false;
  }
  statusText = `Application du modèle Freebuff ${normalized}…`;
  render();
  try {
    account.model = normalized;
    settings = await invoke<AppSettings>("save_settings", { settings });
    await provisionAccountHome(account);
    const discussion = await findFreebuffDiscussionForTerminal(session);
    const folderPath = userEnvironmentPath(
      discussion ? discussionFolderPath(discussion) : session.folderPath ?? session.workspacePath,
    );
    if (!folderPath) {
      throw new Error("la conversation n'a pas d'environnement associé");
    }
    await closeTerminalSession(session.key);
    if (discussion) {
      discussion.folderPath = folderPath;
      await launchFreebuffDiscussionTerminal(discussion, account, folderPath);
    } else {
      const fresh = await createNewTerminal(
        account.id,
        false,
        null,
        providerAgentId("freebuff"),
        null,
        folderPath,
      );
      if (!fresh || !fresh.running || fresh.ptyId === null) {
        throw new Error("le nouveau terminal Freebuff n'a pas pu être créé");
      }
    }
    statusText = `Modèle Freebuff appliqué : ${normalized}`;
    return true;
  } finally {
    render();
  }
};

// Deplacement persistant utilise par le drag-and-drop de la barre laterale.
// Le backend reecrit le cwd (et relocalise la session Claude si necessaire),
// puis renvoie le resume a jour pour les chats deja ouverts.
const moveDiscussionToWorkspace = async (
  discussion: DiscussionSummary,
  workspace: WorkspaceProfile,
) => {
  if (discussionBusyId) return;
  if (discussionHasRunningTurn(discussion)) {
    statusText = "Arretez la reponse en cours avant de deplacer cette conversation";
    render();
    return;
  }
  if (
    discussionFolderPath(discussion) &&
    normalizeWorkspacePath(discussionFolderPath(discussion)!) === normalizeWorkspacePath(workspace.path)
  ) {
    statusText = `La conversation est deja dans ${workspace.label}`;
    return;
  }

  discussionBusyId = discussionIdentityKey(discussion);
  statusText = `Deplacement vers ${workspace.label}…`;
  render();

  try {
    const moved = await invoke<DiscussionSummary>("move_discussion", {
      accountId: discussion.accountId,
      sessionId: discussion.sessionId,
      workspacePath: workspace.path,
    });
    moved.folderPath = workspace.path;
    Object.assign(discussion, moved);
    if (
      chatDiscussion?.accountId === moved.accountId
      && chatDiscussion.sessionId === moved.sessionId
    ) {
      Object.assign(chatDiscussion, moved);
    }
    expertChatPanes.forEach((pane) => {
      if (
        pane.discussion?.accountId === moved.accountId
        && pane.discussion.sessionId === moved.sessionId
      ) {
        Object.assign(pane.discussion, moved);
        pane.pendingWorkspace = workspace.path;
      }
    });
    discussionBusyId = null;
    statusText = `Conversation deplacee vers ${workspace.label}`;
    await refreshDiscussions();
    render();
  } catch (error) {
    discussionBusyId = null;
    statusText = `Deplacement impossible : ${String(error)}`;
    render();
  }
};

const discussionMatchesAnyId = (
  discussion: DiscussionSummary | null | undefined,
  ids: ReadonlySet<string>,
): boolean => !!discussion && (ids.has(discussion.sessionId) || ids.has(discussion.rolloutId));

const removeArchivedDiscussionFromUi = (accountId: string, ids: ReadonlySet<string>) => {
  ids.forEach((id) => discussionTargetSel.delete(discussionIdentityKey({
    accountId,
    sessionId: id,
  })));
  const matchesArchivedDiscussion = (discussion: DiscussionSummary | null | undefined) =>
    !!discussion
    && discussion.accountId === accountId
    && discussionMatchesAnyId(discussion, ids);
  const closedExpertPanes = expertChatPanes.filter((pane) =>
    matchesArchivedDiscussion(pane.discussion),
  );
  closedExpertPanes.forEach((pane) => {
    stopExpertChatSync(pane);
    stopExpertChatTurnPoll(pane);
    resetExpertModelCapacityRetry(pane);
    explicitlyOpenedBusyChatVisibilityPins.delete(pane.key);
  });
  expertChatPanes = expertChatPanes.filter(
    (pane) => !matchesArchivedDiscussion(pane.discussion),
  );
  if (closedExpertPanes.some((pane) => pane.key === activeExpertChatKey)) {
    activeExpertChatKey = expertChatPanes[0]?.key ?? null;
  }
  reconcileExpertChatPage();
  if (closedExpertPanes.length) persistExpertChats();
  if (matchesArchivedDiscussion(chatDiscussion)) {
    resetMainModelCapacityRetry();
    chatDiscussion = null;
    chatMessages = [];
    chatTurn = null;
    chatQueuedSubmissions = [];
    chatQueueDrainInFlight = false;
    chatError = null;
    chatLoading = false;
    chatTruncated = false;
    chatContextUsage = null;
    chatContextCompacting = false;
  }

  // Retire immediatement la ligne du snapshot deja en memoire. Le rescan
  // disque confirme ensuite l'etat en arriere-plan ; il ne bloque plus la
  // disparition visuelle d'un long historique Freebuff.
  if (discussions) {
    const accounts = discussions.accounts.map((group) => {
      if (group.accountId !== accountId) return group;
      const remaining = group.discussions.filter(
        (discussion) => !discussionMatchesAnyId(discussion, ids),
      );
      return {
        ...group,
        discussionCount: remaining.length,
        discussions: remaining,
      };
    });
    applyDiscussionsSnapshot({
      ...discussions,
      totalDiscussions: accounts.reduce((total, group) => total + group.discussionCount, 0),
      accounts,
    });
  }
};

const archiveDiscussionById = async (
  accountId: string,
  archiveId: string,
  relatedIds: readonly string[] = [],
  permanentDelete = false,
): Promise<number> => {
  const result = await invoke<{ count?: number }>("delete_discussion", {
    accountId,
    sessionId: archiveId,
    archive: !permanentDelete,
  });
  removeArchivedDiscussionFromUi(accountId, new Set([archiveId, ...relatedIds]));
  return result?.count ?? 1;
};

const openDiscussionArchiveModal = (discussion: DiscussionSummary) => {
  if (discussionBusyId) return;
  rememberDialogTrigger("discussion-archive", null);
  discussionArchiveCandidate = discussion;
  discussionEraseArmed = false;
  render();
};

const closeDiscussionArchiveModal = () => {
  if (!discussionArchiveCandidate) return;
  const returnFocus = takeDialogTrigger("discussion-archive");
  discussionArchiveCandidate = null;
  discussionEraseArmed = false;
  render();
  restoreDialogTrigger(returnFocus);
};

const deleteDiscussion = async (permanentDelete = false) => {
  const discussion = discussionArchiveCandidate;
  if (!discussion || discussionBusyId) return;
  forgetDialogTrigger("discussion-archive");
  discussionArchiveCandidate = null;
  discussionEraseArmed = false;
  discussionBusyId = discussionIdentityKey(discussion);
  render();
  try {
    const count = await archiveDiscussionById(
      discussion.accountId,
      discussion.sessionId,
      [discussion.rolloutId],
      permanentDelete,
    );
    statusText = permanentDelete
      ? (count > 1 ? `Discussion supprimee definitivement (${count} fichiers)` : "Discussion supprimee definitivement")
      : (count > 1 ? `Discussion archivee (${count} fichiers)` : "Discussion archivee");
  } catch (error) {
    statusText = String(error);
  }
  discussionBusyId = null;
  syncStatusTextDom();
  // Le snapshot local a deja ete corrige apres le succes. La reconstruction
  // complete de l'index ne fait plus partie du chemin critique utilisateur.
  void refreshDiscussions();
};

const openTerminalDeleteModal = (session: TerminalSession) => {
  rememberDialogTrigger("terminal-delete", null);
  terminalDeleteCandidateKey = session.key;
  render();
};

const closeTerminalDeleteModal = () => {
  if (!terminalDeleteCandidateKey) return;
  const returnFocus = takeDialogTrigger("terminal-delete");
  terminalDeleteCandidateKey = null;
  render();
  restoreDialogTrigger(returnFocus);
};

type TerminalDiscussionDeletionTarget = {
  archiveId: string | null;
  relatedIds: string[];
  discussion: DiscussionSummary | null;
};

// Resout uniquement une association prouvee. Pour un terminal adopte depuis un
// autre appareil, le claim serveur recupere d'abord l'id du rollout avant que le
// PTY soit arrete. On ne supprime jamais une discussion sur le seul critere du
// dossier, qui peut contenir plusieurs chats simultanes.
const terminalDiscussionDeletionTarget = async (
  session: TerminalSession,
): Promise<TerminalDiscussionDeletionTarget> => {
  let terminalSessionId = session.codexSessionId ?? session.resumeSessionId;
  if (!terminalSessionId && session.ptyId !== null && !session.loginOnly) {
    try {
      terminalSessionId = await claimSessionForTerminal(session);
      if (terminalSessionId) {
        session.codexSessionId = terminalSessionId;
        session.sessionCaptureDone = true;
        claimedSessionIds.add(terminalSessionId);
        persistTerminalSessions();
      }
    } catch {
      // La recherche dans l'index ci-dessous peut encore retrouver les
      // providers dont le transcript n'est pas claimable comme un rollout Codex.
    }
  }

  await refreshDiscussions();
  const linkedIds = new Set(
    [terminalSessionId, session.codexSessionId, session.resumeSessionId].filter(
      (id): id is string => !!id,
    ),
  );
  let discussion = allDiscussions().find(
    (candidate) =>
      candidate.accountId === session.accountId
      && (
        linkedIds.has(candidate.sessionId)
        || linkedIds.has(candidate.rolloutId)
        || linkedIds.has(freebuffResumeId(candidate) ?? "")
      ),
  ) ?? null;
  if (!discussion && accountProvider(accountById(session.accountId)) === "freebuff") {
    discussion = await findFreebuffDiscussionForTerminal(session);
  }

  const archiveId = discussion?.sessionId ?? terminalSessionId ?? null;
  return {
    archiveId,
    relatedIds: Array.from(new Set([
      ...linkedIds,
      discussion?.sessionId,
      discussion?.rolloutId,
      discussion ? freebuffResumeId(discussion) : null,
    ].filter((id): id is string => !!id && id !== archiveId))),
    discussion,
  };
};

const deleteTerminalHistoryAndChat = async () => {
  const key = terminalDeleteCandidateKey;
  const session = terminalSessions.find((candidate) => candidate.key === key);
  if (!key || !session) {
    terminalDeleteCandidateKey = null;
    render();
    return;
  }

  forgetDialogTrigger("terminal-delete");
  terminalDeleteCandidateKey = null;
  statusText = "Suppression du terminal et de son historique…";
  render();

  let target: TerminalDiscussionDeletionTarget = {
    archiveId: session.codexSessionId ?? session.resumeSessionId,
    relatedIds: [],
    discussion: null,
  };
  try {
    target = await terminalDiscussionDeletionTarget(session);
    if (target.discussion && discussionHasRunningTurn(target.discussion)) {
      statusText = "Arretez la reponse du chat avant de supprimer son historique";
      render();
      return;
    }
  } catch {
    // Le terminal doit rester supprimable meme si l'index des discussions est
    // momentanement indisponible. Un id deja capture reste exploitable.
  }

  await closeTerminalSession(key);
  if (!target.archiveId) {
    statusText = "Terminal masque et historique local efface · aucun chat associe identifie";
    syncStatusTextDom();
    return;
  }

  try {
    const count = await archiveDiscussionById(
      session.accountId,
      target.archiveId,
      target.relatedIds,
      true,
    );
    statusText = count > 1
      ? `Terminal, chat et historique supprimes definitivement (${count} fichiers)`
      : "Terminal, chat et historique supprimes definitivement";
  } catch (error) {
    statusText = `Terminal masque, mais suppression du chat impossible : ${String(error)}`;
  }
  syncStatusTextDom();
  void refreshDiscussions();
};

// Compte cible retenu pour une discussion (defaut = compte d'origine, borne
// aux comptes existants pour rester valide meme si la liste a change).
const discussionTargetFor = (discussion: DiscussionSummary): string => {
  const stored = discussionTargetSel.get(discussionIdentityKey(discussion));
  if (stored && continuationAccountsForDiscussion(discussion).some((account) => account.id === stored)) {
    return stored;
  }
  return discussion.accountId;
};

// Le backend conserve le premier message complet dans `preview` pour que la
// recherche porte sur davantage que le titre. Pour l'affichage, on retire le
// titre (qui est un prefixe exact de ce message) afin de ne pas presenter deux
// fois le meme texte dans la carte.
const discussionSubtitle = (discussion: DiscussionSummary): string => {
  const preview = discussion.preview?.trim() ?? "";
  const title = discussion.title?.trim() ?? "";
  if (!preview || !title || !preview.startsWith(title)) return preview;
  return preview
    .slice(title.length)
    .replace(/^[\s:;,.!?\u2014\u2013-]+/, "")
    .trim();
};

// --- Vue conversation interactive -------------------------------------------
// Le provider tourne en arriere-plan, sans TUI visible. Son JSONL reste la
// source de verite : desktop, web et Android voient donc le meme fil.

const chatSelectedAccount = (): AccountProfile | null => {
  const preferred = chatDiscussion?.accountId ?? chatAccountId ?? settings?.defaultAccountId;
  // Un compte freebuff ne peut pas porter un chat : s'il etait retenu
  // (compte par defaut, ou premier de la liste), le panneau echouerait au
  // premier envoi. On retombe sur le premier compte reellement utilisable.
  const chosen = accountById(preferred);
  if (chosen && accountSupportsChat(chosen)) return chosen;
  return chatCapableAccounts()[0] ?? null;
};

const quotaAlternativeForAccount = (
  currentAccountId: string,
  discussion: DiscussionSummary,
): ChatQuotaSuggestion | null => {
  if (!settings) return null;
  const current = accountById(currentAccountId);
  if (!current) return null;
  const provider = accountProvider(current);
  const eligibleAccountIds = settings.accounts
    .filter(
      (account) => account.id !== current.id && accountProvider(account) === provider,
    )
    .map((account) => account.id);
  const best = bestQuotaAccount(limitStatus, current.id, eligibleAccountIds);
  if (!best) return null;

  return {
    accountId: best.account.id,
    accountLabel: best.account.label,
    remainingPercent: best.remainingPercent,
    busy: discussionIsBusy(discussion),
  };
};

const quotaSuggestionFor = (
  turn: ChatTurnSnapshot | null,
  discussion: DiscussionSummary | null,
): ChatQuotaSuggestion | null => {
  if (
    !turn ||
    turn.status !== "failed" ||
    !isQuotaExhaustionError(turn.error) ||
    !discussion ||
    !settings
  ) {
    return null;
  }
  return quotaAlternativeForAccount(turn.accountId, discussion);
};

const remainingFromUsedPercent = (value?: number | null): number | null =>
  typeof value === "number" && Number.isFinite(value)
    ? Math.max(0, Math.min(100, 100 - value))
    : null;

const chatQuotaResetAt = (quota: AccountLimitView): number | null => {
  const candidates: Array<{ remaining: number; resetAt: number }> = [];
  const add = (usedPercent?: number | null, resetAt?: number | null, exhausted = false) => {
    if (typeof resetAt !== "number" || !Number.isFinite(resetAt)) return;
    const remaining = exhausted ? 0 : remainingFromUsedPercent(usedPercent);
    if (remaining !== null) candidates.push({ remaining, resetAt });
  };

  add(quota.sessionUsedPercent, quota.sessionResetAt);
  add(quota.weeklyUsedPercent, quota.weeklyResetAt);
  quota.buckets.forEach((bucket) => {
    add(bucket.usedPercent, bucket.resetsAt, !!bucket.rateLimitReachedType?.trim());
  });
  candidates.sort((left, right) => left.remaining - right.remaining || left.resetAt - right.resetAt);
  return candidates[0]?.resetAt ?? null;
};

const chatQuotaStatusFor = (account: AccountProfile | null): ChatQuotaStatus => {
  if (!account) {
    return {
      state: "unavailable",
      remainingPercent: null,
      resetAt: null,
      detail: "Aucun compte n'est associé à ce chat.",
    };
  }
  if (!limitStatusLoaded) {
    return {
      state: "loading",
      remainingPercent: null,
      resetAt: null,
      detail: `Lecture des limites de ${account.label}.`,
    };
  }

  const quota = limitStatus.find((candidate) => candidate.id === account.id);
  if (!quota) {
    return {
      state: "unavailable",
      remainingPercent: null,
      resetAt: null,
      detail: `Aucune limite disponible pour ${account.label}.`,
    };
  }
  if (!quota.hasTokens) {
    return {
      state: "disconnected",
      remainingPercent: null,
      resetAt: null,
      detail: `${account.label} doit être connecté avant de pouvoir lire son quota.`,
    };
  }

  if (
    quota.refreshing &&
    quota.sessionUsedPercent == null &&
    quota.weeklyUsedPercent == null &&
    quota.buckets.length === 0
  ) {
    return {
      state: "loading",
      remainingPercent: null,
      resetAt: null,
      detail: `Actualisation des limites de ${account.label} en arrière-plan.`,
    };
  }

  const remainingPercent = remainingQuotaPercent(quota);
  const resetAt = chatQuotaResetAt(quota);
  const windows = [
    remainingFromUsedPercent(quota.sessionUsedPercent) === null
      ? ""
      : `5 h : ${Math.round(remainingFromUsedPercent(quota.sessionUsedPercent) ?? 0)} % restant`,
    remainingFromUsedPercent(quota.weeklyUsedPercent) === null
      ? ""
      : `semaine : ${Math.round(remainingFromUsedPercent(quota.weeklyUsedPercent) ?? 0)} % restant`,
  ].filter(Boolean);
  const detail = windows.join(" · ") || quota.error || `Limite fournie par ${quota.source}.`;

  if (remainingPercent === null) {
    return {
      state: quota.error ? "error" : "unavailable",
      remainingPercent: null,
      resetAt,
      detail,
    };
  }
  return {
    state: remainingPercent <= 0 ? "exhausted" : remainingPercent <= 15 ? "low" : "available",
    remainingPercent,
    resetAt,
    detail,
  };
};

let quotaAlternativeRefresh: Promise<void> | null = null;
const refreshQuotaAlternatives = (): Promise<void> => {
  if (quotaAlternativeRefresh) return quotaAlternativeRefresh;
  const pending = refreshLimitStatus(true, true).finally(() => {
    if (quotaAlternativeRefresh === pending) quotaAlternativeRefresh = null;
    if (activeView !== "chat") return;
    if (isQuotaExhaustionError(chatTurn?.error)) refreshChatFeed();
    expertChatPanes
      .filter((pane) => isQuotaExhaustionError(pane.turn?.error))
      .forEach((pane) => refreshExpertChatPane(pane));
  });
  quotaAlternativeRefresh = pending;
  return pending;
};

const automaticQuotaTransferAttempts = new Set<string>();
let automaticQuotaTransferQueue: Promise<void> = Promise.resolve();
const QUOTA_DURING_COMMAND_ERROR = "Quota epuise detecte pendant une commande en cours";

const failedTurnHasExhaustedQuota = (turn: ChatTurnSnapshot | null | undefined): boolean =>
  turn?.status === "failed" && isQuotaExhaustionError(turn.error);

const quotaTurnNeedsAutomaticTransfer = (
  turn: ChatTurnSnapshot | null | undefined,
): boolean =>
  failedTurnHasExhaustedQuota(turn) || shouldRecoverRunningQuotaTurn(turn, limitStatus);

const sameQuotaTransferTurn = (
  current: ChatTurnSnapshot | null | undefined,
  expected: ChatTurnSnapshot,
): current is ChatTurnSnapshot =>
  !!current &&
  current.id === expected.id &&
  current.accountId === expected.accountId &&
  current.startedAt === expected.startedAt;

const automaticallyTransferQuotaExhaustedDiscussion = (
  discussion: DiscussionSummary,
  turn: ChatTurnSnapshot,
  pane: ExpertChatPane | null = null,
) => {
  if (!quotaTurnNeedsAutomaticTransfer(turn)) return;
  const attemptKey = JSON.stringify([
    pane?.key ?? "main-chat",
    discussion.accountId,
    discussion.sessionId,
    turn.id,
    turn.startedAt,
  ]);
  if (automaticQuotaTransferAttempts.has(attemptKey)) return;
  automaticQuotaTransferAttempts.add(attemptKey);

  automaticQuotaTransferQueue = automaticQuotaTransferQueue
    .catch(() => undefined)
    .then(async () => {
      await refreshQuotaAlternatives();

      const currentDiscussion = pane ? pane.discussion : chatDiscussion;
      const currentTurn = pane ? pane.turn : chatTurn;
      const sourceStillOpen = pane ? expertChatPanes.includes(pane) : !!chatDiscussion;
      if (
        !sourceStillOpen ||
        !currentDiscussion ||
        currentDiscussion.accountId !== discussion.accountId ||
        currentDiscussion.sessionId !== discussion.sessionId ||
        !sameQuotaTransferTurn(currentTurn, turn) ||
        currentDiscussion.accountId !== currentTurn.accountId ||
        !quotaTurnNeedsAutomaticTransfer(currentTurn)
      ) {
        return;
      }

      const suggestion = failedTurnHasExhaustedQuota(currentTurn)
        ? quotaSuggestionFor(currentTurn, currentDiscussion)
        : quotaAlternativeForAccount(currentTurn.accountId, currentDiscussion);
      if (!suggestion) {
        statusText = "Aucune capacité compatible n’est disponible pour poursuivre la conversation pour le moment";
        if (activeView === "chat") {
          if (pane) refreshExpertChatPane(pane);
          else render();
        }
        return;
      }

      if (shouldRecoverRunningQuotaTurn(currentTurn, limitStatus)) {
        statusText = "Continuité automatique · préparation de la reprise…";
        if (activeView === "chat") {
          if (pane) refreshExpertChatPane(pane);
          else render();
        }

        const stopped = await invoke<ChatTurnSnapshot>("stop_chat_turn", {
          id: currentTurn.id,
        });
        const latestTurn = pane ? pane.turn : chatTurn;
        if (!sameQuotaTransferTurn(latestTurn, turn)) return;

        const stoppedWithQuotaFailure = failedTurnHasExhaustedQuota(stopped);
        if (stopped.status !== "cancelled" && !stoppedWithQuotaFailure) {
          if (pane) await applyExpertChatTurnSnapshot(pane, stopped);
          else await applyChatTurnSnapshot(stopped);
          return;
        }

        const failedTurn = stoppedWithQuotaFailure
          ? stopped
          : {
              ...stopped,
              status: "failed" as const,
              finishedAt: stopped.finishedAt ?? Math.floor(Date.now() / 1000),
              error: QUOTA_DURING_COMMAND_ERROR,
            };
        if (pane) {
          pane.messages = markLatestPendingMessageFailed(pane.messages);
          pane.turn = failedTurn;
          explicitlyOpenedBusyChatVisibilityPins.delete(pane.key);
          stopExpertChatTurnPoll(pane);
          if (activeView === "chat") refreshExpertChatPane(pane);
        } else {
          chatMessages = markLatestPendingMessageFailed(chatMessages);
          chatTurn = failedTurn;
          stopChatTurnPoll();
          if (activeView === "chat") render();
        }
      }

      const transferDiscussion = pane ? pane.discussion : chatDiscussion;
      const transferTurn = pane ? pane.turn : chatTurn;
      if (
        !transferDiscussion ||
        transferDiscussion.accountId !== discussion.accountId ||
        transferDiscussion.sessionId !== discussion.sessionId ||
        !sameQuotaTransferTurn(transferTurn, turn) ||
        !failedTurnHasExhaustedQuota(transferTurn)
      ) {
        return;
      }

      statusText = "Continuité automatique en cours…";
      await continueDiscussionWith(currentDiscussion, suggestion.accountId, pane, {
        preserveNavigation: true,
        // Le main-chat n'a aucun panneau a reutiliser : sans activation, la
        // continuation demarrerait dans une tuile cachee tandis que l'ancien
        // compte resterait affiche.
        activateTarget: pane === null,
      });
    })
    .catch((error) => {
      statusText = `Reprise automatique impossible : ${String(error)}`;
      if (activeView === "chat") render();
    })
    .finally(() => {
      automaticQuotaTransferAttempts.delete(attemptKey);
    });
};

// Le provider peut rester vivant dans un outil local sans emettre d'erreur de
// quota. Le polling des limites sert alors de watchdog : il traite les chats
// standards et tous les panneaux experts, y compris ceux hors de la page
// visible de la grille.
const recoverQuotaExhaustedChatTurns = () => {
  if (chatDiscussion && chatTurn && quotaTurnNeedsAutomaticTransfer(chatTurn)) {
    automaticallyTransferQuotaExhaustedDiscussion(chatDiscussion, chatTurn);
  }
  expertChatPanes.forEach((pane) => {
    if (
      !pane.orchestrationId
      && pane.discussion
      && pane.turn
      && quotaTurnNeedsAutomaticTransfer(pane.turn)
    ) {
      automaticallyTransferQuotaExhaustedDiscussion(pane.discussion, pane.turn, pane);
    }
  });
};

const sameModelCapacityRetryTurn = (
  current: ChatTurnSnapshot | null | undefined,
  expected: ChatTurnSnapshot,
): current is ChatTurnSnapshot =>
  !!current &&
  current.id === expected.id &&
  current.accountId === expected.accountId &&
  current.sessionId === expected.sessionId &&
  current.startedAt === expected.startedAt &&
  current.status === "failed" &&
  (isModelCapacityError(current.error) || isTransientStreamError(current.error));

// Un drop transitoire ne se rejoue automatiquement que si le tour ne peut pas
// avoir laisse un effet de bord : modes lecture seule (plan/question), ou aucune
// session encore etablie pour ce tour. Cote Claude, un tool_use / edit ne cree
// NI part NI activity visibles cote UI, donc `turn.parts` n'est pas un signal
// fiable de « sortie produite ». En revanche le session_id n'est emis qu'a
// l'init (avant tout outil), donc son absence prouve que rien n'a pu s'executer.
// Un tour Construire deja engage (session_id present) n'est donc jamais rejoue
// automatiquement : l'utilisateur renvoie « continue » lui-meme, ce qui evite de
// rejouer un edit ou un envoi (email / agenda) deja effectue.
const transientRetryIsSafe = (turn: ChatTurnSnapshot, mode: ChatMode): boolean =>
  mode === "plan" || mode === "ask" || !turn.sessionId?.trim();

// Type d'erreur rejouable pour ce tour, ou null. La saturation modele se rejoue
// toujours ; un drop transitoire seulement s'il est sur (voir ci-dessus).
const retryableTurnErrorKind = (
  turn: ChatTurnSnapshot,
  mode: ChatMode,
): "capacity" | "transient" | null => {
  if (isModelCapacityError(turn.error)) return "capacity";
  if (isTransientStreamError(turn.error) && transientRetryIsSafe(turn, mode)) {
    return "transient";
  }
  return null;
};

const retryLimitForKind = (kind: "capacity" | "transient"): number =>
  kind === "capacity" ? MODEL_CAPACITY_RETRY_LIMIT : TRANSIENT_STREAM_RETRY_LIMIT;

// Un tour echoue est-il rejouable automatiquement (saturation ou drop transitoire
// sur) ? Necessite la soumission active pour connaitre le mode. Utilise par tous
// les points de decision « planifier une reprise vs vider la file ».
const failedTurnIsRetryable = (
  turn: ChatTurnSnapshot | null | undefined,
  activeSubmission: QueuedChatSubmission | null,
): boolean =>
  turn?.status === "failed" &&
  !!activeSubmission &&
  retryableTurnErrorKind(turn, activeSubmission.mode) !== null;

const modelCapacityResumeSessionId = (
  turn: ChatTurnSnapshot,
  discussion: DiscussionSummary | null,
): string | null =>
  turn.sessionId?.trim() || discussion?.rolloutId || discussion?.sessionId || null;

const resetMainModelCapacityRetry = (clearActiveSubmission = true) => {
  if (chatCapacityRetryTimer !== null) {
    window.clearTimeout(chatCapacityRetryTimer);
    chatCapacityRetryTimer = null;
  }
  chatCapacityRetryAttempt = 0;
  if (clearActiveSubmission) chatActiveSubmission = null;
};

const resetExpertModelCapacityRetry = (
  pane: ExpertChatPane,
  clearActiveSubmission = true,
) => {
  if (pane.capacityRetryTimer !== null) {
    window.clearTimeout(pane.capacityRetryTimer);
    pane.capacityRetryTimer = null;
  }
  pane.capacityRetryAttempt = 0;
  if (clearActiveSubmission) pane.activeSubmission = null;
};

const modelCapacityTurnError = (
  turn: ChatTurnSnapshot | null | undefined,
  activeSubmission: QueuedChatSubmission | null,
  retryAttempt: number,
  retryScheduled: boolean,
): string | null => {
  if (turn?.status !== "failed") return null;
  const fallback = turn.error ?? "La reponse a echoue";
  if (!activeSubmission) return fallback;
  const kind = retryableTurnErrorKind(turn, activeSubmission.mode);
  if (!kind) return fallback;
  const limit = retryLimitForKind(kind);
  if (retryScheduled) {
    return kind === "capacity"
      ? `Le modele ${activeSubmission.model} est temporairement sature. Nouvelle tentative automatique avec le meme modele (${retryAttempt}/${limit}).`
      : `Connexion coupee en cours de reponse. Nouvelle tentative automatique (${retryAttempt}/${limit}).`;
  }
  if (retryAttempt >= limit) {
    return kind === "capacity"
      ? `Le modele ${activeSubmission.model} reste sature apres ${limit} tentatives automatiques. Vous pouvez renvoyer « continue » plus tard.`
      : `La connexion a ete coupee malgre ${limit} tentatives automatiques. Renvoyez le message pour reessayer.`;
  }
  return fallback;
};

const scheduleMainModelCapacityRetry = (turn: ChatTurnSnapshot): boolean => {
  if (turn.status !== "failed") return false;
  const activeSubmission = chatActiveSubmission;
  if (!activeSubmission) return false;
  const kind = retryableTurnErrorKind(turn, activeSubmission.mode);
  if (!kind) return false;
  if (chatCapacityRetryTimer !== null) return true;
  const limit = retryLimitForKind(kind);
  if (chatCapacityRetryAttempt >= limit) {
    statusText = kind === "capacity"
      ? `Le modele ${activeSubmission.model} reste sature apres ${limit} tentatives automatiques`
      : `Connexion coupee malgre ${limit} tentatives automatiques`;
    return false;
  }

  chatCapacityRetryAttempt += 1;
  const attempt = chatCapacityRetryAttempt;
  const delay = modelCapacityRetryDelayMs(attempt);
  statusText = kind === "capacity"
    ? `Modele ${activeSubmission.model} sature · nouvelle tentative dans ${Math.ceil(delay / 1_000)} s (${attempt}/${limit})`
    : `Connexion coupee · nouvelle tentative dans ${Math.ceil(delay / 1_000)} s (${attempt}/${limit})`;
  chatCapacityRetryTimer = window.setTimeout(() => {
    chatCapacityRetryTimer = null;
    if (!sameModelCapacityRetryTurn(chatTurn, turn)) return;
    const resumeSessionId = modelCapacityResumeSessionId(turn, chatDiscussion);
    statusText = `Reprise automatique avec ${activeSubmission.model} (${attempt}/${limit})`;
    void sendChatMessage("message", {
      ...activeSubmission,
      prompt: modelCapacityRetryPrompt(resumeSessionId, activeSubmission.prompt),
      model: activeSubmission.model,
      reasoningEffort: activeSubmission.reasoningEffort,
      automaticCapacityRetry: true,
      resumeSessionId,
    });
  }, delay);
  return true;
};

const scheduleExpertModelCapacityRetry = (
  pane: ExpertChatPane,
  turn: ChatTurnSnapshot,
): boolean => {
  if (turn.status !== "failed") return false;
  const activeSubmission = pane.activeSubmission;
  if (!activeSubmission || !expertChatPanes.includes(pane)) return false;
  const kind = retryableTurnErrorKind(turn, activeSubmission.mode);
  if (!kind) return false;
  if (pane.capacityRetryTimer !== null) return true;
  const limit = retryLimitForKind(kind);
  if (pane.capacityRetryAttempt >= limit) {
    statusText = kind === "capacity"
      ? `Le modele ${activeSubmission.model} reste sature apres ${limit} tentatives automatiques`
      : `Connexion coupee malgre ${limit} tentatives automatiques`;
    return false;
  }

  pane.capacityRetryAttempt += 1;
  const attempt = pane.capacityRetryAttempt;
  const delay = modelCapacityRetryDelayMs(attempt);
  statusText = kind === "capacity"
    ? `Modele ${activeSubmission.model} sature · nouvelle tentative dans ${Math.ceil(delay / 1_000)} s (${attempt}/${limit})`
    : `Connexion coupee · nouvelle tentative dans ${Math.ceil(delay / 1_000)} s (${attempt}/${limit})`;
  pane.capacityRetryTimer = window.setTimeout(() => {
    pane.capacityRetryTimer = null;
    if (
      !expertChatPanes.includes(pane) ||
      !sameModelCapacityRetryTurn(pane.turn, turn)
    ) {
      return;
    }
    const resumeSessionId = modelCapacityResumeSessionId(turn, pane.discussion);
    statusText = `Reprise automatique avec ${activeSubmission.model} (${attempt}/${limit})`;
    void sendExpertChatMessage(
      pane,
      expertChatPaneRoot(pane),
      undefined,
      "message",
      {
        ...activeSubmission,
        prompt: modelCapacityRetryPrompt(resumeSessionId, activeSubmission.prompt),
        model: activeSubmission.model,
        reasoningEffort: activeSubmission.reasoningEffort,
        automaticCapacityRetry: true,
        resumeSessionId,
      },
    );
  }, delay);
  return true;
};

const readChatPreferences = (account: AccountProfile, root: ParentNode = document) => {
  const previousModel = accountModel(account);
  const previousReasoningEffort = accountReasoningEffort(account);
  const previousFastMode = account.fastMode === true;
  const requestedModel =
    root.querySelector<HTMLInputElement>("[data-chat-control='model'], #chatModel")?.value.trim() || previousModel;
  const requestedReasoningEffort =
    root.querySelector<HTMLSelectElement>("[data-chat-control='reasoning-effort'], #chatReasoningEffort")?.value ??
      previousReasoningEffort;

  if (requestedModel.length > 160 || /\s/.test(requestedModel)) {
    return {
      model: requestedModel,
      reasoningEffort: null,
      changed: false,
      error: "Le nom du modele doit faire 160 caracteres maximum et ne contenir aucun espace",
    };
  }

  const selection = validatedAccountModelSelection(
    account,
    requestedModel,
    requestedReasoningEffort,
  );
  if (selection.error) {
    return {
      model: requestedModel,
      reasoningEffort: null,
      changed: false,
      error: selection.error,
    };
  }
  const { model, reasoningEffort } = selection;

  account.model = model;
  if (accountIsOpenRouter(account)) account.reasoningEffort = reasoningEffort;
  else if (reasoningEffort) account.reasoningEffort = reasoningEffort;
  if (!accountSupportsFastMode(account, model)) account.fastMode = false;

  return {
    model,
    reasoningEffort,
    changed:
      model !== previousModel ||
      ((accountSupportsReasoningEffort(account, model) || accountIsOpenRouter(account))
        && reasoningEffort !== previousReasoningEffort) ||
      (account.fastMode === true) !== previousFastMode,
    error: null,
  };
};

// Les controles du chat deviennent aussi les valeurs par defaut du compte.
// Les sauvegardes sont serialisees pour qu'un changement rapide de
// modele puis d'intensite ne puisse pas s'ecraser dans settings.json.
const persistChatPreferences = (accountId: string): Promise<boolean> => {
  const save = chatPreferencesSave.then(async () => {
    if (!settings) throw new Error("Réglages indisponibles");
    await invoke<AppSettings>("save_settings", { settings });
    const account = accountById(accountId);
    if (account) await provisionAccountHome(account);
  });
  // Un echec est rendu visible, mais la file elle-meme reste resolue afin de
  // ne pas bloquer les sauvegardes suivantes.
  chatPreferencesSave = save.catch(() => undefined);
  return save
    .then(() => true)
    .catch((error) => {
      statusText = `Préférences du chat non enregistrées : ${String(error)}`;
      render();
      return false;
    });
};

const toggleChatFastMode = (account: AccountProfile): boolean => {
  const model = accountModel(account);
  if (!accountSupportsFastMode(account, model)) {
    statusText = fastModeAvailabilityLabel(accountProvider(account), model, false);
    return false;
  }
  account.fastMode = !accountFastModeEnabled(account);
  persistChatPreferences(account.id);
  statusText = account.fastMode
    ? "Fast mode activé · consommation accrue"
    : "Mode normal activé";
  return true;
};

const chatPanelModel = (): ChatPanelModel => {
  const discussion = chatDiscussion;
  const account = chatSelectedAccount();
  const provider = accountProvider(account);
  const selectedModel = accountModel(account);
  const catalog = account ? chatModelCatalogs.get(account.id) : undefined;
  const workspace =
    discussionFolderPath(discussion) ?? pendingChatWorkspace ?? currentWorkspace() ?? account?.projectDir ?? null;
  const metaParts = discussion
    ? [
        discussion.accountLabel,
        workspace ? displayProjectDir(workspace) : "",
        `${chatMessages.length || discussion.messageCount} message(s)`,
      ].filter(Boolean)
    : [account?.label ?? "Choisissez un compte", workspace ? displayProjectDir(workspace) : "Environnement a choisir"];
  return {
    title: discussion?.title?.trim() || "Nouvelle conversation",
    subtitle: metaParts.join(" \u00b7 "),
    totalTokens: discussion ? discussion.totalTokens : 0,
    contextUsage: chatContextUsage,
    contextCompacting: chatContextCompacting,
    supportsCompact: provider === "codex",
    hasCompactableSession: isPlausibleSessionId(
      discussion?.rolloutId || chatTurn?.sessionId || discussion?.sessionId,
    ),
    accountLabel: account?.label ?? discussion?.accountLabel ?? "Aucun compte",
    providerLabel: accountProviderLabel(account),
    nodeLabel: chatTurn?.nodeLabel ?? discussion?.nodeLabel ?? null,
    loading: chatLoading,
    error: chatError,
    truncated: chatTruncated,
    syncState: discussion ? chatSyncState : "closed",
    messages: chatMessages,
    visibleTurnLimit: chatVisibleTurnLimit,
    activities: chatTurn?.activities ?? [],
    thoughts: chatTurn?.thoughts ?? [],
    parts: chatTurn?.parts ?? [],
    turnStatus: chatTurn?.status ?? "idle",
    turnStartedAt: chatTurn?.startedAt ?? null,
    turnFinishedAt: chatTurn?.finishedAt ?? null,
    turnError: modelCapacityTurnError(
      chatTurn,
      chatActiveSubmission,
      chatCapacityRetryAttempt,
      chatCapacityRetryTimer !== null,
    ),
    waitingForUser: conversationWaitsForUser(chatMessages, chatTurn?.parts ?? []),
    turnStatusDisplayMode: chatTurnStatusDisplayMode,
    quotaStatus: chatQuotaStatusFor(account),
    quotaSuggestion: quotaSuggestionFor(chatTurn, discussion),
    accounts: (settings?.accounts ?? []).map((candidate) => ({
      id: candidate.id,
      label: candidate.label,
      providerLabel: accountProviderLabel(candidate),
      model: accountModel(candidate),
    })),
    selectedAccountId: account?.id ?? "",
    selectedModel,
    modelSuggestions: modelSuggestionsForAccount(account, catalog),
    selectedReasoningEffort: reasoningEffortForChatModel(
      account,
      selectedModel,
      accountReasoningEffort(account),
    ) ?? "",
    reasoningEffortOptions: chatReasoningEffortOptions(account, selectedModel),
    supportsReasoningEffort: accountSupportsReasoningEffort(account, selectedModel),
    reasoningEffortAutomatic: accountIsOpenRouter(account),
    fastModeEnabled: accountFastModeEnabled(account),
    supportsFastMode: accountSupportsFastMode(account, selectedModel),
    fastModeHelp: fastModeAvailabilityLabel(
      provider,
      selectedModel,
      accountSupportsFastMode(account, selectedModel),
    ),
    composerSelectorsEnabled: chatComposerSelectorsEnabled,
    favoritePrompts: loadFavoritePromptShortcuts(accountScopedStorage),
    supportsGoals: providerSupportsGoals(provider),
    agentTools: chatAgentToolDefinitions(),
    enabledTools: chatEnabledTools,
    mode: chatMode,
    draft: chatDraft,
    imageAttachments: chatImageAttachments,
    queuedCount: chatQueuedSubmissions.length,
    newConversation: !discussion,
    workspaceLabel: workspace ? displayProjectDir(workspace) : "Environnement",
    historyOpen: chatHistoryOpen,
  };
};

const patchChatRuntimeStatus = (root: ParentNode, model: ChatPanelModel): boolean => {
  const current = root.querySelector<HTMLElement>("[data-chat-control='runtime']");
  const turnStatus = root.querySelector<HTMLElement>("[data-chat-control='turn-status']");
  const tokenUsage = root.querySelector<HTMLElement>("[data-chat-control='tokens']");
  if (!current && !turnStatus && !tokenUsage) return false;
  const signature = chatRuntimeRenderSignature(model);
  if (chatRuntimeSignatures.get(root) === signature) return false;
  if (current) current.outerHTML = renderChatRuntimeStatus(model);
  if (turnStatus) turnStatus.outerHTML = renderChatTurnStatus(model);
  if (tokenUsage) {
    tokenUsage.outerHTML = renderChatTokenUsage(
      model,
      chatTurnIsBusy(model.turnStatus) || model.contextCompacting,
    );
  }
  chatRuntimeSignatures.set(root, signature);
  return true;
};

const refreshAllChatRuntimeStatus = () => {
  if (activeView !== "chat") return;
  const mainPanel = document.querySelector<HTMLElement>("#chatPanel");
  if (mainPanel && patchChatRuntimeStatus(mainPanel, chatPanelModel())) renderIcons(mainPanel);
  expertChatPanes.forEach((pane) => {
    const root = expertChatPaneRoot(pane);
    if (root && patchChatRuntimeStatus(root, expertChatPanelModel(pane))) renderIcons(root);
  });
  refreshChatRuntimeClocks();
};

const refreshChatRuntimeClocks = () => {
  const now = Date.now() / 1000;
  document.querySelectorAll<HTMLElement>("[data-chat-elapsed]").forEach((element) => {
    const startedAt = Number(element.dataset.chatStartedAt);
    const finishedAt = Number(element.dataset.chatFinishedAt || 0);
    if (!Number.isFinite(startedAt) || startedAt <= 0) return;
    const value = element.querySelector<HTMLElement>("[data-chat-elapsed-value]");
    if (value) {
      value.textContent = formatChatDuration(Math.max(0, (finishedAt || now) - startedAt));
    }
  });
  document.querySelectorAll<HTMLElement>("[data-chat-reset]").forEach((element) => {
    const resetAt = Number(element.dataset.chatResetAt);
    if (Number.isFinite(resetAt) && resetAt > 0) {
      element.textContent = formatChatResetCountdown(resetAt, now);
    }
  });
  refreshAutonomousScheduleLabels();
};

const startChatRuntimeClock = () => {
  if (chatRuntimeClock !== null) return;
  refreshChatRuntimeClocks();
  chatRuntimeClock = window.setInterval(
    () => runWhenPageVisible(refreshChatRuntimeClocks),
    1000,
  );
};

const stopChatRuntimeClock = () => {
  if (chatRuntimeClock !== null) {
    clearInterval(chatRuntimeClock);
    chatRuntimeClock = null;
  }
};

const refreshChatSyncIndicator = () => {
  const indicator = document.querySelector<HTMLSpanElement>("#chatSync");
  if (!indicator) return;
  indicator.className = `chat-sync chat-sync--${chatSyncState}`;
  const label = indicator.querySelector<HTMLElement>("[data-chat-sync-label]");
  if (label) label.textContent = chatSyncLabel(chatSyncState);
};

const rememberChatFeedScroll = (
  feed: HTMLElement,
  state: ChatScrollState,
  userIntent: ChatScrollUserIntent = "none",
) => updateChatScrollState(state, feed, userIntent);

const captureChatFeedScroll = () => {
  if (skipNextChatScrollCapture) {
    skipNextChatScrollCapture = false;
    return;
  }
  const feed = document.querySelector<HTMLDivElement>("#chatFeed");
  if (feed) rememberChatFeedScroll(feed, chatScrollState);
};

// Les tours hors ecran portent `content-visibility: auto` : le navigateur ne
// les met en page qu'a l'approche du viewport. Une reconstruction du fil recree
// tous les elements et perd leur taille memorisee, donc `scrollHeight` ne vaut
// plus qu'une fraction de la hauteur reelle. La position restauree est alors
// ecretee et le fil remonte tout en haut. Cette classe rend la hauteur reelle
// mesurable, et la mise en page qu'elle declenche amorce au passage la taille
// memorisee de chaque tour.
const CHAT_FEED_MEASURING_CLASS = "is-measuring-scroll";

type ChatScrollRestorePass = { frame: number; settle: ChatScrollSettleState };

const chatScrollRestorePasses = new WeakMap<HTMLElement, ChatScrollRestorePass>();
// Position appliquee par le code : l'evenement `scroll` qu'elle declenche ne
// doit pas etre pris pour un geste utilisateur.
const chatProgrammaticScrollTops = new WeakMap<HTMLElement, number>();

const cancelChatFeedScrollRestore = (feed: HTMLElement) => {
  const pending = chatScrollRestorePasses.get(feed);
  if (!pending) return;
  window.cancelAnimationFrame(pending.frame);
  chatScrollRestorePasses.delete(feed);
};

const applyChatFeedScrollTop = (feed: HTMLElement, state: ChatScrollState) => {
  const target = restoreChatScrollTop(state, feed);
  if (Math.abs(feed.scrollTop - target) > 0.5) {
    chatProgrammaticScrollTops.set(feed, target);
    feed.scrollTop = target;
  }
  if (state.followLatest) state.scrollTop = feed.scrollTop;
};

const restoreChatFeedScroll = (
  feed: HTMLElement | null,
  state: ChatScrollState = chatScrollState,
  rebuilt = false,
) => {
  if (!feed) return;
  cancelChatFeedScrollRestore(feed);

  if (rebuilt) {
    // La lecture de `scrollHeight` force la mise en page tant que la classe est
    // posee ; elle est retiree avant la peinture, donc rien ne clignote.
    feed.classList.add(CHAT_FEED_MEASURING_CLASS);
    applyChatFeedScrollTop(feed, state);
    feed.classList.remove(CHAT_FEED_MEASURING_CLASS);
  } else {
    applyChatFeedScrollTop(feed, state);
  }

  // Le premier calcul peut preceder la mise en page finale (police, icones,
  // images, changement de hauteur du composer). On reapplique la position tant
  // que la hauteur bouge, y compris quand le suivi est en pause : sinon une
  // remontee de lecture atterrit sur une hauteur intermediaire et y reste.
  const settle = createChatScrollSettleState(feed);
  const step = () => {
    const pending = chatScrollRestorePasses.get(feed);
    if (!pending) return;
    if (!feed.isConnected) {
      chatScrollRestorePasses.delete(feed);
      return;
    }
    const again = chatScrollSettleContinues(pending.settle, state, feed);
    applyChatFeedScrollTop(feed, state);
    if (!again) {
      chatScrollRestorePasses.delete(feed);
      return;
    }
    pending.frame = window.requestAnimationFrame(step);
  };
  chatScrollRestorePasses.set(feed, { settle, frame: window.requestAnimationFrame(step) });
};

const resetChatFeedScroll = () => {
  chatScrollState.followLatest = true;
  chatScrollState.scrollTop = 0;
  // Le DOM contient encore l'ancien chat jusqu'au prochain render : ne pas
  // capturer sa position apres avoir demande la remise a zero.
  skipNextChatScrollCapture = true;
};

const bindChatFeedScroll = (
  feed: HTMLDivElement,
  state: ChatScrollState = chatScrollState,
) => {
  let scrollbarPointerDown = false;
  let userScrollIntent: ChatScrollUserIntent = "none";
  let clearUserScrollIntentTimer: number | null = null;
  const markUserScrollIntent = (intent: Exclude<ChatScrollUserIntent, "none">) => {
    // Un geste explicite reprend la main : le rattrapage de mise en page ne
    // doit jamais tirer le fil sous les doigts de l'utilisateur.
    cancelChatFeedScrollRestore(feed);
    userScrollIntent = intent;
    if (clearUserScrollIntentTimer !== null) {
      window.clearTimeout(clearUserScrollIntentTimer);
    }
    clearUserScrollIntentTimer = window.setTimeout(() => {
      userScrollIntent = "none";
      clearUserScrollIntentTimer = null;
    }, 300);
  };
  const resumeIfUserReachedLatest = () => {
    if (chatIsAtBottom(feed)) {
      rememberChatFeedScroll(feed, state, "toward-latest");
    }
  };

  feed.addEventListener("scroll", () => {
    const previousScrollTop = state.scrollTop;
    const movedAway = feed.scrollTop < previousScrollTop - 0.5;
    const movedTowardLatest = feed.scrollTop > previousScrollTop + 0.5;
    // Une position posee par le code arrive ici comme n'importe quel scroll.
    // Sans cette garde, une restauration ecretee juste apres un geste passerait
    // pour une remontee volontaire et remplacerait la position memorisee.
    const appliedByCode = chatProgrammaticScrollTops.get(feed);
    const programmatic =
      appliedByCode !== undefined && Math.abs(feed.scrollTop - appliedByCode) <= 0.5;
    const userIntent: ChatScrollUserIntent = programmatic
      ? "none"
      : scrollbarPointerDown
        ? movedAway
          ? "away"
          : movedTowardLatest
            ? "toward-latest"
            : "none"
        : userScrollIntent === "away" && movedAway
          ? "away"
          : userScrollIntent === "toward-latest" && movedTowardLatest
            ? "toward-latest"
            : "none";
    rememberChatFeedScroll(feed, state, userIntent);
    if (userIntent !== "none") markUserScrollIntent(userIntent);
  }, { passive: true });

  // Le listener scroll arrive apres le geste. On desactive donc le suivi des le
  // debut d'une remontee afin qu'un tick de streaming concurrent ne l'annule pas.
  feed.addEventListener(
    "wheel",
    (event) => {
      if (event.deltaY < 0 && feed.scrollTop > 0) {
        markUserScrollIntent("away");
        pauseChatScrollFollow(state, feed);
      } else if (event.deltaY > 0) {
        markUserScrollIntent("toward-latest");
        resumeIfUserReachedLatest();
      }
    },
    { passive: true },
  );

  feed.addEventListener("pointerdown", (event) => {
    const bounds = feed.getBoundingClientRect();
    scrollbarPointerDown =
      event.pointerType === "mouse" &&
      feed.scrollHeight > feed.clientHeight &&
      event.clientX >= bounds.left + feed.clientWidth;
    if (scrollbarPointerDown) cancelChatFeedScrollRestore(feed);
    if (scrollbarPointerDown && feed.scrollTop > 0) pauseChatScrollFollow(state, feed);
  }, { passive: true });
  feed.addEventListener("pointerup", () => {
    scrollbarPointerDown = false;
  }, { passive: true });
  feed.addEventListener("pointercancel", () => {
    scrollbarPointerDown = false;
  }, { passive: true });
  feed.addEventListener("pointerleave", (event) => {
    if (scrollbarPointerDown && event.buttons > 0 && feed.scrollTop > 0) {
      pauseChatScrollFollow(state, feed);
    }
    scrollbarPointerDown = false;
  }, { passive: true });

  feed.addEventListener("keydown", (event) => {
    if (event.target !== feed) return;
    const movesUp =
      event.key === "ArrowUp" ||
      event.key === "PageUp" ||
      event.key === "Home" ||
      (event.key === " " && event.shiftKey);
    const movesDown =
      event.key === "ArrowDown" ||
      event.key === "PageDown" ||
      event.key === "End" ||
      (event.key === " " && !event.shiftKey);
    if (movesUp && feed.scrollTop > 0) {
      markUserScrollIntent("away");
      pauseChatScrollFollow(state, feed);
    } else if (movesDown) {
      markUserScrollIntent("toward-latest");
      resumeIfUserReachedLatest();
    }
  });

  let lastTouchY: number | null = null;
  feed.addEventListener(
    "touchstart",
    (event) => {
      lastTouchY = event.touches[0]?.clientY ?? null;
    },
    { passive: true },
  );
  feed.addEventListener(
    "touchmove",
    (event) => {
      const touchY = event.touches[0]?.clientY ?? null;
      if (touchY !== null && lastTouchY !== null && touchY > lastTouchY && feed.scrollTop > 0) {
        markUserScrollIntent("away");
        pauseChatScrollFollow(state, feed);
      } else if (touchY !== null && lastTouchY !== null && touchY < lastTouchY) {
        markUserScrollIntent("toward-latest");
        resumeIfUserReachedLatest();
      }
      lastTouchY = touchY;
    },
    { passive: true },
  );
  feed.addEventListener("touchend", () => {
    lastTouchY = null;
  }, { passive: true });
  feed.addEventListener("touchcancel", () => {
    lastTouchY = null;
  }, { passive: true });
};

// Patch cible du fil (#chatFeed) : pas de re-render global. Le suivi
// reste actif jusqu'a une remontee explicite, puis reprend quand le bas est
// atteint. La position absolue est conservee pendant le remplacement du HTML.
const refreshChatFeed = () => {
  const feed = document.querySelector<HTMLDivElement>("#chatFeed");
  if (!feed) {
    render();
    return;
  }
  rememberChatFeedScroll(feed, chatScrollState);
  const model = chatPanelModel();
  const feedPatchRoot = patchChatFeedContent(feed, model);
  const feedChanged = feedPatchRoot !== null;
  const panel = document.querySelector<HTMLElement>("#chatPanel");
  const runtimeChanged = panel ? patchChatRuntimeStatus(panel, model) : false;
  const subtitle = document.querySelector<HTMLSpanElement>("#chatSubtitle");
  if (subtitle) subtitle.textContent = model.subtitle;
  const historyCount = document.querySelector<HTMLElement>("#chatHistoryToggle small");
  if (historyCount) {
    historyCount.textContent = String(chatMessages.filter((message) => message.role === "user").length);
  }
  refreshChatSyncIndicator();
  if (feedPatchRoot) renderIcons(feedPatchRoot);
  if (runtimeChanged && panel) renderIcons(panel);
  // Le fil entier a ete reconstruit quand le patch retourne le conteneur : les
  // tailles memorisees des tours sont perdues, la hauteur doit etre remesuree.
  if (feedChanged) restoreChatFeedScroll(feed, chatScrollState, feedPatchRoot === feed);
};

const stopChatTurnPoll = () => {
  if (chatTurnPoll !== null) {
    clearInterval(chatTurnPoll);
    chatTurnPoll = null;
  }
  chatTurnPollInFlight = false;
};

const findDiscussionByRollout = (
  sessionId: string,
  accountId?: string | null,
) =>
  allDiscussions().find(
    (discussion) =>
      (!accountId || discussion.accountId === accountId)
      && (discussion.sessionId === sessionId || discussion.rolloutId === sessionId),
  ) ?? null;

const attachCreatedChat = async (sessionId: string): Promise<boolean> => {
  if (chatDiscussion) return true;
  let discussion = findDiscussionByRollout(sessionId, chatAccountId);
  if (!discussion) {
    await refreshDiscussions();
    discussion = findDiscussionByRollout(sessionId, chatAccountId);
  }
  if (!discussion) return false;

  chatDiscussion = discussion;
  chatContextUsage = null;
  chatAccountId = discussion.accountId;
  void loadChatModelCatalog(chatAccountId);
  chatLoading = false;
  chatError = null;
  startChatSync();
  void loadChatTranscript();
  return true;
};

const applyChatTurnSnapshot = async (snapshot: ChatTurnSnapshot) => {
  const pane = expertChatPanes.find(
    (candidate) =>
      !!candidate.turn &&
      chatTurnIsBusy(candidate.turn?.status) &&
      (candidate.turn.id === 0 || candidate.turn.id === snapshot.id) &&
      candidate.turn.accountId === snapshot.accountId,
  ) ?? activeExpertChatPane();
  if (pane?.turn && chatTurnIsBusy(pane.turn.status)) {
    await applyExpertChatTurnSnapshot(pane, snapshot);
    return;
  }
  if (chatTurn && chatTurn.id !== 0 && snapshot.id !== chatTurn.id) return;
  const previousStatus = chatTurn?.status;
  const previousStartedAt = chatTurn?.startedAt;
  const previousTurnId = chatTurn?.id;
  const turnIdentityChanged = previousTurnId !== snapshot.id;
  if (
    previousStartedAt != null &&
    (previousTurnId === 0 || previousTurnId === snapshot.id)
  ) {
    snapshot = { ...snapshot, startedAt: Math.min(previousStartedAt, snapshot.startedAt) };
  }
  chatTurn = snapshot;
  const quotaExhausted =
    snapshot.status === "failed" &&
    isQuotaExhaustionError(snapshot.error);
  const retryableFailure = failedTurnIsRetryable(snapshot, chatActiveSubmission);
  const attached = snapshot.sessionId ? await attachCreatedChat(snapshot.sessionId) : !!chatDiscussion;

  if (snapshot.status === "finalizing") {
    statusText = "Reponse terminee, synchronisation…";
  } else if (snapshot.status === "completed") {
    statusText = "Reponse terminee";
    if (attached) await loadChatTranscript();
    stopChatTurnPoll();
  } else if (snapshot.status === "failed") {
    chatMessages = markLatestPendingMessageFailed(chatMessages);
    statusText = snapshot.error || "La reponse a echoue";
    stopChatTurnPoll();
  } else if (snapshot.status === "cancelled") {
    statusText = "Reponse arretee";
    stopChatTurnPoll();
  } else {
    statusText = `${chatPanelModel().providerLabel} travaille…`;
  }

  if (retryableFailure) {
    scheduleMainModelCapacityRetry(snapshot);
  } else if (!chatTurnIsBusy(snapshot.status)) {
    resetMainModelCapacityRetry();
  }

  if (
    !quotaExhausted &&
    chatTurnIsBusy(previousStatus) &&
    !chatTurnIsBusy(snapshot.status)
  ) {
    void refreshLimitStatus(true, true);
  }
  if (chatTurnIsBusy(previousStatus) && !chatTurnIsBusy(snapshot.status)) {
    // Les outils Microsoft mettent une action en file sans rien envoyer : la
    // carte de confirmation doit apparaitre des la fin du tour.
    void refreshMicrosoftPendingActions();
  }
  if (chatBecameAvailable(previousStatus, snapshot.status)) {
    void playChatReadySound(chatReadySoundPreferences);
  }
  const promptHadFocus = document.activeElement ===
    document.querySelector<HTMLTextAreaElement>("#chatPrompt");
  if (activeView === "chat") {
    if (previousStatus !== snapshot.status || turnIdentityChanged) render();
    else refreshChatFeed();
  }
  if (promptHadFocus) focusMainChatPrompt();
  if (quotaExhausted) {
    if (chatDiscussion) automaticallyTransferQuotaExhaustedDiscussion(chatDiscussion, snapshot);
    else void refreshQuotaAlternatives();
  } else if (retryableFailure) {
    // La file utilisateur attend d'abord la reprise automatique de ce tour.
  } else if (!chatTurnIsBusy(snapshot.status)) {
    void drainChatSubmissionQueue();
    void drainNextGlobalChatCapacityQueue();
  }
};

const pollChatTurn = async () => {
  if (!chatTurn || chatTurn.id === 0 || chatTurnPollInFlight) return;
  chatTurnPollInFlight = true;
  try {
    const snapshot = await invoke<ChatTurnSnapshot>("chat_turn_status", { id: chatTurn.id });
    await applyChatTurnSnapshot(snapshot);
  } catch (error) {
    statusText = `Suivi de la reponse : ${String(error)}`;
  } finally {
    chatTurnPollInFlight = false;
  }
};

const startChatTurnPoll = () => {
  stopChatTurnPoll();
  chatTurnPoll = window.setInterval(
    () => {
      if (chatQueuedSubmissions.length > 0) void pollChatTurn();
      else runWhenPageVisible(() => void pollChatTurn());
    },
    CHAT_TURN_POLL_INTERVAL_MS,
  );
};

const IMAGE_ONLY_CHAT_PROMPT = "Image jointe.";

type ChatImageAttachmentBinding = {
  current: () => ChatImageAttachment[];
  update: (images: ChatImageAttachment[]) => void;
  refresh: () => void;
  focus: () => void;
};

const attachPastedChatImages = async (
  event: ClipboardEvent,
  binding: ChatImageAttachmentBinding,
): Promise<void> => {
  const files = clipboardChatImageFiles(event.clipboardData);
  if (!files.length) return;
  event.preventDefault();
  try {
    const current = binding.current();
    const additions = await readChatImageAttachments(files, current);
    binding.update([...current, ...additions]);
    statusText = `${additions.length} image${additions.length > 1 ? "s" : ""} jointe${additions.length > 1 ? "s" : ""} au prochain message`;
  } catch (error) {
    statusText = String(error instanceof Error ? error.message : error);
  }
  binding.refresh();
  binding.focus();
};

const removeChatImageAttachment = (
  imageId: string,
  binding: ChatImageAttachmentBinding,
): void => {
  const current = binding.current();
  const removed = current.find((image) => image.id === imageId);
  if (!removed) return;
  disposeChatImagePreviews([removed]);
  binding.update(current.filter((image) => image.id !== imageId));
  statusText = "Image retiree du prochain message";
  binding.refresh();
  binding.focus();
};

const chatSubmissionPrompt = (
  input: HTMLTextAreaElement | null,
  fallback: string,
  intent: ChatSubmitIntent,
  hasImageAttachments = false,
): string => {
  const value = (input?.value ?? fallback).trim();
  if (!value) {
    if (intent === "message" && hasImageAttachments) {
      input?.setCustomValidity("");
      return IMAGE_ONLY_CHAT_PROMPT;
    }
    if (intent === "goal" && input) {
      input.setCustomValidity("Décrivez l'objectif du goal avant de le créer.");
      input.reportValidity();
      input.focus();
    }
    return "";
  }
  input?.setCustomValidity("");
  return intent === "goal" ? createGoalPrompt(value) : value;
};

const focusMainChatPrompt = () => {
  window.requestAnimationFrame(() => {
    const input = document.querySelector<HTMLTextAreaElement>("#chatPrompt");
    input?.focus();
    input?.setSelectionRange(input.value.length, input.value.length);
  });
};

const compactedContextStatus = (
  usage: ChatContextWindowUsage | null,
  automatic = false,
): string => {
  const prefix = automatic ? "Contexte compacté automatiquement" : "Contexte compacté";
  if (!usage) return prefix;
  const presentation = chatTokenUsagePresentation(null, usage);
  return `${prefix} · ${presentation.value} tokens · ${usage.usedPercent} % de la fenêtre exploitable`;
};

const updateCompactionStatus = (message: string) => {
  statusText = message;
  syncStatusTextDom();
};

const compactCurrentChatContext = async (
  clearCommandDraft = false,
  automatic = false,
): Promise<boolean> => {
  const account = chatSelectedAccount();
  const discussion = chatDiscussion;
  const sessionId =
    discussion?.rolloutId?.trim()
    || chatTurn?.sessionId?.trim()
    || discussion?.sessionId?.trim()
    || null;
  if (!account || accountProvider(account) !== "codex") {
    updateCompactionStatus("La commande /compact est disponible uniquement avec Codex");
    return false;
  }
  if (!isPlausibleSessionId(sessionId)) {
    updateCompactionStatus("Envoyez un premier message avant de compacter le contexte");
    return false;
  }
  if (chatContextCompacting) {
    updateCompactionStatus("La compaction du contexte est déjà en cours");
    return false;
  }
  if (
    chatTurnIsBusy(chatTurn?.status)
    || chatQueuedSubmissions.length > 0
    || (discussion ? discussionHasRunningTurn(discussion) : false)
  ) {
    updateCompactionStatus("Attendez la fin de la réponse et de la file avant de lancer /compact");
    return false;
  }

  if (clearCommandDraft) {
    chatDraft = "";
    flushChatDraft();
  }
  chatContextCompacting = true;
  updateCompactionStatus(automatic
    ? "Seuil de 400 000 tokens dépassé · compactage automatique en cours…"
    : "Compaction du contexte Codex en cours…");
  if (activeView === "chat") render();
  try {
    const result = await invoke<CompactChatSessionResult>("compact_chat_session", {
      accountId: account.id,
      sessionId,
    });
    const usage = normalizeChatContextUsage(result.contextUsage);
    if (chatDiscussion === discussion) {
      if (usage) chatContextUsage = usage;
      await loadChatTranscript();
    }
    updateCompactionStatus(compactedContextStatus(usage, automatic));
    void refreshDiscussions();
    return true;
  } catch (error) {
    updateCompactionStatus(automatic
      ? `Compactage automatique impossible : ${String(error)}`
      : `/compact impossible : ${String(error)}`);
    return false;
  } finally {
    chatContextCompacting = false;
    if (activeView === "chat") render();
    if (!automatic) focusMainChatPrompt();
  }
};

const claimAutomaticCompactionAttempt = (
  accountId: string,
  sessionId: string,
  contextUsage: ChatContextWindowUsage | null,
): boolean => {
  const key = `${accountId}:${sessionId}`;
  if (!shouldAutoCompactChatContext(contextUsage)) {
    if (contextUsage && contextUsage.usedTokens <= CHAT_AUTO_COMPACT_THRESHOLD_TOKENS) {
      automaticCompactionAttempts.delete(key);
    }
    return false;
  }
  const attemptedAt = automaticCompactionAttempts.get(key);
  if (attemptedAt !== undefined && contextUsage!.usedTokens <= attemptedAt) return false;
  automaticCompactionAttempts.set(key, contextUsage!.usedTokens);
  return true;
};

const maybeAutoCompactCurrentChatContext = (): boolean => {
  const account = chatSelectedAccount();
  const discussion = chatDiscussion;
  const sessionId =
    discussion?.rolloutId?.trim()
    || chatTurn?.sessionId?.trim()
    || discussion?.sessionId?.trim()
    || null;
  if (
    !account
    || accountProvider(account) !== "codex"
    || !isPlausibleSessionId(sessionId)
    || chatContextCompacting
    || chatTurnIsBusy(chatTurn?.status)
    || chatQueuedSubmissions.length > 0
    || (discussion ? discussionHasRunningTurn(discussion) : false)
    || !claimAutomaticCompactionAttempt(account.id, sessionId, chatContextUsage)
  ) return false;
  void compactCurrentChatContext(false, true);
  return true;
};

const sendChatMessage = async (
  intent: ChatSubmitIntent = "message",
  queuedSubmission: QueuedChatSubmission | null = null,
): Promise<boolean> => {
  const input = queuedSubmission
    ? null
    : document.querySelector<HTMLTextAreaElement>("#chatPrompt");
  const draftImageAttachments = queuedSubmission?.imageAttachments ?? chatImageAttachments;
  const prompt = queuedSubmission?.prompt ?? chatSubmissionPrompt(
    input,
    chatDraft,
    intent,
    draftImageAttachments.length > 0,
  );
  const account = queuedSubmission
    ? accountById(queuedSubmission.accountId)
    : chatSelectedAccount();
  if (!prompt || !account) {
    statusText = account
      ? intent === "goal" ? "Décrivez le goal" : "Ecrivez un message"
      : "Ajoutez d'abord un compte agent";
    return false;
  }
  if (intent === "goal" && !providerSupportsGoals(accountProvider(account))) {
    statusText = "Les goals ne sont pas pris en charge par ce fournisseur";
    return false;
  }
  if (
    !queuedSubmission
    && intent === "message"
    && draftImageAttachments.length === 0
    && isCompactSlashCommand(prompt)
  ) {
    return compactCurrentChatContext(true);
  }
  if (chatContextCompacting) {
    updateCompactionStatus("Attendez la fin de la compaction avant d'envoyer un message");
    return false;
  }
  const preferences = queuedSubmission
    ? (() => {
        const selection = validatedAccountModelSelection(
          account,
          queuedSubmission.model,
          queuedSubmission.reasoningEffort,
        );
        return {
          model: selection.model,
          reasoningEffort: selection.reasoningEffort,
          changed: false,
          error: selection.error,
        };
      })()
    : readChatPreferences(account);
  if (preferences.error) {
    const modelInput = document.querySelector<HTMLInputElement>("#chatModel");
    modelInput?.setCustomValidity(preferences.error);
    modelInput?.reportValidity();
    statusText = preferences.error;
    return false;
  }
  if (preferences.changed && !await persistChatPreferences(account.id)) return false;

  const submission = queuedSubmission ?? {
    prompt,
    imageAttachments: [...draftImageAttachments],
    accountId: account.id,
    mode: chatMode,
    model: preferences.model,
    reasoningEffort: preferences.reasoningEffort,
    enabledTools: [...chatEnabledTools],
    agentSkills: chatAgentSkillPrompts(chatEnabledTools),
  };
  const resourceAdmissionPaused = chatResourceAdmissionPaused();
  if (
    chatTurnIsBusy(chatTurn?.status) ||
    (!queuedSubmission && chatQueuedSubmissions.length > 0) ||
    resourceAdmissionPaused
  ) {
    if (queuedSubmission) chatQueuedSubmissions.unshift(submission);
    else chatQueuedSubmissions.push(submission);
    if (!queuedSubmission) {
      chatDraft = "";
      flushChatDraft();
    }
    if (!queuedSubmission) {
      disposeChatImagePreviews(chatImageAttachments);
      chatImageAttachments = [];
    }
    statusText = chatTurnIsBusy(chatTurn?.status)
      ? `Message mis en attente · ${chatQueuedSubmissions.length} dans la file`
      : resourceAdmissionPaused
        ? "Mémoire temporairement saturée · message en attente"
        : "Envoi du prochain message en attente";
    render();
    focusMainChatPrompt();
    if (!chatTurnIsBusy(chatTurn?.status) && !resourceAdmissionPaused) {
      void drainChatSubmissionQueue();
    }
    return true;
  }

  if (!submission.automaticCapacityRetry) resetMainModelCapacityRetry();
  const turnBeforeStart = chatTurn;
  const messagesBeforeStart = chatMessages;
  chatActiveSubmission = submission;
  const resumeSessionId =
    submission.resumeSessionId ??
    chatDiscussion?.rolloutId ??
    chatDiscussion?.sessionId ??
    null;
  if (!queuedSubmission) {
    chatDraft = "";
    flushChatDraft();
  }
  if (!queuedSubmission) {
    disposeChatImagePreviews(chatImageAttachments);
    chatImageAttachments = [];
  }
  chatError = null;
  chatMessages = [
    ...chatMessages,
    {
      role: "user",
      text: chatBubbleText(prompt, submission.displayText),
      timestamp: Math.floor(Date.now() / 1000),
      deliveryState: "pending",
    },
  ];
  chatTurn = {
    id: 0,
    accountId: account.id,
    sessionId: resumeSessionId,
    status: "running",
    startedAt: Math.floor(Date.now() / 1000),
    finishedAt: null,
    error: null,
    activities: [
      {
        id: "preparing",
        kind: "think",
        label: `${providerLabel(accountProvider(account))} prepare la reponse`,
        detail: null,
        status: "running",
      },
    ],
    thoughts: [
      {
        id: "preparing-thought",
        kind: "reasoning",
        text: `${providerLabel(accountProvider(account))} analyse la demande et prépare la prochaine étape.`,
        status: "running",
      },
    ],
    parts: [],
  };
  statusText = `${providerLabel(accountProvider(account))} travaille…`;
  resetChatFeedScroll();
  render();
  focusMainChatPrompt();

  try {
    const snapshot = await invoke<ChatTurnSnapshot>("start_chat_turn", {
      accountId: account.id,
      sessionId: resumeSessionId,
      prompt,
      imageAttachments: chatImageAttachmentPayloads(submission.imageAttachments),
      projectDir:
        discussionFolderPath(chatDiscussion) ?? pendingChatWorkspace ?? currentWorkspace() ?? account.projectDir ?? null,
      mode: submission.mode,
      model: preferences.model,
      reasoningEffort: preferences.reasoningEffort,
      sourceChatKey: activeExpertChatKey,
      agentTools: submission.enabledTools.filter(isChatAgentModeId),
      agentSkills: submission.agentSkills,
    });
    const pane = expertChatPanes.find(
      (candidate) =>
        candidate.turn?.status === "running" &&
        candidate.turn.id === 0 &&
        candidate.turn.accountId === snapshot.accountId,
    );
    if (pane) {
      pane.activeSubmission ??= chatActiveSubmission;
      const optimisticStartedAt = pane.turn?.startedAt;
      pane.turn = optimisticStartedAt == null
        ? snapshot
        : { ...snapshot, startedAt: Math.min(optimisticStartedAt, snapshot.startedAt) };
      startExpertChatTurnPoll(pane);
      await applyExpertChatTurnSnapshot(pane, pane.turn);
      return snapshot.status !== "failed" && snapshot.status !== "cancelled";
    }
    const optimisticStartedAt = chatTurn?.startedAt;
    chatTurn = optimisticStartedAt == null
      ? snapshot
      : { ...snapshot, startedAt: Math.min(optimisticStartedAt, snapshot.startedAt) };
    startChatTurnPoll();
    await applyChatTurnSnapshot(chatTurn);
    void drainNextGlobalChatCapacityQueue();
    return snapshot.status !== "failed" && snapshot.status !== "cancelled";
  } catch (error) {
    if (isNodeCapacityError(String(error))) {
      pauseChatResourceAdmission();
      chatTurn = turnBeforeStart;
      chatMessages = messagesBeforeStart;
      chatActiveSubmission = null;
      chatQueuedSubmissions.unshift(submission);
      statusText = "Mémoire temporairement saturée · message conservé dans la file";
      render();
      return true;
    }
    const pane = expertChatPanes.find(
      (candidate) =>
        candidate.turn?.status === "running" &&
        candidate.turn.id === 0 &&
        candidate.turn.accountId === account.id,
    );
    if (pane) {
      // Coupure de transport ambigue : le serveur a peut-etre deja lance le tour.
      // Reconcilier par sourceChatKey plutot que fabriquer un « failed » (qui
      // s'afficherait « Disponible » alors que l'agent reflechit encore).
      if (!isDefiniteChatTurnRejection(error) && pane.turn?.status === "running") {
        statusText = "Connexion interrompue — vérification du tour en cours…";
        refreshExpertChatPane(pane);
        await refreshActiveChatTurns();
        if (pane.turn && pane.turn.id !== 0) {
          return chatTurnIsBusy(pane.turn.status);
        }
      }
      chatMessages = markLatestPendingMessageFailed(chatMessages);
      pane.activeSubmission ??= chatActiveSubmission;
      const failedTurn = {
        ...pane.turn!,
        status: "failed",
        finishedAt: Math.floor(Date.now() / 1000),
        error: String(error),
      } as ChatTurnSnapshot;
      pane.turn = failedTurn;
      explicitlyOpenedBusyChatVisibilityPins.delete(pane.key);
      statusText = String(error);
      // Chemin catch (coupure de transport au demarrage du tour) : reprise sur
      // saturation uniquement. Un drop transitoire ne se rejoue que sur le
      // chemin snapshot, ou le session_id du backend fait foi (garde de securite).
      const modelCapacityReached = isModelCapacityError(String(error));
      if (modelCapacityReached) {
        scheduleExpertModelCapacityRetry(pane, failedTurn);
      } else {
        resetExpertModelCapacityRetry(pane);
      }
      refreshExpertChatPane(pane);
      if (isQuotaExhaustionError(String(error))) {
        if (pane.discussion) {
          automaticallyTransferQuotaExhaustedDiscussion(pane.discussion, failedTurn, pane);
        } else {
          void refreshQuotaAlternatives();
        }
      }
      if (!isQuotaExhaustionError(String(error)) && !modelCapacityReached) {
        void drainExpertChatSubmissionQueue(pane);
      }
      return false;
    }
    chatMessages = markLatestPendingMessageFailed(chatMessages);
    const failedTurn = {
      ...chatTurn,
      id: 0,
      status: "failed",
      finishedAt: Math.floor(Date.now() / 1000),
      error: String(error),
    } as ChatTurnSnapshot;
    chatTurn = failedTurn;
    statusText = String(error);
    // Chemin catch : reprise sur saturation uniquement (voir ci-dessus).
    const modelCapacityReached = isModelCapacityError(String(error));
    if (modelCapacityReached) {
      scheduleMainModelCapacityRetry(failedTurn);
    } else {
      resetMainModelCapacityRetry();
    }
    render();
    if (isQuotaExhaustionError(String(error))) {
      if (chatDiscussion) {
        automaticallyTransferQuotaExhaustedDiscussion(chatDiscussion, failedTurn);
      } else {
        void refreshQuotaAlternatives();
      }
    } else if (!modelCapacityReached) {
      void drainChatSubmissionQueue();
    }
    return false;
  }
};

const drainChatSubmissionQueue = async (): Promise<void> => {
  if (
    chatQueueDrainInFlight ||
    chatTurnIsBusy(chatTurn?.status) ||
    chatResourceAdmissionPaused() ||
    chatQueuedSubmissions.length === 0
  ) {
    return;
  }
  const submission = chatQueuedSubmissions.shift();
  if (!submission) return;
  chatQueueDrainInFlight = true;
  try {
    await sendChatMessage("message", submission);
  } finally {
    chatQueueDrainInFlight = false;
    if (
      !chatTurnIsBusy(chatTurn?.status) &&
      !chatResourceAdmissionPaused() &&
      !isQuotaExhaustionError(chatTurn?.error) &&
      !isModelCapacityError(chatTurn?.error) &&
      chatQueuedSubmissions.length > 0
    ) {
      void drainChatSubmissionQueue();
    }
  }
};

const closeWorkspace = async (
  workspace: WorkspaceProfile,
  removedFromEnvironmentMenu = false,
): Promise<void> => {
  if (!settings || workspaceClosingId) return;
  const id = workspaceIdForPath(workspace.path);
  const terminalCount = terminalSessions.filter(
    (session) => session.folderPath && workspaceIdForPath(session.folderPath) === id,
  ).length;

  workspaceClosingId = id;
  const previousWorkspaces = settings.workspaces;
  const previousClosedIds = settings.closedWorkspaceIds;
  const update = closeWorkspaceRegistry(
    settings.workspaces ?? [],
    settings.closedWorkspaceIds ?? [],
    workspace.path,
  );
  settings.workspaces = update.workspaces;
  settings.closedWorkspaceIds = update.closedWorkspaceIds;

  try {
    settings = await invoke<AppSettings>("save_settings", { settings });
  } catch (error) {
    settings.workspaces = previousWorkspaces;
    settings.closedWorkspaceIds = previousClosedIds;
    workspaceClosingId = null;
    statusText = `Fermeture impossible : ${String(error)}`;
    render();
    return;
  }

  forgetWorkspace(workspace.path);
  const activePath = currentWorkspace();
  const closedActiveWorkspace = !!activePath && workspaceIdForPath(activePath) === id;
  if (closedActiveWorkspace) {
    setCurrentWorkspace(null);
  }
  if (terminalFolderFilter && workspaceIdForPath(terminalFolderFilter) === id) {
    terminalFolderFilter = null;
  }
  if (activeChatWorkspaceFilter() === id) setChatWorkspaceFilter(WORKSPACE_ALL);
  if (pendingChatWorkspace && workspaceIdForPath(pendingChatWorkspace) === id) {
    pendingChatWorkspace = null;
  }
  if (newTerminalWorkspacePath && workspaceIdForPath(newTerminalWorkspacePath) === id) {
    newTerminalWorkspacePath = null;
  }
  let expertChatsChanged = false;
  expertChatPanes.forEach((pane) => {
    if (
      !pane.discussion &&
      pane.pendingWorkspace &&
      workspaceIdForPath(pane.pendingWorkspace) === id
    ) {
      pane.pendingWorkspace = null;
      expertChatsChanged = true;
    }
  });
  if (expertChatsChanged) persistExpertChats();

  workspaceClosingId = null;
  const action = removedFromEnvironmentMenu ? "supprime de Switch" : "ferme";
  statusText = terminalCount
    ? `Environnement « ${workspace.label} » ${action} · ${terminalCount} terminal${terminalCount > 1 ? "s restent" : " reste"} ouvert${terminalCount > 1 ? "s" : ""}`
    : `Environnement « ${workspace.label} » ${action}`;
  render();
};

const stopCurrentChatTurn = async () => {
  if (!chatTurn || chatTurn.status !== "running") return;
  if (chatTurn.id === 0) {
    chatTurn = { ...chatTurn, status: "cancelled" };
    stopChatTurnPoll();
    render();
    focusMainChatPrompt();
    void drainChatSubmissionQueue();
    return;
  }
  try {
    await applyChatTurnSnapshot(
      await invoke<ChatTurnSnapshot>("stop_chat_turn", { id: chatTurn.id }),
    );
  } catch (error) {
    statusText = String(error);
  }
};

const openNewChat = () => {
  openNewChatModal();
};

const applyChatTranscript = (
  discussion: DiscussionSummary,
  transcript: DiscussionTranscriptView,
) => {
  if (chatDiscussion !== discussion) return;
  const wasLoading = chatLoading;
  const nextMessages = reconcileChatMessages(
    chatMessages,
    transcript.messages,
    true,
  );
  const changed = !chatMessagesEqual(chatMessages, nextMessages);
  const truncationChanged = chatTruncated !== transcript.truncated;
  const nextContextUsage = Object.hasOwn(transcript, "contextUsage")
    ? normalizeChatContextUsage(transcript.contextUsage)
    : chatContextUsage;
  const contextChanged = JSON.stringify(chatContextUsage) !== JSON.stringify(nextContextUsage);
  chatMessages = nextMessages;
  chatTruncated = transcript.truncated;
  chatContextUsage = nextContextUsage;
  chatLoading = false;
  chatError = null;
  if (activeView === "chat" && (changed || truncationChanged || wasLoading)) {
    if (chatHistoryOpen && changed) render();
    else refreshChatFeed();
  } else if (activeView === "chat") {
    refreshChatSyncIndicator();
  }
  if (activeView === "chat" && contextChanged) {
    const panel = document.querySelector<HTMLElement>("#chatPanel");
    if (panel && patchChatRuntimeStatus(panel, chatPanelModel())) renderIcons(panel);
  }
  void maybeAutoCompactCurrentChatContext();
};

const loadChatTranscript = async () => {
  const discussion = chatDiscussion;
  if (!discussion || chatLoadInFlight) return;
  chatLoadInFlight = true;
  if (chatMessages.length === 0) {
    chatLoading = true;
    chatError = null;
  }
  try {
    const transcript = await invoke<DiscussionTranscriptView>("get_discussion_transcript", {
      accountId: discussion.accountId,
      // rolloutId = fichier HEAD : l'historique le plus complet a travers les
      // reprises (cf. collapse_forks cote backend).
      sessionId: discussion.rolloutId || discussion.sessionId,
    });
    applyChatTranscript(discussion, transcript);
  } catch (error) {
    if (chatDiscussion !== discussion) return;
    chatLoading = false;
    const empty = chatMessages.length === 0;
    if (empty) chatError = String(error);
    statusText = `Conversation : ${String(error)}`;
    if (activeView === "chat") {
      if (empty) refreshChatFeed();
      else refreshChatSyncIndicator();
    }
  } finally {
    chatLoadInFlight = false;
  }
};

const stopChatSync = () => {
  chatLiveUnlisten?.();
  chatLiveUnlisten = null;
  if (chatFallbackPoll !== null) {
    clearInterval(chatFallbackPoll);
    chatFallbackPoll = null;
  }
  chatSyncState = "closed";
};

const startChatSync = () => {
  stopChatSync();
  const discussion = chatDiscussion;
  if (!discussion) return;

  if (!isRemoteMode()) {
    chatSyncState = "polling";
    chatFallbackPoll = window.setInterval(
      () => runWhenPageVisible(() => void loadChatTranscript()),
      LOCAL_TRANSCRIPT_POLL_INTERVAL_MS,
    );
    return;
  }

  chatSyncState = "connecting";
  const watchedSessionId = discussion.rolloutId || discussion.sessionId;
  chatLiveUnlisten = subscribeDiscussionUpdates(
    { accountId: discussion.accountId, sessionId: watchedSessionId },
    (message: DiscussionStreamMessage) => {
      if (chatDiscussion !== discussion) return;
      if (
        message.type === "transcript" &&
        message.accountId === discussion.accountId &&
        message.sessionId === watchedSessionId
      ) {
        applyChatTranscript(discussion, message.transcript as DiscussionTranscriptView);
      } else if (message.type === "error") {
        chatLoading = false;
        const empty = chatMessages.length === 0;
        if (empty) chatError = message.message;
        statusText = `Conversation : ${message.message}`;
        if (activeView === "chat") {
          if (empty) refreshChatFeed();
          else refreshChatSyncIndicator();
        }
      }
    },
    (state: RealtimeConnectionState) => {
      if (chatDiscussion !== discussion) return;
      chatSyncState = state;
      if (activeView === "chat") refreshChatSyncIndicator();
    },
  );
  // Si un reverse-proxy refuse les WebSockets, le REST garde la conversation
  // vivante pendant les tentatives de reconnexion.
  chatFallbackPoll = window.setInterval(() => {
    runWhenPageVisible(() => {
      if (chatSyncState !== "live") void loadChatTranscript();
    });
  }, 2000);
};

const openDiscussionChat = async (discussion: DiscussionSummary) => {
  closeMobileOverlays();
  const provider = discussion.provider ?? accountProvider(accountById(discussion.accountId));
  if (provider === "freebuff") {
    await resumeDiscussion(discussion);
    return;
  }
  const existing = expertChatPanes.find(
    (pane) =>
      pane.discussion?.accountId === discussion.accountId
      && pane.discussion.sessionId === discussion.sessionId,
  );
  // Les workers et testeurs utilisent un sandbox prive qui ne doit jamais
  // remplacer l'environnement principal au simple clic. Leur panneau est deja
  // rattache au bon contexte : l'afficher directement rend le transcript
  // consultable sans passer par la restauration d'un chat utilisateur.
  if (existing && minimizeActiveBusyExpertChat(existing)) return;
  if (existing?.orchestrationId) {
    openDiscussionInExpert(discussion, true);
    return;
  }
  try {
    await restoreDiscussionFolder(discussion);
    openDiscussionInExpert(discussion, true);
  } catch (error) {
    statusText = `Environnement de la discussion non restaure : ${String(error)}`;
    render();
  }
};

// --- Grille de chats persistants, indépendants et paginés -------------------

const createExpertChatPane = (
  discussion: DiscussionSummary | null = null,
  persisted: Partial<PersistedExpertChatPane> = {},
): ExpertChatPane => {
  const capturedWorkspace = userEnvironmentPath(persisted.pendingWorkspace);
  const recentMessages = restoreRecentSentChatMessages(persisted.recentMessages);
  if (discussion && capturedWorkspace && !discussion.folderPath) {
    discussion.folderPath = capturedWorkspace;
  }

  return {
    key: persisted.key || uid("chat-pane"),
    userOpened: persisted.userOpened !== false,
    discussion,
    resumeSessionId:
      discussion?.rolloutId?.trim()
      || persisted.sessionId?.trim()
      || discussion?.sessionId?.trim()
      || null,
    messages: recentMessages,
    loading: !!discussion && recentMessages.length === 0,
    error: null,
    truncated: false,
    contextUsage: null,
    contextCompacting: false,
    syncState: "closed",
    liveUnlisten: null,
    fallbackPoll: null,
    loadInFlight: false,
    discussionAttachPromise: null,
    turn: null,
    turnPoll: null,
    turnPollInFlight: false,
    draft: persisted.draft ?? "",
    imageAttachments: [],
    queuedSubmissions: [],
    queueDrainInFlight: false,
    activeSubmission: null,
    capacityRetryAttempt: 0,
    capacityRetryTimer: null,
    mode:
      persisted.mode === "plan" || persisted.mode === "ask" ? persisted.mode : "build",
    enabledTools: migratePersistedChatAgentTools(persisted),
    accountId:
      discussion?.accountId ??
      persisted.accountId ??
      selectedAccountId ??
      settings?.defaultAccountId ??
      settings?.accounts[0]?.id ??
      null,
    executionTargetId:
      typeof persisted.executionTargetId === "string" && persisted.executionTargetId.trim()
        ? persisted.executionTargetId.trim().toLowerCase()
        : null,
    historyOpen: false,
    pendingWorkspace:
      discussionFolderPath(discussion) ?? capturedWorkspace ?? currentWorkspace(),
    autonomousAgentId: persisted.autonomousAgentId ?? null,
    // Le mode orchestrateur est le nouveau defaut global. Un choix explicite
    // `false` reste durable ; seuls les chats deja pilotes par une orchestration
    // et les agents autonomes restent exclus du lancement automatique.
    automaticOrchestrationEnabled: automaticOrchestrationEnabledByDefault({
      surface: "classic-chat",
      orchestrationRole: persisted.orchestrationRole,
      autonomousAgentId: persisted.autonomousAgentId,
      persistedEnabled: persisted.automaticOrchestrationEnabled,
    }),
    automaticOrchestrationLaunching: false,
    orchestrationId: persisted.orchestrationId ?? null,
    orchestrationRole:
      persisted.orchestrationRole === "orchestrator" || persisted.orchestrationRole === "worker"
        ? persisted.orchestrationRole
        : null,
    orchestrationTaskId: persisted.orchestrationTaskId ?? null,
    orchestrationTesterId: persisted.orchestrationTesterId ?? null,
    followLatest: true,
    scrollTop: 0,
    visibleTurnLimit: initialVisibleChatTurnLimit(),
  };
};

const expertChatPaneEnvironmentPath = (pane: ExpertChatPane): string | null =>
  userEnvironmentPath(
    pane.orchestrationId
      ? pane.pendingWorkspace
      : discussionFolderPath(pane.discussion) ?? pane.pendingWorkspace,
  );

const expertChatPanesForCurrentEnvironment = (): ExpertChatPane[] => {
  const environmentPath = userEnvironmentPath(currentWorkspace());
  if (!environmentPath) return [];
  const environmentId = workspaceIdForPath(environmentPath);
  return expertChatPanes.filter((pane) => {
    const panePath = expertChatPaneEnvironmentPath(pane);
    return !!panePath && workspaceIdForPath(panePath) === environmentId;
  });
};

const userOpenedExpertChatPanesForCurrentEnvironment = (): ExpertChatPane[] =>
  expertChatsOpenedByUser(
    expertChatPanesForCurrentEnvironment(),
    (pane) => pane.userOpened,
  );

const expertChatPaneHasBusyTurn = (pane: ExpertChatPane): boolean =>
  chatTurnIsBusy(pane.turn?.status)
  || activeChatTurnForDiscussion(activeChatTurns, pane.discussion) !== null;

const expertChatPaneIsAvailable = (pane: ExpertChatPane): boolean =>
  !expertChatPaneHasBusyTurn(pane)
  || automaticQuotaResumeVisibilityPins.has(pane.key)
  || explicitlyOpenedBusyChatVisibilityPins.has(pane.key);

const expertChatPaneIsCreatedByUser = (pane: ExpertChatPane): boolean =>
  pane.orchestrationRole !== "worker"
  && !pane.orchestrationTesterId;

const expertChatPaneIsCreatedOrExplicitlyOpened = (pane: ExpertChatPane): boolean =>
  expertChatPaneIsCreatedByUser(pane)
  || explicitlyOpenedAuxiliaryChatVisibilityPins.has(pane.key);

const pinExplicitlyOpenedBusyExpertChat = (pane: ExpertChatPane): void => {
  if (
    pane.userOpened
    && expertChatDisplayMode === "available"
    && expertChatPaneHasBusyTurn(pane)
  ) {
    explicitlyOpenedBusyChatVisibilityPins.add(pane.key);
  }
};

const minimizeActiveBusyExpertChat = (pane: ExpertChatPane): boolean => {
  if (
    activeView !== "chat"
    || !shouldMinimizeActiveBusyExpertChat(
      expertChatDisplayMode,
      expertChatPaneHasBusyTurn(pane),
      pane.key === activeExpertChatKey,
      expertChatPaneIsAvailable(pane),
    )
  ) {
    return false;
  }

  // La reduction est une intention explicite : elle prend le pas sur les deux
  // raisons temporaires qui peuvent garder un chat orange dans le mur.
  automaticQuotaResumeVisibilityPins.delete(pane.key);
  explicitlyOpenedBusyChatVisibilityPins.delete(pane.key);
  if (expertChatFullscreenKey === pane.key) expertChatFullscreenKey = null;
  reconcileExpertChatPage();
  statusText = `Chat en cours réduit · ${expertChatStatusText()}`;
  persistExpertChats();
  render();
  startAllExpertChatWork();
  return true;
};

const displayedExpertChatPanesForCurrentEnvironment = (): ExpertChatPane[] =>
  expertChatsForDisplay(
    expertChatPanesForCurrentEnvironment(),
    expertChatDisplayMode,
    expertChatPaneIsAvailable,
    expertChatPaneIsCreatedOrExplicitlyOpened,
  );

const activeExpertChatPane = (): ExpertChatPane | null => {
  const displayedPanes = displayedExpertChatPanesForCurrentEnvironment();
  return displayedPanes.find((pane) => pane.key === activeExpertChatKey)
    ?? displayedPanes[0]
    ?? null;
};

const EXPERT_CHAT_DESKTOP_TOOLBAR_HEIGHT = 70;
const EXPERT_CHAT_DESKTOP_GRID_INSET = 16;
const EXPERT_CHAT_MOBILE_CHROME_HEIGHT = 110;
const EXPERT_CHAT_MOBILE_GRID_INSET = 8;

const expertChatResponsiveViewport = () => {
  const mobile = window.matchMedia("(max-width: 860px)").matches;
  const sidebarWidth = mobile ? 0 : displayedChatSidebarWidth();
  const contextSidebarWidth = chatContextSidebarWidth(window.innerWidth);
  const toolbarHeight = mobile || expertChatToolbarHidden
    ? 0
    : EXPERT_CHAT_DESKTOP_TOOLBAR_HEIGHT;
  const mobileChromeHeight = mobile ? EXPERT_CHAT_MOBILE_CHROME_HEIGHT : 0;
  const gridInset = mobile
    ? EXPERT_CHAT_MOBILE_GRID_INSET
    : EXPERT_CHAT_DESKTOP_GRID_INSET;
  return {
    mobile,
    width: Math.max(
      1,
      window.innerWidth - sidebarWidth - contextSidebarWidth - gridInset,
    ),
    height: Math.max(
      1,
      window.innerHeight - toolbarHeight - mobileChromeHeight - gridInset,
    ),
  };
};

const effectiveExpertChatPageSizeMode = (): ExpertChatPageSizeMode => {
  if (expertChatPageSizeMode !== "auto") return expertChatPageSizeMode;
  const viewport = expertChatResponsiveViewport();
  return viewport.mobile
    ? 1
    : expertChatResponsiveCapacity(viewport.width, viewport.height);
};

const responsiveExpertChatGridDimensions = (
  visibleChatCount: number,
) => {
  const viewport = expertChatResponsiveViewport();
  if (viewport.mobile) {
    return { columns: 1, rows: Math.max(1, visibleChatCount) };
  }
  return expertChatResponsiveGridDimensions(
    visibleChatCount,
    viewport.width,
    viewport.height,
  );
};

const expertChatLayoutSignature = (visibleChatCount: number): string => {
  const viewport = expertChatResponsiveViewport();
  const pageSize = resolveExpertChatPageSize(effectiveExpertChatPageSizeMode());
  const { columns, rows } = responsiveExpertChatGridDimensions(visibleChatCount);
  return [viewport.mobile, pageSize, expertChatPage, columns, rows].join(":");
};

const scheduleExpertChatResponsiveRender = () => {
  if (expertChatResponsiveRenderFrame) {
    window.cancelAnimationFrame(expertChatResponsiveRenderFrame);
  }
  expertChatResponsiveRenderFrame = window.requestAnimationFrame(() => {
    expertChatResponsiveRenderFrame = 0;
    if (!settings || activeView !== "chat") return;

    reconcileExpertChatPage();
    const visibleCount = visibleExpertChatPanes().length;
    if (expertChatLayoutSignature(visibleCount) === renderedExpertChatLayoutSignature) {
      return;
    }
    render();
    startAllExpertChatWork();
  });
};

const expertChatPageTotal = (): number =>
  expertChatPageCount(
    displayedExpertChatPanesForCurrentEnvironment().length,
    effectiveExpertChatPageSizeMode(),
  );

const visibleExpertChatPanes = (): ExpertChatPane[] =>
  expertChatsOnPage(
    displayedExpertChatPanesForCurrentEnvironment(),
    expertChatPage,
    effectiveExpertChatPageSizeMode(),
  );

const expertChatStatusText = (): string => {
  const totalCount = userOpenedExpertChatPanesForCurrentEnvironment().length;
  const displayedPanes = displayedExpertChatPanesForCurrentEnvironment();
  const count = displayedPanes.length;
  const totalPages = expertChatPageTotal();
  if (expertChatDisplayMode === "created") {
    const backgroundCount = totalCount - count;
    const backgroundDetail = backgroundCount
      ? ` · ${backgroundCount} sous-chat${backgroundCount > 1 ? "s" : ""} en arrière-plan`
      : "";
    return `${count} de vos chat${count > 1 ? "s" : ""} affiché${count > 1 ? "s" : ""} sur ${totalCount}${backgroundDetail} · page ${expertChatPage + 1}/${totalPages}`;
  }
  if (expertChatDisplayMode === "available") {
    const visibleBusyCount = displayedPanes.filter(expertChatPaneHasBusyTurn).length;
    const busyDetail = visibleBusyCount
      ? ` · ${visibleBusyCount} en cours`
      : "";
    return `${count} chat${count > 1 ? "s" : ""} affiché${count > 1 ? "s" : ""} sur ${totalCount}${busyDetail} · page ${expertChatPage + 1}/${totalPages}`;
  }
  return `${count} chat${count > 1 ? "s" : ""} dans cet environnement · page ${expertChatPage + 1}/${totalPages}`;
};

const moveExpertChatPageToPane = (pane: ExpertChatPane | null) => {
  const panes = displayedExpertChatPanesForCurrentEnvironment();
  const index = pane ? panes.indexOf(pane) : -1;
  const pageSizeMode = effectiveExpertChatPageSizeMode();
  expertChatPage = index >= 0
    ? expertChatPageForIndex(index, pageSizeMode)
    : clampExpertChatPage(expertChatPage, panes.length, pageSizeMode);
};

const reconcileExpertChatPage = () => {
  const panes = displayedExpertChatPanesForCurrentEnvironment();
  if (
    pendingActiveExpertChatKey
    && !panes.some((pane) => pane.key === pendingActiveExpertChatKey)
  ) {
    expertChatPage = clampExpertChatPage(
      expertChatPage,
      panes.length,
      effectiveExpertChatPageSizeMode(),
    );
    return;
  }
  const active = panes.find((pane) => pane.key === activeExpertChatKey) ?? panes[0] ?? null;
  if (active) {
    activeExpertChatKey = active.key;
    moveExpertChatPageToPane(active);
    return;
  }
  activeExpertChatKey = null;
  expertChatPage = clampExpertChatPage(
    expertChatPage,
    panes.length,
    effectiveExpertChatPageSizeMode(),
  );
};

const refreshExpertChatDisplayAfterAvailabilityChange = (
  pane: ExpertChatPane,
  wasAvailable: boolean,
): boolean => {
  if (
    activeView !== "chat"
    || !pane.userOpened
    || expertChatDisplayMode !== "available"
    || wasAvailable === expertChatPaneIsAvailable(pane)
  ) {
    return false;
  }
  reconcileExpertChatPage();
  render();
  startAllExpertChatWork();
  return true;
};

const expertChatInstanceId = (pane: ExpertChatPane): string =>
  pane.key.replace(/[^a-zA-Z0-9_-]/g, "-");

const expertChatPaneRoot = (pane: ExpertChatPane): HTMLElement | null =>
  document.getElementById(`chatPanel-${expertChatInstanceId(pane)}`);

const expertChatSelectedAccount = (pane: ExpertChatPane): AccountProfile | null => {
  const preferred = pane.discussion?.accountId ?? pane.accountId ?? settings?.defaultAccountId;
  // Un compte freebuff ne peut pas porter un chat : s'il etait retenu
  // (compte par defaut, ou premier de la liste), le panneau echouerait au
  // premier envoi. On retombe sur le premier compte reellement utilisable.
  const chosen = accountById(preferred);
  if (chosen && accountSupportsChat(chosen)) return chosen;
  return chatCapableAccounts()[0] ?? null;
};

const orchestrationRunForPane = (pane: ExpertChatPane): OrchestrationSnapshot | null =>
  pane.orchestrationId
    ? orchestrations.find((run) => run.id === pane.orchestrationId) ?? null
    : null;

const orchestrationTaskForPane = (
  pane: ExpertChatPane,
  run = orchestrationRunForPane(pane),
): OrchestrationTask | null =>
  pane.orchestrationRole === "worker" && pane.orchestrationTaskId && run
    ? run.tasks.find((task) => task.id === pane.orchestrationTaskId) ?? null
    : null;

const orchestrationTesterForPane = (
  pane: ExpertChatPane,
  run = orchestrationRunForPane(pane),
): OrchestrationTester | null =>
  pane.orchestrationRole === "orchestrator" && pane.orchestrationTesterId && run
    ? run.testers.find((tester) => tester.id === pane.orchestrationTesterId) ?? null
    : null;

const expertChatResumeSessionId = (pane: ExpertChatPane): string | null =>
  pane.discussion?.rolloutId?.trim()
  || pane.turn?.sessionId?.trim()
  || pane.resumeSessionId?.trim()
  || pane.discussion?.sessionId?.trim()
  || null;

const expertChatSourceTurnIsBusy = (pane: ExpertChatPane): boolean =>
  chatTurnIsBusy(pane.turn?.status)
  || (pane.discussion ? discussionHasRunningTurn(pane.discussion) : false);

const expertChatOrchestrationQueueIsBusy = (pane: ExpertChatPane): boolean =>
  pane.queueDrainInFlight || pane.queuedSubmissions.length > 0;

const autonomousAgentForPane = (pane: ExpertChatPane): AutonomousAgentSnapshot | null =>
  pane.autonomousAgentId
    ? autonomousAgents.find((agent) => agent.id === pane.autonomousAgentId) ?? null
    : null;

const expertChatAutonomousOption = (
  pane: ExpertChatPane,
): NonNullable<Parameters<typeof renderChatPanel>[1]>["autonomous"] => {
  if (pane.orchestrationRole) return undefined;
  const agent = autonomousAgentForPane(pane);
  if (agent) {
    return {
      role: "linked",
      label: autonomousStatusLabel(agent.status),
      detail: `${agent.name || "Agent autonome"} · ${autonomousStatusLabel(agent.status)}. Modifier depuis ce chat.`,
      tone: autonomousStatusTone(agent.status) as "active" | "paused" | "completed" | "warning",
    };
  }
  if (pane.autonomousAgentId && !autonomousAgentsLoaded) {
    return {
      role: "linked",
      label: "Autonome",
      detail: "Chargement de l'agent autonome lié à ce chat.",
      tone: "paused",
      disabled: true,
    };
  }

  const busy =
    chatTurnIsBusy(pane.turn?.status)
    || (pane.discussion ? discussionHasRunningTurn(pane.discussion) : false)
    || pane.queueDrainInFlight
    || pane.queuedSubmissions.length > 0;
  return {
    role: "available",
    label: "Autonomiser",
    detail: busy
      ? "Attendez la fin du tour et de la file avant de créer l'agent autonome."
      : "Créer un agent autonome à partir de ce chat sans fermer la conversation.",
    tone: "paused",
    disabled: busy,
  };
};

const expertChatAutomaticOrchestrationOption = (
  pane: ExpertChatPane,
): NonNullable<Parameters<typeof renderChatPanel>[1]>["automaticOrchestration"] => {
  if (
    pane.orchestrationRole
    || autonomousAgentForPane(pane)
    || (pane.autonomousAgentId && !autonomousAgentsLoaded)
  ) {
    return undefined;
  }
  return {
    enabled: pane.automaticOrchestrationEnabled,
    detail: pane.automaticOrchestrationEnabled
      ? "Actif : chaque tâche lance l’orchestrateur, qui choisit de 1 à 5 workers pour aller au plus vite sans découpage artificiel."
      : "Mode direct : ce chat traite seul les prochaines demandes.",
    disabled: pane.automaticOrchestrationLaunching,
  };
};

const expertChatOrchestrationOption = (
  pane: ExpertChatPane,
): NonNullable<Parameters<typeof renderChatPanel>[1]>["orchestration"] => {
  if (autonomousAgentForPane(pane) || (pane.autonomousAgentId && !autonomousAgentsLoaded)) {
    return undefined;
  }
  const run = orchestrationRunForPane(pane);
  if (pane.orchestrationRole === "orchestrator") {
    const tester = orchestrationTesterForPane(pane, run);
    return {
      role: "orchestrator",
      label: tester ? `Orchestrateur testeur ${tester.position}` : "Orchestrateur",
      detail: tester
        ? `${run?.name ?? "Orchestration"} · ${orchestrationTesterStatusLabel(tester.status)}. Ouvrir le suivi.`
        : run
          ? `${run.name} · ${orchestrationPhaseLabel(run.phase)}. Ouvrir le suivi.`
          : "Chat orchestrateur · ouvrir le suivi.",
    };
  }
  if (pane.orchestrationRole === "worker") {
    const task = orchestrationTaskForPane(pane, run);
    return {
      role: "worker",
      label: task ? `Worker ${task.position}` : "Worker",
      detail: task
        ? `${task.title} · ${orchestrationTaskStatusLabel(task.status)}. Ouvrir le suivi.`
        : "Chat worker · ouvrir le suivi.",
    };
  }

  return undefined;
};

const expertChatPanelModel = (pane: ExpertChatPane): ChatPanelModel => {
  const discussion = pane.discussion;
  const run = orchestrationRunForPane(pane);
  const task = orchestrationTaskForPane(pane, run);
  const tester = orchestrationTesterForPane(pane, run);
  const managedByOrchestration = !!pane.orchestrationRole;
  const account = expertChatSelectedAccount(pane);
  const provider = accountProvider(account);
  const selectedModel = accountModel(account);
  const catalog = account ? chatModelCatalogs.get(account.id) : undefined;
  const workspace =
    discussionFolderPath(discussion) ?? pane.pendingWorkspace ?? currentWorkspace() ?? account?.projectDir ?? null;
  const requestedTargetLabel = pane.executionTargetId
    ? remoteChatExecutionTargets().find((target) => target.id === pane.executionTargetId)?.label ?? null
    : null;
  const metaParts = managedByOrchestration
    ? [
        pane.orchestrationRole === "orchestrator"
          ? tester ? `Orchestrateur testeur ${tester.position}` : "Orchestrateur"
          : `Worker ${task?.position ?? ""}`.trim(),
        tester
          ? orchestrationTesterStatusLabel(tester.status)
          : task ? orchestrationTaskStatusLabel(task.status) : run ? orchestrationPhaseLabel(run.phase) : "Orchestration",
        workspace ? displayProjectDir(workspace) : "",
      ].filter(Boolean)
    : discussion
    ? [
        discussion.accountLabel,
        workspace ? displayProjectDir(workspace) : "",
        `${pane.messages.length || discussion.messageCount} message(s)`,
      ].filter(Boolean)
    : [
        account?.label ?? "Choisissez un compte",
        requestedTargetLabel ? `Cible ${requestedTargetLabel}` : "Cible automatique",
        workspace ? displayProjectDir(workspace) : "Environnement a choisir",
      ];
  // Tour serveur de cette discussion (meme resolution que le bandeau lateral).
  // pane.turn repasse a null a chaque changement de discussion et la
  // reconciliation peut tarder : sans ce repli, le badge du panneau afficherait
  // « Disponible » alors que le tour tourne encore cote serveur.
  const paneServerTurn =
    activeChatTurnForDiscussion(activeChatTurns, discussion)
    ?? activeChatTurnForPaneIdentity(activeChatTurns, pane);
  const paneLocalWaitsForUser = conversationWaitsForUser(
    pane.messages,
    pane.turn?.parts ?? [],
  );
  const paneServerWaitsForUser =
    !!paneServerTurn
    && (!pane.turn || paneServerTurn.id !== pane.turn.id || chatTurnIsBusy(pane.turn.status))
    && paneServerTurn.waitingForUser;
  return {
    title:
      pane.orchestrationRole === "orchestrator"
        ? tester
          ? `Tests · ${tester.assignedTaskIds.map((taskId) => taskId.replace("task-", "W")).join(", ")}`
          : run?.name || discussion?.title?.trim() || "Orchestrateur"
        : pane.orchestrationRole === "worker"
          ? task?.title || "Worker en préparation"
          : discussion?.title?.trim() || "Nouvelle conversation",
    subtitle: metaParts.join(" \u00b7 "),
    totalTokens: discussion ? discussion.totalTokens : 0,
    contextUsage: pane.contextUsage,
    contextCompacting: pane.contextCompacting,
    supportsCompact: provider === "codex",
    hasCompactableSession: isPlausibleSessionId(expertChatResumeSessionId(pane)),
    accountLabel: account?.label ?? discussion?.accountLabel ?? "Aucun compte",
    providerLabel: accountProviderLabel(account),
    nodeLabel: pane.turn?.nodeLabel ?? discussion?.nodeLabel ?? null,
    loading: pane.loading || (managedByOrchestration && !discussion),
    error: pane.error,
    truncated: pane.truncated,
    syncState: discussion ? pane.syncState : "closed",
    messages: pane.messages,
    visibleTurnLimit: pane.visibleTurnLimit,
    activities: pane.turn?.activities ?? [],
    thoughts: pane.turn?.thoughts ?? [],
    parts: pane.turn?.parts ?? [],
    turnStatus: pane.turn?.status ?? "idle",
    serverTurnStatus: paneServerTurn?.status ?? null,
    turnStartedAt: pane.turn?.startedAt ?? null,
    turnFinishedAt: pane.turn?.finishedAt ?? null,
    turnError: modelCapacityTurnError(
      pane.turn,
      pane.activeSubmission,
      pane.capacityRetryAttempt,
      pane.capacityRetryTimer !== null,
    ),
    waitingForUser: paneLocalWaitsForUser || paneServerWaitsForUser,
    turnStatusDisplayMode: chatTurnStatusDisplayMode,
    quotaStatus: chatQuotaStatusFor(account),
    quotaSuggestion: managedByOrchestration ? null : quotaSuggestionFor(pane.turn, discussion),
    accounts: (settings?.accounts ?? []).map((candidate) => ({
      id: candidate.id,
      label: candidate.label,
      providerLabel: accountProviderLabel(candidate),
      model: accountModel(candidate),
    })),
    selectedAccountId: account?.id ?? "",
    selectedModel,
    modelSuggestions: modelSuggestionsForAccount(account, catalog),
    selectedReasoningEffort: reasoningEffortForChatModel(
      account,
      selectedModel,
      accountReasoningEffort(account),
    ) ?? "",
    reasoningEffortOptions: chatReasoningEffortOptions(account, selectedModel),
    supportsReasoningEffort: accountSupportsReasoningEffort(account, selectedModel),
    reasoningEffortAutomatic: accountIsOpenRouter(account),
    fastModeEnabled: accountFastModeEnabled(account),
    supportsFastMode: accountSupportsFastMode(account, selectedModel),
    fastModeHelp: fastModeAvailabilityLabel(
      provider,
      selectedModel,
      accountSupportsFastMode(account, selectedModel),
    ),
    composerSelectorsEnabled: chatComposerSelectorsEnabled,
    favoritePrompts: loadFavoritePromptShortcuts(accountScopedStorage),
    supportsGoals: providerSupportsGoals(provider),
    agentTools: chatAgentToolDefinitions(),
    enabledTools: pane.enabledTools,
    mode: pane.mode,
    draft: pane.draft,
    imageAttachments: pane.imageAttachments,
    queuedCount: pane.queuedSubmissions.length,
    newConversation: !discussion && !managedByOrchestration,
    workspaceLabel: workspace ? displayProjectDir(workspace) : "Environnement",
    historyOpen: pane.historyOpen,
  };
};

const expertChatSidebarStatus = (
  pane: ExpertChatPane | null,
  discussion: DiscussionSummary | null = pane?.discussion ?? null,
) => {
  const serverTurn = activeChatTurnForDiscussion(activeChatTurns, discussion);
  const localTurn = pane?.turn;
  const localWaitsForUser = conversationWaitsForUser(
    pane?.messages ?? [],
    localTurn?.parts ?? [],
  );
  const serverWaitsForUser = !!serverTurn &&
    (!localTurn || serverTurn.id !== localTurn.id || chatTurnIsBusy(localTurn.status)) &&
    serverTurn.waitingForUser;
  return chatSidebarStatus(
    localTurn?.status,
    localWaitsForUser || serverWaitsForUser,
    serverTurn?.status,
  );
};

const renderChatSidebarStatus = (
  pane: ExpertChatPane | null,
  discussion: DiscussionSummary | null = pane?.discussion ?? null,
  orchestrator = false,
): string => {
  const status = expertChatSidebarStatus(pane, discussion);
  if (pane) chatSidebarPaneStatuses.set(pane, status);
  const label = chatSidebarStatusLabel(status);
  const accessibleLabel = orchestrator ? `Orchestrateur · ${label}` : label;
  const paneAttribute = pane
    ? ` data-chat-status-pane="${escapeAttr(pane.key)}"`
    : "";
  const roleClass = orchestrator ? " chat-side-status--orchestrator" : "";
  return `<span class="chat-side-status chat-side-status--${status}${roleClass}"${paneAttribute} role="img" title="${escapeAttr(accessibleLabel)}" aria-label="Statut : ${escapeAttr(accessibleLabel)}"></span>`;
};

const refreshExpertChatSidebarStatus = (pane: ExpertChatPane) => {
  const status = expertChatSidebarStatus(pane);
  const previousStatus = chatSidebarPaneStatuses.get(pane);
  chatSidebarPaneStatuses.set(pane, status);
  if (
    previousStatus !== undefined
    && previousStatus !== status
    && (chatSidebarPriorityMode !== "recent" || chatSidebarHideRunning)
  ) {
    refreshChatSidebarConversations();
    return;
  }
  const label = chatSidebarStatusLabel(status);
  const indicator = [...document.querySelectorAll<HTMLElement>("[data-chat-status-pane]")]
    .find((candidate) => candidate.dataset.chatStatusPane === pane.key);
  if (!indicator) return;
  indicator.classList.remove(
    "chat-side-status--idle",
    "chat-side-status--running",
    "chat-side-status--question",
  );
  indicator.classList.add(`chat-side-status--${status}`);
  const accessibleLabel = indicator.classList.contains("chat-side-status--orchestrator")
    ? `Orchestrateur · ${label}`
    : label;
  indicator.title = accessibleLabel;
  indicator.setAttribute("aria-label", `Statut : ${accessibleLabel}`);
};

const persistedRecentChatMessagesForPane = (
  pane: ExpertChatPane,
): PersistedSentChatMessage[] => {
  const recentMessages = recentSentChatMessages(pane.messages);
  if (pane.turn?.status !== "completed") return recentMessages;

  // Le transcript durable peut arriver quelques instants apres la fin du tour.
  // Conserver entre-temps le texte final deja recu, sans ses parts reasoning/tool.
  const completedReply = recentSentChatMessages([{
    role: "assistant",
    text: "",
    timestamp: pane.turn.finishedAt ?? pane.turn.startedAt,
    parts: pane.turn.parts,
  }]).at(-1);
  if (!completedReply) return recentMessages;
  const latest = recentMessages.at(-1);
  if (latest?.role === "assistant" && latest.text === completedReply.text) {
    return recentMessages;
  }
  return recentSentChatMessages([...recentMessages, completedReply]);
};

const persistExpertChats = () => {
  // Ne pas ecraser l'etat local par une liste vide avant sa restauration.
  if (!expertChatsRestored && expertChatPanes.length === 0) return;
  const openKeys = new Set(expertChatPanes.map((pane) => pane.key));
  const state: PersistedExpertChats = {
    v: 2,
    activeKey: activeExpertChatKey ?? pendingActiveExpertChatKey,
    panes: [...expertChatPanes.map((pane) => ({
      key: pane.key,
      userOpened: pane.userOpened,
      sessionId:
        pane.turn?.sessionId?.trim()
        || pane.resumeSessionId?.trim()
        || pane.discussion?.rolloutId?.trim()
        || pane.discussion?.sessionId?.trim()
        || null,
      awaitingDiscussion: !pane.discussion && !!expertChatResumeSessionId(pane),
      accountId: pane.accountId,
      executionTargetId: pane.executionTargetId,
      recentMessages: persistedRecentChatMessagesForPane(pane),
      draft: pane.draft,
      mode: pane.mode,
      enabledTools: pane.enabledTools,
      pendingWorkspace: pane.pendingWorkspace,
      autonomousAgentId: pane.autonomousAgentId,
      automaticOrchestrationEnabled: pane.automaticOrchestrationEnabled,
      orchestrationId: pane.orchestrationId,
      orchestrationRole: pane.orchestrationRole,
      orchestrationTaskId: pane.orchestrationTaskId,
      orchestrationTesterId: pane.orchestrationTesterId,
    })), ...pendingExpertChatRecords.filter((record) => !openKeys.has(record.key))],
  };
  accountScopedStorage.setItem(EXPERT_OPEN_CHATS_STORAGE_KEY, JSON.stringify(state));
};

const attachPendingExpertChatRecords = (
  availableDiscussions: readonly DiscussionSummary[],
): ExpertChatPane[] => {
  if (pendingExpertChatRecords.length === 0) return [];
  const remaining: PersistedExpertChatPane[] = [];
  const attached: ExpertChatPane[] = [];

  pendingExpertChatRecords.forEach((record) => {
    const discussion = record.sessionId
      ? (
        record.accountId
          ? discussionForSession(availableDiscussions, record.accountId, record.sessionId)
          : availableDiscussions.find((candidate) =>
            candidate.rolloutId === record.sessionId || candidate.sessionId === record.sessionId
          ) ?? null
      )
      : null;
    if (!discussion) {
      remaining.push(record);
      return;
    }
    if (expertChatPanes.some((pane) => pane.key === record.key)) return;
    const pane = createExpertChatPane(discussion, record);
    expertChatPanes.push(pane);
    attached.push(pane);
  });

  pendingExpertChatRecords = remaining;
  if (
    pendingActiveExpertChatKey
    && attached.some((pane) => pane.key === pendingActiveExpertChatKey)
  ) {
    activeExpertChatKey = pendingActiveExpertChatKey;
    pendingActiveExpertChatKey = null;
  }
  if (attached.length > 0) reconcileExpertChatPage();
  return attached;
};

const restoreExpertChats = () => {
  if (expertChatsRestored) return;
  expertChatsRestored = true;
  let persisted: PersistedExpertChats | null = null;
  try {
    const parsed = JSON.parse(accountScopedStorage.getItem(EXPERT_OPEN_CHATS_STORAGE_KEY) ?? "null") as Partial<PersistedExpertChats> | null;
    if ((parsed?.v === 1 || parsed?.v === 2) && Array.isArray(parsed.panes)) {
      persisted = parsed as PersistedExpertChats;
    }
  } catch {
    accountScopedStorage.removeItem(EXPERT_OPEN_CHATS_STORAGE_KEY);
  }

  pendingExpertChatRecords = [];
  pendingActiveExpertChatKey = null;
  const persistedVersion = persisted?.v ?? 2;
  expertChatPanes = (persisted?.panes ?? [])
    .flatMap((record) => {
      if (!record || typeof record.key !== "string") return [];
      // Les anciennes versions pouvaient adopter un tour d'orchestration avant
      // que son groupe ne soit charge, puis creer un second panneau lors de la
      // reconciliation. Ces panneaux techniques se reconnaissent a leur cle
      // serveur et doivent etre reconstruits uniquement par l'orchestrateur.
      if (record.key.startsWith("orchestration:")) return [];
      const normalizedRecord: PersistedExpertChatPane = {
        ...record,
        // La v1 ne permet pas de distinguer un chat ouvert volontairement
        // d'un panneau adopte automatiquement. Ses discussions restent dans
        // la barre laterale et repassent au premier plan au premier clic.
        userOpened: persistedVersion === 2 ? record.userOpened !== false : !record.sessionId,
      };
      const discussion = record.sessionId
        ? (
          record.accountId
            ? discussionForSession(allDiscussions(), record.accountId, record.sessionId)
            : findDiscussionByRollout(record.sessionId)
        )
        : null;
      if (
        record.sessionId
        && !discussion
        && !record.awaitingDiscussion
        && !record.orchestrationId
        && !record.autonomousAgentId
      ) {
        pendingExpertChatRecords.push(normalizedRecord);
        return [];
      }
      return [createExpertChatPane(discussion, normalizedRecord)];
    });
  pendingActiveExpertChatKey = persisted?.activeKey
    && pendingExpertChatRecords.some(
      (record) => record.key === persisted.activeKey && record.userOpened !== false,
    )
    ? persisted.activeKey
    : null;
  activeExpertChatKey =
    (persisted?.activeKey && expertChatPanes.some(
      (pane) => pane.key === persisted.activeKey && pane.userOpened,
    )
      ? persisted.activeKey
      : pendingActiveExpertChatKey
        ? null
        : userOpenedExpertChatPanesForCurrentEnvironment()[0]?.key) ?? null;
  reconcileExpertChatPage();
  persistExpertChats();
};

const captureExpertChatScroll = (pane: ExpertChatPane, root = expertChatPaneRoot(pane)) => {
  const feed = root?.querySelector<HTMLElement>("[data-chat-control='feed']");
  if (!feed) return;
  rememberChatFeedScroll(feed, pane);
};

const restoreExpertChatScroll = (
  pane: ExpertChatPane,
  root = expertChatPaneRoot(pane),
  rebuilt = false,
) => {
  const feed = root?.querySelector<HTMLElement>("[data-chat-control='feed']");
  if (!feed) return;
  restoreChatFeedScroll(feed, pane, rebuilt);
};

const captureAllExpertChatScroll = () => expertChatPanes.forEach((pane) => captureExpertChatScroll(pane));

type ExpertChatPromptFocusSnapshot = {
  paneKey: string;
  selectionStart: number;
  selectionEnd: number;
  selectionDirection: "forward" | "backward" | "none";
  scrollTop: number;
  scrollLeft: number;
};

const captureFocusedExpertChatPrompt = (): ExpertChatPromptFocusSnapshot | null => {
  const prompt = document.activeElement;
  if (
    !(prompt instanceof HTMLTextAreaElement)
    || prompt.dataset.chatControl !== "prompt"
  ) return null;
  const paneKey = prompt.closest<HTMLElement>("[data-chat-panel]")?.dataset.chatPanel;
  if (!paneKey) return null;
  return {
    paneKey,
    selectionStart: prompt.selectionStart,
    selectionEnd: prompt.selectionEnd,
    selectionDirection: prompt.selectionDirection,
    scrollTop: prompt.scrollTop,
    scrollLeft: prompt.scrollLeft,
  };
};

const restoreFocusedExpertChatPrompt = (
  snapshot: ExpertChatPromptFocusSnapshot | null,
): void => {
  if (!snapshot || activeView !== "chat") return;
  const pane = expertChatPanes.find((candidate) => candidate.key === snapshot.paneKey);
  const prompt = pane
    ? expertChatPaneRoot(pane)?.querySelector<HTMLTextAreaElement>("[data-chat-control='prompt']")
    : null;
  if (!prompt) return;
  const selectionStart = Math.min(snapshot.selectionStart, prompt.value.length);
  const selectionEnd = Math.min(snapshot.selectionEnd, prompt.value.length);
  prompt.focus({ preventScroll: true });
  prompt.setSelectionRange(selectionStart, selectionEnd, snapshot.selectionDirection);
  prompt.scrollTop = snapshot.scrollTop;
  prompt.scrollLeft = snapshot.scrollLeft;
};

const renderExpertChatPane = (pane: ExpertChatPane): string =>
  renderChatPanel(expertChatPanelModel(pane), {
    instanceId: pane.key,
    paneIndex: expertChatPanes.indexOf(pane) + 1,
    active: pane.key === activeExpertChatKey,
    compact: true,
    fullscreen: pane.key === expertChatFullscreenKey,
    autonomous: expertChatAutonomousOption(pane),
    orchestration: expertChatOrchestrationOption(pane),
    automaticOrchestration: expertChatAutomaticOrchestrationOption(pane),
    accountTransition: expertChatAccountTransitions.get(pane.key),
  });

const refreshExpertChatSyncIndicator = (pane: ExpertChatPane) => {
  const indicator = expertChatPaneRoot(pane)?.querySelector<HTMLElement>("[data-chat-control='sync']");
  if (!indicator) return;
  indicator.className = `chat-sync chat-sync--${pane.syncState}`;
  const label = indicator.querySelector<HTMLElement>("[data-chat-sync-label]");
  if (label) label.textContent = chatSyncLabel(pane.syncState);
};

const refreshExpertChatFeed = (pane: ExpertChatPane) => {
  refreshExpertChatSidebarStatus(pane);
  const root = expertChatPaneRoot(pane);
  const feed = root?.querySelector<HTMLElement>("[data-chat-control='feed']");
  if (!root || !feed) return;
  const model = expertChatPanelModel(pane);
  rememberChatFeedScroll(feed, pane);
  const feedPatchRoot = patchChatFeedContent(feed, model, pane.key);
  const feedChanged = feedPatchRoot !== null;
  const runtimeChanged = patchChatRuntimeStatus(root, model);
  const subtitle = root.querySelector<HTMLElement>("[data-chat-control='subtitle']");
  if (subtitle) subtitle.textContent = model.subtitle;
  const historyCount = root.querySelector<HTMLElement>("[data-chat-action='history-toggle'] small");
  if (historyCount) {
    historyCount.textContent = String(pane.messages.filter((message) => message.role === "user").length);
  }
  refreshExpertChatSyncIndicator(pane);
  if (feedPatchRoot) renderIcons(feedPatchRoot);
  if (runtimeChanged) renderIcons(root);
  if (feedChanged) restoreExpertChatScroll(pane, root, feedPatchRoot === feed);
};

const syncExpertChatHistoryUi = (pane: ExpertChatPane, root: HTMLElement): void => {
  const conversation = root.querySelector<HTMLElement>(".chat-conversation-body");
  const currentHistory = conversation?.querySelector<HTMLElement>("[data-chat-control='history']");
  const toggle = root.querySelector<HTMLButtonElement>("[data-chat-action='history-toggle']");

  root.classList.toggle("chat-panel--history", pane.historyOpen);
  toggle?.classList.toggle("primary", pane.historyOpen);
  toggle?.setAttribute("aria-expanded", String(pane.historyOpen));

  if (!conversation) return;
  if (!pane.historyOpen) {
    currentHistory?.remove();
    return;
  }
  if (currentHistory) return;

  conversation.insertAdjacentHTML(
    "beforeend",
    renderChatHistory(expertChatPanelModel(pane), expertChatInstanceId(pane)),
  );
  const nextHistory = conversation.querySelector<HTMLElement>("[data-chat-control='history']");
  if (!nextHistory) return;
  renderIcons(nextHistory);
  bindExpertChatHistoryPanelUi(pane, root);
};

const refreshExpertChatPane = (pane: ExpertChatPane) => {
  refreshExpertChatSidebarStatus(pane);
  const root = expertChatPaneRoot(pane);
  if (!root) return;
  const prompt = root.querySelector<HTMLTextAreaElement>("[data-chat-control='prompt']");
  const promptHadFocus = document.activeElement === prompt;
  const selectionStart = prompt?.selectionStart ?? pane.draft.length;
  const selectionEnd = prompt?.selectionEnd ?? selectionStart;
  captureExpertChatScroll(pane, root);
  root.outerHTML = renderExpertChatPane(pane);
  const nextRoot = expertChatPaneRoot(pane);
  if (nextRoot) renderIcons(nextRoot);
  if (nextRoot) bindExpertChatPaneUi(pane, nextRoot);
  if (promptHadFocus) {
    const nextPrompt = nextRoot?.querySelector<HTMLTextAreaElement>("[data-chat-control='prompt']");
    nextPrompt?.focus();
    nextPrompt?.setSelectionRange(
      Math.min(selectionStart, nextPrompt.value.length),
      Math.min(selectionEnd, nextPrompt.value.length),
    );
  }
  // La fenetre a ete re-rendue entierement : les tours sont des elements neufs.
  restoreExpertChatScroll(pane, nextRoot, true);
};

const stopExpertChatTurnPoll = (pane: ExpertChatPane) => {
  if (pane.turnPoll !== null) {
    clearInterval(pane.turnPoll);
    pane.turnPoll = null;
  }
  pane.turnPollInFlight = false;
};

const stopExpertChatSync = (pane: ExpertChatPane) => {
  pane.liveUnlisten?.();
  pane.liveUnlisten = null;
  if (pane.fallbackPoll !== null) {
    clearInterval(pane.fallbackPoll);
    pane.fallbackPoll = null;
  }
  pane.syncState = "closed";
};

const stopAllExpertChatWork = () => {
  expertChatPanes.forEach((pane) => {
    stopExpertChatSync(pane);
    if (
      pane.queuedSubmissions.length > 0 &&
      pane.turn &&
      chatTurnIsBusy(pane.turn.status) &&
      pane.turn.id !== 0
    ) {
      if (pane.turnPoll === null) startExpertChatTurnPoll(pane);
    } else {
      stopExpertChatTurnPoll(pane);
    }
  });
};

const automaticOrchestrationDecisionFromParts = (
  parts: readonly ChatPart[],
): AutomaticOrchestrationDecision | null =>
  parseAutomaticOrchestrationDecision(
    parts
      .filter((part) => part.kind === "text" && part.text?.trim())
      .map((part) => part.text!.trim())
      .join("\n"),
  );

const presentAutomaticOrchestrationMessage = (message: ChatMessage): ChatMessage => {
  if (message.role !== "assistant") return message;
  const decision =
    parseAutomaticOrchestrationDecision(message.text)
    ?? automaticOrchestrationDecisionFromParts(message.parts ?? []);
  if (!decision) return message;
  const notice = automaticOrchestrationNotice(decision);
  return {
    ...message,
    text: notice,
    parts: message.parts?.map((part) =>
      part.kind === "text" && parseAutomaticOrchestrationDecision(part.text)
        ? { ...part, text: notice }
        : part),
  };
};

const applyExpertChatTranscript = (
  pane: ExpertChatPane,
  discussion: DiscussionSummary,
  transcript: DiscussionTranscriptView,
) => {
  if (!expertChatPanes.includes(pane) || pane.discussion !== discussion) return;
  const wasLoading = pane.loading;
  const nextMessages = reconcileChatMessages(
    pane.messages,
    transcript.messages.map(presentAutomaticOrchestrationMessage),
    true,
  );
  const changed = !chatMessagesEqual(pane.messages, nextMessages);
  const truncationChanged = pane.truncated !== transcript.truncated;
  const nextContextUsage = Object.hasOwn(transcript, "contextUsage")
    ? normalizeChatContextUsage(transcript.contextUsage)
    : pane.contextUsage;
  const contextChanged = JSON.stringify(pane.contextUsage) !== JSON.stringify(nextContextUsage);
  pane.messages = nextMessages;
  pane.truncated = transcript.truncated;
  pane.contextUsage = nextContextUsage;
  pane.loading = false;
  pane.error = null;
  if (changed) persistExpertChats();
  if (activeView === "chat" && (changed || truncationChanged || wasLoading)) {
    if (pane.historyOpen && changed) refreshExpertChatPane(pane);
    else refreshExpertChatFeed(pane);
  } else if (activeView === "chat") {
    refreshExpertChatSyncIndicator(pane);
  }
  if (activeView === "chat" && contextChanged) {
    const root = expertChatPaneRoot(pane);
    if (root && patchChatRuntimeStatus(root, expertChatPanelModel(pane))) renderIcons(root);
  }
  void maybeAutoCompactExpertChatContext(pane);
};

const loadExpertChatTranscript = async (pane: ExpertChatPane) => {
  const discussion = pane.discussion;
  if (!discussion || pane.loadInFlight || !expertChatPanes.includes(pane)) return;
  pane.loadInFlight = true;
  if (pane.messages.length === 0) {
    pane.loading = true;
    pane.error = null;
  }
  try {
    const transcript = await invoke<DiscussionTranscriptView>("get_discussion_transcript", {
      accountId: discussion.accountId,
      sessionId: discussion.rolloutId || discussion.sessionId,
    });
    applyExpertChatTranscript(pane, discussion, transcript);
  } catch (error) {
    if (!expertChatPanes.includes(pane) || pane.discussion !== discussion) return;
    pane.loading = false;
    if (pane.messages.length === 0) pane.error = String(error);
    statusText = `Conversation : ${String(error)}`;
    if (activeView === "chat") refreshExpertChatPane(pane);
  } finally {
    pane.loadInFlight = false;
  }
};

const startExpertChatSync = (pane: ExpertChatPane) => {
  stopExpertChatSync(pane);
  const discussion = pane.discussion;
  if (!discussion) return;

  if (!isRemoteMode()) {
    pane.syncState = "polling";
    pane.fallbackPoll = window.setInterval(
      () => runWhenPageVisible(() => void loadExpertChatTranscript(pane)),
      LOCAL_TRANSCRIPT_POLL_INTERVAL_MS,
    );
    return;
  }

  pane.syncState = "connecting";
  const watchedSessionId = discussion.rolloutId || discussion.sessionId;
  pane.liveUnlisten = subscribeDiscussionUpdates(
    { accountId: discussion.accountId, sessionId: watchedSessionId },
    (message: DiscussionStreamMessage) => {
      if (!expertChatPanes.includes(pane) || pane.discussion !== discussion) return;
      if (
        message.type === "transcript" &&
        message.accountId === discussion.accountId &&
        message.sessionId === watchedSessionId
      ) {
        applyExpertChatTranscript(pane, discussion, message.transcript as DiscussionTranscriptView);
      } else if (message.type === "error") {
        pane.loading = false;
        if (pane.messages.length === 0) pane.error = message.message;
        statusText = `Conversation : ${message.message}`;
        if (activeView === "chat") refreshExpertChatPane(pane);
      }
    },
    (state: RealtimeConnectionState) => {
      if (!expertChatPanes.includes(pane) || pane.discussion !== discussion) return;
      pane.syncState = state;
      if (activeView === "chat") refreshExpertChatSyncIndicator(pane);
    },
  );
  pane.fallbackPoll = window.setInterval(() => {
    runWhenPageVisible(() => {
      if (pane.syncState !== "live") void loadExpertChatTranscript(pane);
    });
  }, 2000);
};

const discussionMatchesExpertPaneSession = (
  discussion: DiscussionSummary,
  pane: ExpertChatPane,
  sessionId: string,
): boolean => {
  if (pane.accountId && discussion.accountId !== pane.accountId) return false;
  const expectedNode = pane.executionTargetId?.trim().toLowerCase() ?? "";
  const discussionNode = discussion.nodeId?.trim().toLowerCase() ?? "";
  if (expectedNode && discussionNode && discussionNode !== expectedNode) return false;
  return discussion.sessionId === sessionId || discussion.rolloutId === sessionId;
};

const attachCreatedExpertChat = (
  pane: ExpertChatPane,
  sessionId: string,
): Promise<boolean> => {
  const normalizedSessionId = sessionId.trim();
  if (normalizedSessionId) pane.resumeSessionId = normalizedSessionId;
  if (pane.discussion) return Promise.resolve(true);
  if (pane.discussionAttachPromise) return pane.discussionAttachPromise;

  const pending = (async () => {
    let discussion = allDiscussions().find((candidate) =>
      discussionMatchesExpertPaneSession(candidate, pane, normalizedSessionId)
    ) ?? null;
    if (!discussion) {
      await refreshDiscussions();
      discussion = allDiscussions().find((candidate) =>
        discussionMatchesExpertPaneSession(candidate, pane, normalizedSessionId)
      ) ?? null;
    }
    if (!discussion || !expertChatPanes.includes(pane)) return false;
    const capturedWorkspace = userEnvironmentPath(pane.pendingWorkspace);
    if (capturedWorkspace) {
      // Conserver l'environnement capture a la creation empeche le panneau de
      // disparaitre de la grille avant la persistance du cwd dans le JSONL.
      discussion.folderPath = capturedWorkspace;
      pane.pendingWorkspace = capturedWorkspace;
    }
    pane.discussion = discussion;
    pane.resumeSessionId = discussion.rolloutId?.trim() || normalizedSessionId;
    pane.contextUsage = null;
    pane.accountId = discussion.accountId;
    pane.loading = false;
    pane.error = null;
    void loadChatModelCatalog(pane.accountId);
    startExpertChatSync(pane);
    persistExpertChats();
    void loadExpertChatTranscript(pane);
    return true;
  })();
  pane.discussionAttachPromise = pending;
  const clear = () => {
    if (pane.discussionAttachPromise === pending) pane.discussionAttachPromise = null;
  };
  void pending.then(clear, clear);
  return pending;
};

const automaticOrchestrationName = (objective: string): string => {
  const compact = objective.replace(/\s+/g, " ").trim();
  if (compact.length <= 120) return compact;
  return `${compact.slice(0, 117).trimEnd()}…`;
};

const launchAutomaticOrchestration = async (
  pane: ExpertChatPane,
  submission: QueuedChatSubmission,
  sessionId: string | null,
  decision: AutomaticOrchestrationDecision,
): Promise<boolean> => {
  const account = accountById(submission.accountId) ?? expertChatSelectedAccount(pane);
  sessionId = sessionId?.trim() || expertChatResumeSessionId(pane);
  const projectDir =
    discussionFolderPath(pane.discussion)
    ?? userEnvironmentPath(pane.pendingWorkspace)
    ?? userEnvironmentPath(currentWorkspace())
    ?? account?.projectDir
    ?? "";
  const queuedPrompts = pane.queuedSubmissions
    .map((queued) => queued.prompt.trim())
    .filter(Boolean);
  const objective = [
    submission.prompt.trim(),
    queuedPrompts.length
      ? `Demandes ajoutées pendant la décision de routage :\n${queuedPrompts.map((prompt, index) => `${index + 1}. ${prompt}`).join("\n")}`
      : "",
  ].filter(Boolean).join("\n\n");

  if (!account || !projectDir) {
    pane.automaticOrchestrationLaunching = false;
    if (!pane.draft.trim()) pane.draft = submission.prompt;
    statusText = !account
      ? "Orchestration automatique impossible : compte introuvable"
      : "Orchestration automatique impossible : environnement introuvable";
    persistExpertChats();
    refreshExpertChatPane(pane);
    return false;
  }

  statusText = `Orchestration automatique retenue · l’orchestrateur choisit de ${decision.workerCount} à ${MAX_ORCHESTRATION_WORKER_COUNT} workers utiles`;
  refreshExpertChatPane(pane);
  try {
    const selection = requireValidatedAccountModelSelection(
      account,
      submission.model,
      submission.reasoningEffort,
    );
    const created = await invoke<OrchestrationSnapshot>("create_orchestration", {
      request: {
        name: automaticOrchestrationName(submission.prompt) || null,
        objective,
        // Le workerCount adaptatif est un plancher. L'orchestrateur choisit
        // ensuite lui-meme la cardinalite utile jusqu'au plafond, en visant le
        // maximum de missions paralleles sans doublon ni travail artificiel.
        workerCount: decision.workerCount,
        adaptiveFanout: true,
        maxTaskCount: MAX_ORCHESTRATION_WORKER_COUNT,
        maxConcurrency: MAX_ORCHESTRATION_WORKER_COUNT,
        // Un nouveau chat n'a pas encore de session. Le backend cree alors
        // directement celle de l'orchestrateur pendant son tour de planification.
        orchestratorSessionId: sessionId || null,
        orchestratorAccountId: account.id,
        workerAccountIds: Array.from({ length: decision.workerCount }, () => account.id),
        accountId: account.id,
        projectDir,
        model: selection.model,
        reasoningEffort: selection.reasoningEffort,
        testCommand: orchestrationTestCommandDraft.trim() || "git diff --check",
        testTimeoutSeconds: Math.max(5, Math.min(1800, orchestrationTestTimeoutSeconds)),
      },
    });
    updateOrchestrationLocally(created);
    pane.automaticOrchestrationLaunching = false;
    pane.orchestrationId = created.id;
    pane.orchestrationRole = "orchestrator";
    pane.orchestrationTaskId = null;
    pane.orchestrationTesterId = null;
    pane.pendingWorkspace = orchestrationRequestedProjectDir(created);
    pane.draft = "";
    pane.queuedSubmissions = [];
    orchestrationWorkerCount = created.workerCount;
    syncOrchestrationChatPanes();
    persistExpertChats();
    statusText = `Orchestration automatique lancée · planification adaptative jusqu’à ${MAX_ORCHESTRATION_WORKER_COUNT} workers`;
    render();
    startAllExpertChatWork();
    startOrchestrationsPoll();
    void refreshOrchestrations();
    return true;
  } catch (error) {
    pane.automaticOrchestrationLaunching = false;
    if (!pane.draft.trim()) pane.draft = submission.prompt;
    statusText = `Mode orchestrateur non lancé : ${String(error)}`;
    persistExpertChats();
    refreshExpertChatPane(pane);
    focusExpertChatPrompt(pane);
    return false;
  }
};

const pinExplicitlyOpenedExpertChat = (pane: ExpertChatPane): void => {
  if (
    expertChatDisplayMode === "created"
    && !expertChatPaneIsCreatedByUser(pane)
  ) {
    explicitlyOpenedAuxiliaryChatVisibilityPins.add(pane.key);
  }
  pinExplicitlyOpenedBusyExpertChat(pane);
};

const applyExpertChatTurnSnapshot = async (
  pane: ExpertChatPane,
  snapshot: ChatTurnSnapshot,
) => {
  if (!expertChatPanes.includes(pane)) return;
  if (pane.turn && pane.turn.id !== 0 && snapshot.id !== pane.turn.id) return;
  const wasAvailable = expertChatPaneIsAvailable(pane);
  const previousStatus = pane.turn?.status;
  const previousStartedAt = pane.turn?.startedAt;
  const previousTurnId = pane.turn?.id;
  const turnIdentityChanged = previousTurnId !== snapshot.id;
  const automaticSubmission = pane.activeSubmission?.automaticOrchestration
    ? pane.activeSubmission
    : null;
  const automaticDecision =
    snapshot.status === "completed" && automaticSubmission
      ? automaticOrchestrationDecisionFromParts(snapshot.parts)
      : null;
  const shouldLaunchAutomaticOrchestration =
    !!automaticDecision
    && !pane.orchestrationRole
    && !pane.automaticOrchestrationLaunching;
  if (automaticDecision) {
    snapshot = {
      ...snapshot,
      parts: snapshot.parts.map((part) =>
        part.kind === "text" && parseAutomaticOrchestrationDecision(part.text)
          ? { ...part, text: automaticOrchestrationNotice(automaticDecision) }
          : part),
    };
  }
  if (shouldLaunchAutomaticOrchestration) {
    // Réserver immédiatement le lancement : un poll peut recevoir le même snapshot
    // pendant la synchronisation de la discussion et ne doit pas créer une seconde équipe.
    pane.automaticOrchestrationLaunching = true;
  }
  const automaticOrchestrationPending =
    !!automaticDecision
    && !pane.orchestrationRole
    && pane.automaticOrchestrationLaunching;
  if (
    previousStartedAt != null &&
    (previousTurnId === 0 || previousTurnId === snapshot.id)
  ) {
    snapshot = { ...snapshot, startedAt: Math.min(previousStartedAt, snapshot.startedAt) };
  }
  const learnedSessionId = snapshot.sessionId?.trim() || null;
  const sessionIdentityChanged = !!learnedSessionId && pane.resumeSessionId !== learnedSessionId;
  if (learnedSessionId) pane.resumeSessionId = learnedSessionId;
  pane.turn = snapshot;
  if (!chatTurnIsBusy(snapshot.status)) {
    automaticQuotaResumeVisibilityPins.delete(pane.key);
    explicitlyOpenedBusyChatVisibilityPins.delete(pane.key);
  }
  const quotaExhausted =
    snapshot.status === "failed" &&
    isQuotaExhaustionError(snapshot.error);
  const retryableFailure = failedTurnIsRetryable(snapshot, pane.activeSubmission);
  let attached = !!pane.discussion;
  if (sessionIdentityChanged && !attached) persistExpertChats();
  if (snapshot.sessionId) {
    const attachment = attachCreatedExpertChat(pane, snapshot.sessionId);
    if (shouldLaunchAutomaticOrchestration) {
      try {
        attached = await attachment;
      } catch (error) {
        pane.automaticOrchestrationLaunching = false;
        throw error;
      }
    } else {
      // L'index des rollouts est un cache secondaire. Il ne doit jamais bloquer
      // le statut, le flux de réponse ni l'adoption des autres chats pendant un
      // scan lent : le rattachement coalescé se termine en arrière-plan.
      void attachment.catch((error) => {
        if (!expertChatPanes.includes(pane)) return;
        statusText = `Indexation du chat : ${String(error)}`;
        if (activeView === "chat") refreshExpertChatSyncIndicator(pane);
      });
    }
  }

  if (snapshot.status === "finalizing") {
    statusText = "Reponse terminee, synchronisation…";
  } else if (snapshot.status === "completed") {
    statusText = automaticOrchestrationPending
      ? "Orchestration automatique retenue · préparation de l'équipe"
      : "Reponse terminee";
    if (attached) await loadExpertChatTranscript(pane);
    stopExpertChatTurnPoll(pane);
  } else if (snapshot.status === "failed") {
    pane.messages = markLatestPendingMessageFailed(pane.messages);
    statusText = snapshot.error || "La reponse a echoue";
    stopExpertChatTurnPoll(pane);
  } else if (snapshot.status === "cancelled") {
    statusText = "Reponse arretee";
    stopExpertChatTurnPoll(pane);
  } else {
    statusText = `${expertChatPanelModel(pane).providerLabel} travaille…`;
  }

  if (snapshot.status === "completed") persistExpertChats();

  if (retryableFailure) {
    scheduleExpertModelCapacityRetry(pane, snapshot);
  } else if (!chatTurnIsBusy(snapshot.status)) {
    resetExpertModelCapacityRetry(pane);
  }

  if (
    !quotaExhausted &&
    chatTurnIsBusy(previousStatus) &&
    !chatTurnIsBusy(snapshot.status)
  ) {
    void refreshLimitStatus(true, true);
  }
  if (chatTurnIsBusy(previousStatus) && !chatTurnIsBusy(snapshot.status)) {
    // Meme garde-fou que le chat principal : une action Microsoft mise en file
    // pendant ce tour doit etre proposee immediatement a la confirmation.
    void refreshMicrosoftPendingActions();
  }
  if (chatBecameAvailable(previousStatus, snapshot.status)) {
    void playChatReadySound(chatReadySoundPreferences);
  }
  if (activeView === "chat") {
    const displayChanged = refreshExpertChatDisplayAfterAvailabilityChange(
      pane,
      wasAvailable,
    );
    if (!displayChanged) {
      if (previousStatus !== snapshot.status || turnIdentityChanged) refreshExpertChatPane(pane);
      else refreshExpertChatFeed(pane);
    }
  }
  if (quotaExhausted && !pane.orchestrationId) {
    if (pane.discussion) {
      automaticallyTransferQuotaExhaustedDiscussion(pane.discussion, snapshot, pane);
    } else {
      void refreshQuotaAlternatives();
    }
  } else if (retryableFailure) {
    // Les messages suivants restent en file jusqu'a la reprise du meme modele.
  } else if (
    shouldLaunchAutomaticOrchestration
    && automaticSubmission
    && automaticDecision
  ) {
    void launchAutomaticOrchestration(
      pane,
      automaticSubmission,
      snapshot.sessionId?.trim() || expertChatResumeSessionId(pane),
      automaticDecision,
    );
  } else if (automaticOrchestrationPending) {
    // Le premier traitement de ce verdict possède la réservation et lancera l'équipe.
  } else if (!chatTurnIsBusy(snapshot.status)) {
    void drainExpertChatSubmissionQueue(pane);
    void drainNextGlobalChatCapacityQueue();
  }
};

const pollExpertChatTurn = async (pane: ExpertChatPane) => {
  if (!pane.turn || pane.turn.id === 0 || pane.turnPollInFlight || !expertChatPanes.includes(pane)) return;
  pane.turnPollInFlight = true;
  try {
    const snapshot = await invoke<ChatTurnSnapshot>("chat_turn_status", { id: pane.turn.id });
    await applyExpertChatTurnSnapshot(pane, snapshot);
  } catch (error) {
    statusText = `Suivi de la reponse : ${String(error)}`;
  } finally {
    pane.turnPollInFlight = false;
  }
};

const startExpertChatTurnPoll = (pane: ExpertChatPane) => {
  stopExpertChatTurnPoll(pane);
  pane.turnPoll = window.setInterval(
    () => {
      if (pane.queuedSubmissions.length > 0) void pollExpertChatTurn(pane);
      else runWhenPageVisible(() => void pollExpertChatTurn(pane));
    },
    CHAT_TURN_POLL_INTERVAL_MS,
  );
};

const focusExpertChatPrompt = (pane: ExpertChatPane) => {
  window.requestAnimationFrame(() => {
    const input = expertChatPaneRoot(pane)
      ?.querySelector<HTMLTextAreaElement>("[data-chat-control='prompt']");
    input?.focus();
    input?.setSelectionRange(input.value.length, input.value.length);
  });
};

const compactExpertChatContext = async (
  pane: ExpertChatPane,
  clearCommandDraft = false,
  automatic = false,
): Promise<boolean> => {
  const account = expertChatSelectedAccount(pane);
  const discussion = pane.discussion;
  const sessionId = expertChatResumeSessionId(pane);
  if (!account || accountProvider(account) !== "codex") {
    updateCompactionStatus("La commande /compact est disponible uniquement avec Codex");
    return false;
  }
  if (!isPlausibleSessionId(sessionId)) {
    updateCompactionStatus("Envoyez un premier message avant de compacter le contexte");
    return false;
  }
  if (pane.contextCompacting) {
    updateCompactionStatus("La compaction du contexte est déjà en cours");
    return false;
  }
  if (
    chatTurnIsBusy(pane.turn?.status)
    || pane.queuedSubmissions.length > 0
    || (discussion ? discussionHasRunningTurn(discussion) : false)
  ) {
    updateCompactionStatus("Attendez la fin de la réponse et de la file avant de lancer /compact");
    return false;
  }

  if (clearCommandDraft) pane.draft = "";
  pane.contextCompacting = true;
  updateCompactionStatus(automatic
    ? "Seuil de 400 000 tokens dépassé · compactage automatique en cours…"
    : "Compaction du contexte Codex en cours…");
  refreshExpertChatPane(pane);
  try {
    const result = await invoke<CompactChatSessionResult>("compact_chat_session", {
      accountId: account.id,
      sessionId,
    });
    if (!expertChatPanes.includes(pane)) return true;
    const usage = normalizeChatContextUsage(result.contextUsage);
    if (pane.discussion === discussion) {
      if (usage) pane.contextUsage = usage;
      await loadExpertChatTranscript(pane);
    }
    updateCompactionStatus(compactedContextStatus(usage, automatic));
    void refreshDiscussions();
    return true;
  } catch (error) {
    updateCompactionStatus(automatic
      ? `Compactage automatique impossible : ${String(error)}`
      : `/compact impossible : ${String(error)}`);
    return false;
  } finally {
    pane.contextCompacting = false;
    if (expertChatPanes.includes(pane)) {
      refreshExpertChatPane(pane);
      if (!automatic) focusExpertChatPrompt(pane);
    }
  }
};

const maybeAutoCompactExpertChatContext = (pane: ExpertChatPane): boolean => {
  const account = expertChatSelectedAccount(pane);
  const discussion = pane.discussion;
  const sessionId = expertChatResumeSessionId(pane);
  if (
    !expertChatPanes.includes(pane)
    || !account
    || accountProvider(account) !== "codex"
    || !isPlausibleSessionId(sessionId)
    || pane.contextCompacting
    || chatTurnIsBusy(pane.turn?.status)
    || pane.queuedSubmissions.length > 0
    || (discussion ? discussionHasRunningTurn(discussion) : false)
    || !claimAutomaticCompactionAttempt(account.id, sessionId, pane.contextUsage)
  ) return false;
  void compactExpertChatContext(pane, false, true);
  return true;
};

const sendExpertChatMessage = async (
  pane: ExpertChatPane,
  root: HTMLElement | null,
  promptOverride?: string,
  intent: ChatSubmitIntent = "message",
  queuedSubmission: QueuedChatSubmission | null = null,
): Promise<boolean> => {
  const input = queuedSubmission
    ? null
    : root?.querySelector<HTMLTextAreaElement>("[data-chat-control='prompt']") ?? null;
  const draftImageAttachments = queuedSubmission?.imageAttachments ?? pane.imageAttachments;
  const prompt = queuedSubmission?.prompt ?? chatSubmissionPrompt(
    promptOverride === undefined ? input : null,
    promptOverride ?? pane.draft,
    intent,
    draftImageAttachments.length > 0,
  );
  const account = queuedSubmission
    ? accountById(queuedSubmission.accountId)
    : expertChatSelectedAccount(pane);
  if (!prompt || !account) {
    statusText = account
      ? intent === "goal" ? "Décrivez le goal" : "Ecrivez un message"
      : "Ajoutez d'abord un compte agent";
    return false;
  }
  if (intent === "goal" && !providerSupportsGoals(accountProvider(account))) {
    statusText = "Les goals ne sont pas pris en charge par ce fournisseur";
    return false;
  }
  if (
    !queuedSubmission
    && intent === "message"
    && draftImageAttachments.length === 0
    && isCompactSlashCommand(prompt)
  ) {
    return compactExpertChatContext(pane, true);
  }
  if (pane.contextCompacting) {
    updateCompactionStatus("Attendez la fin de la compaction avant d'envoyer un message");
    return false;
  }
  const preferences = queuedSubmission
    ? (() => {
        const selection = validatedAccountModelSelection(
          account,
          queuedSubmission.model,
          queuedSubmission.reasoningEffort,
        );
        return {
          model: selection.model,
          reasoningEffort: selection.reasoningEffort,
          changed: false,
          error: selection.error,
        };
      })()
    : readChatPreferences(account, root ?? document);
  if (preferences.error) {
    const modelInput = root?.querySelector<HTMLInputElement>("[data-chat-control='model']");
    modelInput?.setCustomValidity(preferences.error);
    modelInput?.reportValidity();
    statusText = preferences.error;
    return false;
  }
  if (preferences.changed && !await persistChatPreferences(account.id)) return false;

  const automaticOrchestration =
    intent === "message"
    && pane.automaticOrchestrationEnabled
    && !pane.orchestrationRole
    && !pane.autonomousAgentId;
  const submission = queuedSubmission ?? {
    prompt,
    imageAttachments: [...draftImageAttachments],
    accountId: account.id,
    mode: pane.mode,
    model: preferences.model,
    reasoningEffort: preferences.reasoningEffort,
    enabledTools: [...pane.enabledTools],
    agentSkills: [...chatAgentSkillPrompts(pane.enabledTools)],
    automaticOrchestration,
  };
  const displayPrompt = chatBubbleText(prompt, submission.displayText);
  const resourceAdmissionPaused = chatResourceAdmissionPaused();
  if (
    chatTurnIsBusy(pane.turn?.status) ||
    (!queuedSubmission && pane.queuedSubmissions.length > 0) ||
    resourceAdmissionPaused
  ) {
    if (queuedSubmission) pane.queuedSubmissions.unshift(submission);
    else pane.queuedSubmissions.push(submission);
    if (!queuedSubmission) pane.draft = "";
    if (!queuedSubmission) {
      disposeChatImagePreviews(pane.imageAttachments);
      pane.imageAttachments = [];
    }
    statusText = chatTurnIsBusy(pane.turn?.status)
      ? `Message mis en attente · ${pane.queuedSubmissions.length} dans la file`
      : resourceAdmissionPaused
        ? "Mémoire temporairement saturée · message en attente"
        : "Envoi du prochain message en attente";
    persistExpertChats();
    refreshExpertChatPane(pane);
    if (!queuedSubmission) focusExpertChatPrompt(pane);
    if (!chatTurnIsBusy(pane.turn?.status) && !resourceAdmissionPaused) {
      void drainExpertChatSubmissionQueue(pane);
    }
    return true;
  }

  if (submission.automaticOrchestration) {
    // Le bouton est une commande, pas une suggestion adressee au modele. Creer
    // l'equipe avant tout tour normal garantit qu'aucun agent principal ne peut
    // commencer la tache seul ni decider silencieusement de ne pas orchestrer.
    const messagesBeforeLaunch = pane.messages;
    const launchedAt = Math.floor(Date.now() / 1000);
    pane.automaticOrchestrationLaunching = true;
    pane.error = null;
    pane.messages = [
      ...pane.messages,
      {
        role: "user",
        text: displayPrompt,
        timestamp: launchedAt,
        deliveryState: "pending",
      },
    ];
    statusText = `Mode orchestrateur · choix de 1 à ${MAX_ORCHESTRATION_WORKER_COUNT} workers par l’orchestrateur`;
    persistExpertChats();
    refreshExpertChatPane(pane);

    const launched = await launchAutomaticOrchestration(
      pane,
      submission,
      expertChatResumeSessionId(pane),
      {
        workerCount: 1,
        reason: "Mode orchestrateur actif · cardinalité choisie par l’orchestrateur",
      },
    );
    if (!launched) {
      pane.messages = messagesBeforeLaunch;
      // Un moteur d'orchestration indisponible ne doit jamais rendre le chat
      // entier inutilisable. Revenir explicitement au chat direct, desactiver
      // le bouton pour les messages suivants et rejouer exactement la demande
      // conservee (ainsi que ses pieces jointes) sans demander une seconde
      // action a l'utilisateur.
      pane.automaticOrchestrationEnabled = false;
      statusText = "Orchestrateur indisponible · lancement du chat direct";
      persistExpertChats();
      refreshExpertChatPane(pane);
      return sendExpertChatMessage(
        pane,
        expertChatPaneRoot(pane),
        submission.prompt,
        intent,
      );
    }
    pane.messages = pane.messages.map((message, index) =>
      index === pane.messages.length - 1 && message.deliveryState === "pending"
        ? { role: message.role, text: message.text, timestamp: message.timestamp }
        : message
    );
    if (!queuedSubmission) {
      pane.draft = "";
      disposeChatImagePreviews(pane.imageAttachments);
      pane.imageAttachments = [];
    }
    persistExpertChats();
    refreshExpertChatPane(pane);
    return true;
  }

  const wasAvailable = expertChatPaneIsAvailable(pane);
  if (!submission.automaticCapacityRetry) resetExpertModelCapacityRetry(pane);
  const turnBeforeStart = pane.turn;
  const messagesBeforeStart = pane.messages;
  pane.activeSubmission = submission;
  const resumeSessionId =
    submission.resumeSessionId ??
    pane.discussion?.rolloutId ??
    pane.discussion?.sessionId ??
    null;
  if (!queuedSubmission) pane.draft = "";
  if (!queuedSubmission) {
    disposeChatImagePreviews(pane.imageAttachments);
    pane.imageAttachments = [];
  }
  pane.error = null;
  pane.messages = [
    ...pane.messages,
    {
      role: "user",
      text: displayPrompt,
      timestamp: Math.floor(Date.now() / 1000),
      deliveryState: "pending",
    },
  ];
  pane.turn = {
    id: 0,
    accountId: account.id,
    sessionId: resumeSessionId,
    status: "running",
    startedAt: Math.floor(Date.now() / 1000),
    finishedAt: null,
    error: null,
    activities: [
      {
        id: "preparing",
        kind: "think",
        label: `${providerLabel(accountProvider(account))} prepare la reponse`,
        detail: null,
        status: "running",
      },
    ],
    thoughts: [
      {
        id: "preparing-thought",
        kind: "reasoning",
        text: `${providerLabel(accountProvider(account))} analyse la demande et prépare la prochaine étape.`,
        status: "running",
      },
    ],
    parts: [],
  };
  if (
    shouldPinActiveExpertChatDuringTurn(
      expertChatDisplayMode,
      wasAvailable,
      pane.key === activeExpertChatKey,
    )
  ) {
    pinExplicitlyOpenedBusyExpertChat(pane);
  }
  pane.followLatest = true;
  pane.scrollTop = 0;
  statusText = `${providerLabel(accountProvider(account))} travaille…`;
  persistExpertChats();
  const displayChanged = refreshExpertChatDisplayAfterAvailabilityChange(
    pane,
    wasAvailable,
  );
  if (!displayChanged) refreshExpertChatPane(pane);
  if (!queuedSubmission && !displayChanged) focusExpertChatPrompt(pane);

  try {
    const snapshot = await invoke<ChatTurnSnapshot>("start_chat_turn", {
      accountId: account.id,
      sessionId: resumeSessionId,
      prompt,
      imageAttachments: chatImageAttachmentPayloads(submission.imageAttachments),
      projectDir:
        discussionFolderPath(pane.discussion) ?? pane.pendingWorkspace ?? currentWorkspace() ?? account.projectDir ?? null,
      mode: submission.mode,
      model: preferences.model,
      reasoningEffort: preferences.reasoningEffort,
      sourceChatKey: pane.key,
      targetNodeId: resumeSessionId ? null : pane.executionTargetId,
      agentTools: submission.enabledTools.filter(isChatAgentModeId),
      agentSkills: submission.agentSkills,
    });
    if (!expertChatPanes.includes(pane)) return false;
    const wasAvailableBeforeSnapshot = expertChatPaneIsAvailable(pane);
    const optimisticStartedAt = pane.turn?.startedAt;
    pane.turn = optimisticStartedAt == null
      ? snapshot
      : { ...snapshot, startedAt: Math.min(optimisticStartedAt, snapshot.startedAt) };
    startExpertChatTurnPoll(pane);
    await applyExpertChatTurnSnapshot(pane, pane.turn);
    void drainNextGlobalChatCapacityQueue();
    refreshExpertChatDisplayAfterAvailabilityChange(
      pane,
      wasAvailableBeforeSnapshot,
    );
    return snapshot.status !== "failed" && snapshot.status !== "cancelled";
  } catch (error) {
    if (!expertChatPanes.includes(pane)) return false;
    if (isNodeCapacityError(String(error))) {
      pauseChatResourceAdmission();
      pane.turn = turnBeforeStart;
      pane.messages = messagesBeforeStart;
      pane.activeSubmission = null;
      pane.queuedSubmissions.unshift(submission);
      statusText = "Mémoire temporairement saturée · message conservé dans la file";
      persistExpertChats();
      refreshExpertChatPane(pane);
      return true;
    }
    // Un poll ou une notification runtime a pu deja adopter le vrai tour serveur
    // (id != 0) avant que cette requete echoue : ne jamais l'ecraser en « failed ».
    if (pane.turn && pane.turn.id !== 0) {
      return chatTurnIsBusy(pane.turn.status);
    }
    // Coupure de transport ambigue : le serveur a peut-etre deja committe et lance
    // le tour (une image alourdit la requete et elargit cette fenetre). Reconcilier
    // via list_active_chat_turns — adoption par sourceChatKey — au lieu de marquer
    // « failed », ce qui afficherait « Disponible » alors que l'agent reflechit.
    if (!isDefiniteChatTurnRejection(error) && pane.turn?.status === "running") {
      statusText = "Connexion interrompue — vérification du tour en cours…";
      refreshExpertChatPane(pane);
      await refreshActiveChatTurns();
      if (!expertChatPanes.includes(pane)) return false;
      if (pane.turn && pane.turn.id !== 0) {
        return chatTurnIsBusy(pane.turn.status);
      }
      // Aucun tour serveur actif : le tour n'a vraiment pas demarre -> vrai echec.
    }
    const wasAvailableBeforeFailure = expertChatPaneIsAvailable(pane);
    pane.messages = markLatestPendingMessageFailed(pane.messages);
    const failedTurn = {
      ...pane.turn,
      id: 0,
      status: "failed",
      finishedAt: Math.floor(Date.now() / 1000),
      error: String(error),
    } as ChatTurnSnapshot;
    pane.turn = failedTurn;
    automaticQuotaResumeVisibilityPins.delete(pane.key);
    explicitlyOpenedBusyChatVisibilityPins.delete(pane.key);
    statusText = String(error);
    // Chemin catch : reprise sur saturation uniquement (voir ci-dessus).
    const modelCapacityReached = isModelCapacityError(String(error));
    if (modelCapacityReached) {
      scheduleExpertModelCapacityRetry(pane, failedTurn);
    } else {
      resetExpertModelCapacityRetry(pane);
    }
    if (isQuotaExhaustionError(String(error))) {
      if (pane.discussion) {
        automaticallyTransferQuotaExhaustedDiscussion(pane.discussion, failedTurn, pane);
      } else {
        void refreshQuotaAlternatives();
      }
    } else if (!modelCapacityReached) {
      void drainExpertChatSubmissionQueue(pane);
    }
    if (!refreshExpertChatDisplayAfterAvailabilityChange(pane, wasAvailableBeforeFailure)) {
      refreshExpertChatPane(pane);
    }
    return false;
  }
};

const drainExpertChatSubmissionQueue = async (pane: ExpertChatPane): Promise<void> => {
  if (
    !expertChatPanes.includes(pane) ||
    pane.queueDrainInFlight ||
    chatTurnIsBusy(pane.turn?.status) ||
    chatResourceAdmissionPaused() ||
    pane.queuedSubmissions.length === 0
  ) {
    return;
  }
  const submission = pane.queuedSubmissions.shift();
  if (!submission) return;
  pane.queueDrainInFlight = true;
  try {
    await sendExpertChatMessage(
      pane,
      expertChatPaneRoot(pane),
      undefined,
      "message",
      submission,
    );
  } finally {
    pane.queueDrainInFlight = false;
    if (
      expertChatPanes.includes(pane) &&
      !chatTurnIsBusy(pane.turn?.status) &&
      !chatResourceAdmissionPaused() &&
      !isQuotaExhaustionError(pane.turn?.error) &&
      !isModelCapacityError(pane.turn?.error) &&
      pane.queuedSubmissions.length > 0
    ) {
      void drainExpertChatSubmissionQueue(pane);
    }
  }
};

/**
 * Lance un seul message global en attente lorsqu'une place se libere. Chaque
 * lancement pose immediatement un tour optimiste id=0. En cas de pression
 * memoire, le serveur met temporairement cette reprise en pause.
 */
const drainNextGlobalChatCapacityQueue = async (): Promise<void> => {
  if (chatResourceAdmissionPaused()) return;
  if (
    chatQueuedSubmissions.length > 0 &&
    !chatQueueDrainInFlight &&
    !chatTurnIsBusy(chatTurn?.status)
  ) {
    await drainChatSubmissionQueue();
    return;
  }
  const pane = expertChatPanes.find((candidate) =>
    candidate.queuedSubmissions.length > 0 &&
    !candidate.queueDrainInFlight &&
    !chatTurnIsBusy(candidate.turn?.status)
  );
  if (pane) await drainExpertChatSubmissionQueue(pane);
};

const stopExpertChatTurn = async (pane: ExpertChatPane) => {
  if (!pane.turn || pane.turn.status !== "running") return;
  if (pane.turn.id === 0) {
    const wasAvailable = expertChatPaneIsAvailable(pane);
    pane.turn = { ...pane.turn, status: "cancelled" };
    automaticQuotaResumeVisibilityPins.delete(pane.key);
    explicitlyOpenedBusyChatVisibilityPins.delete(pane.key);
    stopExpertChatTurnPoll(pane);
    const displayChanged = refreshExpertChatDisplayAfterAvailabilityChange(
      pane,
      wasAvailable,
    );
    if (!displayChanged) {
      refreshExpertChatPane(pane);
      focusExpertChatPrompt(pane);
    }
    void drainExpertChatSubmissionQueue(pane);
    return;
  }
  try {
    await applyExpertChatTurnSnapshot(
      pane,
      await invoke<ChatTurnSnapshot>("stop_chat_turn", { id: pane.turn.id }),
    );
  } catch (error) {
    statusText = String(error);
  }
};

const startAllExpertChatWork = () => {
  const visiblePanes = new Set(visibleExpertChatPanes());
  const currentEnvironmentPanes = new Set(expertChatPanesForCurrentEnvironment());
  expertChatPanes.forEach((pane) => {
    if (visiblePanes.has(pane) && pane.discussion) {
      startExpertChatSync(pane);
      void loadExpertChatTranscript(pane);
    } else {
      stopExpertChatSync(pane);
    }
    if (
      (
        visiblePanes.has(pane)
        || pane.queuedSubmissions.length > 0
        || (
          expertChatDisplayMode !== "all"
          && currentEnvironmentPanes.has(pane)
        )
      )
      && pane.turn
      && chatTurnIsBusy(pane.turn.status)
      && pane.turn.id !== 0
    ) {
      startExpertChatTurnPoll(pane);
    } else {
      stopExpertChatTurnPoll(pane);
    }
  });
};

const activateExpertChatPane = (pane: ExpertChatPane, focusPrompt = false) => {
  if (!expertChatPanes.includes(pane)) return;
  pane.userOpened = true;
  pendingActiveExpertChatKey = null;
  pinExplicitlyOpenedExpertChat(pane);
  activeExpertChatKey = pane.key;
  moveExpertChatPageToPane(pane);
  document.querySelectorAll<HTMLElement>("[data-chat-panel]").forEach((panel) => {
    panel.classList.toggle("active", panel.dataset.chatPanel === pane.key);
  });
  persistExpertChats();
  if (focusPrompt) {
    expertChatPaneRoot(pane)
      ?.querySelector<HTMLTextAreaElement>("[data-chat-control='prompt']")
      ?.focus();
  }
};

const setExpertChatPage = (requestedPage: number) => {
  captureAllExpertChatScroll();
  const environmentPanes = displayedExpertChatPanesForCurrentEnvironment();
  expertChatPage = clampExpertChatPage(
    requestedPage,
    environmentPanes.length,
    effectiveExpertChatPageSizeMode(),
  );
  const panes = visibleExpertChatPanes();
  if (!panes.some((pane) => pane.key === activeExpertChatKey)) {
    activeExpertChatKey = panes[0]?.key ?? null;
  }
  statusText = expertChatStatusText();
  persistExpertChats();
  render();
  startAllExpertChatWork();
};

const addExpertChatPane = (
  accountId: string | null = null,
  options: {
    mode?: ChatMode;
    pendingWorkspace?: string | null;
    executionTargetId?: string | null;
    automaticOrchestrationEnabled?: boolean;
  } = {},
) => {
  const environmentPath = userEnvironmentPath(options.pendingWorkspace ?? currentWorkspace());
  if (!environmentPath) {
    openTerminalEnvironmentMenu();
    return null;
  }
  const pane = createExpertChatPane(null, {
    userOpened: true,
    accountId: accountId ?? selectedAccountId ?? settings?.defaultAccountId ?? null,
    pendingWorkspace: environmentPath,
    mode: options.mode,
    automaticOrchestrationEnabled: options.automaticOrchestrationEnabled,
    executionTargetId: options.executionTargetId === undefined
      ? workspaceExecutionTargetIdForPath(environmentPath)
      : normalizeWorkspaceExecutionTargetId(options.executionTargetId),
  });
  expertChatPanes.push(pane);
  activeExpertChatKey = pane.key;
  moveExpertChatPageToPane(pane);
  activeView = "chat";
  statusText = expertChatStatusText();
  persistExpertChats();
  render();
  startAllExpertChatWork();
  window.setTimeout(() => activateExpertChatPane(pane, true), 0);
  return pane;
};

const openDiscussionInExpert = (
  discussion: DiscussionSummary,
  revealBusyChat = false,
): ExpertChatPane => {
  const existing = expertChatPanes.find(
    (pane) =>
      pane.discussion?.accountId === discussion.accountId
      && pane.discussion.sessionId === discussion.sessionId,
  );
  if (existing) {
    existing.userOpened = true;
    if (revealBusyChat) pinExplicitlyOpenedBusyExpertChat(existing);
    activeView = "chat";
    activateExpertChatPane(existing);
    statusText = expertChatStatusText();
    render();
    startAllExpertChatWork();
    return existing;
  }
  const pane = createExpertChatPane(discussion, { userOpened: true });
  expertChatPanes.push(pane);
  if (revealBusyChat) pinExplicitlyOpenedBusyExpertChat(pane);
  activeExpertChatKey = pane.key;
  moveExpertChatPageToPane(pane);
  activeView = "chat";
  statusText = expertChatStatusText();
  void loadChatModelCatalog(pane.accountId);
  persistExpertChats();
  render();
  startAllExpertChatWork();
  return pane;
};

const dismissedOrchestrationWorkerPanes = new Set<string>();
const dismissedOrchestrationTesterPanes = new Set<string>();

const orchestrationWorkerPaneKey = (runId: string, taskId: string): string =>
  `${runId}:${taskId}`;

const orchestrationTesterPaneKey = (runId: string, testerId: string): string =>
  `${runId}:${testerId}`;

const attachOrchestrationDiscussion = (
  pane: ExpertChatPane,
  sessionId: string | null,
  accountId: string,
): boolean => {
  let changed = false;
  const normalizedSessionId = sessionId?.trim() || null;
  if (normalizedSessionId && pane.resumeSessionId !== normalizedSessionId) {
    pane.resumeSessionId = normalizedSessionId;
    changed = true;
  }
  if (pane.accountId !== accountId) {
    pane.accountId = accountId;
    void loadChatModelCatalog(accountId);
    changed = true;
  }
  const attachedDiscussionMatches = !!pane.discussion
    && !!normalizedSessionId
    && discussionForSession([pane.discussion], accountId, normalizedSessionId) !== null;
  if (
    pane.discussion
    && !attachedDiscussionMatches
  ) {
    stopExpertChatSync(pane);
    pane.discussion = null;
    pane.messages = [];
    pane.contextUsage = null;
    pane.loading = false;
    pane.error = null;
    changed = true;
  }
  if (!normalizedSessionId || pane.discussion) return changed;
  const discussion = discussionForSession(allDiscussions(), accountId, normalizedSessionId);
  if (!discussion) return changed;
  pane.discussion = discussion;
  pane.contextUsage = null;
  pane.accountId = discussion.accountId;
  pane.loading = true;
  pane.error = null;
  void loadChatModelCatalog(pane.accountId);
  if (activeView === "chat") {
    startExpertChatSync(pane);
    void loadExpertChatTranscript(pane);
  }
  return true;
};

const syncOrchestrationChatPanes = (): {
  changed: boolean;
  missingDiscussions: boolean;
} => {
  let changed = false;
  let missingDiscussions = false;
  const runsById = new Map(orchestrations.map((run) => [run.id, run]));
  const activeEnvironment = userEnvironmentPath(currentWorkspace());
  const activeEnvironmentId = activeEnvironment
    ? workspaceIdForPath(activeEnvironment)
    : null;

  if (orchestrationsLoaded) {
    expertChatPanes = expertChatPanes.filter((pane) => {
      if (!pane.orchestrationId || runsById.has(pane.orchestrationId)) return true;
      if (pane.orchestrationRole === "worker" || pane.orchestrationTesterId) {
        stopExpertChatSync(pane);
        stopExpertChatTurnPoll(pane);
        changed = true;
        return false;
      }
      pane.orchestrationId = null;
      pane.orchestrationRole = null;
      pane.orchestrationTaskId = null;
      pane.orchestrationTesterId = null;
      changed = true;
      return true;
    });
  }

  orchestrations.forEach((run) => {
    const groupProjectDir = orchestrationRequestedProjectDir(run);
    const groupEnvironment = userEnvironmentPath(groupProjectDir);
    const alreadyLinked = expertChatPanes.some((pane) => pane.orchestrationId === run.id);
    // Une orchestration peut avoir ete lancee dans un autre onglet ou avant un
    // rechargement. La liste serveur est alors la seule source de verite : on
    // adopte les equipes de l'environnement ouvert sans materialiser les chats
    // de tous les environnements quand leur nombre devient important.
    if (!groupEnvironment) return;
    if (
      !alreadyLinked
      && run.status === "completed"
      && (
        !activeEnvironmentId
        || workspaceIdForPath(groupEnvironment) !== activeEnvironmentId
      )
    ) return;
    const taskIds = new Set(run.tasks.map((task) => task.id));
    const testerIds = new Set(run.testers.map((tester) => tester.id));

    let orchestratorPane = expertChatPanes.find(
      (pane) =>
        pane.orchestrationId === run.id
        && pane.orchestrationRole === "orchestrator"
        && !pane.orchestrationTesterId,
    );
    if (!orchestratorPane) {
      orchestratorPane = createExpertChatPane(null, {
        accountId: orchestrationOrchestratorAccountId(run),
        pendingWorkspace: groupProjectDir,
        mode: "build",
        orchestrationId: run.id,
        orchestrationRole: "orchestrator",
        orchestrationTaskId: null,
        orchestrationTesterId: null,
      });
      expertChatPanes.push(orchestratorPane);
      changed = true;
    }

    expertChatPanes
      .filter((pane) => pane.orchestrationId === run.id)
      .forEach((pane) => {
        if (pane.pendingWorkspace !== groupProjectDir) {
          pane.pendingWorkspace = groupProjectDir;
          changed = true;
        }
        if (pane.orchestrationRole === "orchestrator" && !pane.orchestrationTesterId) {
          const attached = attachOrchestrationDiscussion(
            pane,
            run.orchestratorSessionId,
            orchestrationOrchestratorAccountId(run),
          );
          changed = attached || changed;
          if (run.orchestratorSessionId && !pane.discussion) missingDiscussions = true;
        }
      });

    expertChatPanes = expertChatPanes.filter((pane) => {
      if (
        pane.orchestrationId !== run.id
        || pane.orchestrationRole !== "orchestrator"
        || !pane.orchestrationTesterId
        || testerIds.has(pane.orchestrationTesterId)
      ) {
        return true;
      }
      stopExpertChatSync(pane);
      stopExpertChatTurnPoll(pane);
      changed = true;
      return false;
    });

    run.testers.forEach((tester) => {
      const dismissedKey = orchestrationTesterPaneKey(run.id, tester.id);
      let pane = expertChatPanes.find(
        (candidate) =>
          candidate.orchestrationId === run.id
          && candidate.orchestrationRole === "orchestrator"
          && candidate.orchestrationTesterId === tester.id,
      );
      if (!pane && !dismissedOrchestrationTesterPanes.has(dismissedKey)) {
        pane = createExpertChatPane(null, {
          accountId: orchestrationOrchestratorAccountId(run),
          pendingWorkspace: groupProjectDir,
          mode: "build",
          orchestrationId: run.id,
          orchestrationRole: "orchestrator",
          orchestrationTaskId: null,
          orchestrationTesterId: tester.id,
        });
        expertChatPanes.push(pane);
        changed = true;
      }
      if (!pane) return;
      const attached = attachOrchestrationDiscussion(
        pane,
        tester.sessionId,
        orchestrationOrchestratorAccountId(run),
      );
      changed = attached || changed;
      if (tester.sessionId && !pane.discussion) missingDiscussions = true;
    });

    expertChatPanes = expertChatPanes.filter((pane) => {
      if (
        pane.orchestrationId !== run.id
        || pane.orchestrationRole !== "worker"
        || !pane.orchestrationTaskId
        || taskIds.has(pane.orchestrationTaskId)
      ) {
        return true;
      }
      stopExpertChatSync(pane);
      stopExpertChatTurnPoll(pane);
      changed = true;
      return false;
    });

    run.tasks.forEach((task) => {
      const dismissedKey = orchestrationWorkerPaneKey(run.id, task.id);
      let pane = expertChatPanes.find(
        (candidate) =>
          candidate.orchestrationId === run.id
          && candidate.orchestrationRole === "worker"
          && candidate.orchestrationTaskId === task.id,
      );
      if (!pane && !dismissedOrchestrationWorkerPanes.has(dismissedKey)) {
        pane = createExpertChatPane(null, {
          userOpened: false,
          accountId: orchestrationWorkerAccountId(run, task),
          pendingWorkspace: groupProjectDir,
          mode: "build",
          orchestrationId: run.id,
          orchestrationRole: "worker",
          orchestrationTaskId: task.id,
        });
        expertChatPanes.push(pane);
        changed = true;
      }
      if (!pane) return;
      const attached = attachOrchestrationDiscussion(
        pane,
        task.sessionId,
        orchestrationWorkerAccountId(run, task),
      );
      changed = attached || changed;
      if (task.sessionId && !pane.discussion) missingDiscussions = true;
    });
  });

  if (changed) {
    reconcileExpertChatPage();
    persistExpertChats();
  }
  return { changed, missingDiscussions };
};

const releaseOrchestrationChatPanes = (runId: string) => {
  expertChatPanes = expertChatPanes.filter((pane) => {
    if (pane.orchestrationId !== runId) return true;
    if (pane.orchestrationRole === "worker" || pane.orchestrationTesterId) {
      stopExpertChatSync(pane);
      stopExpertChatTurnPoll(pane);
      return false;
    }
    pane.orchestrationId = null;
    pane.orchestrationRole = null;
    pane.orchestrationTaskId = null;
    pane.orchestrationTesterId = null;
    return true;
  });
  [...dismissedOrchestrationWorkerPanes]
    .filter((key) => key.startsWith(`${runId}:`))
    .forEach((key) => dismissedOrchestrationWorkerPanes.delete(key));
  [...dismissedOrchestrationTesterPanes]
    .filter((key) => key.startsWith(`${runId}:`))
    .forEach((key) => dismissedOrchestrationTesterPanes.delete(key));
  reconcileExpertChatPage();
  persistExpertChats();
};

type ExpertChatAccountTransferSnapshot = {
  discussion: DiscussionSummary | null;
  accountId: string | null;
  messages: ChatMessage[];
  loading: boolean;
  error: string | null;
  truncated: boolean;
  contextUsage: ChatContextWindowUsage | null;
  turn: ChatTurnSnapshot | null;
  draft: string;
  queuedSubmissions: QueuedChatSubmission[];
  queueDrainInFlight: boolean;
  activeSubmission: QueuedChatSubmission | null;
  capacityRetryAttempt: number;
  mode: ChatMode;
  enabledTools: ChatAgentToolId[];
  pendingWorkspace: string | null;
  historyOpen: boolean;
  followLatest: boolean;
  scrollTop: number;
};

const captureExpertChatAccountTransfer = (
  pane: ExpertChatPane,
): ExpertChatAccountTransferSnapshot => ({
  discussion: pane.discussion,
  accountId: pane.accountId,
  messages: [...pane.messages],
  loading: pane.loading,
  error: pane.error,
  truncated: pane.truncated,
  contextUsage: pane.contextUsage,
  turn: pane.turn,
  draft: pane.draft,
  queuedSubmissions: pane.queuedSubmissions.map((submission) => ({ ...submission })),
  queueDrainInFlight: pane.queueDrainInFlight,
  activeSubmission: pane.activeSubmission ? { ...pane.activeSubmission } : null,
  capacityRetryAttempt: pane.capacityRetryAttempt,
  mode: pane.mode,
  enabledTools: [...pane.enabledTools],
  pendingWorkspace: pane.pendingWorkspace,
  historyOpen: pane.historyOpen,
  followLatest: pane.followLatest,
  scrollTop: pane.scrollTop,
});

const prepareExpertChatAccountTransfer = (
  pane: ExpertChatPane,
  discussion: DiscussionSummary | null,
  account: AccountProfile,
  folderPath: string,
  activatePane: boolean,
) => {
  stopExpertChatSync(pane);
  stopExpertChatTurnPoll(pane);
  resetExpertModelCapacityRetry(pane);

  pane.discussion = discussion;
  pane.accountId = account.id;
  pane.contextUsage = null;
  pane.contextCompacting = false;
  pane.loading = false;
  pane.error = null;
  pane.turn = null;
  pane.activeSubmission = null;
  pane.capacityRetryAttempt = 0;
  pane.queueDrainInFlight = false;
  pane.queuedSubmissions = pane.queuedSubmissions.map((submission) => ({
    ...submission,
    accountId: account.id,
    model: accountModel(account),
    reasoningEffort: accountProvider(account) === "codex"
      ? accountReasoningEffort(account)
      : null,
    automaticCapacityRetry: false,
    resumeSessionId: null,
  }));
  pane.mode = "build";
  pane.pendingWorkspace = folderPath;
  pane.loadInFlight = false;
  pane.turnPollInFlight = false;
  if (activatePane) {
    activeExpertChatKey = pane.key;
    moveExpertChatPageToPane(pane);
    activeView = "chat";
  }

  const transition = expertChatAccountTransitions.get(pane.key);
  if (transition) {
    expertChatAccountTransitions.set(pane.key, {
      ...transition,
      detail: `Contexte conservé · reprise avec ${account.label}`,
    });
  }

  void loadChatModelCatalog(account.id);
  if (discussion) startExpertChatSync(pane);
  persistExpertChats();
  if (expertChatPaneRoot(pane)) refreshExpertChatPane(pane);
  else if (activatePane) render();
  refreshChatSidebarConversations();
};

const restoreExpertChatAfterAccountTransfer = (
  pane: ExpertChatPane,
  snapshot: ExpertChatAccountTransferSnapshot,
) => {
  stopExpertChatSync(pane);
  stopExpertChatTurnPoll(pane);
  resetExpertModelCapacityRetry(pane);
  expertChatAccountTransitions.delete(pane.key);
  automaticQuotaResumeVisibilityPins.delete(pane.key);

  pane.discussion = snapshot.discussion;
  pane.accountId = snapshot.accountId;
  pane.messages = snapshot.messages;
  pane.loading = snapshot.loading;
  pane.error = snapshot.error;
  pane.truncated = snapshot.truncated;
  pane.contextUsage = snapshot.contextUsage;
  pane.contextCompacting = false;
  pane.turn = snapshot.turn;
  pane.draft = snapshot.draft;
  pane.queuedSubmissions = snapshot.queuedSubmissions;
  pane.queueDrainInFlight = snapshot.queueDrainInFlight;
  pane.activeSubmission = snapshot.activeSubmission;
  pane.capacityRetryAttempt = snapshot.capacityRetryAttempt;
  pane.capacityRetryTimer = null;
  pane.mode = snapshot.mode;
  pane.enabledTools = snapshot.enabledTools;
  pane.pendingWorkspace = snapshot.pendingWorkspace;
  pane.historyOpen = snapshot.historyOpen;
  pane.followLatest = snapshot.followLatest;
  pane.scrollTop = snapshot.scrollTop;
  pane.loadInFlight = false;
  pane.turnPollInFlight = false;

  if (pane.discussion) {
    startExpertChatSync(pane);
    void loadExpertChatTranscript(pane);
  }
  persistExpertChats();
  if (expertChatPaneRoot(pane)) refreshExpertChatPane(pane);
  else if (activeView !== "chat") render();
  refreshChatSidebarConversations();
};

// Ouvre la continuation dans la grille de chats et demarre son premier tour en
// arriere-plan. Les boutons « Reprendre » et « Deplacer + reprendre » restent
// ainsi dans l'interface de chat, sans creer de terminal interactif.
type ResumeDiscussionInChatOptions = {
  preserveNavigation?: boolean;
  activateTarget?: boolean;
};

const resumeDiscussionInChat = async (
  discussion: DiscussionSummary | null,
  accountId: string,
  folderPath: string,
  prompt: string,
  reusePane: ExpertChatPane | null = null,
  options: ResumeDiscussionInChatOptions = {},
): Promise<ExpertChatPane | null> => {
  if (discussion) discussion.folderPath = folderPath;
  const targetAccount = accountById(accountId);
  if (!targetAccount) return null;
  const preserveNavigation = options.preserveNavigation === true;
  const activateTarget = options.activateTarget === true;
  const keepReusedPaneVisible = preserveNavigation
    && !!reusePane
    && !!expertChatPaneRoot(reusePane);
  const transferSnapshot = reusePane
    ? captureExpertChatAccountTransfer(reusePane)
    : null;
  const activateReusePane = !!reusePane
    && (!preserveNavigation || activateTarget)
    && activeView !== "chat";
  let pane = reusePane;
  if (!pane && preserveNavigation) {
    pane = discussion
      ? expertChatPanes.find(
          (candidate) =>
            candidate.discussion?.accountId === discussion.accountId
            && candidate.discussion.sessionId === discussion.sessionId,
        ) ?? null
      : null;
    if (!pane) {
      pane = createExpertChatPane(discussion, {
        accountId,
        mode: "build",
        pendingWorkspace: folderPath,
      });
      expertChatPanes.push(pane);
      if (discussion) startExpertChatSync(pane);
      void loadChatModelCatalog(accountId);
      persistExpertChats();
      refreshChatSidebarConversations();
    }
  }
  pane ??= discussion
    ? openDiscussionInExpert(discussion)
    : addExpertChatPane(accountId, { mode: "build", pendingWorkspace: folderPath });
  if (!pane) return null;

  if (transferSnapshot) {
    prepareExpertChatAccountTransfer(
      pane,
      discussion,
      targetAccount,
      folderPath,
      activateReusePane || activateTarget,
    );
  } else {
    pane.accountId = accountId;
    pane.pendingWorkspace = folderPath;
    pane.mode = "build";
  }
  if (activateTarget) {
    activeExpertChatKey = pane.key;
    moveExpertChatPageToPane(pane);
    activeView = "chat";
  }
  if (
    !preserveNavigation &&
    (!transferSnapshot || activateReusePane) &&
    expertChatFullscreenKey &&
    expertChatFullscreenKey !== pane.key
  ) {
    expertChatFullscreenKey = pane.key;
  }
  persistExpertChats();

  let root = expertChatPaneRoot(pane);
  const targetMustBeRendered = activateTarget || (!transferSnapshot && !preserveNavigation);
  if (!root && targetMustBeRendered) {
    render();
    await waitForFrame();
    root = expertChatPaneRoot(pane);
  }
  if (!root && targetMustBeRendered) {
    return null;
  }

  const transferSubmission: QueuedChatSubmission | null = transferSnapshot
    ? {
        prompt,
        // L'amorce porte tout l'historique de la conversation : elle part en
        // entier au modele, mais la bulle n'en montre qu'un resume.
        displayText: resumeSeedBubbleText(prompt),
        imageAttachments: [],
        accountId: targetAccount.id,
        mode: "build",
        model: accountModel(targetAccount),
        reasoningEffort: accountProvider(targetAccount) === "codex"
          ? reasoningEffortForChatModel(
              targetAccount,
              accountModel(targetAccount),
              accountReasoningEffort(targetAccount),
            )
          : null,
        enabledTools: [...pane.enabledTools],
        agentSkills: [...chatAgentSkillPrompts(pane.enabledTools)],
        automaticOrchestration:
          pane.automaticOrchestrationEnabled && !pane.orchestrationRole && !pane.autonomousAgentId,
        resumeSessionId: discussion?.rolloutId || discussion?.sessionId || null,
      }
    : null;
  if (keepReusedPaneVisible) {
    automaticQuotaResumeVisibilityPins.add(pane.key);
  }
  const sent = await sendExpertChatMessage(
    pane,
    root,
    transferSnapshot ? undefined : prompt,
    "message",
    transferSubmission,
  );
  if (!sent && transferSnapshot) {
    restoreExpertChatAfterAccountTransfer(pane, transferSnapshot);
  } else if (!sent) {
    automaticQuotaResumeVisibilityPins.delete(pane.key);
  }
  return sent ? pane : null;
};

const expertChatFullscreenAnimations = new WeakMap<HTMLElement, Animation>();

const syncExpertChatFullscreenPanelUi = (
  root: HTMLElement,
  fullscreen: boolean,
): void => {
  root.classList.toggle("is-fullscreen", fullscreen);
  const button = root.querySelector<HTMLButtonElement>("[data-chat-action='fullscreen']");
  if (!button) return;
  const label = fullscreen ? "Quitter le plein écran" : "Afficher ce chat en plein écran";
  button.title = label;
  button.setAttribute("aria-label", label);
  button.setAttribute("aria-pressed", String(fullscreen));
  button.innerHTML = `<i data-lucide="${fullscreen ? "minimize-2" : "maximize-2"}"></i>`;
  renderIcons(button);
};

const animateExpertChatFullscreenChange = (
  root: HTMLElement,
  previousRect: DOMRect,
): void => {
  expertChatFullscreenAnimations.get(root)?.cancel();
  if (
    window.matchMedia("(prefers-reduced-motion: reduce)").matches
    || window.matchMedia("(max-width: 860px)").matches
  ) return;

  const nextRect = root.getBoundingClientRect();
  if (
    previousRect.width <= 0
    || previousRect.height <= 0
    || nextRect.width <= 0
    || nextRect.height <= 0
  ) return;

  const translateX = previousRect.left - nextRect.left;
  const translateY = previousRect.top - nextRect.top;
  const scaleX = previousRect.width / nextRect.width;
  const scaleY = previousRect.height / nextRect.height;
  if (
    Math.abs(translateX) < 8
    && Math.abs(translateY) < 8
    && Math.abs(scaleX - 1) < 0.03
    && Math.abs(scaleY - 1) < 0.03
  ) return;

  root.classList.add("is-fullscreen-transitioning");
  const animation = root.animate(
    [
      {
        opacity: 0.94,
        transform: `translate3d(${translateX}px, ${translateY}px, 0) scale(${scaleX}, ${scaleY})`,
        transformOrigin: "top left",
      },
      { opacity: 1, transform: "translate3d(0, 0, 0) scale(1)", transformOrigin: "top left" },
    ],
    { duration: 220, easing: "cubic-bezier(0.22, 1, 0.36, 1)" },
  );
  expertChatFullscreenAnimations.set(root, animation);
  const cleanup = () => {
    if (expertChatFullscreenAnimations.get(root) !== animation) return;
    expertChatFullscreenAnimations.delete(root);
    root.classList.remove("is-fullscreen-transitioning");
  };
  animation.addEventListener("finish", cleanup, { once: true });
  animation.addEventListener("cancel", cleanup, { once: true });
};

const toggleExpertChatFullscreen = (pane: ExpertChatPane) => {
  if (!expertChatPanes.includes(pane)) return;
  const root = expertChatPaneRoot(pane);
  if (!root) return;

  const previousFullscreenPane = expertChatPanes.find(
    (candidate) => candidate.key === expertChatFullscreenKey,
  ) ?? null;
  const previousFullscreenRoot = previousFullscreenPane && previousFullscreenPane !== pane
    ? expertChatPaneRoot(previousFullscreenPane)
    : null;
  const previousFullscreenRect = previousFullscreenRoot?.getBoundingClientRect() ?? null;
  const previousRect = root.getBoundingClientRect();
  const nextFullscreen = expertChatFullscreenKey !== pane.key;

  expertChatFullscreenKey = nextFullscreen ? pane.key : null;
  pane.historyOpen = expertChatHistoryOpenAfterFullscreenChange(
    pane.historyOpen,
    nextFullscreen,
    {
      openOnFullscreen: expertChatHistoryOpenOnFullscreen,
      closeOnCompact: expertChatHistoryCloseOnCompact,
    },
  );
  if (nextFullscreen) activeExpertChatKey = pane.key;

  document.querySelectorAll<HTMLElement>("[data-chat-panel]").forEach((panel) => {
    panel.classList.toggle("active", panel.dataset.chatPanel === activeExpertChatKey);
  });
  if (previousFullscreenRoot && previousFullscreenRect) {
    syncExpertChatFullscreenPanelUi(previousFullscreenRoot, false);
    animateExpertChatFullscreenChange(previousFullscreenRoot, previousFullscreenRect);
  }
  syncExpertChatHistoryUi(pane, root);
  syncExpertChatFullscreenPanelUi(root, nextFullscreen);
  animateExpertChatFullscreenChange(root, previousRect);
};

const closeExpertChatPane = (pane: ExpertChatPane) => {
  if (pane.contextCompacting) {
    updateCompactionStatus("Attendez la fin de la compaction avant de fermer ce chat");
    return;
  }
  if (chatTurnIsBusy(pane.turn?.status)) {
    statusText = pane.turn?.status === "finalizing"
      ? "La conversation termine sa synchronisation"
      : "Arretez la reponse avant de fermer ce chat";
    return;
  }
  const index = expertChatPanes.indexOf(pane);
  if (index < 0) return;
  if (pane.orchestrationId && pane.orchestrationRole === "worker" && pane.orchestrationTaskId) {
    dismissedOrchestrationWorkerPanes.add(
      orchestrationWorkerPaneKey(pane.orchestrationId, pane.orchestrationTaskId),
    );
  } else if (pane.orchestrationId && pane.orchestrationTesterId) {
    dismissedOrchestrationTesterPanes.add(
      orchestrationTesterPaneKey(pane.orchestrationId, pane.orchestrationTesterId),
    );
  }
  stopExpertChatSync(pane);
  stopExpertChatTurnPoll(pane);
  resetExpertModelCapacityRetry(pane);
  disposeChatImagePreviews(pane.imageAttachments);
  pane.imageAttachments = [];
  expertChatAccountTransitions.delete(pane.key);
  automaticQuotaResumeVisibilityPins.delete(pane.key);
  explicitlyOpenedBusyChatVisibilityPins.delete(pane.key);
  explicitlyOpenedAuxiliaryChatVisibilityPins.delete(pane.key);
  expertChatPanes.splice(index, 1);
  const environmentPanes = userOpenedExpertChatPanesForCurrentEnvironment();
  if (activeExpertChatKey === pane.key) {
    activeExpertChatKey = environmentPanes[0]?.key ?? null;
  }
  if (expertChatFullscreenKey === pane.key) expertChatFullscreenKey = null;
  reconcileExpertChatPage();
  statusText = expertChatStatusText();
  persistExpertChats();
  render();
  startAllExpertChatWork();
};

function bindExpertChatHistoryPanelUi(pane: ExpertChatPane, root: HTMLElement): void {
  root.querySelector<HTMLButtonElement>("[data-chat-action='history-close']")?.addEventListener("click", () => {
    pane.historyOpen = false;
    syncExpertChatHistoryUi(pane, root);
  });
  root.querySelectorAll<HTMLButtonElement>("[data-chat-history-message]").forEach((button) => {
    button.addEventListener("click", () => {
      const index = Number(button.dataset.chatHistoryMessage);
      if (!Number.isInteger(index)) return;
      const reveal = () => {
        const liveRoot = expertChatPaneRoot(pane);
        const message = liveRoot?.querySelector<HTMLElement>(`[data-chat-message-index='${index}']`);
        message?.scrollIntoView({ behavior: "smooth", block: "center" });
        message?.classList.add("chat-msg--located");
        window.setTimeout(() => message?.classList.remove("chat-msg--located"), 1400);
      };
      if (window.matchMedia("(max-width: 760px)").matches) {
        pane.visibleTurnLimit = null;
        pane.historyOpen = false;
        syncExpertChatHistoryUi(pane, root);
        refreshExpertChatFeed(pane);
        window.requestAnimationFrame(reveal);
      } else {
        reveal();
      }
    });
  });
}

const bindExpertChatPaneUi = (pane: ExpertChatPane, root: HTMLElement) => {
  root.addEventListener("pointerdown", () => {
    if (pane.key !== activeExpertChatKey) activateExpertChatPane(pane);
  });
  root.addEventListener("click", (event) => {
    const target = event.target as HTMLElement | null;
    if (handleMicrosoftPendingActionClick(target)) {
      event.preventDefault();
      return;
    }
    if (target?.closest("[data-chat-action='show-older-turns']")) {
      event.preventDefault();
      pane.visibleTurnLimit = (pane.visibleTurnLimit ?? 0) + chatTurnBatchForViewport();
      refreshExpertChatFeed(pane);
      return;
    }
    if (target?.closest("[data-chat-action='compact']")) {
      event.preventDefault();
      activateExpertChatPane(pane, true);
      void compactExpertChatContext(pane);
      return;
    }
    if (!target?.closest("[data-chat-action='focus-prompt']")) return;
    activateExpertChatPane(pane, true);
  });

  root.querySelector<HTMLButtonElement>("[data-chat-action='back']")?.addEventListener("click", () => {
    if (window.matchMedia("(max-width: 760px)").matches) {
      document.body.classList.add("chat-sidebar-open");
      syncMobileDrawerAccessibility(true, true);
    } else {
      openDiscussionHistory();
    }
  });
  root.querySelector<HTMLButtonElement>("[data-chat-action='new']")?.addEventListener("click", () => openNewChatModal());
  root.querySelectorAll<HTMLButtonElement>("[data-chat-action='autonomize'], [data-chat-action='edit-autonomous']")
    .forEach((button) => {
      button.addEventListener("click", () => openAutonomousChatEditor(pane));
    });
  root.querySelector<HTMLButtonElement>("[data-chat-action='toggle-automatic-orchestration']")?.addEventListener("click", () => {
    if (pane.automaticOrchestrationLaunching || pane.orchestrationRole) return;
    pane.automaticOrchestrationEnabled = !pane.automaticOrchestrationEnabled;
    persistExpertChats();
    statusText = pane.automaticOrchestrationEnabled
      ? "Mode orchestrateur actif : les tâches peuvent être réparties entre 5 sous-chats"
      : "Mode orchestrateur inactif : ce chat travaillera seul";
    refreshExpertChatPane(pane);
    focusExpertChatPrompt(pane);
  });
  root.querySelector<HTMLButtonElement>("[data-chat-action='orchestrate']")?.addEventListener("click", () => {
    openOrchestrationConversion(pane);
  });
  root.querySelectorAll<HTMLButtonElement>("[data-chat-action='open-orchestration']").forEach((button) => {
    button.addEventListener("click", () => setActiveView("orchestration"));
  });
  root.querySelector<HTMLButtonElement>("[data-chat-action='close']")?.addEventListener("click", () => closeExpertChatPane(pane));
  root.querySelector<HTMLButtonElement>("[data-chat-action='fullscreen']")?.addEventListener("click", () => toggleExpertChatFullscreen(pane));
  root.querySelector<HTMLButtonElement>("[data-chat-action='refresh']")?.addEventListener("click", () => {
    if (pane.discussion) void loadExpertChatTranscript(pane);
    else void refreshDiscussions();
  });
  root.querySelector<HTMLButtonElement>("[data-chat-action='history-toggle']")?.addEventListener("click", () => {
    pane.historyOpen = !pane.historyOpen;
    syncExpertChatHistoryUi(pane, root);
  });
  bindExpertChatHistoryPanelUi(pane, root);
  root.querySelector<HTMLButtonElement>("[data-chat-action='stop']")?.addEventListener("click", () => {
    void stopExpertChatTurn(pane);
  });
  root.querySelector<HTMLButtonElement>("[data-chat-action='clear-queue']")?.addEventListener("click", () => {
    pane.queuedSubmissions = [];
    statusText = "File d'attente annulée";
    refreshExpertChatPane(pane);
    focusExpertChatPrompt(pane);
  });
  root.querySelector<HTMLButtonElement>("[data-chat-action='goal']")?.addEventListener("click", () => {
    void sendExpertChatMessage(pane, root, undefined, "goal");
  });
  root.querySelector<HTMLButtonElement>("[data-chat-action='prompts']")?.addEventListener("click", () => {
    openExpertChatPromptQuickPicker(pane, root);
  });
  root.querySelectorAll<HTMLButtonElement>("[data-chat-action='favorite-prompt']").forEach((button) => {
    button.addEventListener("click", () => {
      const promptId = button.dataset.chatPromptId;
      if (promptId) insertFavoritePromptInExpertChat(pane, root, promptId);
    });
  });
  root.querySelectorAll<HTMLButtonElement>("[data-chat-action='toggle-agent-tool']").forEach((button) => {
    button.addEventListener("click", () => {
      const toolId = button.dataset.chatTool;
      if (!isChatAgentToolId(toolId)) return;
      pane.enabledTools = toggleChatAgentTool(pane.enabledTools, toolId);
      const enabled = pane.enabledTools.includes(toolId);
      statusText = `${chatAgentToolLabel(toolId, chatAgentToolDefinitions())} ${enabled ? "activé" : "désactivé"} pour ce chat`;
      persistExpertChats();
      refreshExpertChatPane(pane);
      focusExpertChatPrompt(pane);
    });
  });
  const prompt = root.querySelector<HTMLTextAreaElement>("[data-chat-control='prompt']");
  const imageAttachmentBinding: ChatImageAttachmentBinding = {
    current: () => pane.imageAttachments,
    update: (images) => {
      pane.imageAttachments = images;
    },
    refresh: () => refreshExpertChatPane(pane),
    focus: () => focusExpertChatPrompt(pane),
  };
  root.querySelectorAll<HTMLButtonElement>("[data-chat-action='remove-image']").forEach((button) => {
    button.addEventListener("click", () => {
      const imageId = button.dataset.chatImageId;
      if (imageId) removeChatImageAttachment(imageId, imageAttachmentBinding);
    });
  });
  const promptMaxHeight = root.matches(".chat-panel--compact:not(.is-fullscreen)") ? 64 : 132;
  const resizePrompt = () => {
    if (!prompt) return;
    prompt.style.height = "0px";
    prompt.style.height = `${Math.min(prompt.scrollHeight, promptMaxHeight)}px`;
  };
  prompt?.addEventListener("input", () => {
    pane.draft = prompt.value;
    prompt.setCustomValidity("");
    resizePrompt();
  });
  prompt?.addEventListener("keydown", (event) => {
    if (event.key === "Enter" && !event.shiftKey && !event.isComposing) {
      event.preventDefault();
      void sendExpertChatMessage(pane, root);
    }
  });
  prompt?.addEventListener("paste", (event) => {
    void attachPastedChatImages(event, imageAttachmentBinding);
  });
  resizePrompt();
  bindVoiceComposer(root);
  root.querySelector<HTMLFormElement>("[data-chat-control='composer']")?.addEventListener("submit", (event) => {
    event.preventDefault();
    void sendExpertChatMessage(pane, root);
  });
  root.querySelector<HTMLSelectElement>("[data-chat-control='mode']")?.addEventListener("change", (event) => {
    pane.mode = (event.currentTarget as HTMLSelectElement).value as ChatMode;
    persistExpertChats();
  });

  const modelInput = root.querySelector<HTMLInputElement>("[data-chat-control='model']");
  const commitPreferences = () => {
    const account = expertChatSelectedAccount(pane);
    if (!account) return false;
    const preferences = readChatPreferences(account, root);
    modelInput?.setCustomValidity(preferences.error ?? "");
    if (preferences.error) {
      modelInput?.reportValidity();
      statusText = preferences.error;
      return false;
    }
    if (preferences.changed) persistChatPreferences(account.id);
    return true;
  };
  modelInput?.addEventListener("input", () => modelInput.setCustomValidity(""));
  modelInput?.addEventListener("change", () => {
    if (commitPreferences()) refreshExpertChatPane(pane);
  });
  modelInput?.addEventListener("keydown", (event) => {
    if (event.key !== "Enter") return;
    event.preventDefault();
    modelInput.blur();
  });
  root.querySelector<HTMLSelectElement>("[data-chat-control='reasoning-effort']")?.addEventListener("change", commitPreferences);
  root.querySelector<HTMLButtonElement>("[data-chat-control='fast-mode']")?.addEventListener("click", () => {
    const account = expertChatSelectedAccount(pane);
    if (account && toggleChatFastMode(account)) refreshExpertChatPane(pane);
  });
  root.querySelectorAll<HTMLButtonElement>("[data-chat-starter]").forEach((button) => {
    button.addEventListener("click", () => {
      pane.draft = button.dataset.chatStarter ?? "";
      if (prompt) {
        prompt.value = pane.draft;
        prompt.dispatchEvent(new Event("input"));
        prompt.focus();
        prompt.setSelectionRange(prompt.value.length, prompt.value.length);
      }
    });
  });

  const feed = root.querySelector<HTMLDivElement>("[data-chat-control='feed']");
  if (feed) bindChatFeedScroll(feed, pane);
  feed?.addEventListener("click", (event) => {
    const button = (event.target as HTMLElement | null)?.closest<HTMLButtonElement>(".chat-code-copy, [data-chat-copy]");
    if (!button) return;
    const code = button.matches("[data-chat-copy]")
      ? button.closest(".chat-user-message, [data-chat-copy-source]")?.querySelector<HTMLElement>(".chat-msg-body, .chat-assistant-markdown")?.innerText ?? ""
      : button.closest(".chat-code")?.querySelector("code")?.textContent ?? "";
    if (!code) return;
    void navigator.clipboard.writeText(code).then(() => {
      button.classList.add("copied");
      window.setTimeout(() => button.classList.remove("copied"), 1200);
    });
  });
};

const bindExpertChatGridUi = () => {
  expertChatPanes.forEach((pane) => {
    const root = expertChatPaneRoot(pane);
    if (root) {
      bindExpertChatPaneUi(pane, root);
      restoreExpertChatScroll(pane, root, true);
    }
  });
};

const renderDiscussionRow = (discussion: DiscussionSummary, accountLabel: string) => {
  const busy = discussionIsBusy(discussion);
  const title = discussion.title?.trim() || "(sans titre)";
  const subtitle = discussionSubtitle(discussion);
  const provider = discussion.provider ?? "codex";
  const folderPath = discussionFolderPath(discussion);
  const meta = [
    `<span class="discussion-badge prov-${provider}" title="Fournisseur d'origine"><i data-lucide="cpu"></i>${escapeHtml(providerLabel(provider))}</span>`,
    folderPath
      ? `<span title="${escapeAttr(folderPath)}"><i data-lucide="folder-open"></i>${escapeHtml(displayProjectDir(folderPath))}</span>`
      : "",
    `<span><i data-lucide="clock-3"></i>${escapeHtml(formatTimestamp(discussion.lastActivity))}</span>`,
    discussion.totalTokens
      ? `<span><i data-lucide="bar-chart-3"></i>${escapeHtml(formatTokens(discussion.totalTokens))} tok</span>`
      : "",
    `<span>${discussion.messageCount} msg</span>`,
    discussion.forkCount > 1
      ? `<span title="Reprises regroupees (${discussion.forkCount} fichiers)"><i data-lucide="history"></i>${discussion.forkCount - 1} reprise${discussion.forkCount - 1 > 1 ? "s" : ""}</span>`
      : "",
  ]
    .filter(Boolean)
    .join("");

  // Compte cible : origine EN PREMIER (marquee), puis les autres. Choisir un
  // autre compte cree une copie fidele et conserve la source dans l'Historique
  // jusqu'a son retrait manuel — logique portee par continueDiscussionWith.
  const accounts = continuationAccountsForDiscussion(discussion);
  const target = discussionTargetFor(discussion);
  const targetAccount = accounts.find((account) => account.id === target) ?? null;
  // La disponibilite ne concerne que les comptes Freebuff (un seul terminal par
  // compte) : un compte cible Freebuff occupe desactive la reprise.
  const targetUnavailable = accountSessionBusy(targetAccount);
  const sourceUnavailable = provider === "freebuff"
    && accountSessionBusy(accountById(discussion.accountId));
  const targetIsFreebuff = accountProvider(targetAccount) === "freebuff";
  const willCopy = target !== discussion.accountId;
  const copyLabel = "Copier + reprendre";
  const copyTitle = provider === "freebuff"
    ? "Copier la conversation vers le compte Freebuff choisi, la reprendre et conserver la source dans l’Historique"
    : targetIsFreebuff
      ? "Copier la discussion dans le compte Freebuff choisi, la reprendre dans son terminal et conserver la source dans l’Historique"
      : "Copier la discussion dans le compte choisi, la reprendre automatiquement et conserver la source dans l’Historique";
  const options =
    accounts
      .map((account) => {
        const selected = account.id === target ? " selected" : "";
        const suffix = account.id === discussion.accountId ? " (origine)" : "";
        const isFreebuffOption = accountProvider(account) === "freebuff";
        const unavailable = accountSessionBusy(account);
        const availability = isFreebuffOption
          ? unavailable ? " · indisponible (terminal ouvert)" : " · disponible"
          : "";
        return `<option value="${escapeAttr(account.id)}"${selected}${unavailable ? " disabled" : ""}>${escapeHtml(account.label)}${suffix}${availability}</option>`;
      })
      .join("") ||
    `<option value="${escapeAttr(discussion.accountId)}" selected>${escapeHtml(accountLabel)}</option>`;

  return `
    <div class="discussion-row ${busy ? "busy" : ""}">
      <div class="discussion-main">
        <strong class="discussion-title" title="${escapeAttr(title)}">${escapeHtml(title)}</strong>
        ${subtitle ? `<span class="discussion-preview">${escapeHtml(subtitle)}</span>` : ""}
        <span class="discussion-meta">${meta}</span>
      </div>
      <div class="discussion-actions">
        <label class="discussion-account" title="Choisir le compte dans lequel reprendre cette discussion">
          <i data-lucide="users"></i>
          <select class="discussion-target" data-target-for="${escapeAttr(discussion.sessionId)}" data-target-account="${escapeAttr(discussion.accountId)}">
            ${options}
          </select>
          ${targetIsFreebuff ? `<span class="discussion-account-state ${targetUnavailable ? "is-busy" : "is-available"}" data-account-state>${targetUnavailable ? "Indisponible · terminal ouvert" : "Disponible"}</span>` : ""}
        </label>
        <button class="tool-button" data-resume-session="${escapeAttr(discussion.sessionId)}" data-resume-account="${escapeAttr(discussion.accountId)}"${targetUnavailable ? " disabled" : ""} title="${targetUnavailable ? escapeAttr(`${targetAccount?.label ?? "Ce compte"} est indisponible : un terminal Freebuff est déjà ouvert`) : willCopy ? copyTitle : provider === "freebuff" ? "Continuer dans le TUI Freebuff" : "Reprendre automatiquement dans le chat"}">
          <i data-lucide="${willCopy ? "copy" : "play"}"></i><span data-resume-label>${willCopy ? copyLabel : "Reprendre"}</span>
        </button>
        <button class="tool-button primary" data-open-chat="${escapeAttr(discussion.sessionId)}" data-open-account="${escapeAttr(discussion.accountId)}"${sourceUnavailable ? " disabled" : ""} title="${sourceUnavailable ? "Compte source indisponible : un terminal Freebuff est déjà ouvert" : provider === "freebuff" ? "Ouvrir cette conversation dans un terminal Freebuff" : "Ouvrir cette conversation dans le chat"}">
          <i data-lucide="${provider === "freebuff" ? "terminal" : "messages-square"}"></i><span>${provider === "freebuff" ? "Ouvrir le terminal" : "Ouvrir le chat"}</span>
        </button>
        <button class="icon-button wide" data-rename-session="${escapeAttr(discussion.sessionId)}" data-rename-account="${escapeAttr(discussion.accountId)}" title="Renommer ce chat" aria-label="Renommer ${escapeAttr(title)}">
          <i data-lucide="pencil"></i>
        </button>
        <button class="icon-button wide danger" data-delete-session="${escapeAttr(discussion.sessionId)}" data-delete-account="${escapeAttr(discussion.accountId)}" title="Retirer de l'historique (archive toutes les reprises)">
          <i data-lucide="trash-2"></i>
        </button>
      </div>
    </div>
  `;
};

const compactOpenHistoryText = (value: string, maxChars: number): string => {
  const compact = value.replace(/\s+/g, " ").trim();
  if (compact.length <= maxChars) return compact;
  return `${compact.slice(0, Math.max(1, maxChars - 1)).trimEnd()}…`;
};

const openHistoryPaneText = (pane: ExpertChatPane): string =>
  pane.messages.find((message) => message.role === "user" && chatMessageHasVisibleContent(message))
    ?.text.trim()
  ?? pane.messages.find((message) => chatMessageHasVisibleContent(message))?.text.trim()
  ?? "";

const openHistoryPaneTitle = (pane: ExpertChatPane): string => {
  const persistedTitle = pane.discussion?.title?.trim();
  if (persistedTitle) return persistedTitle;
  const firstMessage = openHistoryPaneText(pane);
  if (firstMessage) return compactOpenHistoryText(firstMessage, 80);

  // Certains tours recuperes depuis le serveur n'exposent pas encore leur
  // premier message. Leur identifiant court donne alors un titre stable et
  // distinct, au lieu de plusieurs rangees « conversation sans titre ».
  const identity = expertChatResumeSessionId(pane) ?? pane.key;
  const shortId = identity.slice(-8);
  return `${chatTurnIsBusy(pane.turn?.status) ? "Chat en cours" : "Chat ouvert"} · ${shortId}`;
};

// Le serveur peut connaitre une session active avant que son index de fichiers
// ait produit DiscussionSummary (notamment juste apres une mise a jour du format
// Codex). Ces panneaux restent de vrais chats utilisateur : l'Historique doit
// donc les montrer immediatement, puis les dedupliquer des que l'index les voit.
const unindexedOpenHistoryPanes = (): ExpertChatPane[] => {
  const indexed = new Set<string>();
  allDiscussions().forEach((discussion) => {
    [discussion.sessionId, discussion.rolloutId, discussion.resumeId]
      .filter((id): id is string => !!id?.trim())
      .forEach((id) => indexed.add(`${discussion.accountId}:${id.trim()}`));
  });

  const seen = new Set<string>();
  return expertChatPanes.filter((pane) => {
    const account = expertChatSelectedAccount(pane);
    if (!account) return false;
    const identities = [
      pane.discussion?.sessionId,
      pane.discussion?.rolloutId,
      pane.discussion?.resumeId,
      pane.turn?.sessionId,
      pane.resumeSessionId,
    ].filter((id): id is string => !!id?.trim());
    if (identities.some((id) => indexed.has(`${account.id}:${id.trim()}`))) return false;

    const identity = `${account.id}:${identities[0]?.trim() || pane.key}`;
    if (seen.has(identity)) return false;
    seen.add(identity);
    return true;
  });
};

const openHistoryPaneMatches = (pane: ExpertChatPane): boolean => {
  const query = discussionSearch.trim().toLocaleLowerCase();
  if (!query) return true;
  const account = expertChatSelectedAccount(pane);
  return [
    openHistoryPaneTitle(pane),
    openHistoryPaneText(pane),
    account?.label ?? "",
    expertChatPaneEnvironmentPath(pane) ?? "",
    expertChatResumeSessionId(pane) ?? "",
  ].some((value) => value.toLocaleLowerCase().includes(query));
};

const renderOpenHistoryPaneRow = (pane: ExpertChatPane): string => {
  const account = expertChatSelectedAccount(pane);
  const provider = accountProvider(account);
  const title = openHistoryPaneTitle(pane);
  const firstMessage = openHistoryPaneText(pane);
  const preview = firstMessage && firstMessage !== title
    ? compactOpenHistoryText(firstMessage, 200)
    : "";
  const workspace = expertChatPaneEnvironmentPath(pane);
  const status = expertChatSidebarStatus(pane);
  const statusLabel = chatSidebarStatusLabel(status);
  const sessionId = expertChatResumeSessionId(pane);
  const meta = [
    `<span class="discussion-badge prov-${provider}" title="Fournisseur d'origine"><i data-lucide="cpu"></i>${escapeHtml(providerLabel(provider))}</span>`,
    account ? `<span><i data-lucide="user-round"></i>${escapeHtml(account.label)}</span>` : "",
    workspace
      ? `<span title="${escapeAttr(workspace)}"><i data-lucide="folder-open"></i>${escapeHtml(displayProjectDir(workspace))}</span>`
      : "",
    `<span><i data-lucide="activity"></i>${escapeHtml(statusLabel)}</span>`,
    sessionId ? `<span title="Session ${escapeAttr(sessionId)}"><i data-lucide="history"></i>Indexation en cours</span>` : "",
  ].filter(Boolean).join("");

  return `
    <div class="discussion-row pending-index">
      <div class="discussion-main">
        <strong class="discussion-title" title="${escapeAttr(title)}">${escapeHtml(title)}</strong>
        ${preview ? `<span class="discussion-preview">${escapeHtml(preview)}</span>` : ""}
        <span class="discussion-meta">${renderChatSidebarStatus(pane)}${meta}</span>
      </div>
      <div class="discussion-actions">
        <button class="tool-button primary" data-open-pane="${escapeAttr(pane.key)}" title="Ouvrir ce chat déjà actif">
          <i data-lucide="messages-square"></i><span>Ouvrir le chat</span>
        </button>
      </div>
    </div>
  `;
};

const discussionHistoryCounts = () => {
  const groups = discussions?.accounts ?? [];
  const openPanes = unindexedOpenHistoryPanes();
  return {
    total: groups.reduce((sum, group) => sum + group.discussionCount, 0) + openPanes.length,
    visible: groups.reduce(
      (sum, group) => sum + group.discussions.filter((discussion) => discussionMatches(discussion, group.label)).length,
      0,
    ) + openPanes.filter(openHistoryPaneMatches).length,
  };
};

const renderDiscussionGroups = () => {
  if (!discussionsLoaded) {
    return `<div class="pool-empty">Lecture des discussions Codex…</div>`;
  }
  const groups = discussions?.accounts ?? [];
  const openPanes = unindexedOpenHistoryPanes();
  if (groups.length === 0 && openPanes.length === 0) {
    return `<div class="pool-empty">Aucune discussion trouvee</div>`;
  }

  const visibleOpenPanes = openPanes.filter(openHistoryPaneMatches);
  const openBlock = visibleOpenPanes.length
    ? `
      <section class="discussion-group discussion-group--open">
        <header class="discussion-group-head">
          <strong>Chats ouverts</strong>
          <span>${visibleOpenPanes.length}/${openPanes.length} chat(s) pas encore indexé(s)</span>
        </header>
        <div class="discussion-list">${visibleOpenPanes.map(renderOpenHistoryPaneRow).join("")}</div>
      </section>
    `
    : "";
  const indexedBlocks = groups
    .map((group) => {
      const rows = group.discussions.filter((discussion) => discussionMatches(discussion, group.label));
      if (rows.length === 0) return "";
      return `
        <section class="discussion-group">
          <header class="discussion-group-head">
            <strong>${escapeHtml(group.label)}</strong>
            <span>${rows.length}/${group.discussionCount} discussion(s)${group.hasTokens ? "" : " · deconnecte"}</span>
          </header>
          ${group.error ? `<div class="limit-error">${escapeHtml(group.error)}</div>` : ""}
          <div class="discussion-list">${rows.map((discussion) => renderDiscussionRow(discussion, group.label)).join("")}</div>
        </section>
      `;
    })
    .filter(Boolean)
    .join("");

  const blocks = `${openBlock}${indexedBlocks}`;

  return blocks || `<div class="pool-empty">Aucune discussion ne correspond a « ${escapeHtml(discussionSearch)} »</div>`;
};

const renderDiscussionsPanel = () => {
  const groups = discussions?.accounts ?? [];
  const { total, visible } = discussionHistoryCounts();
  const hasSearch = discussionSearch.trim().length > 0;
  const connected = groups.filter((group) => group.hasTokens).length;
  return `
    <section class="discussions-panel">
      <div class="discussions-head">
        <div>
          <strong>Historique</strong>
          <span id="discussionCountSummary">${hasSearch ? `${visible} affichée(s) sur ${total}` : `${total} discussion(s)`} · ${connected}/${settings?.accounts.length ?? 0} compte(s)</span>
        </div>
        <div class="discussions-tools">
          <label class="discussion-search">
            <i data-lucide="search"></i>
            <input id="discussionSearch" type="search" placeholder="Rechercher (titre, environnement, id)" value="${escapeAttr(discussionSearch)}" />
          </label>
          <button id="clearDiscussionSearch" class="tool-button" title="Effacer le filtre et afficher toutes les conversations">
            <i data-lucide="list"></i><span>Tout afficher</span>
          </button>
          <button id="refreshDiscussions" class="tool-button" title="Actualiser">
            <i data-lucide="refresh-ccw"></i><span>Actualiser</span>
          </button>
        </div>
      </div>
      <div class="discussion-groups" id="discussionGroups">${renderDiscussionGroups()}</div>
    </section>
  `;
};

const refreshDiscussionList = () => {
  const host = document.querySelector<HTMLDivElement>("#discussionGroups");
  if (!host) {
    render();
    return;
  }
  host.innerHTML = renderDiscussionGroups();
  const groups = discussions?.accounts ?? [];
  const { total, visible } = discussionHistoryCounts();
  const hasSearch = discussionSearch.trim().length > 0;
  const summary = document.querySelector<HTMLElement>("#discussionCountSummary");
  if (summary) {
    summary.textContent = `${hasSearch ? `${visible} affichée(s) sur ${total}` : `${total} discussion(s)`} · ${groups.filter((group) => group.hasTokens).length}/${settings?.accounts.length ?? 0} compte(s)`;
  }
  renderIcons(host);
  bindDiscussionRowUi();
};

const clearChatDragUi = () => {
  draggedChatSessionId = null;
  draggedChatAccountId = null;
  document
    .querySelectorAll<HTMLElement>(".chat-side-item.dragging, .chat-workspace-group.drag-over")
    .forEach((element) => element.classList.remove("dragging", "drag-over"));
  document.body.classList.remove("chat-dragging");
  if (chatSidebarRefreshPending) {
    window.requestAnimationFrame(refreshChatSidebarConversations);
  }
};

// Attache les gestionnaires de la liste de workspaces. Le root optionnel permet
// de rebinder seulement les groupes remplaces par un rafraichissement cible.
const bindWorkspaceSwitcherUi = (root: ParentNode = document) => {
  root.querySelector<HTMLButtonElement>("#chooseEnvironmentFromSidebar")?.addEventListener(
    "click",
    openTerminalEnvironmentMenu,
  );
  root.querySelector<HTMLButtonElement>("#newChatGroupFromSidebar")?.addEventListener(
    "click",
    () => openNewChatModal({ group: true }),
  );
  root.querySelectorAll<HTMLButtonElement>("[data-ws-select]").forEach((button) => {
    button.addEventListener("click", () => {
      const value = button.dataset.wsSelect;
      if (value) void openFolderTerminals(value);
    });
  });
  root.querySelectorAll<HTMLButtonElement>("[data-open-folder-terminal]").forEach((button) => {
    button.addEventListener("click", () => {
      const session = terminalSessions.find(
        (candidate) => candidate.key === button.dataset.openFolderTerminal,
      );
      if (!session) return;
      activateTerminalSession(session);
      requestTerminalFocusKey = session.key;
      activeView = "terminal";
      stopLimitPoll();
      stopUsagePoll();
      stopKombaiPoll();
      stopDiscussionsPoll();
      stopChatSync();
      statusText = `Terminal actif: ${terminalTitle(session)}`;
      render();
      persistTerminalSessions();
    });
  });
  root.querySelectorAll<HTMLButtonElement>("[data-delete-terminal-history]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.stopPropagation();
      const session = terminalSessions.find(
        (candidate) => candidate.key === button.dataset.deleteTerminalHistory,
      );
      if (session) openTerminalDeleteModal(session);
    });
  });
  root.querySelectorAll<HTMLButtonElement>("[data-new-chat-workspace]").forEach((button) => {
    button.addEventListener("click", () => {
      const workspace = knownWorkspaces().find(
        (candidate) => candidate.id === button.dataset.newChatWorkspace,
      );
      if (!workspace) return;
      setCurrentWorkspace(workspace.path);
      setChatWorkspaceFilter(workspace.id);
      pendingChatWorkspace = workspace.path;
      void upsertWorkspaceRegistry(workspace.path);
      openNewChat();
    });
  });
  root.querySelectorAll<HTMLButtonElement>("[data-close-workspace]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.stopPropagation();
      const id = button.dataset.closeWorkspace;
      const workspace = knownWorkspaces().find((candidate) => candidate.id === id);
      if (workspace) void closeWorkspace(workspace);
    });
  });
  root.querySelector<HTMLButtonElement>("#wsOpenFolder")?.addEventListener("click", () => {
    openTerminalEnvironmentMenu();
  });
  root
    .querySelectorAll<HTMLElement>("[data-drag-chat][draggable=\"true\"]")
    .forEach((row) => {
      row.addEventListener("dragstart", (event) => {
        const dragEvent = event as DragEvent;
        const sessionId = row.dataset.dragChat;
        const accountId = row.dataset.dragAccount;
        const discussion = findDiscussion(sessionId, accountId);
        if (
          !sessionId
          || !accountId
          || !discussion
          || discussionBusyId
          || discussionHasRunningTurn(discussion)
        ) {
          dragEvent.preventDefault();
          return;
        }
        draggedChatSessionId = sessionId;
        draggedChatAccountId = accountId;
        dragEvent.dataTransfer?.setData(
          CHAT_DRAG_MIME,
          discussionIdentityKey(discussion),
        );
        dragEvent.dataTransfer?.setData("text/plain", sessionId);
        if (dragEvent.dataTransfer) dragEvent.dataTransfer.effectAllowed = "move";
        document.body.classList.add("chat-dragging");
        window.requestAnimationFrame(() => row.classList.add("dragging"));
      });
      row.addEventListener("dragend", clearChatDragUi);
    });

  root.querySelectorAll<HTMLElement>("[data-chat-drop-workspace]").forEach((target) => {
    const dropContext = (event: DragEvent) => {
      let transferredAccountId: string | null = null;
      let transferredSessionId: string | null = null;
      try {
        const transferred = JSON.parse(event.dataTransfer?.getData(CHAT_DRAG_MIME) || "null");
        if (
          Array.isArray(transferred)
          && typeof transferred[0] === "string"
          && typeof transferred[1] === "string"
        ) {
          [transferredAccountId, transferredSessionId] = transferred;
        }
      } catch {
        // Un payload externe ou ancien n'est jamais resolu par session seule.
      }
      const sessionId = draggedChatSessionId || transferredSessionId;
      const accountId = draggedChatAccountId || transferredAccountId;
      const discussion = findDiscussion(sessionId, accountId);
      const workspace = knownWorkspaces().find(
        (candidate) => candidate.id === target.dataset.chatDropWorkspace,
      );
      if (
        !accountId
        || !discussion
        || !workspace
        || discussionBusyId
        || discussionHasRunningTurn(discussion)
      ) {
        return null;
      }
      const folderPath = discussionFolderPath(discussion);
      if (folderPath && normalizeWorkspacePath(folderPath) === normalizeWorkspacePath(workspace.path)) {
        return null;
      }
      return { discussion, workspace };
    };

    target.addEventListener("dragover", (event) => {
      const dragEvent = event as DragEvent;
      if (!dropContext(dragEvent)) return;
      dragEvent.preventDefault();
      if (dragEvent.dataTransfer) dragEvent.dataTransfer.dropEffect = "move";
      document
        .querySelectorAll<HTMLElement>(".chat-workspace-group.drag-over")
        .forEach((group) => group.classList.toggle("drag-over", group === target));
    });
    target.addEventListener("dragleave", (event) => {
      const related = (event as DragEvent).relatedTarget;
      if (related instanceof Node && target.contains(related)) return;
      target.classList.remove("drag-over");
    });
    target.addEventListener("drop", (event) => {
      const dragEvent = event as DragEvent;
      const context = dropContext(dragEvent);
      if (!context) return;
      dragEvent.preventDefault();
      clearChatDragUi();
      void moveDiscussionToWorkspace(context.discussion, context.workspace);
    });
  });
};

// Rafraichit uniquement l'en-tete des workspaces sans re-render global.
const refreshWorkspaceSwitcher = () => {
  const current = document.querySelector<HTMLElement>("#chatWsSwitcher");
  if (!current) return;
  // Rien n'a change depuis le dernier rendu : on ne touche pas au DOM (evite
  // repaint/perte de focus inutiles a chaque poll).
  if (current.dataset.wsSig === workspaceSwitcherSignature()) return;
  const wrapper = document.createElement("div");
  wrapper.innerHTML = renderWorkspaceSwitcher();
  const next = wrapper.firstElementChild;
  if (!next) return;
  current.replaceWith(next);
  renderIcons(next);
  bindWorkspaceSwitcherUi(next);
};

const bindDiscussionRowUi = () => {
  document.querySelectorAll<HTMLButtonElement>("[data-rename-session]").forEach((button) => {
    button.addEventListener("click", () => {
      const discussion = findDiscussion(button.dataset.renameSession, button.dataset.renameAccount);
      if (discussion) void renameDiscussion(discussion);
    });
  });
  document.querySelectorAll<HTMLButtonElement>("[data-delete-session]").forEach((button) => {
    button.addEventListener("click", () => {
      const discussion = findDiscussion(
        button.dataset.deleteSession,
        button.dataset.deleteAccount,
      );
      if (discussion) openDiscussionArchiveModal(discussion);
    });
  });
  document.querySelectorAll<HTMLButtonElement>("[data-open-chat]").forEach((button) => {
    button.addEventListener("click", () => {
      const discussion = findDiscussion(
        button.dataset.openChat,
        button.dataset.openAccount,
      );
      if (discussion) openDiscussionChat(discussion);
    });
  });
  // Rangees de brouillons (chats ouverts sans discussion listee) : activees et
  // fermees par cle de pane, faute de sessionId a resoudre.
  document.querySelectorAll<HTMLButtonElement>("[data-open-pane]").forEach((button) => {
    button.addEventListener("click", () => {
      const pane = expertChatPanes.find((item) => item.key === button.dataset.openPane);
      if (!pane) return;
      closeMobileOverlays();
      if (minimizeActiveBusyExpertChat(pane)) return;
      activeView = "chat";
      pinExplicitlyOpenedExpertChat(pane);
      activateExpertChatPane(pane, true);
      statusText = expertChatStatusText();
      render();
      window.setTimeout(() => activateExpertChatPane(pane, true), 0);
    });
  });
  document.querySelectorAll<HTMLButtonElement>("[data-close-pane]").forEach((button) => {
    button.addEventListener("click", () => {
      const pane = expertChatPanes.find((item) => item.key === button.dataset.closePane);
      if (pane) closeExpertChatPane(pane);
    });
  });
  // Revenir a un terminal deja ouvert depuis la colonne de gauche.
  document.querySelectorAll<HTMLButtonElement>("[data-open-terminal]").forEach((button) => {
    button.addEventListener("click", () => {
      const session = terminalSessions.find((item) => item.key === button.dataset.openTerminal);
      if (!session) return;
      closeMobileOverlays();
      activateTerminalSession(session);
      activeView = "terminal";
      requestTerminalFocusKey = session.key;
      render();
    });
  });
  // Changement de compte cible : on memorise le choix et on met a jour, sans
  // re-render complet, le libelle/icone du bouton (Reprendre <-> Deplacer +
  // reprendre) pour ne pas voler le focus du select.
  document.querySelectorAll<HTMLSelectElement>(".discussion-target[data-target-for]").forEach((select) => {
    select.addEventListener("change", () => {
      const id = select.dataset.targetFor ?? "";
      const discussion = findDiscussion(id, select.dataset.targetAccount);
      if (!discussion) return;
      discussionTargetSel.set(discussionIdentityKey(discussion), select.value);
      const willCopy = select.value !== discussion.accountId;
      const provider = discussion.provider ?? accountProvider(accountById(discussion.accountId));
      const targetAccount = accountById(select.value);
      const targetIsFreebuff = accountProvider(targetAccount) === "freebuff";
      const copyLabel = "Copier + reprendre";
      const row = select.closest(".discussion-row");
      const button = row?.querySelector<HTMLButtonElement>("[data-resume-session]");
      const label = button?.querySelector<HTMLElement>("[data-resume-label]");
      const targetUnavailable = accountSessionBusy(targetAccount);
      const accountState = row?.querySelector<HTMLElement>("[data-account-state]");
      if (label) label.textContent = willCopy ? copyLabel : "Reprendre";
      if (accountState) {
        accountState.textContent = targetUnavailable
          ? "Indisponible · terminal ouvert"
          : "Disponible";
        accountState.classList.toggle("is-busy", targetUnavailable);
        accountState.classList.toggle("is-available", !targetUnavailable);
      }
      if (button) {
        button.disabled = targetUnavailable;
        button.title = targetUnavailable
          ? `${targetAccount?.label ?? "Ce compte"} est indisponible : un terminal Freebuff est déjà ouvert`
          : willCopy
          ? provider === "freebuff"
            ? "Copier la conversation vers le compte Freebuff choisi, la reprendre et conserver la source dans l’Historique"
            : targetIsFreebuff
              ? "Copier la discussion dans le compte Freebuff choisi, la reprendre dans son terminal et conserver la source dans l’Historique"
              : "Copier la discussion dans le compte choisi, la reprendre automatiquement et conserver la source dans l’Historique"
          : provider === "freebuff"
            ? "Continuer dans le TUI Freebuff"
            : "Reprendre automatiquement dans le chat";
      }
    });
  });
  document.querySelectorAll<HTMLButtonElement>("[data-resume-session]").forEach((button) => {
    button.addEventListener("click", () => {
      const discussion = findDiscussion(
        button.dataset.resumeSession,
        button.dataset.resumeAccount,
      );
      if (!discussion) return;
      const target = discussionTargetFor(discussion);
      if (target && target !== discussion.accountId) {
        void continueDiscussionWith(discussion, target);
      } else {
        void resumeDiscussion(discussion);
      }
    });
  });
};

// --- Historique des demandes, regroupe par chat / terminal ----------------
// Le backend renvoie les messages utilisateur individuellement. La vue les
// regroupe par session ET par compte afin qu'une carte resume exclusivement les
// messages envoyes dans le chat ou le terminal correspondant.
const refreshPromptHistory = (): Promise<void> => {
  if (promptHistoryRefreshPromise) return promptHistoryRefreshPromise;
  promptHistoryRefreshPromise = (async () => {
    try {
      promptHistory = await invoke<PromptHistoryView>("list_prompt_history", { limit: 4000 });
      promptHistoryLoaded = true;
    } catch (error) {
      statusText = String(error);
      promptHistoryLoaded = true;
    }

    if (activeView === "history") render();
  })().finally(() => {
    promptHistoryRefreshPromise = null;
  });
  return promptHistoryRefreshPromise;
};

const promptHistoryPanelModel = () => ({
  history: promptHistory,
  loaded: promptHistoryLoaded,
  freebuffAccounts: (settings?.accounts ?? [])
    .filter((account) => accountProvider(account) === "freebuff")
    .map((account) => ({ id: account.id, label: account.label })),
  formatTimestamp,
  displayProjectDir,
});

const importCodexHistoryToFreebuff = async (
  sourceAccountId: string,
  sessionId: string,
  targetAccountId: string,
) => {
  const source = accountById(sourceAccountId);
  const target = accountById(targetAccountId);
  if (!source || !target || accountProvider(target) !== "freebuff") return;
  if (accountProvider(source) !== "codex") {
    statusText = "Seuls les historiques Codex peuvent être importés vers Freebuff pour le moment.";
    render();
    return;
  }
  statusText = `Import de « ${source.label} » vers ${target.label}…`;
  render();
  try {
    const folderPath = userEnvironmentPath(promptHistory?.prompts.find(
      (entry) => entry.accountId === sourceAccountId && entry.sessionId === sessionId,
    )?.cwd ?? source.projectDir ?? null);
    // Ne pas creer un chat orphelin si le compte est deja occupe par un autre
    // terminal Freebuff : la disponibilite est controlee avant l'import, puis
    // reverifiee par launchFreebuffDiscussionTerminal juste avant le spawn.
    await assertFreebuffAccountAvailable(target);
    const transcript = await invoke<string>("export_discussion_transcript", {
      accountId: sourceAccountId,
      sessionId,
    });
    const imported = await invoke<DiscussionSummary>("import_codex_transcript_to_freebuff", {
      sourceAccountId,
      sessionId,
      targetAccountId,
      folderPath,
      transcript,
    });
    if (!folderPath) {
      statusText = `Historique Codex importé dans Freebuff « ${target.label} » (terminal non ouvert : aucun environnement associé à cet historique).`;
    } else {
      // Freebuff n'expose pas de chat structure : la discussion se poursuit
      // dans le terminal TUI du compte cible, ouvert sur le chat importe.
      imported.folderPath = folderPath;
      await launchFreebuffDiscussionTerminal(imported, target, folderPath);
      statusText = `Historique Codex importé et repris dans Freebuff « ${target.label} ».`;
    }
  } catch (error) {
    statusText = `Import Codex → Freebuff échoué : ${String(error)}`;
  }
  render();
};

const openDiscussionForSession = (accountId: string, sessionId: string) => {
  const discussion = discussionForSession(allDiscussions(), accountId, sessionId);
  if (discussion) {
    openDiscussionChat(discussion);
    return;
  }
  openDiscussionHistory(sessionId);
};

type OrchestrationSessionTarget = {
  run: OrchestrationSnapshot;
  accountId: string;
  role: "orchestrator" | "worker";
  taskId: string | null;
  testerId: string | null;
  label: string;
};

const orchestrationSessionTarget = (
  sessionId: string,
): OrchestrationSessionTarget | null => {
  const normalizedSessionId = sessionId.trim();
  for (const run of orchestrations) {
    if (run.orchestratorSessionId?.trim() === normalizedSessionId) {
      return {
        run,
        accountId: orchestrationOrchestratorAccountId(run),
        role: "orchestrator",
        taskId: null,
        testerId: null,
        label: "Chat orchestrateur",
      };
    }
    const tester = run.testers.find(
      (candidate) => candidate.sessionId?.trim() === normalizedSessionId,
    );
    if (tester) {
      return {
        run,
        accountId: orchestrationOrchestratorAccountId(run),
        role: "orchestrator",
        taskId: null,
        testerId: tester.id,
        label: `Chat testeur ${tester.position}`,
      };
    }
    const task = run.tasks.find(
      (candidate) => candidate.sessionId?.trim() === normalizedSessionId,
    );
    if (task) {
      return {
        run,
        accountId: orchestrationWorkerAccountId(run, task),
        role: "worker",
        taskId: task.id,
        testerId: null,
        label: `Sous-chat worker ${task.position}`,
      };
    }
  }
  return null;
};

const openOrchestrationSession = async (
  requestedAccountId: string,
  sessionId: string,
): Promise<void> => {
  await refreshDiscussions();
  const target = orchestrationSessionTarget(sessionId);
  if (!target) {
    openDiscussionForSession(requestedAccountId, sessionId);
    return;
  }

  if (target.taskId) {
    dismissedOrchestrationWorkerPanes.delete(
      orchestrationWorkerPaneKey(target.run.id, target.taskId),
    );
  } else if (target.testerId) {
    dismissedOrchestrationTesterPanes.delete(
      orchestrationTesterPaneKey(target.run.id, target.testerId),
    );
  }
  syncOrchestrationChatPanes();

  let pane = expertChatPanes.find(
    (candidate) =>
      candidate.orchestrationId === target.run.id
      && candidate.orchestrationRole === target.role
      && candidate.orchestrationTaskId === target.taskId
      && candidate.orchestrationTesterId === target.testerId,
  ) ?? null;
  if (!pane) {
    pane = createExpertChatPane(null, {
      accountId: target.accountId,
      pendingWorkspace: orchestrationRequestedProjectDir(target.run),
      mode: "build",
      sessionId,
      orchestrationId: target.run.id,
      orchestrationRole: target.role,
      orchestrationTaskId: target.taskId,
      orchestrationTesterId: target.testerId,
    });
    expertChatPanes.push(pane);
  }
  attachOrchestrationDiscussion(pane, sessionId, target.accountId);
  if (!pane.discussion) {
    pane.loading = true;
    pane.error = null;
  }

  closeMobileOverlays();
  activeView = "chat";
  activateExpertChatPane(pane);
  statusText = pane.discussion
    ? `${target.label} ouvert`
    : `${target.label} ouvert · transcript en cours d’initialisation`;
  persistExpertChats();
  render();
  startAllExpertChatWork();
  if (!pane.discussion) void refreshOrchestrations();
};

// Rattache une session restauree a son PTY encore vivant sur le noeud.
// Renvoie false si le terminal n'existe plus. En mode web, l'appelant oublie
// alors cet ancien onglet au lieu de recreer un CLI devenu inutile.
const attachRestoredTerminal = async (
  session: TerminalSession,
  ptyId: number,
  remoteMetadata: { nodeId?: string | null; remoteId?: number | null } = {},
): Promise<boolean> => {
  const previousPtyId = session.ptyId;
  const previousNodeId = session.nodeId ?? null;
  const previousRemoteId = session.remoteId ?? null;
  const currentOwner = terminalSessionsByPtyId.get(ptyId);
  if (currentOwner && currentOwner !== session) {
    // Deux restaurations concurrentes ne doivent jamais partager le même PTY :
    // la seconde sonde peut réussir, mais son socket écraserait ensuite celui
    // de la première session.
    return false;
  }
  if (previousPtyId !== null && previousPtyId !== ptyId) {
    terminalSessionsByPtyId.delete(previousPtyId);
  }
  session.ptyId = ptyId;
  if (remoteMetadata.nodeId !== undefined) session.nodeId = remoteMetadata.nodeId ?? null;
  if (remoteMetadata.remoteId !== undefined) session.remoteId = remoteMetadata.remoteId ?? null;
  terminalSessionsByPtyId.set(ptyId, session);
  try {
    await invoke("attach_terminal", {
      id: ptyId,
      nodeId: session.nodeId ?? undefined,
      remoteId: session.remoteId ?? undefined,
      cols: session.terminal.cols,
      rows: session.terminal.rows,
    });
  } catch {
    if (terminalSessionsByPtyId.get(ptyId) === session) {
      terminalSessionsByPtyId.delete(ptyId);
    }
    session.ptyId = previousPtyId;
    if (remoteMetadata.nodeId !== undefined) session.nodeId = previousNodeId;
    if (remoteMetadata.remoteId !== undefined) session.remoteId = previousRemoteId;
    if (previousPtyId !== null) terminalSessionsByPtyId.set(previousPtyId, session);
    return false;
  }    session.running = true;
    session.status = "Rattache";
    flushTerminalInput(session);
    // La sonde et l'association sont atomiques du point de vue du registre
    // local : aucune autre restauration ne peut prendre ce PTY entre les deux.
    if (terminalSessionsByPtyId.get(ptyId) !== session) {
      terminalSessionsByPtyId.delete(ptyId);
      session.ptyId = previousPtyId;
      session.nodeId = previousNodeId;
      session.remoteId = previousRemoteId;
      if (previousPtyId !== null) terminalSessionsByPtyId.set(previousPtyId, session);
      return false;
    }
  terminalActivity.touch(session.key);
  // Les dimensions du PTY distant ne sont plus celles du DOM local apres
  // rattachement. Sans ce resize, l'affichage wrapperait a 80 colonnes alors
  // que le panneau en offre 120. Si le terminal n'est pas encore monte dans le
  // DOM, l'appel est sans effet (host.clientWidth < 2) ; mountExpertTerminals
  // prendra le relais au prochain render().
  fitAndResizeTerminal(session);
  return true;
};

const restoreTerminals = async () => {
  if (!settings) return;
  const state = loadOpenTerminalRecords();
  const eligibleRecords = state.terminals.filter(
    (record) =>
      settings!.accounts.some((account) => account.id === record.accountId) &&
      !!userEnvironmentPath(record.folderPath),
  );
  const records = eligibleRecords;
  if (records.length === 0) {
    if (eligibleRecords.length === 0 && state.terminals.length > 0) persistTerminalSessions();
    return;
  }

  let restored: TerminalSession[] = [];
  for (const record of records) {
    const account = settings.accounts.find((candidate) => candidate.id === record.accountId);
    if (!account) continue;
    const agentId =
      record.agentId && settings.agents.some((agent) => agent.id === record.agentId)
        ? record.agentId
        : codexAgentId();
    const restoredFolder = userEnvironmentPath(record.folderPath);
    if (!restoredFolder) continue;
    const session = await createTerminalSession(
      account,
      proxyForAccount(account),
      agentId,
      restoredFolder,
    );
    session.nodeId = record.nodeId ?? null;
    session.remoteId = record.remoteId ?? null;
    session.key = record.key;
    session.codexSessionId = record.codexSessionId ?? null;
    session.resumeSessionId = record.codexSessionId ?? null;
    session.workspaceId = record.workspaceId?.trim() || null;
    session.workspacePath = record.workspacePath?.trim() || null;
    session.projectDir = record.projectDir?.trim() || account.projectDir?.trim() || null;
    if (session.codexSessionId) claimedSessionIds.add(session.codexSessionId);
    terminalSessions.push(session);
    restored.push(session);
  }

  if (isRemoteMode()) {
    const recordByKey = new Map(records.map((record) => [record.key, record]));
    const liveRemoteKeys = new Set<string>();

    // Sonder les PTY existants par petits lots garde l'ouverture du mur rapide,
    // meme si le navigateur avait memorise beaucoup d'anciens onglets.
    for (let index = 0; index < restored.length; index += TERMINAL_RESTORE_CONCURRENCY) {
      const results = await Promise.all(
        restored.slice(index, index + TERMINAL_RESTORE_CONCURRENCY).map(async (session) => {
          const record = recordByKey.get(session.key);
          const attached =
            typeof record?.ptyId === "number"
            && await attachRestoredTerminal(session, record.ptyId, {
              nodeId: record.nodeId,
              remoteId: record.remoteId,
            });
          return { session, attached };
        }),
      );
      results.forEach(({ session, attached }) => {
        if (attached) liveRemoteKeys.add(session.key);
      });
    }

    // Un identifiant absent correspond a un ancien terminal deja termine. Le
    // relancer automatiquement recreait jusqu'a 16 CLI et bloquait la fenetre.
    const staleSessions = restored.filter((session) => !liveRemoteKeys.has(session.key));
    staleSessions.forEach((session) => {
      if (session.codexSessionId) claimedSessionIds.delete(session.codexSessionId);
      terminalActivity.forget(session.key);
      session.terminal.dispose();
    });
    if (staleSessions.length > 0) {
      const staleKeys = new Set(staleSessions.map((session) => session.key));
      terminalSessions = terminalSessions.filter((session) => !staleKeys.has(session.key));
      restored = restored.filter((session) => !staleKeys.has(session.key));
    }
  }

  if (restored.length === 0) {
    if (activeTerminalKey && !terminalSessions.some((session) => session.key === activeTerminalKey)) {
      activeTerminalKey = terminalSessions[0]?.key ?? null;
    }
    persistTerminalSessions();
    if (activeView === "terminal" || activeView === "chat") render();
    return;
  }

  activeTerminalKey =
    (state.activeKey && restored.some((session) => session.key === state.activeKey) && state.activeKey) ||
    restored[0].key;
  const restoredActive = activeTerminal();
  if (restoredActive && activeView === "terminal") activateTerminalSession(restoredActive);
  // La vue chat liste elle aussi les terminaux (colonne de gauche et tuiles du
  // mur) : sans ce rendu, les sessions restaurees restaient invisibles jusqu'a
  // la prochaine action de l'utilisateur, qui les faisait apparaitre d'un coup.
  if (activeView === "terminal" || activeView === "chat") render();

  // Les PTY desktop disparaissent avec l'application : leur reprise reste utile.
  // En mode web, seuls les PTY effectivement rattaches ci-dessus sont conserves
  // et aucune ancienne commande n'est relancee automatiquement.
  const restartable = isRemoteMode() ? [] : restored;
  for (let index = 0; index < restartable.length; index += TERMINAL_RESTORE_CONCURRENCY) {
    const batch = restartable.slice(index, index + TERMINAL_RESTORE_CONCURRENCY);
    await Promise.all(batch.map((session) => {
      const command = isPlausibleSessionId(session.codexSessionId)
        ? buildResumeCommand(session.codexSessionId, accountById(session.accountId))
        : null;
      return startTerminalSession(session, command, false, false);
    }));
    if (activeView === "terminal" || activeView === "chat") render();
  }

  if (eligibleRecords.length > records.length) {
    statusText = `${records.length} terminaux restaures; la limite de la fenetre est atteinte`;
  }
  persistTerminalSessions();
};

const refreshActiveTerminals = async (forceReattach = false): Promise<boolean> => {
  if (!isRemoteMode() || !settings) return true;
  if (activeTerminalsInFlight) {
    activeTerminalsRefreshRequested = true;
    activeTerminalsForceReattachRequested ||= forceReattach;
    return true;
  }
  activeTerminalsInFlight = true;
  try {
    // Le catalogue est lu avant la restauration locale : la couche distante
    // memorise ainsi le noeud de chaque PTY, indispensable pour sonder un
    // terminal qui vit sur un VPS secondaire.
    const active = await invoke<ActiveTerminalSummary[]>("list_active_terminals");
    await ensureTerminalsRestored();

    let changed = false;
    for (const summary of active) {
      const ptyId = Number(summary.id);
      if (!Number.isInteger(ptyId) || ptyId <= 0 || summary.loginOnly) continue;
      const compatibilityFallback = summary.compatibilityFallback === true;
      const account = accountById(summary.accountId)
        ?? (compatibilityFallback ? selectedAccount() ?? settings.accounts[0] ?? null : null);
      const folderPath = userWorkspacePath(summary.workspacePath)
        ?? (compatibilityFallback
          ? userEnvironmentPath(currentWorkspace()) ?? userEnvironmentPath(account?.projectDir)
          : null);
      if (!account || !folderPath) continue;

      const sourceTerminalKey = summary.sourceTerminalKey?.trim()
        || (compatibilityFallback ? `terminal-compat-${ptyId}` : null);
      let session = terminalSessions.find((candidate) => candidate.ptyId === ptyId) ?? null;
      if (!session && sourceTerminalKey) {
        session = terminalSessions.find((candidate) =>
          candidate.key === sourceTerminalKey
          && candidate.accountId === summary.accountId,
        ) ?? null;
      }

      if (!session) {
        const requestedAgentId = summary.agentId?.trim() || null;
        const agentId = requestedAgentId && settings.agents.some((agent) => agent.id === requestedAgentId)
          ? requestedAgentId
          : codexAgentId();
        session = await createTerminalSession(
          account,
          proxyForAccount(account),
          agentId,
          folderPath,
        );
        if (compatibilityFallback) {
          session.displayTitleOverride = `Terminal existant #${String(ptyId).slice(-6)}`;
        }
        if (
          sourceTerminalKey
          && !terminalSessions.some((candidate) => candidate.key === sourceTerminalKey)
        ) {
          session.key = sourceTerminalKey;
        } else {
          session.key = uid("terminal-synced");
        }
        session.workspaceId = summary.workspaceId?.trim() || null;
        session.workspacePath = summary.workspacePath?.trim() || folderPath;
        session.nodeId = summary.nodeId ?? null;
        session.remoteId = Number.isSafeInteger((summary as ActiveTerminalSummary & { remoteId?: number }).remoteId)
          ? Number((summary as ActiveTerminalSummary & { remoteId?: number }).remoteId)
          : ptyId;
        session.projectDir = account.projectDir?.trim() || null;
        session.startedAtUnix = Number.isFinite(summary.startedAt) ? summary.startedAt : null;
        session.externalSync = summary.external === true;
        terminalSessions.push(session);

        if (!session.externalSync && !await attachRestoredTerminal(session, ptyId)) {
          terminalSessions = terminalSessions.filter((candidate) => candidate !== session);
          session.terminal.dispose();
          continue;
        }
        rememberWorkspace(folderPath);
        if (!activeTerminalKey) activeTerminalKey = session.key;
        changed = true;
        continue;
      }

      if (compatibilityFallback) {
        session.displayTitleOverride = `Terminal existant #${String(ptyId).slice(-6)}`;
      }

      const metadataChanged =
        session.folderPath !== folderPath
        || session.workspaceId !== (summary.workspaceId?.trim() || null)
        || session.workspacePath !== (summary.workspacePath?.trim() || folderPath)
        || session.startedAtUnix !== (Number.isFinite(summary.startedAt) ? summary.startedAt : null);
      session.folderPath = folderPath;
      session.workspaceId = summary.workspaceId?.trim() || null;
      session.workspacePath = summary.workspacePath?.trim() || folderPath;
      session.startedAtUnix = Number.isFinite(summary.startedAt) ? summary.startedAt : null;
      session.externalSync = summary.external === true;
      let reattached = false;
      if (
        !session.externalSync
        && (session.ptyId !== ptyId
          || !session.running
          || (forceReattach && session.key === activeTerminalKey))
      ) {
        if (!await attachRestoredTerminal(session, ptyId)) continue;
        reattached = true;
      }
      if (metadataChanged || reattached) changed = true;
      rememberWorkspace(folderPath);
    }

    if (changed) {
      persistTerminalSessions();
      if (activeView === "terminal" || activeView === "chat") render();
    }
    return true;
  } catch {
    return false;
  } finally {
    activeTerminalsInFlight = false;
    if (activeTerminalsRefreshRequested) {
      const forceNextRefresh = activeTerminalsForceReattachRequested;
      activeTerminalsRefreshRequested = false;
      activeTerminalsForceReattachRequested = false;
      window.setTimeout(() => void refreshActiveTerminals(forceNextRefresh), 0);
    }
    scheduleRuntimeSyncFlush();
  }
};

// Reconcile le PTY serveur, remplace un WebSocket eventuellement semi-ouvert,
// puis redonne le clavier a xterm apres le remontage du DOM et des overlays.
const recoverActiveTerminalInput = async (): Promise<void> => {
  if (activeView !== "terminal") return;
  requestTerminalFocusKey = activeTerminalKey;
  await refreshActiveTerminals(true);
  if (activeView !== "terminal") return;

  const session = activeTerminal();
  if (!session?.running) return;
  requestTerminalFocusKey = session.key;
  window.requestAnimationFrame(() => {
    window.requestAnimationFrame(() => {
      const current = activeTerminal();
      if (
        activeView !== "terminal"
        || current?.key !== session.key
        || !current.running
        || activeModalDialog()
        || !current.terminal.element?.isConnected
      ) {
        return;
      }
      fitAndResizeTerminal(current);
      current.terminal.focus();
      if (requestTerminalFocusKey === current.key) requestTerminalFocusKey = null;
    });
  });
};

const readClaudeDesignSessions = (): Record<string, string> => {
  try {
    const parsed = JSON.parse(accountScopedStorage.getItem(DESIGN_CLAUDE_SESSIONS_STORAGE_KEY) ?? "{}") as unknown;
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return {};
    return Object.fromEntries(
      Object.entries(parsed)
        .filter((entry): entry is [string, string] => typeof entry[1] === "string" && entry[1].trim().length > 0),
    );
  } catch {
    return {};
  }
};

const writeClaudeDesignSessions = (sessions: Record<string, string>) => {
  try {
    accountScopedStorage.setItem(DESIGN_CLAUDE_SESSIONS_STORAGE_KEY, JSON.stringify(sessions));
  } catch {
    // Le studio reste utilisable si le stockage du navigateur est indisponible.
  }
};

const claudeDesignAccounts = (): AccountProfile[] =>
  (settings?.accounts ?? []).filter((account) => accountProvider(account) === "claude");

const selectedClaudeDesignAccount = (): AccountProfile | null => {
  const accounts = claudeDesignAccounts();
  return accounts.find((account) => account.id === designClaudeAccountId) ?? accounts[0] ?? null;
};

const claudeDesignContextKeyFor = (
  account: AccountProfile,
  projectDir: string | null,
): string => JSON.stringify([account.id, projectDir ?? ""]);

const stopClaudeDesignPoll = () => {
  if (designClaudePoll !== null) {
    clearInterval(designClaudePoll);
    designClaudePoll = null;
  }
};

const syncClaudeDesignContext = (): boolean => {
  const account = selectedClaudeDesignAccount();
  if (!account) {
    if (designClaudeContextKey === null && designClaudeAccountId === null) return false;
    stopClaudeDesignPoll();
    designClaudeTranscriptRequestId += 1;
    designClaudeAccountId = null;
    designClaudeContextKey = null;
    designClaudeProjectDir = currentProjectDir();
    designClaudeSessionId = null;
    designClaudeMessages = [];
    designClaudeTurn = null;
    designClaudeError = null;
    designClaudeLoading = false;
    designClaudeTranscriptLoaded = true;
    return true;
  }

  if (designClaudeAccountId !== account.id) {
    designClaudeAccountId = account.id;
    accountScopedStorage.setItem(DESIGN_CLAUDE_ACCOUNT_STORAGE_KEY, account.id);
  }
  const projectDir = currentProjectDir() ?? account.projectDir?.trim() ?? null;
  const contextKey = claudeDesignContextKeyFor(account, projectDir);
  if (contextKey === designClaudeContextKey) return false;
  if (chatTurnIsBusy(designClaudeTurn?.status)) return false;

  stopClaudeDesignPoll();
  designClaudeTranscriptRequestId += 1;
  designClaudeContextKey = contextKey;
  designClaudeProjectDir = projectDir;
  designClaudeSessionId = readClaudeDesignSessions()[contextKey] ?? null;
  designClaudeMessages = [];
  designClaudeTurn = null;
  designClaudeError = null;
  designClaudeLoading = !!designClaudeSessionId;
  designClaudeTranscriptLoaded = !designClaudeSessionId;
  designClaudeTranscriptInFlight = false;
  return true;
};

const rememberClaudeDesignSession = (sessionId: string | null | undefined) => {
  const normalized = sessionId?.trim();
  if (!normalized || !designClaudeContextKey) return;
  designClaudeSessionId = normalized;
  const sessions = readClaudeDesignSessions();
  sessions[designClaudeContextKey] = normalized;
  writeClaudeDesignSessions(sessions);
};

const forgetCurrentClaudeDesignSession = () => {
  if (!designClaudeContextKey) return;
  const sessions = readClaudeDesignSessions();
  delete sessions[designClaudeContextKey];
  writeClaudeDesignSessions(sessions);
};

const loadClaudeDesignTranscriptIfNeeded = async () => {
  syncClaudeDesignContext();
  const account = selectedClaudeDesignAccount();
  const sessionId = designClaudeSessionId;
  const contextKey = designClaudeContextKey;
  if (
    !account || !sessionId || !contextKey ||
    designClaudeTranscriptLoaded || designClaudeTranscriptInFlight ||
    chatTurnIsBusy(designClaudeTurn?.status)
  ) {
    return;
  }

  const requestId = ++designClaudeTranscriptRequestId;
  designClaudeTranscriptInFlight = true;
  designClaudeLoading = true;
  try {
    const transcript = await invoke<DiscussionTranscriptView>("get_discussion_transcript", {
      accountId: account.id,
      sessionId,
    });
    if (requestId !== designClaudeTranscriptRequestId || contextKey !== designClaudeContextKey) return;
    designClaudeMessages = transcript.messages;
    designClaudeError = null;
  } catch (error) {
    if (requestId !== designClaudeTranscriptRequestId || contextKey !== designClaudeContextKey) return;
    designClaudeError = `Session Design introuvable : ${String(error)}`;
  } finally {
    if (requestId === designClaudeTranscriptRequestId && contextKey === designClaudeContextKey) {
      designClaudeLoading = false;
      designClaudeTranscriptLoaded = true;
      designClaudeTranscriptInFlight = false;
      if (activeView === "design" && activeDesignTool === "claude") render();
    }
  }
};

const claudeDesignModeLabel = (mode: ClaudeDesignMode): string => {
  switch (mode) {
    case "wireframe": return "wireframe et parcours utilisateur";
    case "presentation": return "présentation et narration visuelle";
    case "system": return "design system, composants et tokens";
    default: return "prototype d’interface fonctionnel";
  }
};

const claudeDesignSkill = (
  mode: ClaudeDesignMode,
  projectDir: string,
): ChatAgentSkillPrompt => ({
  id: "claude-design-studio",
  name: "Claude Design Studio intégré",
  content: `# Mission

Tu travailles dans le studio Design intégré de Codex Switch Terminal. La demande concerne un ${claudeDesignModeLabel(mode)}.
La racine locale obligatoire du projet est : ${projectDir.replaceAll("`", "'")}

- Commence par comprendre le projet et son langage visuel existant avant de proposer ou modifier quoi que ce soit.
- Toute réalisation demandée doit être enregistrée physiquement sur le PC dans cette racine projet avant la réponse finale. Ne livre jamais uniquement du code ou un prototype dans le chat.
- Pour une application existante, modifie les fichiers source appropriés à leur emplacement actuel. Pour un livrable autonome sans emplacement indiqué, crée-le sous \`design-output/<nom-du-livrable>/\` dans la racine projet.
- N’écris jamais en dehors de la racine projet. Utilise les outils disponibles pour inspecter, créer et modifier les fichiers.
- Avant de terminer, vérifie sur disque que chaque fichier annoncé existe et que les validations pertinentes passent. Si l’écriture échoue, signale clairement l’échec au lieu de prétendre avoir sauvegardé.
- Produis une interface crédible, responsive, accessible et cohérente avec le produit, pas une simple description théorique.
- Préserve les changements existants et évite toute opération destructive hors du besoin exprimé.
- À la fin, donne les chemins locaux exacts des fichiers créés ou modifiés et la manière de les prévisualiser ou de les vérifier.
- Reste dans le périmètre design demandé et échange en français sauf demande contraire.`,
});

const claudeDesignAssistantText = (snapshot: ChatTurnSnapshot): string =>
  snapshot.parts
    .filter((part) => part.kind === "text" && part.text?.trim())
    .map((part) => part.text!.trim())
    .join("\n\n")
    .trim();

const settleLatestClaudeDesignMessage = (failed = false) => {
  for (let index = designClaudeMessages.length - 1; index >= 0; index -= 1) {
    const message = designClaudeMessages[index];
    if (message.role !== "user" || message.deliveryState !== "pending") continue;
    designClaudeMessages[index] = failed
      ? { ...message, deliveryState: "failed" }
      : { role: message.role, text: message.text, timestamp: message.timestamp };
    break;
  }
};

const claudeDesignStudioModel = (): ClaudeDesignStudioModel => {
  syncClaudeDesignContext();
  const accounts = claudeDesignAccounts();
  const account = selectedClaudeDesignAccount();
  return {
    accounts: accounts.map((candidate) => ({
      id: candidate.id,
      label: candidate.label,
      model: accountModel(candidate),
    })),
    selectedAccountId: account?.id ?? "",
    projectDir: designClaudeProjectDir ?? currentProjectDir(),
    messages: designClaudeMessages,
    livePartsHtml: designClaudeTurn?.parts.length
      ? renderChatTurnParts(
          designClaudeTurn.parts,
          "Claude",
          designClaudeTurn.startedAt,
          designClaudeTurn.finishedAt ?? null,
        )
      : "",
    status: designClaudeTurn?.status ?? "idle",
    error: designClaudeError,
    draft: designClaudeDraft,
    loading: designClaudeLoading,
    mode: designClaudeMode,
    sessionId: designClaudeSessionId,
  };
};

const scrollClaudeDesignFeedToEnd = () => {
  window.requestAnimationFrame(() => {
    const feed = document.querySelector<HTMLElement>("#claudeDesignFeed");
    if (feed) feed.scrollTop = feed.scrollHeight;
  });
};

const syncClaudeDesignLiveDom = () => {
  if (activeView !== "design" || activeDesignTool !== "claude") return;
  const feed = document.querySelector<HTMLElement>("#claudeDesignFeed");
  const live = document.querySelector<HTMLElement>("#claudeDesignLive");
  const followLatest = !!feed && feed.scrollHeight - feed.scrollTop - feed.clientHeight < 120;
  const busy = chatTurnIsBusy(designClaudeTurn?.status);
  if (live) {
    live.innerHTML = designClaudeTurn?.parts.length
      ? renderChatTurnParts(
          designClaudeTurn.parts,
          "Claude",
          designClaudeTurn.startedAt,
          designClaudeTurn.finishedAt ?? null,
        )
      : "";
    live.dataset.busy = String(busy);
    renderIcons(live);
  }

  const state = document.querySelector<HTMLElement>("#claudeDesignRunState");
  if (state) {
    const label = designClaudeTurn?.status === "finalizing" ? "Finalisation" : busy ? "Claude travaille" : "Prêt";
    state.classList.toggle("is-running", busy);
    state.innerHTML = `<i data-lucide="${busy ? "loader-circle" : "circle-check"}"></i>${label}`;
    renderIcons(state);
  }

  const error = document.querySelector<HTMLElement>("#claudeDesignError");
  if (error) {
    error.hidden = !designClaudeError;
    error.innerHTML = designClaudeError
      ? `<i data-lucide="circle-alert"></i><span>${escapeHtml(designClaudeError)}</span>`
      : "";
    if (designClaudeError) renderIcons(error);
  }
  if (followLatest && feed) feed.scrollTop = feed.scrollHeight;
};

const applyClaudeDesignSnapshot = async (snapshot: ChatTurnSnapshot) => {
  const previousStatus = designClaudeTurn?.status;
  designClaudeTurn = snapshot;
  rememberClaudeDesignSession(snapshot.sessionId);

  if (chatTurnIsBusy(snapshot.status)) {
    statusText = snapshot.status === "finalizing"
      ? "Claude Design finalise le résultat…"
      : "Claude Design travaille dans le projet…";
    syncStatusTextDom();
    syncClaudeDesignLiveDom();
    return;
  }

  stopClaudeDesignPoll();
  if (snapshot.status === "completed") {
    settleLatestClaudeDesignMessage(false);
    const response = claudeDesignAssistantText(snapshot);
    if (response && previousStatus !== "completed") {
      designClaudeMessages.push({
        role: "assistant",
        text: response,
        timestamp: snapshot.finishedAt ?? Math.floor(Date.now() / 1000),
      });
    }
    designClaudeTurn = { ...snapshot, parts: [] };
    designClaudeError = null;
    designClaudeTranscriptLoaded = true;
    statusText = "Claude Design a terminé";
    void refreshDiscussions();
  } else if (snapshot.status === "failed") {
    settleLatestClaudeDesignMessage(true);
    designClaudeError = snapshot.error || "Claude Design n’a pas pu terminer la demande.";
    statusText = designClaudeError;
  } else {
    settleLatestClaudeDesignMessage(false);
    designClaudeError = null;
    statusText = "Claude Design arrêté";
  }
  if (activeView === "design" && activeDesignTool === "claude") {
    render();
    scrollClaudeDesignFeedToEnd();
  } else {
    syncStatusTextDom();
  }
};

const pollClaudeDesignTurn = async () => {
  if (!designClaudeTurn || designClaudeTurn.id <= 0 || designClaudePollInFlight) return;
  designClaudePollInFlight = true;
  try {
    const snapshot = await invoke<ChatTurnSnapshot>("chat_turn_status", { id: designClaudeTurn.id });
    await applyClaudeDesignSnapshot(snapshot);
  } catch (error) {
    designClaudeError = `Suivi de Claude Design impossible : ${String(error)}`;
    syncClaudeDesignLiveDom();
  } finally {
    designClaudePollInFlight = false;
  }
};

const startClaudeDesignPoll = () => {
  stopClaudeDesignPoll();
  designClaudePoll = window.setInterval(
    () => runWhenPageVisible(() => void pollClaudeDesignTurn()),
    650,
  );
};

const sendClaudeDesignMessage = async () => {
  syncClaudeDesignContext();
  const input = document.querySelector<HTMLTextAreaElement>("#claudeDesignPrompt");
  const prompt = (input?.value ?? designClaudeDraft).trim();
  const account = selectedClaudeDesignAccount();
  if (!account) {
    designClaudeError = "Ajoute d’abord un compte Claude dans la page Comptes.";
    render();
    return;
  }
  const projectDir = designClaudeProjectDir ?? account.projectDir?.trim() ?? null;
  if (!projectDir) {
    designClaudeError = "Sélectionne un environnement local avant de lancer Claude Design : les fichiers doivent être sauvegardés dans un dossier précis du PC.";
    statusText = "Claude Design · dossier local requis";
    render();
    return;
  }
  if (!prompt || chatTurnIsBusy(designClaudeTurn?.status)) {
    if (!prompt) {
      input?.setCustomValidity("Décris ce que Claude doit concevoir.");
      input?.reportValidity();
    }
    return;
  }

  const startedAt = Math.floor(Date.now() / 1000);
  designClaudeDraft = "";
  designClaudeError = null;
  designClaudeMessages.push({
    role: "user",
    text: prompt,
    timestamp: startedAt,
    deliveryState: "pending",
  });
  designClaudeTurn = {
    id: 0,
    accountId: account.id,
    sessionId: designClaudeSessionId,
    status: "running",
    startedAt,
    finishedAt: null,
    error: null,
    activities: [],
    thoughts: [],
    parts: [],
  };
  statusText = "Claude Design démarre…";
  render();
  scrollClaudeDesignFeedToEnd();

  try {
    const snapshot = await invoke<ChatTurnSnapshot>("start_chat_turn", {
      accountId: account.id,
      sessionId: designClaudeSessionId,
      prompt,
      projectDir,
      mode: "build",
      model: accountModel(account),
      reasoningEffort: null,
      sourceChatKey: "claude-design-studio",
      agentTools: [],
      agentSkills: [claudeDesignSkill(designClaudeMode, projectDir)],
    });
    await applyClaudeDesignSnapshot(snapshot);
    if (chatTurnIsBusy(snapshot.status)) startClaudeDesignPoll();
  } catch (error) {
    settleLatestClaudeDesignMessage(true);
    designClaudeTurn = {
      ...designClaudeTurn!,
      status: "failed",
      finishedAt: Math.floor(Date.now() / 1000),
      error: String(error),
    };
    designClaudeError = String(error);
    statusText = designClaudeError;
    stopClaudeDesignPoll();
    if (activeView === "design" && activeDesignTool === "claude") render();
  }
};

const stopClaudeDesignTurn = async () => {
  if (!designClaudeTurn || designClaudeTurn.id <= 0) {
    designClaudeError = "Claude est encore en cours de démarrage.";
    syncClaudeDesignLiveDom();
    return;
  }
  try {
    const snapshot = await invoke<ChatTurnSnapshot>("stop_chat_turn", { id: designClaudeTurn.id });
    await applyClaudeDesignSnapshot(snapshot);
  } catch (error) {
    designClaudeError = `Arrêt impossible : ${String(error)}`;
    syncClaudeDesignLiveDom();
  }
};

const resetClaudeDesignSession = () => {
  if (chatTurnIsBusy(designClaudeTurn?.status)) return;
  stopClaudeDesignPoll();
  forgetCurrentClaudeDesignSession();
  designClaudeTranscriptRequestId += 1;
  designClaudeSessionId = null;
  designClaudeMessages = [];
  designClaudeTurn = null;
  designClaudeDraft = "";
  designClaudeError = null;
  designClaudeLoading = false;
  designClaudeTranscriptLoaded = true;
  statusText = "Nouvelle session Claude Design";
  render();
};

