const readAgentsModalForm = () => {
  if (!settings) return;
  document.querySelectorAll<HTMLElement>("[data-agent-id]").forEach((element) => {
    const input = element as HTMLInputElement | HTMLSelectElement;
    const id = input.dataset.agentId;
    const field = input.dataset.agentField;
    const agent = settings?.agents.find((candidate) => candidate.id === id);
    if (!agent || !field) return;
    if (field === "label") {
      const value = input.value.trim();
      if (value || !agent.builtin) agent.label = value || agent.label;
    } else if (field === "command") {
      agent.command = input.value.trim();
    } else if (field === "kind" && !agent.builtin) {
      agent.kind = input.value === "ide" ? "ide" : "cli";
    }
  });
};

const addAgent = () => {
  if (!settings) return;
  readAgentsModalForm();
  settings.agents.push({
    id: uid("agent"),
    label: "Nouvel agent",
    command: "",
    kind: "cli",
    builtin: false,
    loginCommand: null,
    statusCommand: null,
    doctorCommand: null,
  });
  statusText = "Agent ajoute";
  render();
};

const removeAgent = (id: string | null) => {
  if (!settings || !id) return;
  const agent = settings.agents.find((candidate) => candidate.id === id);
  if (!agent || agent.builtin) return;
  readAgentsModalForm();
  settings.agents = settings.agents.filter((candidate) => candidate.id !== id);
  if (settings.activeAgentId === id) {
    settings.activeAgentId = settings.agents[0]?.id ?? null;
  }
  statusText = "Agent supprime";
  render();
};

const saveAgentsModal = async () => {
  if (!settings) return;
  readAgentsModalForm();
  // Un agent non integre sans commande ne peut pas etre lance : on l'ecarte
  // pour eviter qu'un "run" retombe silencieusement sur Codex.
  settings.agents = settings.agents.filter((agent) => agent.builtin || agent.command.trim());
  forgetDialogTrigger("agents");
  agentsModalOpen = false;
  await saveSettings();
};

const readNewTerminalModalForm = () => {
  if (!settings || !newTerminalAccountId) return null;
  const account = settings.accounts.find((candidate) => candidate.id === newTerminalAccountId);
  if (!account) return null;

  newTerminalWorkspacePath =
    document.querySelector<HTMLInputElement>("#newTerminalWorkspace")?.value.trim() || null;

  account.codexHome =
    document.querySelector<HTMLInputElement>("#newTerminalCodexHome")?.value.trim() ||
    account.codexHome ||
    defaultCodexHomeForLabel(account.label);
  account.projectDir =
    document.querySelector<HTMLInputElement>("#newTerminalProjectDir")?.value.trim() || null;
  if (settings.proxyControlsEnabled) {
    account.proxyId = document.querySelector<HTMLSelectElement>("#newTerminalProxy")?.value || null;
  }
  account.model =
    document.querySelector<HTMLInputElement>("#newTerminalModel")?.value.trim() ||
    accountModel(account);
  // L'intensite du compte n'est pertinente que pour Codex. Pour Claude, elle se
  // choisit dans chaque chat (sans ecraser une eventuelle valeur du compositeur).
  if (accountProvider(account) === "codex") {
    account.reasoningEffort = normalizeCodexReasoningEffort(
      document.querySelector<HTMLSelectElement>("#newTerminalReasoningEffort")?.value ??
        account.reasoningEffort,
    );
  }
  account.bypass =
    document.querySelector<HTMLInputElement>("#newTerminalBypass")?.checked ??
    accountBypassEnabled(account);
  account.fastMode =
    (document.querySelector<HTMLInputElement>("#newTerminalFastMode")?.checked ??
      (account.fastMode === true)) &&
    accountSupportsFastMode(account);
  const agentSelect = document.querySelector<HTMLSelectElement>("#newTerminalAgent");
  if (agentSelect) newTerminalAgentId = agentSelect.value || newTerminalAgentId;
  settings.autoRunCodex = document.querySelector<HTMLInputElement>("#newTerminalAutoRun")?.checked ?? settings.autoRunCodex;
  return account;
};

const readNewTerminalAccountDraft = () => {
  newTerminalAccountLabel =
    document.querySelector<HTMLInputElement>("#newTerminalAccountLabel")?.value.trim() ??
    newTerminalAccountLabel;
  const providerValue = document.querySelector<HTMLSelectElement>("#newAccountProvider")?.value;
  const previousDefault = providerDefaultModel(
    newTerminalAccountProvider,
    newTerminalInferenceProvider,
  );
  const choice = parseProviderChoice(providerValue);
  newTerminalAccountProvider = choice.provider;
  newTerminalInferenceProvider = choice.inferenceProvider;
  newTerminalAccountBypass =
    document.querySelector<HTMLInputElement>("#newAccountBypass")?.checked ??
    newTerminalAccountBypass;
  newTerminalAccountFastMode =
    document.querySelector<HTMLInputElement>("#newAccountFastMode")?.checked ??
    newTerminalAccountFastMode;
  const modelDraft = document.querySelector<HTMLInputElement>("#newAccountModel")?.value.trim() ?? "";
  newTerminalAccountModel = !modelDraft || modelDraft === previousDefault
    ? providerDefaultModel(newTerminalAccountProvider, newTerminalInferenceProvider)
    : modelDraft;
  if (newTerminalAccountProvider === "codex") {
    newTerminalAccountReasoningEffort = normalizeCodexReasoningEffort(
      document.querySelector<HTMLSelectElement>("#newAccountReasoningEffort")?.value ??
        newTerminalAccountReasoningEffort,
    );
  }
  if (!providerModelSupportsFastMode(newTerminalAccountProvider, newTerminalAccountModel)) {
    newTerminalAccountFastMode = false;
  }
};

const addAccountFromModal = () => {
  if (!settings) return;
  readNewTerminalAccountDraft();
  const label = newTerminalAccountLabel;
  if (!label) {
    statusText = "Nom de compte manquant";
    render();
    return;
  }

  const account = newAccountProfile(label, undefined, null, null, {
    provider: newTerminalAccountProvider,
    inferenceProvider: newTerminalInferenceProvider,
    bypass: newTerminalAccountBypass,
    model: newTerminalAccountModel,
    reasoningEffort: newTerminalAccountReasoningEffort,
    fastMode: newTerminalAccountFastMode,
  });
  settings.accounts.push(account);
  scheduleUnconnectedAccountCleanup();
  selectedAccountId = account.id;
  newTerminalAccountId = account.id;
  newTerminalAccountLabel = "";
  const providerNote = accountProviderLabel(account);
  const loginHint =
    account.provider === "aihubmix"
      ? " — saisis la clé API dans le terminal sécurisé"
      : account.provider === "claude"
      ? " — lance-le puis tape /login pour t'authentifier"
      : account.provider === "opencode"
        ? " — connecte ensuite la clé API dans OpenCode"
        : "";
  statusText = `Compte ${providerNote} ajoute (${account.bypass ? "bypass" : "sandbox"}, ${account.model})${loginHint}`;
  render();
};

// Depuis la page Comptes : cree un home isole pour le fournisseur choisi,
// persiste le compte, puis ouvre directement sa connexion interactive.
const addAccountAndLogin = async () => {
  if (!settings) return;
  const submitButton = document.querySelector<HTMLButtonElement>("#addAccount");
  if (submitButton?.disabled) return;
  const providerValue = document.querySelector<HTMLInputElement>(
    'input[name="newAccountProvider"]:checked',
  )?.value;
  const { provider, inferenceProvider } = parseProviderChoice(providerValue);
  const isBai = providerValue === "opencode:b.ai";
  const openAiCompatibleBaseInput = document.querySelector<HTMLInputElement>(
    "#newOpenAiCompatibleBaseUrl",
  );
  const openAiCompatibleKeyInput = document.querySelector<HTMLInputElement>(
    "#newOpenAiCompatibleApiKey",
  );
  const openAiCompatibleBaseUrl = provider === "openai-compatible"
    ? normalizeOpenAiCompatibleBaseUrl(openAiCompatibleBaseInput?.value ?? "")
    : null;
  const openAiCompatibleApiKey = provider === "openai-compatible"
    ? openAiCompatibleKeyInput?.value.trim() ?? ""
    : "";
  const openAiCompatibleModel = provider === "openai-compatible"
    ? document.querySelector<HTMLInputElement>("#newOpenAiCompatibleModel")?.value.trim() ?? ""
    : "";
  if (provider === "openai-compatible" && !openAiCompatibleBaseUrl) {
    openAiCompatibleBaseInput?.setCustomValidity(
      "Saisis une URL HTTP(S) valide, sans identifiants ni paramètres.",
    );
    openAiCompatibleBaseInput?.reportValidity();
    return;
  }
  openAiCompatibleBaseInput?.setCustomValidity("");
  if (provider === "openai-compatible" && !openAiCompatibleApiKey) {
    openAiCompatibleKeyInput?.setCustomValidity("Saisis la clé API de ce fournisseur.");
    openAiCompatibleKeyInput?.reportValidity();
    return;
  }
  openAiCompatibleKeyInput?.setCustomValidity("");
  if (submitButton) {
    submitButton.disabled = true;
    submitButton.setAttribute("aria-busy", "true");
  }
  const requestedLabel =
    document.querySelector<HTMLInputElement>("#newAccountLabel")?.value.trim() ?? "";
  const serviceLabel = isBai
    ? "b.ai"      : provider === "opencode"
        ? openCodeProviderOption(inferenceProvider)?.label ?? "OpenCode"
        : providerLabel(provider);
  const label = requestedLabel || `Nouveau compte ${serviceLabel}`;
  const account = newAccountProfile(
    label,
    uniqueCodexHomeForLabel(label, provider),
    null,
    null,
    {
      provider,
      inferenceProvider,
      ...(provider === "openai-compatible"
        ? {
          baseUrl: openAiCompatibleBaseUrl,
          apiKey: openAiCompatibleApiKey,
          model: openAiCompatibleModel || null,
        }
        : {}),
      // Le type b.ai est fixe sur DeepSeek V4 Flash en intensite max.
      ...(isBai ? { model: BAI_ACCOUNT_MODEL, reasoningEffort: "max" } : {}),
    },
  );
  // Identite serveur du type special : le backend la reconnait (id reserve,
  // home isole codex-homes/opencode-b-ai) et y provisionne la cle depuis
  // CST_BAI_API_KEY.
  if (isBai) account.id = SPECIAL_BAI_ACCOUNT_ID;
  settings.accounts.push(account);
  selectedAccountId = account.id;
  settings.defaultAccountId = account.id;
  const remoteCodexLogin = provider === "codex" && isRemoteMode();
  const nativeMobileLogin = remoteCodexLogin && hasMobileExternalHttpsOpener();
  const deferredMobileLogin =
    remoteCodexLogin &&
    (nativeMobileLogin || window.matchMedia("(max-width: 860px)").matches);
  // Un navigateur web exige l'ouverture du nouvel onglet pendant le clic.
  // En affichage mobile, on ne quitte jamais l'application avant la sauvegarde
  // et le demarrage du terminal de device-auth. Android ouvrira ensuite le lien
  // nativement ; un navigateur mobile gardera le bouton OpenAI dans le panneau.
  const popupPrepared =
    remoteCodexLogin
      ? deferredMobileLogin
        ? prepareRemoteCodexLoginTab(account.id, account.label)
        : openRemoteCodexLoginWindow(account.id, account.label)
      : false;
  try {
    if (isRemoteMode()) {
      const sharedAccountSettings = await invoke<AppSettings>("add_shared_account", { account });
      // Seul le registre de comptes est global. La vue des workspaces reste
      // celle de l'utilisateur courant et ne doit jamais etre remplacee par le
      // snapshot global renvoye pendant l'ajout.
      settings.accounts = sharedAccountSettings.accounts;
      settings.defaultAccountId = account.id;
    } else {
      settings = await invoke<AppSettings>("save_settings", { settings });
    }
    scheduleUnconnectedAccountCleanup();
  } catch (error) {
    statusText = String(error);
    if (popupPrepared) failRemoteCodexLoginWindow(account.id, statusText);
    render();
    return;
  }
  if (provider === "openai-compatible") {
    chatModelCatalogs.delete(account.id);
    chatModelCatalogErrors.delete(account.id);
    await loadChatModelCatalog(account.id, true);
    const catalog = chatModelCatalogs.get(account.id) ?? [];
    const error = chatModelCatalogErrors.get(account.id);
    statusText = error
      ? `Compte ${label} créé, mais le scan a échoué : ${error}`
      : `Compte ${label} prêt · ${catalog.length} modèle${catalog.length === 1 ? "" : "s"} détecté${catalog.length === 1 ? "" : "s"}`;
    render();
    return;
  }
  render();
  // Ouvre directement le terminal temporaire de connexion du compte.
  await reloginAccount(account.id, deferredMobileLogin);
  if (nativeMobileLogin && remoteCodexLoginWindowIsOpen(account.id)) {
    try {
      await openExternalHttpsUrl(CODEX_DEVICE_VERIFICATION_URL);
    } catch (error) {
      // Le terminal et le compte restent utilisables : le panneau permanent
      // fournit encore le lien OpenAI et le code de device-auth.
      statusText = `Compte ${account.label} créé. ${String(error)}`;
      render();
    }
  } else if (deferredMobileLogin && remoteCodexLoginWindowIsOpen(account.id)) {
    statusText = `Compte ${account.label} créé — touche « Ouvrir OpenAI » pour terminer la connexion.`;
    render();
  }
};

// Suppression depuis la liste simple. Avec l'auto-detection active, les fichiers
// locaux doivent aussi partir pour eviter que le compte reapparaisse au prochain
// chargement. Un seul dialogue confirme toute l'operation.
const deleteSelectedAccount = async () => {
  if (!settings || !selectedAccountId) return;
  const id = selectedAccountId;
  const target = settings.accounts.find((account) => account.id === id);
  const label = target?.label ?? "";
  if (!target) return;

  const deleteFiles = settings.autoDiscoverAccounts;
  const confirmed = window.confirm(
    deleteFiles
      ? `Supprimer « ${label} » et ses données de connexion locales ?\n\nCette action est définitive.`
      : `Supprimer le compte « ${label} » ?`,
  );
  if (!confirmed) return;

  try {
    settings = await invoke<AppSettings>("remove_account", { accountId: id, deleteFiles });
    statusText = deleteFiles
      ? `Compte « ${label} » supprimé (fichiers effacés)`
      : `Compte « ${label} » supprimé`;
  } catch (error) {
    // Un compte cree dans une autre vue peut encore n'exister qu'en memoire.
    // Pour toute autre erreur (dossier protege, verrouille…), on ne contourne
    // jamais les garde-fous du backend.
    if (!/Compte introuvable/i.test(String(error))) {
      statusText = String(error);
      render();
      return;
    }
    settings.accounts = settings.accounts.filter((account) => account.id !== id);
    if (settings.defaultAccountId === id) {
      settings.defaultAccountId = settings.accounts[0]?.id ?? null;
    }
    try {
      settings = await invoke<AppSettings>("save_settings", { settings });
      statusText = `Compte « ${label} » retiré`;
    } catch (error) {
      statusText = String(error);
      render();
      return;
    }
  }
  selectedAccountId = settings.defaultAccountId ?? settings.accounts[0]?.id ?? null;
  scheduleUnconnectedAccountCleanup();
  render();
};

let chatSideMoreMenuController: AbortController | null = null;

const bindChatSideMoreMenu = (): void => {
  chatSideMoreMenuController?.abort();
  chatSideMoreMenuController = null;

  const wrapper = document.querySelector<HTMLElement>(".chat-side-more");
  const trigger = document.querySelector<HTMLButtonElement>("#chatSideMoreToggle");
  const menu = document.querySelector<HTMLElement>("#chatSideMoreMenu");
  if (!wrapper || !trigger || !menu) return;

  const controller = new AbortController();
  const { signal } = controller;
  chatSideMoreMenuController = controller;
  const items = [...menu.querySelectorAll<HTMLButtonElement>("[role='menuitem']")];
  const positionMenu = (): void => {
    if (menu.hidden) return;
    const viewportPadding = 8;
    const menuGap = 10;
    const viewportWidth = document.documentElement.clientWidth;
    const viewportHeight = document.documentElement.clientHeight;
    const menuWidth = Math.min(258, Math.max(180, viewportWidth - viewportPadding * 2));
    const triggerRect = trigger.getBoundingClientRect();

    menu.style.width = `${menuWidth}px`;
    menu.style.maxHeight = `${Math.max(120, viewportHeight - viewportPadding * 2)}px`;
    menu.style.right = "auto";
    menu.style.bottom = "auto";
    const measuredHeight = menu.getBoundingClientRect().height;
    const preferredLeft = triggerRect.left - menuWidth - menuGap;
    const fallbackLeft = triggerRect.right + menuGap;
    const left = preferredLeft >= viewportPadding
      ? preferredLeft
      : Math.min(fallbackLeft, viewportWidth - menuWidth - viewportPadding);
    const top = Math.min(
      Math.max(viewportPadding, triggerRect.bottom - measuredHeight),
      Math.max(viewportPadding, viewportHeight - measuredHeight - viewportPadding),
    );
    menu.style.left = `${Math.max(viewportPadding, left)}px`;
    menu.style.top = `${top}px`;
  };
  const setOpen = (open: boolean, focusIndex: number | null = null): void => {
    chatSideMoreMenuOpen = open;
    trigger.setAttribute("aria-expanded", String(open));
    menu.hidden = !open;
    wrapper.classList.toggle("is-open", open);
    if (open) positionMenu();
    if (open && focusIndex !== null) {
      items[focusIndex]?.focus();
    }
  };
  setOpen(chatSideMoreMenuOpen);

  trigger.addEventListener("click", () => {
    setOpen(trigger.getAttribute("aria-expanded") !== "true");
  }, { signal });
  trigger.addEventListener("keydown", (event) => {
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      setOpen(true, event.key === "ArrowUp" ? items.length - 1 : 0);
    } else if (event.key === "Escape" && trigger.getAttribute("aria-expanded") === "true") {
      event.preventDefault();
      setOpen(false);
    }
  }, { signal });
  menu.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
      event.preventDefault();
      event.stopPropagation();
      setOpen(false);
      trigger.focus();
      return;
    }
    const current = items.indexOf(document.activeElement as HTMLButtonElement);
    let next: number | null = null;
    if (event.key === "Home") next = 0;
    else if (event.key === "End") next = items.length - 1;
    else if (event.key === "ArrowDown" || event.key === "ArrowRight") {
      next = current < 0 ? 0 : (current + 1) % items.length;
    } else if (event.key === "ArrowUp" || event.key === "ArrowLeft") {
      next = current <= 0 ? items.length - 1 : current - 1;
    }
    if (next === null) return;
    event.preventDefault();
    items[next]?.focus();
  }, { signal });
  menu.addEventListener("click", () => setOpen(false), { capture: true, signal });
  wrapper.addEventListener("focusout", (event) => {
    if (!wrapper.isConnected) return;
    const next = event.relatedTarget;
    if (!(next instanceof Node) || !wrapper.contains(next)) setOpen(false);
  }, { signal });
  document.addEventListener("pointerdown", (event) => {
    if (trigger.getAttribute("aria-expanded") !== "true") return;
    const target = event.target;
    if (!(target instanceof Node) || !wrapper.contains(target)) setOpen(false);
  }, { capture: true, signal });
  window.addEventListener("resize", positionMenu, { signal });
  wrapper.closest(".chat-side-tools")?.addEventListener("scroll", positionMenu, {
    passive: true,
    signal,
  });
};

