const readSettingsForm = () => {
  if (!settings) return;
  const proxyControls = document.querySelector<HTMLInputElement>("#proxyControls");
  if (proxyControls) {
    settings.proxyControlsEnabled = proxyControls.checked;
  }

  const account = selectedAccount();
  const accountLabel = document.querySelector<HTMLInputElement>("#accountLabel");
  const accountHome = document.querySelector<HTMLInputElement>("#accountHome");
  const projectDir = document.querySelector<HTMLInputElement>("#projectDir");
  const proxySelect = document.querySelector<HTMLSelectElement>("#proxySelect");
  const accountBypass = document.querySelector<HTMLInputElement>("#accountBypass");
  const accountModelInput = document.querySelector<HTMLInputElement>("#accountModel");
  const accountReasoningEffortSelect =
    document.querySelector<HTMLSelectElement>("#accountReasoningEffort");

  if (
    account &&
    (accountLabel ||
      accountHome ||
      projectDir ||
      proxySelect ||
      accountBypass ||
      accountModelInput ||
      accountReasoningEffortSelect)
  ) {
    if (accountLabel) account.label = accountLabel.value.trim() || account.label;
    if (accountHome) account.codexHome = accountHome.value.trim() || account.codexHome;
    if (projectDir) account.projectDir = projectDir.value.trim() || null;
    if (settings.proxyControlsEnabled) {
      account.proxyId = proxySelect?.value || null;
    }
    if (accountBypass) account.bypass = accountBypass.checked;
    if (accountModelInput) {
      account.model = accountModelInput.value.trim()
        || providerDefaultModel(accountProvider(account));
    }
    if (accountReasoningEffortSelect) {
      account.reasoningEffort = normalizeCodexReasoningEffort(accountReasoningEffortSelect.value);
    }
    syncSessionsForAccount(account);
  }

  const shellInput = document.querySelector<HTMLInputElement>("#shellInput");
  const codexCommand = document.querySelector<HTMLInputElement>("#codexCommand");
  const autoRun = document.querySelector<HTMLInputElement>("#autoRun");
  const codexBypass = document.querySelector<HTMLInputElement>("#codexBypass");
  const autoDiscover = document.querySelector<HTMLInputElement>("#autoDiscover");
  if (shellInput) settings.shell = shellInput.value.trim() || settings.shell;
  if (codexCommand) settings.codexCommand = codexCommand.value.trim() || settings.codexCommand || "codex";
  if (autoRun) settings.autoRunCodex = autoRun.checked;
  if (codexBypass) settings.codexBypass = codexBypass.checked;
  if (autoDiscover) settings.autoDiscoverAccounts = autoDiscover.checked;
};

const createTerminalSession = async (
  account: AccountProfile,
  proxy: ProxyProfile | null,
  agentId: string,
  folderPath: string | null,
  loginOnly = false,
): Promise<TerminalSession> => {
  const capturedEnvironment = userWorkspacePath(folderPath);
  if (!loginOnly && !capturedEnvironment) {
    throw new Error("Environnement terminal obligatoire");
  }
  const { createTerminalRuntime } = await loadTerminalRuntime();
  const { terminal, fitAddon } = createTerminalRuntime(activeTheme);

  const session: TerminalSession = {
    key: uid("terminal"),
    ptyId: null,
    accountId: account.id,
    agentId,
    title: account.label,
    loginOnly,
    folderPath: loginOnly ? null : capturedEnvironment,
    workspaceId: null,
    workspacePath: null,
    projectDir: account.projectDir?.trim() || null,
    proxySummary: proxy ? maskProxy(proxy.proxyUrl) : "sans proxy",
    status: "Pret",
    running: false,
    startedAtUnix: null,
    codexSessionId: null,
    resumeSessionId: null,
    sessionCaptureDone: false,
    terminal,
    fitAddon,
  };

  terminal.onData((data) => {
    const probing = termInputProbeActive();
    if (probing) {
      console.log(
        "[TERM-INPUT] onData",
        JSON.stringify(data),
        "ptyId=", session.ptyId,
        "running=", session.running,
        "externalSync=", session.externalSync,
        "key=", session.key,
      );
    }
    // Terminal Freebuff Desktop synchronise : aucun PTY Switch derriere.
    // Ne jamais tenter d'ecrire ni de bufferiser (ce qui rendait muet le
    // terminal et simulant un clavier actif sans aucune sortie).
    if (session.externalSync) return;
    if (session.ptyId !== null && session.running) {
      if (probing) {
        const st = terminalProbeStats.get(session.key) ?? { sent: 0, echoed: 0 };
        st.sent += data.length;
        terminalProbeStats.set(session.key, st);
      }
      void invoke("write_terminal", { id: session.ptyId, data }).catch(() => {
        queueTerminalInput(session, data);
        if (probing) console.log("[TERM-INPUT] write_terminal ECHOUÉ -> bufferisé", JSON.stringify(data));
      });
      return;
    }
    if (probing) {
      console.log(
        "[TERM-INPUT] onData mais ptyId/running non prêt (ptyId=",
        session.ptyId,
        ", running=",
        session.running,
        ") -> bufferisé, jamais envoyé tant que non rattaché",
      );
    }
    // Le changement Chat -> Terminal peut arriver pendant la reconnexion VPS.
    // Ne pas perdre les caractères saisis avant que le PTY soit réattaché.
    queueTerminalInput(session, data);
  });
  return session;
};

const terminalFocusHosts = new WeakSet<HTMLElement>();
const terminalPendingInput = new Map<string, string[]>();

const queueTerminalInput = (session: TerminalSession, data: string): void => {
  if (!data) return;
  const chunks = terminalPendingInput.get(session.key) ?? [];
  chunks.push(data);
  terminalPendingInput.set(session.key, chunks);
};

const flushTerminalInput = (session: TerminalSession): void => {
  if (!session.running || session.ptyId === null) return;
  const chunks = terminalPendingInput.get(session.key);
  if (!chunks?.length) return;
  terminalPendingInput.delete(session.key);
  void invoke("write_terminal", { id: session.ptyId, data: chunks.join("") }).catch(() => {
    const retry = terminalPendingInput.get(session.key) ?? [];
    terminalPendingInput.set(session.key, [...chunks, ...retry]);
  });
};

// --- Verrou clavier terminal -----------------------------------------------
// Le textarea cache de xterm reste le seul capteur de clavier (mecanisme
// officiel de xterm.js). Les protections documentees dans
// docs/terminal-focus-vps-fix.md (file terminalPendingInput, flushTerminalInput,
// focus differe) restent en place ; ce bloc ajoute trois couches pour qu'une
// frappe ne soit jamais perdue et qu'un silence ne soit plus jamais muet :
//  1. un chien de garde qui reprend le focus toutes les 500 ms ;
//  2. un intercepteur global keydown qui re-delivre a xterm la premiere frappe
//     tapee hors focus (alt-tab, remontage DOM, clic hors terminal...) ;
//  3. un badge par terminal montrant focus, file d'attente et transport.
type TerminalKeyboardBadgeTone = "ok" | "warn" | "off";

const TERMINAL_KEYBOARD_WATCHDOG_MS = 500;
const TERMINAL_INPUT_QUEUE_GUARD_MS = 2_000;

// Touches que l'intercepteur re-delivre a xterm quand le focus a ete perdu.
// Ctrl+lettre (hors AltGr) reste la propriete du navigateur et des raccourcis
// applicatifs ; Echap et F11 gardent leur comportement global.
const TERMINAL_KEYBOARD_INTERCEPT_SPECIAL_KEYS = new Set([
  "Enter",
  "Backspace",
  "Delete",
  "Tab",
  "Insert",
  "ArrowUp",
  "ArrowDown",
  "ArrowLeft",
  "ArrowRight",
  "Home",
  "End",
  "PageUp",
  "PageDown",
]);
const TERMINAL_KEYBOARD_INTERCEPT_SKIP_KEYS = new Set([
  "Shift",
  "Control",
  "Alt",
  "Meta",
  "AltGraph",
  "CapsLock",
  "NumLock",
  "ScrollLock",
  "Escape",
  "Dead",
  "Unidentified",
  "ContextMenu",
  "F11",
]);

// Sonde javascript de diagnostic des inputs terminaux (cote navigateur).
// Activee par `localStorage.setItem("cst.termInputProbe","1")` avant rechargement.
// Consigne dans la console chaque etape d'une frappe : keydown intercepte,
// focus textarea, onData xterm, envoi socket. Permet de localiser la couche
// qui perd les touches (capteur clavier vs focus vs transport) sans toucher au
// serveur.
const termInputProbeActive = (): boolean => {
  try {
    return window.localStorage.getItem("cst.termInputProbe") === "1";
  } catch {
    return false;
  }
};

// Compteurs d'octets emiss/receus par terminal, uniquement en mode sonde, pour
// distinguer dans l'overlay « les touches partent mais rien ne revient » (emiss>0,
// echo=0 -> transport/serveur) de « xterm n'emet pas onData » (emiss=0 -> focus).
const terminalProbeStats = new Map<string, { sent: number; echoed: number }>();

const updateTerminalProbeStatus = (): void => {
  if (!termInputProbeActive()) return;
  terminalSessions.forEach((session) => {
    const pill = document.querySelector<HTMLElement>(
      `[data-probe-status="${CSS.escape(session.key)}"]`,
    );
    if (!pill) return;
    const transport =
      session.externalSync
        ? "externe(RO)"
        : isRemoteMode() && session.ptyId !== null
          ? terminalTransportState(session.ptyId)
          : (session.ptyId !== null ? "local" : "aucun");
    const pending =
      session.ptyId !== null && isRemoteMode() ? terminalRemotePendingInputChars(session.ptyId) : 0;
    const st = terminalProbeStats.get(session.key);
    const focus =
      document.activeElement === session.terminal.textarea && document.hasFocus()
        ? "focus:OK"
        : "focus:PAS-FOCUS";
    pill.textContent = (
      "probe | ptyId=" + (session.ptyId ?? "-")
      + " running=" + String(session.running)
      + " | " + focus
      + " | transport=" + transport
      + " | pending=" + pending
      + " | echo=" + (st ? String(st.sent) + "->" + String(st.echoed) : "0->0")
    );
  });
};

const terminalKeyboardOverlayOpen = (): boolean =>
  activeModalDialog() !== null ||
  newTerminalModalOpen ||
  agentsModalOpen ||
  workspaceModalOpen ||
  terminalEnvironmentMenuOpen;

// L'intercepteur ne vole jamais une frappe destinee a un element interactif :
// le clavier du terminal ne se reprend que lorsque la frappe ne vise rien.
const terminalKeyboardBlockedTarget = (target: EventTarget | null): boolean => {
  if (!(target instanceof Element)) return false;
  if (target.closest(".xterm, [data-terminal-host]")) return true;
  return Boolean(
    target.closest(
      "input, textarea, select, button, a, label, summary, option, [contenteditable='true'], [contenteditable='plaintext-only'], [role='button'], [role='menuitem']",
    ),
  );
};

const focusTerminalKeyboard = (session: TerminalSession): void => {
  const textarea = session.terminal.textarea;
  if (!textarea || textarea.disabled) return;
  activeTerminalKey = session.key;
  session.terminal.focus();
  textarea.focus({ preventScroll: true });
  if (termInputProbeActive()) {
    console.log(
      "[TERM-INPUT] focusTerminalKeyboard key=",
      session.key,
      "ptyId=",
      session.ptyId,
      "running=",
      session.running,
      "activeElement=",
      document.activeElement?.tagName,
      "hasFocus=",
      document.hasFocus(),
      "textareaDisabled=",
      textarea.disabled,
    );
  }
};

const activeElementBlocksTerminalFocus = (): boolean => {
  const active = document.activeElement;
  if (!active || active === document.body || active === document.documentElement) return false;
  if (active.tagName === "TEXTAREA" && active.classList.contains("xterm-helper-textarea")) {
    return false;
  }
  return (
    active.tagName === "INPUT" ||
    active.tagName === "SELECT" ||
    active.tagName === "TEXTAREA" ||
    (active instanceof HTMLElement && active.isContentEditable)
  );
};

const terminalKeydownIsInterceptable = (event: KeyboardEvent): boolean => {
  // Une frappe synthetique (re-delivrance) ne doit jamais etre reinterceptee :
  // c'est aussi ce qui empeche toute boucle.
  if (!event.isTrusted || event.isComposing || event.metaKey) return false;
  if (TERMINAL_KEYBOARD_INTERCEPT_SKIP_KEYS.has(event.key)) return false;
  const printable = event.key.length === 1;
  // AltGr arrive comme Ctrl+Alt sous Windows : c'est une saisie de caractere,
  // pas un raccourci. Un Ctrl simple reste hors interception.
  const printableCombo = printable && (!event.ctrlKey || event.altKey);
  const special =
    TERMINAL_KEYBOARD_INTERCEPT_SPECIAL_KEYS.has(event.key) && !event.ctrlKey && !event.altKey;
  return printableCombo || special;
};

const interceptTerminalKeyboard = (event: KeyboardEvent): void => {
  const probing = termInputProbeActive();
  if (activeView !== "terminal" || terminalKeyboardOverlayOpen()) {
    if (probing) console.log("[TERM-INPUT] keydown NON intercepté (vue/overlay) key=", event.key);
    return;
  }
  if (!terminalKeydownIsInterceptable(event)) {
    if (probing && event.key.length === 1 && event.isTrusted) {
      console.log("[TERM-INPUT] keydown non interceptable key=", JSON.stringify(event.key), "ctrl=", event.ctrlKey, "alt=", event.altKey, "trusted=", event.isTrusted);
    }
    return;
  }
  if (terminalKeyboardBlockedTarget(event.target)) {
    if (probing) console.log("[TERM-INPUT] keydown laissé à xterm (target dans .xterm) key=", JSON.stringify(event.key), "target=", (event.target as Element)?.className);
    return;
  }
  const session = activeTerminal();
  if (!session?.running || !session.terminal.element?.isConnected) {
    if (probing) console.log("[TERM-INPUT] keydown ignoré (pas de session running/isConnected) key=", JSON.stringify(event.key));
    return;
  }
  const textarea = session.terminal.textarea;
  if (!textarea || textarea.disabled) return;
  // Le focus a ete perdu (alt-tab, remontage DOM, clic hors terminal) : on le
  // reprend puis on re-delivre l'evenement a la textarea pour que xterm traduise
  // la sequence exactement comme une frappe recue directement.
  event.preventDefault();
  event.stopImmediatePropagation();
  focusTerminalKeyboard(session);
  textarea.dispatchEvent(
    new KeyboardEvent("keydown", {
      key: event.key,
      code: event.code,
      location: event.location,
      repeat: event.repeat,
      ctrlKey: event.ctrlKey,
      altKey: event.altKey,
      shiftKey: event.shiftKey,
      metaKey: event.metaKey,
      bubbles: true,
      cancelable: true,
    }),
  );
};

const lastTerminalKeyboardBadgeState = new Map<string, string>();

const terminalKeyboardBadgeState = (
  session: TerminalSession,
): { tone: TerminalKeyboardBadgeTone; label: string; title: string } => {
  if (session.externalSync) {
    return {
      tone: "off",
      label: "Lecture seule",
      title: "Terminal Freebuff Desktop synchronisé : Switch l'affiche en miroir mais n'a aucun clavier à piloter. Utilise « Ouvrir un terminal Switch pour ce compte » pour taper.",
    };
  }
  if (!session.running) {
    return {
      tone: "off",
      label: "Inactif",
      title: "Aucun PTY actif pour ce terminal. Cliquez pour tenter un rattachement.",
    };
  }
  const transport =
    isRemoteMode() && session.ptyId !== null ? terminalTransportState(session.ptyId) : "socket";
  if (transport === "reconnecting" || transport === "starting") {
    return {
      tone: "warn",
      label: "Reconnexion",
      title: "Le transport vers le PTY se retablit ; les frappes sont conservees dans l'ordre.",
    };
  }
  if (transport === "ended" || transport === "idle") {
    return {
      tone: "off",
      label: "PTY perdu",
      title: "Le PTY distant n'est plus rattache a cet onglet. Cliquez pour rattacher.",
    };
  }
  const localPending = (terminalPendingInput.get(session.key) ?? []).join("").length;
  const remotePending =
    session.ptyId !== null && isRemoteMode() ? terminalRemotePendingInputChars(session.ptyId) : 0;
  const pending = localPending + remotePending;
  if (pending > 0) {
    return {
      tone: "warn",
      label: `File ${pending}`,
      title: "Des frappes sont bufferisees et partiront des que le PTY sera pret.",
    };
  }
  const textarea = session.terminal.textarea;
  if (textarea && document.activeElement === textarea && document.hasFocus()) {
    return { tone: "ok", label: "Clavier", title: "Les touches tapees vont dans ce terminal." };
  }
  return {
    tone: "off",
    label: "Clavier",
    title: "Ce terminal n'a pas le focus clavier. Cliquez dedans ou tapez une touche pour l'activer.",
  };
};

const updateTerminalKeyboardBadges = (): void => {
  terminalSessions.forEach((session) => {
    const badge = document.querySelector<HTMLElement>(
      `[data-terminal-keyboard="${CSS.escape(session.key)}"]`,
    );
    if (!badge) return;
    const state = terminalKeyboardBadgeState(session);
    const signature = `${state.tone}:${state.label}:${state.title}`;
    if (lastTerminalKeyboardBadgeState.get(session.key) === signature) return;
    lastTerminalKeyboardBadgeState.set(session.key, signature);
    badge.dataset.terminalKeyboardTone = state.tone;
    const label = badge.querySelector<HTMLElement>("[data-terminal-keyboard-label]");
    if (label) label.textContent = state.label;
    badge.title = state.title;
  });
};

let terminalKeyboardWatchdogTimer: number | null = null;
let terminalInputQueueGuardTimer: number | null = null;

const ensureTerminalKeyboardWatchdog = (): void => {
  if (terminalKeyboardWatchdogTimer !== null) return;
  terminalKeyboardWatchdogTimer = window.setInterval(() => {
    if (activeView === "terminal" && document.hasFocus() && !terminalKeyboardOverlayOpen()) {
      const session = activeTerminal();
      // Le chien de garde ne vole jamais le focus d'un champ reellement editable
      // (recherche, code de login, cle API...) : il ne reprend le clavier que
      // lorsque le focus repose sur le corps de la page ou un element non editable.
      if (
        session?.running
        && session.terminal.element?.isConnected
        && document.activeElement !== session.terminal.textarea
        && !activeElementBlocksTerminalFocus()
      ) {
        focusTerminalKeyboard(session);
      }
    }
    updateTerminalKeyboardBadges();
    updateTerminalProbeStatus();
  }, TERMINAL_KEYBOARD_WATCHDOG_MS);
};

const ensureTerminalInputQueueGuard = (): void => {
  if (terminalInputQueueGuardTimer !== null) return;
  terminalInputQueueGuardTimer = window.setInterval(() => {
    if (terminalPendingInput.size === 0) return;
    // Une session prete avec une file stagnante (flush rate pendant un
    // demarrage, ecriture echouee) repart sans attendre une nouvelle frappe.
    terminalSessions.forEach((session) => {
      if (session.running && session.ptyId !== null) flushTerminalInput(session);
    });
  }, TERMINAL_INPUT_QUEUE_GUARD_MS);
};

const mountExpertTerminals = () => {
  // Les terminaux ne sont montes que dans la vue Terminal. La session et son PTY
  // restent actifs lorsque l'utilisateur revient aux chats.
  const sessionByKey = new Map(terminalSessions.map((session) => [session.key, session]));
  const hosts = document.querySelectorAll<HTMLDivElement>("[data-terminal-host]");
  const fontSize = hosts.length > 9 ? 10 : hosts.length > 4 ? 11 : 12;

  hosts.forEach((host) => {
    const session = sessionByKey.get(host.dataset.terminalHost ?? "");
    if (!session) return;
    session.terminal.options.fontSize = session.key === expertTerminalFullscreenKey ? 13 : fontSize;
    if (session.terminal.element) {
      // xterm ne tolère pas les détachements/attachés répétés : on ne le
      // déplace que s'il n'est pas déjà dans ce conteneur. Sinon on garde la
      // même instance (scrollback, curseur) et on se contente de la re-mesurer.
      if (session.terminal.element.parentElement !== host) {
        host.appendChild(session.terminal.element);
      }
    } else {
      session.terminal.open(host);
    }
    if (!terminalFocusHosts.has(host)) {
      terminalFocusHosts.add(host);
      const restorePointerFocus = () => {
        if (!session.running || activeView !== "terminal" || activeModalDialog()) return;
        activeTerminalKey = session.key;
        session.terminal.focus();
        const input = host.querySelector<HTMLTextAreaElement>(".xterm-helper-textarea");
        if (input && !input.disabled) input.focus({ preventScroll: true });
      };
      const restorePointerFocusAfterPaint = () => {
        window.requestAnimationFrame(() => {
          window.requestAnimationFrame(restorePointerFocus);
        });
      };
      host.addEventListener("pointerdown", restorePointerFocus, true);
      host.addEventListener("pointerup", () => {
        restorePointerFocus();
        restorePointerFocusAfterPaint();
      }, true);
      host.addEventListener("keydown", (event) => {
        if (
          event.key !== "Enter"
          || !(event.target instanceof HTMLTextAreaElement)
          || !event.target.matches(".xterm-helper-textarea")
        ) {
          return;
        }
        // Le choix du modele Freebuff se valide avec Entree. Son TUI peut
        // alors rendre un nouvel ecran et faire perdre le textarea clavier
        // de xterm : on le reprend une fois ce nouvel ecran peint.
        restorePointerFocusAfterPaint();
      }, true);
    }
  });

  const modalOpen =
    activeModalDialog() !== null ||
    newTerminalModalOpen ||
    agentsModalOpen ||
    workspaceModalOpen ||
    terminalEnvironmentMenuOpen;
  const focusKey = requestTerminalFocusKey ?? focusedTerminalKeyBeforeRender;
  if (!modalOpen && focusKey) {
    const claudeCodeInput = Array.from(
      document.querySelectorAll<HTMLInputElement>("[data-claude-login-code-input]"),
    ).find((input) => input.dataset.claudeLoginCodeInput === focusKey);
    const openCodeKeyInput = Array.from(
      document.querySelectorAll<HTMLInputElement>("[data-opencode-login-key-input]"),
    ).find((input) => input.dataset.opencodeLoginKeyInput === focusKey);
    const terminalSession = sessionByKey.get(focusKey) ?? null;
    if (claudeCodeInput) claudeCodeInput.focus();
    else if (openCodeKeyInput) openCodeKeyInput.focus();
    else terminalSession?.terminal.focus();
    if (claudeCodeInput || openCodeKeyInput || terminalSession) {
      if (requestTerminalFocusKey === focusKey) requestTerminalFocusKey = null;
      if (terminalSession) {
        window.requestAnimationFrame(() => {
          window.requestAnimationFrame(() => {
            if (
              activeView === "terminal"
              && !activeModalDialog()
              && terminalSession.running
              && terminalSession.terminal.element?.isConnected
            ) {
              terminalSession.terminal.focus();
            }
          });
        });
      }
    }
  }
  updateTerminalKeyboardBadges();
  requestAnimationFrame(() => {
    requestAnimationFrame(() => fitAndResizeExpertTerminals());
  });
};

const createNewTerminalOnce = async (
  accountId = selectedAccountId,
  settingsAlreadyRead = false,
  commandOverride: string | null = null,
  agentId: string | null = null,
  resumeSessionId: string | null = null,
  folderPath: string | null | undefined = undefined,
  loginOnly = false,
) => {
  if (!settings) return null;
  const environmentPath = loginOnly ? null : userWorkspacePath(folderPath);
  if (!loginOnly && !environmentPath) {
    statusText = "Creation bloquee: choisis d'abord un environnement";
    render();
    return null;
  }
  const backgroundLogin =
    loginOnly && !!accountId && remoteCodexLoginWindowIsOpen(accountId);

  if (!backgroundLogin) activeView = "terminal";
  // Ouvrir un login ne doit pas faire apparaitre en meme temps tous les
  // terminaux de travail sauvegardes. Si une restauration a deja commence, on
  // l'attend toutefois pour ne pas melanger la restauration et le login.
  if (!loginOnly && !terminalRestoreAttempted) {
    // Premiere creation apres chargement : ne pas bloquer le spawn du nouveau
    // terminal sur la restauration des anciens onglets. Celle-ci se poursuit
    // en arriere-plan ; ses rattachements par ptyId n'entrent pas en conflit
    // avec cette nouvelle session (identifiants distincts), et le focus du
    // terminal fraichement cree reste porte par requestTerminalFocusKey.
    void ensureTerminalsRestored();
  } else if (!loginOnly || terminalRestoreAttempted) {
    await ensureTerminalsRestored();
  }

  if (!settingsAlreadyRead) {
    readSettingsForm();
  }
  const account = settings.accounts.find((candidate) => candidate.id === accountId) ?? null;
  if (!account) {
    return null;
  }

  const agents = settings.agents;
  const activeId = settings.activeAgentId ?? null;
  let chosenAgentId =
    (agentId && agents.some((agent) => agent.id === agentId) && agentId) ||
    (activeId && agents.some((agent) => agent.id === activeId) && activeId) ||
    agents[0]?.id ||
    "codex";

  // L'agent CLI lance doit correspondre au provider du compte : un compte Claude
  // se lance avec l'agent Claude (CLAUDE_CONFIG_DIR + `claude`), un compte Codex
  // avec Codex. Sinon la variable de home et la commande se contrediraient. On
  // ne force que pour les agents CLI "premier rang" (on laisse les agents IDE /
  // customs intacts).
  const wantedProvider = accountProvider(account);
  if (wantedProvider === "freebuff") {
    try {
      await assertFreebuffAccountAvailable(account);
    } catch (error) {
      statusText = `Lancement Freebuff refusé : ${String(error)}`;
      render();
      return null;
    }
  }
  const chosenAgent = agentById(chosenAgentId);
  if (isFirstPartyAgent(chosenAgent) && agentProvider(chosenAgent) !== wantedProvider) {
    chosenAgentId = providerAgentId(wantedProvider);
  }

  selectedAccountId = account.id;
  settings.defaultAccountId = account.id;
  settings.activeAgentId = chosenAgentId;
  if (!loginOnly) {
    try {
      settings = await invoke<AppSettings>("save_settings", { settings });
    } catch (error) {
      throw error;
    }
  }

  // Les comptes et leurs homes sont globaux sur le serveur. Un login ne doit
  // jamais repasser par PUT /settings : cette route synchronise aussi la vue
  // personnelle des workspaces et rejetterait a tort les anciens chemins
  // partages encore presents dans le navigateur d'un utilisateur.
  const savedAccount = settings.accounts.find((candidate) => candidate.id === account.id) ?? null;
  if (!savedAccount) {
    return null;
  }

  const session = await createTerminalSession(
    savedAccount,
    proxyForAccount(savedAccount),
    chosenAgentId,
    environmentPath,
    loginOnly,
  );
  session.resumeSessionId = resumeSessionId;
  if (resumeSessionId) {
    session.codexSessionId = resumeSessionId;
    claimedSessionIds.add(resumeSessionId);
    if (wantedProvider === "freebuff") session.sessionCaptureDone = true;
  }
  terminalSessions.push(session);
  if (!backgroundLogin) {
    activateTerminalSession(session);
    requestTerminalFocusKey = session.key;
    activeView = "terminal";
    stopLimitPoll();
    stopUsagePoll();
    stopDiscussionsPoll();
    stopChatSync();
    stopChatTurnPoll();
    statusText = "Demarrage terminal";
  } else {
    selectedAccountId = account.id;
    statusText = `Préparation de la fenêtre OpenAI pour ${account.label}…`;
  }
  render();

  await startTerminalSession(session, commandOverride, loginOnly, !backgroundLogin);
  if (backgroundLogin) {
    statusText = `Connexion OpenAI en attente pour ${account.label}`;
    render();
  }
  persistTerminalSessions();
  return session;
};

const createNewTerminal = async (
  accountId = selectedAccountId,
  settingsAlreadyRead = false,
  commandOverride: string | null = null,
  agentId: string | null = null,
  resumeSessionId: string | null = null,
  folderPath: string | null | undefined = undefined,
  loginOnly = false,
): Promise<TerminalSession | null> => {
  const create = () =>
    createNewTerminalOnce(
      accountId,
      settingsAlreadyRead,
      commandOverride,
      agentId,
      resumeSessionId,
      folderPath,
      loginOnly,
    );

  if (!loginOnly || !accountId) return create();

  const existingLogin = terminalSessions.find(
    (session) =>
      session.loginOnly &&
      session.accountId === accountId &&
      session.ptyId !== null &&
      session.status !== "Ferme",
  );
  if (existingLogin) {
    if (remoteCodexLoginWindowIsOpen(accountId)) {
      focusRemoteCodexLoginWindow(accountId);
      statusText = "Connexion déjà ouverte dans l’onglet OpenAI";
      render();
      return existingLogin;
    }
    activateTerminalSession(existingLogin);
    activeView = "terminal";
    requestTerminalFocusKey = existingLogin.key;
    statusText = "Connexion deja ouverte dans le terminal affiche";
    render();
    return existingLogin;
  }

  const inFlightLogin = loginTerminalCreations.get(accountId);
  if (inFlightLogin) {
    const popupFocused = focusRemoteCodexLoginWindow(accountId);
    statusText = popupFocused
      ? "Connexion déjà en cours dans la fenêtre OpenAI"
      : "Connexion deja en cours dans le terminal ouvert";
    render();
    return inFlightLogin;
  }

  const creation = create();
  loginTerminalCreations.set(accountId, creation);
  try {
    return await creation;
  } finally {
    if (loginTerminalCreations.get(accountId) === creation) {
      loginTerminalCreations.delete(accountId);
    }
  }
};

const applyRemoteCodexLoginOutput = (session: TerminalSession, data: string) => {
  if (!session.loginOnly) return "none" as const;
  const update = consumeRemoteCodexLoginOutput(session.accountId, data);
  if (update.type === "ready") {
    statusText = `Onglet OpenAI ouvert — code ${update.userCode} copié, collez-le pour continuer`;
    render();
    return update.type;
  }
  if (update.type === "success") {
    const accountLabel = accountById(session.accountId)?.label ?? session.title;
    void closeTerminalSession(session.key).finally(() => {
      statusText = `Connexion réussie pour ${accountLabel}`;
      render();
      void refreshLimitStatus(true, true);
    });
    return update.type;
  }
  if (update.type === "error") {
    void closeTerminalSession(session.key).finally(() => {
      statusText = update.message;
      render();
    });
  }
  return update.type;
};

const applyRemoteClaudeLoginOutput = (session: TerminalSession, data: string) => {
  if (
    !isRemoteMode()
    || !session.loginOnly
    || accountProvider(accountById(session.accountId)) !== "claude"
  ) {
    return "none" as const;
  }

  const update = consumeRemoteClaudeLoginOutput(session.key, data);
  if (update.type === "ready") {
    statusText = "Ouverture de Claude dans le navigateur…";
    render();
    void openExternalHttpsUrl(update.url)
      .then(() => {
        if (!terminalSessions.includes(session)) return;
        statusText = "Copie le code affiché par Claude, puis colle-le dans ce terminal";
        requestTerminalFocusKey = session.key;
        render();
      })
      .catch(() => {
        if (!terminalSessions.includes(session)) return;
        statusText = "Ouverture automatique bloquée : clique sur le lien Claude dans ce terminal";
        requestTerminalFocusKey = session.key;
        render();
      });
    return update.type;
  }
  if (update.type === "success") {
    const accountLabel = accountById(session.accountId)?.label ?? session.title;
    void closeTerminalSession(session.key).finally(() => {
      statusText = `Connexion Claude réussie pour ${accountLabel}`;
      render();
      void refreshLimitStatus(true, true);
    });
  }
  return update.type;
};

// `opencode auth login` ne passe par aucun navigateur : il demande la cle API
// dans le terminal puis se termine. Sans cette lecture, le terminal de
// connexion restait ouvert sans fin, meme quand OpenCode n'etait pas installe
// (le shell affichait juste « command not found » puis rendait la main).
const applyOpenCodeLoginOutput = (session: TerminalSession, data: string) => {
  if (
    !session.loginOnly
    || accountProvider(accountById(session.accountId)) !== "opencode"
  ) {
    return "none" as const;
  }

  const update = consumeOpenCodeLoginOutput(session.key, data);
  if (update.type === "prompt") {
    statusText = `Colle la clé API ${accountProviderLabel(accountById(session.accountId))} puis valide`;
    requestTerminalFocusKey = session.key;
    render();
    return update.type;
  }
  if (update.type === "success") {
    const accountLabel = accountById(session.accountId)?.label ?? session.title;
    void closeTerminalSession(session.key).finally(() => {
      statusText = `Connexion réussie pour ${accountLabel}`;
      render();
      void refreshLimitStatus(true, true);
    });
    return update.type;
  }
  if (update.type === "error") {
    void closeTerminalSession(session.key).finally(() => {
      statusText = update.message;
      render();
    });
  }
  return update.type;
};

// Le WebSocket peut livrer les premiers octets du CLI pendant que l'appel
// POST /terminals se termine. Le transport conserve donc un court snapshot que
// l'on rejoue ici jusqu'a retrouver le lien et le code appareil. Cette voie de
// secours evite une fenetre de connexion qui tourne indefiniment.
const replayRemoteCodexLoginOutput = async (session: TerminalSession) => {
  const terminalId = session.ptyId;
  if (
    !isRemoteMode()
    || !session.loginOnly
    || terminalId === null
    || !remoteCodexLoginWindowNeedsCode(session.accountId)
  ) {
    return;
  }

  let previous = "";
  const deadline = Date.now() + 12_000;
  while (
    Date.now() < deadline
    && terminalSessions.includes(session)
    && session.ptyId === terminalId
  ) {
    if (!remoteCodexLoginWindowNeedsCode(session.accountId)) {
      if (!remoteCodexLoginWindowIsOpen(session.accountId)) {
        await closeTerminalSession(session.key);
      }
      return;
    }
    const snapshot = await invoke<string>("terminal_output_snapshot", { id: terminalId })
      .catch(() => "");
    if (snapshot && snapshot !== previous) {
      const delta = snapshot.startsWith(previous) ? snapshot.slice(previous.length) : snapshot;
      previous = snapshot;
      if (applyRemoteCodexLoginOutput(session, delta) !== "none") return;
    }
    await new Promise<void>((resolve) => window.setTimeout(resolve, 200));
  }

  if (
    terminalSessions.includes(session)
    && session.ptyId === terminalId
    && remoteCodexLoginWindowNeedsCode(session.accountId)
  ) {
    const message = "Le code OpenAI n’a pas été reçu. Fermez cette fenêtre puis réessayez.";
    failRemoteCodexLoginWindow(session.accountId, message);
    await closeTerminalSession(session.key);
    statusText = message;
    render();
  }
};

// Claude imprime dynamiquement son URL OAuth apres le demarrage du CLI. Le
// premier message peut arriver avant l'abonnement WebSocket du navigateur ; le
// tampon du transport permet alors de relayer tout de meme cette URL vers le
// navigateur systeme. Contrairement a Codex, le terminal reste visible afin que
// l'utilisateur puisse y recoller le code affiche par Claude.
const replayRemoteClaudeLoginOutput = async (session: TerminalSession) => {
  const terminalId = session.ptyId;
  if (
    !isRemoteMode()
    || !session.loginOnly
    || terminalId === null
    || accountProvider(accountById(session.accountId)) !== "claude"
  ) {
    return;
  }

  let previous = "";
  const deadline = Date.now() + 12_000;
  while (
    Date.now() < deadline
    && terminalSessions.includes(session)
    && session.ptyId === terminalId
  ) {
    const snapshot = await invoke<string>("terminal_output_snapshot", { id: terminalId })
      .catch(() => "");
    if (snapshot && snapshot !== previous) {
      const delta = snapshot.startsWith(previous) ? snapshot.slice(previous.length) : snapshot;
      previous = snapshot;
      if (applyRemoteClaudeLoginOutput(session, delta) !== "none") return;
    }
    await new Promise<void>((resolve) => window.setTimeout(resolve, 200));
  }
};

// Meme fenetre de course que Claude, avec un enjeu supplementaire : l'echec le
// plus frequent (`opencode` absent du PATH du serveur) est imprime dans les
// premieres millisecondes. Sans ce rejeu, l'utilisateur restait devant un
// terminal vide sans jamais savoir que la CLI manquait.
const replayOpenCodeLoginOutput = async (session: TerminalSession) => {
  const terminalId = session.ptyId;
  if (
    !isRemoteMode()
    || !session.loginOnly
    || terminalId === null
    || accountProvider(accountById(session.accountId)) !== "opencode"
  ) {
    return;
  }

  let previous = "";
  const deadline = Date.now() + 12_000;
  while (
    Date.now() < deadline
    && terminalSessions.includes(session)
    && session.ptyId === terminalId
  ) {
    const snapshot = await invoke<string>("terminal_output_snapshot", { id: terminalId })
      .catch(() => "");
    if (snapshot && snapshot !== previous) {
      const delta = snapshot.startsWith(previous) ? snapshot.slice(previous.length) : snapshot;
      previous = snapshot;
      // Une invite de saisie n'arrete pas le rejeu : le succes ou l'erreur
      // arrivent ensuite, et le flux live peut ne pas encore etre abonne.
      const update = applyOpenCodeLoginOutput(session, delta);
      if (update === "success" || update === "error") return;
    }
    await new Promise<void>((resolve) => window.setTimeout(resolve, 200));
  }
};

const startTerminalSession = async (
  session: TerminalSession,
  commandOverride: string | null = null,
  loginOnly = false,
  renderProgress = true,
) => {
  if (!settings) return;
  const startedAccount = settings.accounts.find((candidate) => candidate.id === session.accountId) ?? null;
  const folder = loginOnly
    ? userEnvironmentPath(startedAccount?.codexHome)
    : userWorkspacePath(session.folderPath);
  if (!folder) {
    session.running = false;
    session.status = "Bloque";
    statusText = "Demarrage refuse: aucun environnement selectionne";
    render();
    return;
  }

  await waitForFrame();
  fitAndResizeTerminal(session);

  const requestedId = reservePtyId();
  session.ptyId = requestedId;
  terminalSessionsByPtyId.set(requestedId, session);
  session.running = true;
  session.status = "Demarrage";
  session.startedAtUnix = Math.floor(Date.now() / 1000);
  statusText = "Demarrage terminal";
  if (renderProgress) render();

  const sessionAgent = agentById(session.agentId);
  const isIde = agentIsIde(sessionAgent);
  // Un agent IDE ne se tape pas dans le PTY : on ouvre l'editeur apres coup.
  const autoRunCommand =
    !loginOnly && settings.autoRunCodex && !isIde
      ? agentRunCommand(sessionAgent, accountById(session.accountId))
      : null;

  try {
    // Workspace capture dans CETTE session :
    //  - web  : envoye au serveur comme `workspacePath` (cwd = ce dossier ; le
    //           serveur ignore alors `repoUrl`) ;
    //  - desktop : envoye comme `projectDir` (override du dossier du compte).
    const started = await invoke<number | TerminalStartResponse>("start_terminal", {
      id: requestedId,
      accountId: session.accountId,
      repoUrl: isRemoteMode() && !loginOnly ? session.projectDir ?? "" : undefined,
      workspacePath: isRemoteMode() && !loginOnly ? folder ?? undefined : undefined,
      projectDir: !isRemoteMode() ? folder ?? undefined : undefined,
      branch: null,
      cols: session.terminal.cols,
      rows: session.terminal.rows,
      command: commandOverride ?? autoRunCommand,
      agentId: session.agentId,
      sourceTerminalKey: session.key,
      loginOnly,
      targetNodeId: isRemoteMode() ? workspaceExecutionTargetIdForPath(folder) : undefined,
    });
    const ptyId = typeof started === "number" ? started : started.id;
    if (ptyId !== requestedId) terminalSessionsByPtyId.delete(requestedId);
    if (typeof started !== "number") {
      session.nodeId = started.nodeId ?? null;
      session.remoteId = started.remoteId ?? ptyId;
    } else {
      session.nodeId = null;
      session.remoteId = null;
    }
    session.ptyId = ptyId;
    terminalSessionsByPtyId.set(ptyId, session);
    flushTerminalInput(session);
    flushTerminalInput(session);
    session.workspaceId = loginOnly || typeof started === "number" ? null : started.workspaceId;
    session.workspacePath = loginOnly || typeof started === "number" ? null : started.workspacePath;
    session.running = true;
    session.status = "Actif";
    statusText = "Terminal actif";
    if (loginOnly && isRemoteMode()) {
      if (remoteCodexLoginWindowIsOpen(session.accountId)) {
        void replayRemoteCodexLoginOutput(session);
      } else if (accountProvider(startedAccount) === "claude") {
        void replayRemoteClaudeLoginOutput(session);
      } else if (accountProvider(startedAccount) === "opencode") {
        void replayOpenCodeLoginOutput(session);
      }
    }
    if (!loginOnly && settings.autoRunCodex && isIde && sessionAgent && !commandOverride) {
      // Utilise le workspace capture par cette session, meme si l'utilisateur
      // en a selectionne un autre pendant le demarrage du PTY.
      void launchIde(sessionAgent, session.workspacePath ?? session.folderPath ?? session.projectDir);
    }
    persistTerminalSessions();
    const effectiveCommand = commandOverride ?? autoRunCommand ?? startedAccount?.startupCommand ?? null;
    if (
      !loginOnly &&
      (session.resumeSessionId || (isCodexAgent(sessionAgent) && !isIde && !!effectiveCommand))
    ) {
      void captureCodexSessionId(session);
    }
  } catch (error) {
    terminalSessionsByPtyId.delete(requestedId);
    if (session.ptyId !== null) terminalSessionsByPtyId.delete(session.ptyId);
    session.ptyId = null;
    session.running = false;
    session.status = "Erreur";
    statusText = String(error);
    session.terminal.writeln(`\r\n${String(error)}`);
  }

  if (renderProgress) render();
};

const closeTerminalSession = async (key: string) => {
  const index = terminalSessions.findIndex((session) => session.key === key);
  if (index === -1) return;

  const [session] = terminalSessions.splice(index, 1);
  if (session.loginOnly) {
    forgetRemoteClaudeLoginOutput(session.key);
    forgetOpenCodeLoginOutput(session.key);
  }
  if (expertTerminalFullscreenKey === key) expertTerminalFullscreenKey = null;
  const timer = terminalFitTimers.get(key);
  if (timer !== undefined) window.clearTimeout(timer);
  terminalFitTimers.delete(key);
  terminalActivity.forget(key);
  terminalPendingInput.delete(key);
  lastTerminalKeyboardBadgeState.delete(key);
  const closedWorkspaceKey = terminalWorkspaceDescriptor(session).key;
  const ptyId = session.ptyId;
  if (ptyId !== null) terminalSessionsByPtyId.delete(ptyId);
  session.ptyId = null;
  session.running = false;
  session.terminal.dispose();

  if (activeTerminalKey === key) {
    const replacement =
      terminalSessions.find(
        (candidate) => terminalWorkspaceDescriptor(candidate).key === closedWorkspaceKey,
      ) ?? terminalSessions[Math.max(0, index - 1)] ?? terminalSessions[0] ?? null;
    if (replacement) {
      activateTerminalSession(replacement);
    } else {
      activeTerminalKey = null;
    }
  }

  statusText = "Terminal ferme";
  render();
  persistTerminalSessions();

  if (ptyId !== null) {
    await invoke("stop_terminal", { id: ptyId }).catch(() => undefined);
  }
  await persistTerminalDiscussionFolder(session).catch(() => undefined);
};

const sendLine = async (line: string) => {
  const session = activeTerminal();
  if (!session?.running || session.ptyId === null) return false;
  try {
    await invoke("write_terminal", { id: session.ptyId, data: `${line}\r` });
    return true;
  } catch (error) {
    statusText = String(error);
    render();
    return false;
  }
};


const escapeHtml = (value: string) =>
  value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");

const escapeAttr = escapeHtml;

const userHomeHint = () => (isRemoteMode() ? "%CST_DATA_DIR%\\codex-homes" : "%USERPROFILE%");

const expertChatKeyFromElement = (element: Element | null): string | null => {
  return element?.closest<HTMLElement>("[data-chat-panel]")?.dataset.chatPanel || null;
};

const expertChatKeyAtPointer = (): string | null => {
  const pointedElement = lastPointerClientX !== null && lastPointerClientY !== null
    ? document.elementFromPoint(lastPointerClientX, lastPointerClientY)
    : null;
  const pointedKey = expertChatKeyFromElement(pointedElement);
  if (pointedKey) return pointedKey;

  return document.querySelector<HTMLElement>("[data-chat-panel]:hover")?.dataset.chatPanel || null;
};

const closeHoveredExpertChat = (action: ChatHoverShortcutAction): boolean => {
  if (activeView !== "chat") return false;
  if (document.querySelector(".modal-backdrop")) return false;

  const key = expertChatKeyAtPointer();
  const pane = expertChatPanes.find((candidate) => candidate.key === key);
  if (!pane) return false;

  if (action === "close-chat-and-discussion") {
    void closeExpertChatAndDiscussion(pane);
  } else {
    closeExpertChatPane(pane);
  }
  return true;
};

const toggleHoveredExpertFullscreen = (): boolean => {
  if (activeView === "terminal") {
    const hoveredPane = document.querySelector<HTMLElement>("[data-expert-terminal-pane]:hover");
    const key = expertTerminalFullscreenKey ?? hoveredPane?.dataset.expertTerminalPane;
    const session = terminalSessions.find((candidate) => candidate.key === key);
    if (!session) return false;
    toggleExpertTerminalFullscreen(session);
    return true;
  }

  if (activeView === "chat") {
    const hoveredPane = document.querySelector<HTMLElement>("[data-chat-panel]:hover");
    const key = expertChatFullscreenKey ?? hoveredPane?.dataset.chatPanel;
    const pane = expertChatPanes.find((candidate) => candidate.key === key);
    if (!pane) return false;
    toggleExpertChatFullscreen(pane);
    return true;
  }

  return false;
};

type HoveredTerminalShortcutAction =
  | "close-terminal"
  | "maximize-terminal"
  | "restore-terminal";

const handleHoveredExpertTerminalShortcut = (
  action: HoveredTerminalShortcutAction,
): boolean => {
  if (activeView !== "terminal") return false;
  const hoveredPane = document.querySelector<HTMLElement>("[data-expert-terminal-pane]:hover");
  const key = hoveredPane?.dataset.expertTerminalPane ?? expertTerminalFullscreenKey;
  if (!key) return false;
  const session = terminalSessions.find((candidate) => candidate.key === key);
  if (!session) return false;

  if (action === "close-terminal") {
    void closeTerminalSession(session.key);
    return true;
  }
  if (action === "maximize-terminal") {
    if (expertTerminalFullscreenKey !== session.key) {
      toggleExpertTerminalFullscreen(session);
    }
    return true;
  }
  if (action === "restore-terminal") {
    if (expertTerminalFullscreenKey === session.key) {
      toggleExpertTerminalFullscreen(session);
    }
    return true;
  }
  return false;
};

const setupEvents = async () => {
  window.addEventListener("keydown", (event) => {
    captureKeyboardShortcut(event);
  }, true);
  window.addEventListener("keydown", trapActiveDialogFocus, true);
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState !== "visible") return;
    refreshChatRuntimeClocks();
    if (activeView === "terminal") void recoverActiveTerminalInput();
    void dispatchDueScheduledChats();
    if ((nextUnconnectedAccountExpiry() ?? Number.POSITIVE_INFINITY) <= Date.now()) {
      void cleanupExpiredUnconnectedAccounts();
    }
    if (activeView === "chat" || activeView === "discussions") {
      void refreshDiscussions();
      void refreshActiveChatTurns();
    }
    if (
      activeView === "limits" || activeView === "chat" ||
      chatTurnIsBusy(chatTurn?.status) ||
      expertChatPanes.some((pane) => chatTurnIsBusy(pane.turn?.status))
    ) {
      void refreshLimitStatus(true);
    }
    if (activeView === "pool") {
      void refreshAccountCompletions();
      void refreshPoolStatus();
    }
    if (activeView === "dashboard") {
      void refreshUsageDashboard();
      void refreshAccountUsage();
      void refreshWorkTimeDashboard();
      void refreshReferralDashboard(false, true);
    }
    if (activeView === "tracking") {
      void trackingViewModule?.refreshTrackingPanel(render, true);
    }
    if (activeView === "duello-bank") {
      void duelloBankModule?.refreshDuelloBankPanel(render, true);
    }
    if (activeView === "freebuff-cloud") {
      void freebuffCloudModule?.refreshFreebuffCloudPanel(render, true);
    }
    if (activeView === "vps") void vpsModule?.refreshVpsPanel(render, true);
    if (activeView === "video") void videoModule?.refreshVideoPanel(render, true);
    if (activeView === "transcription") {
      void transcriptionModule?.refreshTranscriptionPanel(render, true);
    }
    if (activeView === "design" && activeDesignTool === "kombai") void refreshKombaiStatus();
    if (
      activeView === "design" && activeDesignTool === "claude" &&
      chatTurnIsBusy(designClaudeTurn?.status)
    ) {
      void pollClaudeDesignTurn();
    }
    if (activeView === "settings") {
      void refreshVoiceRuntimeStatus();
      void refreshWhatsAppConnection();
    }
    void refreshAutonomousAgents();
    if (activeView === "orchestration") void refreshOrchestrations();
    if (activeView === "chat") {
      if (chatTurn?.status === "running") void pollChatTurn();
      visibleExpertChatPanes().forEach((pane) => {
        if (pane.turn?.status === "running") void pollExpertChatTurn(pane);
      });
    }
  });
  const recoverTerminalOnPageReturn = () => {
    if (activeView === "terminal") void recoverActiveTerminalInput();
  };
  window.addEventListener("pageshow", recoverTerminalOnPageReturn);
  window.addEventListener("online", recoverTerminalOnPageReturn);
  document.addEventListener("fullscreenchange", scheduleFullscreenSync);
  document.addEventListener("webkitfullscreenchange", scheduleFullscreenSync);
  window.addEventListener("resize", scheduleFullscreenSync);
  window.addEventListener("pointermove", (event) => {
    lastPointerClientX = event.clientX;
    lastPointerClientY = event.clientY;
  }, true);
  window.addEventListener("pointerdown", (event) => {
    lastPointerClientX = event.clientX;
    lastPointerClientY = event.clientY;
  }, true);
  document.addEventListener("pointerleave", () => {
    lastPointerClientX = null;
    lastPointerClientY = null;
  });
  window.addEventListener("blur", () => {
    lastPointerClientX = null;
    lastPointerClientY = null;
  });

  startTerminalActivityTicker();
  unlistenData = await listen<PtyDataEvent>("pty-data", (event) => {
    const session = terminalSessionsByPtyId.get(event.payload.id);
    if (session) {
      // xterm accepte les écritures par lots ; éviter de forcer un layout/reflow
      // pour chaque fragment PTY réduit les micro-freezes pendant le streaming.
      session.terminal.write(event.payload.data);
      terminalActivity.record(session.key, event.payload.data);
      // Le relais Freebuff suit la sortie du terminal cible pour la renvoyer
      // dans son fil de chat.
      freebuffRelayOutputListeners.forEach((listener) => {
        listener(session.key, event.payload.data);
      });
    }
    if (session?.loginOnly) {
      applyRemoteCodexLoginOutput(session, event.payload.data);
      applyRemoteClaudeLoginOutput(session, event.payload.data);
      applyOpenCodeLoginOutput(session, event.payload.data);
    }
  });

  unlistenExit = await listen<PtyExitEvent>("pty-exit", (event) => {
    const session = terminalSessionsByPtyId.get(event.payload.id);
    if (!session) return;
    terminalSessionsByPtyId.delete(event.payload.id);
    const sessionIndex = terminalSessions.indexOf(session);
    if (sessionIndex >= 0) terminalSessions.splice(sessionIndex, 1);
    if (session.codexSessionId) claimedSessionIds.delete(session.codexSessionId);

    session.ptyId = null;
    session.running = false;
    session.status = "Ferme";
    terminalActivity.forget(session.key);

    if (session.loginOnly) {
      forgetRemoteClaudeLoginOutput(session.key);
      forgetOpenCodeLoginOutput(session.key);
      failRemoteCodexLoginWindow(
        session.accountId,
        "La connexion s’est interrompue avant d’être validée.",
      );
    }

    if (session.key === activeTerminalKey) {
      statusText = "Terminal ferme";
    }

    // Ne pas re-render tant que l'iframe Kombai tourne : un render() reconstruit
    // app.innerHTML et rechargerait l'editeur embarque (perte de l'etat). L'etat
    // terminal est deja a jour en memoire ; la sidebar se rafraichit au prochain
    // render (changement de vue, clic terminal...).
    if (!(activeView === "design" && activeDesignTool === "kombai" && (kombaiStatus?.running ?? false))) {
      render();
    }
    persistTerminalSessions();
    void persistTerminalDiscussionFolder(session).catch(() => undefined);
  });

  window.addEventListener("resize", () => {
    syncChatContextSidebarWidthDom();
    syncChatSidebarWidthDom();
    fitAndResizeVisibleTerminals();
    syncAutonomousMonitorPositionUi(true);
    scheduleExpertChatResponsiveRender();
  });

  window.addEventListener("keydown", (event) => {
    if (keyboardShortcutTargetIsTerminal(event.target)) return;
    if (!keyboardShortcutMatchesAction("toggle-environments", event) || !settings) return;
    if (
      !terminalEnvironmentMenuOpen &&
      (newTerminalModalOpen ||
        agentsModalOpen ||
        workspaceModalOpen)
    ) {
      return;
    }
    event.preventDefault();
    event.stopImmediatePropagation();
    toggleTerminalEnvironmentMenu();
  }, true);

  window.addEventListener("keydown", (event) => {
    const action = chatHoverShortcutAction(event, {
      "close-chat": keyboardShortcutBinding("close-chat"),
      "close-chat-and-discussion": keyboardShortcutBinding("close-chat-and-discussion"),
    });
    if (!action || !closeHoveredExpertChat(action)) return;
    event.preventDefault();
    event.stopImmediatePropagation();
  }, true);

  window.addEventListener("keydown", (event) => {
    if (!keyboardShortcutMatchesAction("toggle-pane-fullscreen", event)) return;
    const target = event.target as HTMLElement | null;
    const tag = target?.tagName;
    if (tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT" || target?.isContentEditable === true) return;
    if (document.querySelector(".modal-backdrop")) return;
    if (!toggleHoveredExpertFullscreen()) return;
    event.preventDefault();
    event.stopImmediatePropagation();
  }, true);

  window.addEventListener("keydown", (event) => {
    const action: HoveredTerminalShortcutAction | null =
      keyboardShortcutMatchesAction("close-terminal", event)
        ? "close-terminal"
        : keyboardShortcutMatchesAction("maximize-terminal", event)
          ? "maximize-terminal"
          : keyboardShortcutMatchesAction("restore-terminal", event)
            ? "restore-terminal"
            : null;
    if (!action) return;
    const target = event.target as HTMLElement | null;
    const tag = target?.tagName;
    if (tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT" || target?.isContentEditable === true) return;
    if (document.querySelector(".modal-backdrop")) return;
    if (!handleHoveredExpertTerminalShortcut(action)) return;
    event.preventDefault();
    event.stopImmediatePropagation();
  }, true);

  window.addEventListener("keydown", (event) => {
    if (keyboardShortcutTargetIsTerminal(event.target)) return;
    if (keyboardShortcutMatchesAction("toggle-sidebar", event)) {
      event.preventDefault();
      event.stopImmediatePropagation();
      toggleChatSidebar();
      return;
    }

    if (keyboardShortcutMatchesAction("new-chat", event)) {
      event.preventDefault();
      event.stopImmediatePropagation();
      openNewChat();
      return;
    }

    if (keyboardShortcutMatchesAction("new-terminal", event)) {
      event.preventDefault();
      event.stopImmediatePropagation();
      openNewTerminalModal();
      return;
    }

    if (keyboardShortcutMatchesAction("open-settings", event)) {
      event.preventDefault();
      event.stopImmediatePropagation();
      setActiveView("settings");
      return;
    }

    if (keyboardShortcutMatchesAction("open-discussions", event)) {
      event.preventDefault();
      event.stopImmediatePropagation();
      openDiscussionHistory();
      return;
    }

    if (keyboardShortcutMatchesAction("search-discussions", event)) {
      event.preventDefault();
      event.stopImmediatePropagation();
      if (!window.matchMedia("(max-width: 760px)").matches && displayedChatSidebarWidth() === 0) {
        setChatSidebarWidth(defaultChatSidebarWidth(window.innerWidth));
      }
      document.body.classList.add("chat-sidebar-open");
      if (window.matchMedia("(max-width: 860px)").matches) {
        syncMobileDrawerAccessibility(true, true);
      } else {
        document.querySelector<HTMLInputElement>("#chatSidebarSearch")?.focus();
      }
      return;
    }

    if (event.key === "Escape" && autonomousMonitorOpen) {
      event.preventDefault();
      closeAutonomousMonitor();
      return;
    }

    if (event.key === "Escape" && discussionArchiveCandidate) {
      event.preventDefault();
      closeDiscussionArchiveModal();
      return;
    }

    if (event.key === "Escape" && terminalDeleteCandidateKey) {
      event.preventDefault();
      closeTerminalDeleteModal();
      return;
    }

    if (event.key === "Escape" && terminalEnvironmentMenuOpen) {
      event.preventDefault();
      closeTerminalEnvironmentMenu();
      return;
    }

    if (event.key === "Escape" && workspaceModalOpen) {
      event.preventDefault();
      closeWorkspaceModal();
      return;
    }

    if (event.key === "Escape" && document.body.classList.contains("m-sheet-open")) {
      event.preventDefault();
      closeMobileOverlays();
      return;
    }

    if (event.key === "Escape" && document.body.classList.contains("chat-sidebar-open")) {
      event.preventDefault();
      closeMobileOverlays();
      return;
    }

    if (event.key === "Escape" && proxyManagerModalOpen) {
      event.preventDefault();
      closeProxyManagerModal();
      return;
    }

    if (event.key === "Escape" && agentsModalOpen) {
      event.preventDefault();
      closeAgentsModal();
      return;
    }

    if (event.key === "Escape" && orchestrationConversion) {
      event.preventDefault();
      closeOrchestrationConversion();
      return;
    }

    if (event.key === "Escape" && autonomousChatEditor) {
      event.preventDefault();
      closeAutonomousChatEditor();
      return;
    }

    if (event.key === "Escape" && autonomousOrchestrationPromotion) {
      event.preventDefault();
      closeAutonomousOrchestrationPromotion();
      return;
    }

    if (event.key === "Escape" && newChatModalOpen) {
      event.preventDefault();
      closeNewChatModal();
      return;
    }

    if (event.key === "Escape" && newTerminalModalOpen) {
      event.preventDefault();
      closeNewTerminalModal();
      return;
    }

    if (event.key !== "F11") return;
    event.preventDefault();
    void toggleFullscreen();
  });

  // Verrou clavier terminal : la fenetre qui revient au premier plan, la
  // premiere frappe tapee hors focus et les files stagnantes sont repris ici.
  // Enregistre en dernier : les raccourcis applicatifs et les echappements de
  // modales restent toujours prioritaires sur la re-delivrance a xterm.
  window.addEventListener("focus", () => {
    if (activeView === "terminal") void recoverActiveTerminalInput();
  });
  window.addEventListener("keydown", interceptTerminalKeyboard, true);
  ensureTerminalKeyboardWatchdog();
  ensureTerminalInputQueueGuard();
  // Tout rechargement (web-update, chunk perime, F5) passe par pagehide :
  // le brouillon differe est force sur disque avant la navigation. La mise en
  // arriere-plan est un second filet : certains navigateurs mobiles sautent
  // pagehide dans des cas limites.
  window.addEventListener("pagehide", flushChatDraft);
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "hidden") flushChatDraft();
  });
};

const isRepairableConnectionError = (error: string | null) =>
  Boolean(error && /failed to fetch|networkerror|network request failed|fetch failed|load failed/i.test(error));

const renderRemoteLogin = (error: string | null = null) => {
  const repairable = isRepairableConnectionError(error);
  app.innerHTML = `
    <main class="remote-login">
      <section class="remote-login-panel">
        <div class="remote-login-head">
          <span><i data-lucide="server"></i></span>
          <div>
            <h1>Codex Switch Terminal</h1>
            <p>Connexion au serveur SaaS</p>
          </div>
        </div>
        ${error ? `<div class="remote-login-error">${escapeHtml(error)}</div>` : ""}
        ${repairable ? `
          <div class="remote-login-repair">
            <strong>La connexion peut etre reparee automatiquement.</strong>
            <p>Le bouton remet l'API sur cette adresse, conserve vos identifiants et nettoie le cache obsolete.</p>
            <button id="remoteRepairConnection" class="tool-button primary" type="button">
              <i data-lucide="wrench"></i>
              <span>Reparer la connexion</span>
            </button>
            <small id="remoteRepairStatus" role="status" aria-live="polite"></small>
          </div>
        ` : ""}
        <form id="remoteLoginForm" class="remote-login-form">
          <label>
            <span>Serveur</span>
            <input id="remoteBaseUrl" value="${escapeAttr(remoteBaseUrl())}" placeholder="http://IP_VM:8080" />
          </label>
          <label>
            <span>Token admin</span>
            <input id="remoteToken" type="password" autocomplete="current-password" />
          </label>
          <label>
            <span>Pool VPS · chats et terminaux</span>
            <textarea id="remoteNodes" placeholder="PC fixe|http://100.x.x.x:8080||0&#10;Oracle free|http://100.y.y.y:8080||20">${escapeHtml(remoteNodesText())}</textarea>
          </label>
          <button class="tool-button primary" type="submit">
            <i data-lucide="badge-check"></i>
            <span>Se connecter</span>
          </button>
        </form>
      </section>
    </main>
  `;
  renderIcons(app);
  document.querySelector<HTMLButtonElement>("#remoteRepairConnection")?.addEventListener("click", async (event) => {
    const button = event.currentTarget as HTMLButtonElement;
    const label = button.querySelector("span");
    const status = document.querySelector<HTMLElement>("#remoteRepairStatus");
    button.disabled = true;
    if (label) label.textContent = "Reparation en cours...";
    if (status) status.textContent = `Test de ${window.location.origin}...`;

    try {
      const repaired = await repairRemoteConnection();
      if (status) status.textContent = `Serveur joignable (${repaired.baseUrl}). Reconnexion...`;
      await boot();
    } catch (repairError) {
      if (status) status.textContent = String(repairError);
      button.disabled = false;
      if (label) label.textContent = "Reessayer la reparation";
    }
  });
  document.querySelector<HTMLFormElement>("#remoteLoginForm")?.addEventListener("submit", async (event) => {
    event.preventDefault();
    const baseUrl = document.querySelector<HTMLInputElement>("#remoteBaseUrl")?.value.trim() || remoteBaseUrl();
    const token = document.querySelector<HTMLInputElement>("#remoteToken")?.value.trim() || "";
    if (!token) {
      renderRemoteLogin("Token admin requis");
      return;
    }
    const nodes = document.querySelector<HTMLTextAreaElement>("#remoteNodes")?.value ?? "";
    saveRemoteConfig(baseUrl, token, nodes);
    // Un timeout TCP vers le VPS met ~20 s a echouer. On affiche donc un statut
    // de progression des le clic, puis on catch systematiquement l'erreur pour
    // la remonter dans le formulaire (au lieu de l'avaler silencieusement).
    const submitButton = document.querySelector<HTMLButtonElement>("#remoteLoginForm button[type='submit']");
    if (submitButton) {
      submitButton.disabled = true;
      const label = submitButton.querySelector("span");
      if (label) label.textContent = "Connexion en cours…";
    }
    try {
      await boot();
    } catch (error) {
      renderRemoteLogin(isTransportError(error)
        ? `Le serveur ${baseUrl} n'est pas joignable. Verifie Tailscale puis reessaie.`
        : String(error));
    }
  });
};

type IdleCapableWindow = Window & {
  requestIdleCallback?: (callback: () => void, options?: { timeout: number }) => number;
};

const scheduleIdleTask = (task: () => void) => {
  const requestIdle = (window as IdleCapableWindow).requestIdleCallback;
  if (requestIdle) requestIdle.call(window, task, { timeout: 4_000 });
  else window.setTimeout(task, 1_000);
};

const initDesktopUpdaterDeferred = () => {
  if (!("__TAURI_INTERNALS__" in window)) return;
  // Le client Cloud est lance depuis un binaire local explicitement choisi
  // par connect-vps.ps1. Une mise a jour/relaunch pendant l'initialisation
  // distante coupe le tunnel SSH et le connecteur Android.
  if (isRemoteMode()) return;
  scheduleIdleTask(() => {
    void import("./updater").then(({ initDesktopUpdater }) => initDesktopUpdater());
  });
};

const boot = async () => {
  await initializePlatform();

  if (isRemoteMode()) {
    const userAuth = await initializeUserAuth();
    if (userAuth === "required") {
      renderUserAuthGate(app, boot);
      return;
    }
    if (userAuth === "unsupported" && !hasRemoteAuth()) {
      renderRemoteLogin();
      return;
    }
  }

  // localStorage est partage par origine : le compte authentifie devient la
  // portee de toutes les donnees fonctionnelles conservees sur cet appareil.
  setAccountStorageScope(isRemoteMode() ? authenticatedUser()?.id : null);
  // Le brouillon tape avant un rechargement impose est restaure avec la portee
  // compte : l'utilisateur retrouve son message au lieu de le retaper.
  restoreChatDraft();
  activeDesignTool = normalizeDesignToolPreference(
    accountScopedStorage.getItem(DESIGN_TOOL_STORAGE_KEY),
  );
  designClaudeAccountId = accountScopedStorage.getItem(DESIGN_CLAUDE_ACCOUNT_STORAGE_KEY);
  designClaudeMode = normalizeClaudeDesignModePreference(
    accountScopedStorage.getItem(DESIGN_CLAUDE_MODE_STORAGE_KEY),
  );
  autonomousSeenReportIds = loadSeenAutonomousReportIds();
  autonomousMonitorCompact =
    accountScopedStorage.getItem(AUTONOMOUS_MONITOR_COMPACT_STORAGE_KEY) === "1";
  autonomousMonitorPosition = loadAutonomousMonitorPosition();
  autonomousMonitorSize = loadAutonomousMonitorSize();

  try {
    settings = await invoke<AppSettings>("load_settings");
  } catch (error) {
    if (isRemoteMode()) {
      renderRemoteLogin(String(error));
      return;
    }
    throw error;
  }
  selectedAccountId = settings.defaultAccountId || settings.accounts[0]?.id || null;
  chatAccountId = selectedAccountId;
  scheduleUnconnectedAccountCleanup();
  poolNewAccountBypass = settings.codexBypass ?? true;
  poolNewAccountFastMode = false;
  // Migre le registre de workspaces (localStorage -> settings) et fixe le
  // filtre par defaut, avant le premier rendu de la barre laterale.
  expertGridLayout = loadExpertGridLayout();
  expertChatPageSizeMode = loadExpertChatPageSizeMode();
  expertChatDisplayMode = loadExpertChatDisplayMode();
  chatComposerSelectorsEnabled = loadChatComposerSelectorsEnabled();
  chatTurnStatusDisplayMode = loadChatTurnStatusDisplayMode();
  chatSidebarPriorityMode = loadChatSidebarPriorityMode();
  chatSidebarHideRunning = loadChatSidebarHideRunning();
  chatContextTasksVisible = loadChatContextTasksVisible();
  expertChatHistoryOpenOnFullscreen = loadExpertChatHistoryOpenOnFullscreen();
  expertChatHistoryCloseOnCompact = loadExpertChatHistoryCloseOnCompact();
  expertChatToolbarHidden = loadExpertChatToolbarHidden();
  chatSidebarWidth = loadChatSidebarWidth();
  chatContextSidebarWidthPreference = loadChatContextSidebarWidthPreference();
  const [fullscreen] = await Promise.all([
    appWindow.isFullscreen().catch(() => false),
    setupEvents(),
    syncWorkspaceRegistry(),
  ]);
  isFullscreen = fullscreen;
  const recoveredLazyView = consumeRecoveredLazyView();
  activeView = "chat";
  render();
  scheduleAccountCompletionMidnightReset();
  unlistenMobileAutonomousAgentHandoff?.();
  unlistenMobileAutonomousAgentHandoff = installMobileAutonomousAgentHandoffListener((handoff) => {
    void openMobileAutonomousAgentHandoff(handoff);
  });
  unlistenMobilePaymentHandoff?.();
  unlistenMobilePaymentHandoff = installMobilePaymentHandoffListener((handoff) => {
    void openMobilePaymentHandoff(handoff);
  });
  if (recoveredLazyView && recoveredLazyView !== "chat") {
    setActiveView(recoveredLazyView);
  }
  // Retour OAuth du dashboard social (Instagram/TikTok) : le fournisseur a
  // redirigé sur /?switch_social=... — on ouvre l'onglet Réseaux sociaux qui
  // affiche la confirmation du compte connecté.
  const switchSocialCallback = takeSwitchSocialCallback();
  if (switchSocialCallback) {
    pendingSwitchSocialCallback = switchSocialCallback;
    setActiveView("social");
  }
  // La liaison se pilote depuis Mon compte : au retour de Microsoft, on rouvre
  // cette modale, sinon les messages de succes et d'echec ne seraient jamais lus.
  if (takeMicrosoftOAuthResultRedirect()) openUserProfileModal();
  if (isRemoteMode()) {
    scheduleIdleTask(() => {
      void loadMessagingModule()
        .then((module) => {
          module.startMessagingPolling(render);
          return module.refreshMessaging(render, { silent: true });
        })
        .catch(() => undefined);
    });
  }
  startRuntimeSync();
  startActiveTerminalsTracking();
  startAutonomousAgentsPoll();
  initDesktopUpdaterDeferred();
  startChatRuntimeClock();
  startLimitPoll();
  startDiscussionsPoll();
  void refreshDiscussions().then(() => {
    restoreExpertChats();
    // Le premier catalogue de tours peut arriver avant la restauration du
    // localStorage. Une seconde reconciliation adopte alors les chats crees
    // sur mobile sans attendre un nouvel evenement serveur.
    void refreshActiveChatTurns();
    if (activeView === "chat") {
      render();
      startAllExpertChatWork();
    }
    expertChatPanes.forEach((pane) => void loadChatModelCatalog(pane.accountId));
    startScheduledChatScheduler();
  });
  // Le chat et sa liste de discussions constituent le chemin critique. Les
  // catalogues secondaires et le quota attendent une fenetre idle afin de ne
  // pas disputer le premier rendu et le chargement du transcript sur mobile.
  scheduleIdleTask(() => {
    void refreshSkills();
    void refreshAutonomousAgents();
    void refreshLimitStatus(true);
    void refreshMicrosoftPendingActions();
    startMicrosoftPendingPolling(render);
  });
};

window.addEventListener("beforeunload", () => {
  if (accountCompletionResetTimer !== null) {
    window.clearTimeout(accountCompletionResetTimer);
    accountCompletionResetTimer = null;
  }
  persistTerminalSessions();
  persistExpertChats();
  unlistenData?.();
  unlistenMobileAutonomousAgentHandoff?.();
  unlistenMobilePaymentHandoff?.();
  unlistenExit?.();
  stopPoolPoll();
  stopLimitPoll();
  stopLimitRefreshFollowup();
  stopUnconnectedAccountCleanup();
  stopUsagePoll();
  stopKombaiPoll();
  stopAutonomousAgentsPoll();
  stopAutonomousMonitorTurnPoll();
  stopOrchestrationsPoll();
  stopDiscussionsPoll();
  stopActiveTerminalsTracking();
  stopRuntimeSync();
  forumModule?.stopForumPolling();
  messagingModule?.stopMessagingPolling();
  gmailModule?.stopGmailPolling();
  tiktokAccountsModule?.deactivateTikTokAccountsPanel();
  socialViewModule?.deactivateSocialPanel();
  deviceFleetModule?.deactivateDeviceFleetPanel();
  androidControlModule?.deactivateAndroidControlPanel();
  stopChatSync();
  stopChatTurnPoll();
  stopChatRuntimeClock();
  stopScheduledChatScheduler();
  stopAllExpertChatWork();
  // Le navigateur web ne possede pas le code-server partage du noeud : fermer
  // un onglet ne doit jamais arreter Kombai pour les autres clients. En desktop
  // local, on nettoie uniquement une instance que cette application sait lancee.
  if (!isRemoteMode() && (kombaiStatus?.running || kombaiStatus?.started)) {
    void invoke("kombai_stop").catch(() => undefined);
  }
  // Un onglet web parle a un noeud partage : ses terminaux vivent dans le
  // serveur et doivent survivre au rechargement comme a la fermeture de
  // l'onglet, exactement comme Kombai juste au-dessus. Le chargement suivant
  // s'y rattache par l'identifiant persiste. En desktop local, les PTY meurent
  // avec l'application : on les ferme pour ne pas laisser d'orphelins.
  if (!isRemoteMode()) {
    terminalSessions.forEach((session) => {
      if (session.ptyId !== null) {
        void invoke("stop_terminal", { id: session.ptyId }).catch(() => undefined);
      }
    });
  }
});

initPwaSupport();
initWebAutoUpdate();

void boot().catch((error) => {
  if (isRemoteMode()) {
    renderRemoteLogin(String(error));
    return;
  }
  app.innerHTML = `<main class="boot error">${escapeHtml(String(error))}</main>`;
});
